export const SPELL_DATABASE: Record<string, any> = {
  Bard: {
    Cantrips: [
      { name: "Dancing Lights", components: "V, S, M", desc: "Anda membuat hingga empat lampu seukuran obor dalam jangkauan, menjadikannya tampak seperti obor, lentera, atau bola bercahaya yang melayang di udara selama durasi tersebut. Anda juga dapat menggabungkan keempat lampu menjadi satu bentuk humanoid samar-samar berukuran sedang. Apapun bentuk yang Anda pilih, setiap lampu memancarkan cahaya redup dalam radius 10 kaki.\nSebagai tindakan bonus pada giliran Anda, Anda dapat memindahkan lampu hingga 60 kaki ke tempat baru dalam jangkauan. Sebuah cahaya harus berada dalam jarak 20 kaki dari cahaya lain yang diciptakan oleh mantra ini, dan sebuah cahaya akan berkedip jika melebihi jangkauan mantranya." },
      { name: "Light", components: "V, M", desc: "Anda menyentuh satu objek yang ukurannya tidak lebih besar dari 10 kaki dalam dimensi apa pun. Hingga mantranya berakhir, objek tersebut memancarkan cahaya terang dalam radius 20 kaki dan cahaya redup dalam radius tambahan 20 kaki. Lampunya bisa diwarnai sesuka Anda. Menutupi objek sepenuhnya dengan sesuatu yang buram menghalangi cahaya. Mantra berakhir jika Anda mengucapkannya lagi atau mengabaikannya sebagai suatu tindakan.\nJika Anda mengincar benda yang dipegang atau dikenakan oleh makhluk musuh, makhluk tersebut harus berhasil melakukan lemparan penyelamatan ketangkasan untuk menghindari mantranya." },
      { name: "Mage Hand", components: "V, S", desc: "Tangan spektral dan mengambang muncul pada titik yang Anda pilih dalam jangkauan. Tangan tersebut bertahan selama atau sampai Anda mengabaikannya sebagai suatu tindakan. Tangan itu akan hilang jika jaraknya lebih dari 30 kaki dari Anda atau jika Anda mengucapkan mantra ini lagi.\nAnda dapat menggunakan tindakan Anda untuk mengontrol tangan. Anda dapat menggunakan tangan untuk memanipulasi suatu benda, membuka pintu atau wadah yang tidak terkunci, menyimpan atau mengambil suatu benda dari wadah terbuka, atau menuangkan isinya ke dalam botol. Anda dapat menggerakkan tangan hingga 30 kaki setiap kali menggunakannya.\nTangan tidak dapat menyerang, mengaktifkan item sihir, atau membawa beban lebih dari 10 pon." },
      { name: "Mending", components: "V, S, M", desc: "Mantra ini memperbaiki satu kerusakan atau robekan pada benda yang Anda sentuh, seperti kunci rusak, jubah robek, atau kantong anggur yang bocor. Selama patah atau robeknya tidak lebih dari 1 kaki di dimensi mana pun, Anda memperbaikinya, tanpa meninggalkan bekas kerusakan sebelumnya.\nMantra ini secara fisik dapat memperbaiki item atau konstruksi sihir, tetapi mantra tersebut tidak dapat memulihkan sihir ke objek tersebut." },
      { name: "Message", components: "V, S, M", desc: "Anda mengarahkan jari Anda ke arah makhluk dalam jangkauan dan membisikkan pesan. Target (dan hanya target) yang mendengar pesan tersebut dan dapat membalas dengan bisikan yang hanya dapat didengar oleh Anda.\nAnda dapat mengucapkan mantra ini melalui benda padat jika Anda familiar dengan targetnya dan mengetahui bahwa targetnya berada di luar penghalang. Keheningan magis, batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu setinggi 3 kaki menghalangi mantra tersebut. Mantranya tidak harus mengikuti garis lurus dan dapat bergerak bebas di sudut atau melalui celah." },
      { name: "Minor Illusion", components: "S, M", desc: "Anda membuat suara atau gambar suatu objek dalam jangkauan yang berlangsung selama durasi tersebut. Ilusi juga berakhir jika Anda mengabaikannya sebagai suatu tindakan atau mengucapkan mantra ini lagi.\nJika Anda membuat suara, volumenya bisa berkisar dari bisikan hingga jeritan. Bisa berupa suara Anda, suara orang lain, auman singa, tabuhan genderang, atau suara lain yang Anda pilih. Suara tersebut terus terdengar tanpa henti sepanjang durasi, atau Anda dapat membuat suara terpisah pada waktu yang berbeda sebelum mantra berakhir.\nJika Anda membuat gambar suatu objek--seperti kursi, jejak kaki berlumpur, atau peti kecil--ukurannya tidak boleh lebih dari kubus berukuran 5 kaki. Gambar tidak dapat menimbulkan suara, cahaya, bau, atau efek sensorik lainnya. Interaksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya.\nJika makhluk menggunakan tindakannya untuk memeriksa suara atau gambar, makhluk tersebut dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk mengenali ilusi apa adanya, ilusi tersebut menjadi samar bagi makhluk tersebut." },
      { name: "Prestidigitation", components: "V, S", desc: "Mantra ini adalah trik magis kecil yang digunakan oleh perapal mantra pemula untuk latihan. Anda membuat salah satu efek ajaib berikut dalam 'jangkauan':\nAnda menciptakan efek sensorik yang seketika dan tidak berbahaya, seperti percikan api, hembusan angin, not musik yang samar, atau bau yang aneh.\nAnda langsung menyalakan atau mematikan lilin, obor, atau api unggun kecil.\nAnda langsung membersihkan atau mengotori benda yang ukurannya tidak lebih dari 1 kaki kubik.\nAnda mendinginkan, menghangatkan, atau membumbui hingga 1 kaki kubik bahan tak hidup selama 1 jam.\nAnda membuat warna, tanda kecil, atau simbol muncul pada suatu benda atau permukaan selama 1 jam.\nAnda membuat pernak-pernik non-magis atau gambar ilusi yang pas di tangan Anda dan bertahan hingga akhir giliran Anda berikutnya.\nJika Anda mengucapkan mantra ini beberapa kali, Anda dapat mengaktifkan hingga tiga efek non-instannya sekaligus, dan Anda dapat mengabaikan efek tersebut sebagai tindakan." },
      { name: "True Strike", components: "S", desc: "Anda mengulurkan tangan dan mengarahkan jari ke sasaran dalam jangkauan. Sihir Anda memberi Anda wawasan singkat tentang pertahanan target. Pada giliran berikutnya, Anda mendapatkan keuntungan dari serangan pertama Anda terhadap target, asalkan mantra ini belum berakhir." },
      { name: "Vicious Mockery", components: "V", desc: "Anda melepaskan serangkaian hinaan yang dibumbui dengan pesona halus pada makhluk yang dapat Anda lihat dalam jangkauan. Jika target dapat mendengar Anda (walaupun ia tidak perlu memahami Anda), ia harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau menerima kerusakan psikis 1d4 dan memiliki kerugian pada serangan berikutnya yang dilakukannya sebelum akhir giliran berikutnya.\nKerusakan mantra ini meningkat sebesar 1d4 ketika Anda mencapai level 5 (2d4), level 11 (3d4), dan level 17 (4d4)." },
    ],
    Level1: [
      { name: "Animal Friendship", components: "V, S, M", desc: "Mantra ini memungkinkan Anda meyakinkan binatang bahwa Anda tidak bermaksud jahat. Pilih binatang yang dapat Anda lihat dalam jangkauan. Ia harus melihat dan mendengar Anda. Jika Intelijen binatang itu 4 atau lebih tinggi, mantranya gagal. Jika tidak, binatang itu harus berhasil dalam lemparan penyelamatan kebijaksanaan atau terpesona oleh Anda selama durasi mantra tersebut. Jika Anda atau salah satu teman Anda melukai target, mantranya akan berakhir." },
      { name: "Bane", components: "V, S, M", desc: "Hingga tiga makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan harus melakukan lemparan yang menghemat karisma. Setiap kali target yang gagal melakukan lemparan penyelamatan ini melakukan serangan lemparan atau lemparan penyelamatan sebelum mantra berakhir, target harus melempar d4 dan mengurangi jumlah yang diperoleh dari lemparan serangan atau lemparan penyelamatan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 1." },
      { name: "Charm Person", components: "V, S", desc: "Anda mencoba memikat humanoid yang dapat Anda lihat dalam jangkauan. Ia harus melakukan lemparan penyelamatan yang bijaksana, dan melakukannya dengan keuntungan jika Anda atau teman Anda melawannya. Jika gagal dalam lemparan penyelamatan, ia akan terpesona oleh Anda hingga mantranya berakhir atau hingga Anda atau teman Anda melakukan sesuatu yang membahayakannya. Makhluk yang terpesona menganggap Anda sebagai kenalan yang ramah. Saat mantranya berakhir, makhluk itu tahu bahwa dia terpesona oleh Anda.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 1. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Comprehend Languages", components: "V, S, M", desc: "Selama ini, Anda memahami arti literal dari setiap bahasa lisan yang Anda dengar. Anda juga memahami bahasa tertulis apa pun yang Anda lihat, tetapi Anda harus menyentuh permukaan tempat kata-kata itu ditulis. Dibutuhkan sekitar 1 menit untuk membaca satu halaman teks.\nMantra ini tidak memecahkan kode pesan rahasia dalam teks atau mesin terbang, seperti sigil misterius, yang bukan bagian dari bahasa tertulis." },
      { name: "Cure Wounds", components: "V, S", desc: "Makhluk yang Anda sentuh mendapatkan kembali sejumlah poin hit yang setara dengan 1d8 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, penyembuhan meningkat sebesar 1d8 untuk setiap slot level di atas 1." },
      { name: "Detect Magic", components: "V, S", desc: "Selama durasi tersebut, Anda merasakan kehadiran sihir dalam jarak 30 kaki dari Anda. Jika Anda merasakan sihir dengan cara ini, Anda dapat menggunakan tindakan Anda untuk melihat aura samar di sekitar makhluk atau objek apa pun yang terlihat di area yang mengandung sihir, dan Anda mempelajari sekolah sihirnya, jika ada.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Disguise Self", components: "V, S", desc: "Anda membuat diri Anda sendiri--termasuk pakaian, baju besi, senjata, dan barang-barang lainnya pada diri Anda--terlihat berbeda sampai mantranya berakhir atau sampai Anda menggunakan tindakan Anda untuk mengabaikannya. Anda bisa terlihat 1 kaki lebih pendek atau lebih tinggi dan bisa terlihat kurus, gemuk, atau di antara keduanya. Anda tidak dapat mengubah tipe tubuh Anda, jadi Anda harus mengambil bentuk yang memiliki susunan dasar anggota tubuh yang sama. Jika tidak, sejauh mana ilusi itu terserah Anda.\nPerubahan yang dilakukan oleh mantra ini gagal memenuhi pemeriksaan fisik. Misalnya, jika Anda menggunakan mantra ini untuk menambahkan topi ke pakaian Anda, benda akan melewati topi tersebut, dan siapa pun yang menyentuhnya tidak akan merasakan apa pun atau akan merasakan kepala dan rambut Anda. Jika Anda menggunakan mantra ini untuk terlihat lebih kurus dari Anda, tangan seseorang yang mengulurkan tangan untuk menyentuh Anda akan menabrak Anda saat tangan itu tampak masih di udara.\nUntuk mengetahui bahwa Anda sedang menyamar, makhluk dapat menggunakan tindakannya untuk memeriksa penampilan Anda dan harus berhasil dalam pemeriksaan Intelijen (Investigasi) terhadap mantra penyelamatan DC Anda." },
      { name: "Feather Fall", components: "V, M", desc: "Pilih hingga lima makhluk yang jatuh dalam jangkauan. Kecepatan turunnya makhluk yang jatuh melambat hingga 60 kaki per putaran hingga mantranya berakhir. Jika makhluk itu mendarat sebelum mantranya berakhir, ia tidak menerima kerusakan akibat jatuh dan dapat mendarat dengan kakinya, dan mantranya berakhir untuk makhluk itu." },
      { name: "Healing Word", components: "V", desc: "Makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan mendapatkan kembali poin hit yang setara dengan 1d4 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, penyembuhan meningkat sebesar 1d4 untuk setiap slot level di atas 1." },
      { name: "Heroism", components: "V, S", desc: "Makhluk rela yang Anda sentuh dipenuhi dengan keberanian. Hingga mantranya berakhir, makhluk itu kebal terhadap rasa takut dan memperoleh poin serangan sementara yang setara dengan pengubah kemampuan merapal mantra Anda di awal setiap giliran. Saat mantra berakhir, target kehilangan sisa poin hit sementara dari mantra ini." },
      { name: "Hideous Laughter", components: "V, S, M", desc: "Makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan menganggap segala sesuatu sebagai sesuatu yang sangat lucu dan tertawa terbahak-bahak jika mantra ini memengaruhinya. Target harus berhasil dalam lemparan penyelamatan yang bijaksana atau rawan jatuh, menjadi tidak berdaya dan tidak mampu berdiri selama jangka waktu tersebut. Makhluk dengan skor Intelijen 4 atau kurang tidak terpengaruh.\nDi akhir setiap giliran, dan setiap kali menerima kerusakan, target dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Target mempunyai keuntungan dalam penyelamatan jika dipicu oleh kerusakan. Jika berhasil, mantranya berakhir." },
      { name: "Identify", components: "V, S, M", desc: "Anda memilih satu objek yang harus Anda sentuh selama merapal mantra. Jika itu adalah benda ajaib atau benda lain yang mengandung sihir, Anda akan mempelajari propertinya dan cara menggunakannya, apakah memerlukan attunement untuk menggunakannya, dan berapa banyak muatan yang dimilikinya, jika ada. Anda mengetahui apakah ada mantra yang memengaruhi item dan apa saja pengaruhnya. Jika item dibuat oleh mantra, Anda akan mengetahui mantra mana yang menciptakannya.\nJika Anda malah menyentuh makhluk selama casting, Anda akan mengetahui mantra apa, jika ada, yang saat ini memengaruhinya." },
      { name: "Illusory Script", components: "S, M", desc: "Anda menulis di perkamen, kertas, atau bahan tulis lain yang sesuai dan memberinya ilusi kuat yang bertahan selama itu.\nBagi Anda dan makhluk apa pun yang Anda tunjuk saat mengucapkan mantra, tulisan itu tampak normal, ditulis di tangan Anda, dan menyampaikan makna apa pun yang Anda inginkan saat menulis teks tersebut. Bagi orang lain, tulisan tersebut tampak seolah-olah ditulis dalam naskah yang tidak diketahui atau ajaib yang tidak dapat dipahami. Alternatifnya, Anda dapat membuat tulisan tersebut tampak seperti pesan yang sama sekali berbeda, ditulis dengan tangan dan bahasa yang berbeda, meskipun bahasanya haruslah bahasa yang Anda ketahui.\nJika mantranya dihilangkan, naskah asli dan ilusinya akan hilang.\nMakhluk yang memiliki pandangan sejati dapat membaca pesan tersembunyi." },
      { name: "Longstrider", components: "V, S, M", desc: "Anda menyentuh makhluk. Kecepatan target meningkat 10 kaki hingga mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot mantra di atas level 1." },
      { name: "Silent Image", components: "V, S, M", desc: "Anda membuat gambar suatu benda, makhluk, atau fenomena nyata lainnya yang ukurannya tidak lebih besar dari kubus berukuran 15 kaki. Gambar muncul di suatu tempat dalam jangkauan dan berlangsung selama durasi tersebut. Gambar tersebut murni visual; tidak disertai suara, bau, atau efek sensorik lainnya.\nAnda dapat menggunakan tindakan Anda untuk menyebabkan gambar berpindah ke tempat mana pun dalam jangkauan. Saat gambar berpindah lokasi, Anda dapat mengubah tampilannya sehingga gerakannya tampak natural pada gambar. Misalnya, jika Anda membuat gambar makhluk dan memindahkannya, Anda dapat mengubah gambar tersebut sehingga tampak seperti sedang berjalan.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk dapat mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut." },
      { name: "Sleep", components: "V, S, M", desc: "Mantra ini membuat makhluk tertidur secara ajaib. Gulung 5d8; totalnya adalah berapa banyak poin serangan makhluk yang dapat dipengaruhi oleh mantra ini. Makhluk dalam jarak 20 kaki dari titik yang Anda pilih dalam jangkauan akan terpengaruh dalam urutan titik serangan mereka saat ini (mengabaikan makhluk yang tidak sadarkan diri).\nDimulai dengan makhluk yang memiliki poin serangan terendah saat ini, setiap makhluk yang terkena mantra ini akan jatuh pingsan hingga mantranya berakhir, orang yang tidur menerima kerusakan, atau seseorang menggunakan tindakan untuk mengguncang atau menampar orang yang tidur tersebut hingga terbangun. Kurangi poin hit setiap makhluk dari total sebelum melanjutkan ke makhluk dengan poin hit terendah berikutnya. Hit point suatu makhluk harus sama dengan atau kurang dari total yang tersisa agar makhluk tersebut dapat terpengaruh.\nMayat hidup dan makhluk yang kebal terhadap pesona tidak terpengaruh oleh mantra ini.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, putar 2d8 tambahan untuk setiap level slot di atas 1." },
      { name: "Speak with Animals", components: "V, S", desc: "Anda memperoleh kemampuan untuk memahami dan berkomunikasi secara verbal dengan binatang selama durasi tersebut. Pengetahuan dan kesadaran banyak binatang dibatasi oleh kecerdasan mereka, tetapi minimal, binatang dapat memberi Anda informasi tentang lokasi dan monster terdekat, termasuk apa pun yang dapat mereka lihat atau rasakan dalam satu hari terakhir. Anda mungkin bisa membujuk seekor binatang untuk memberikan bantuan kecil kepada Anda, sesuai kebijaksanaan GM." },
      { name: "Thunderwave", components: "V, S", desc: "Gelombang kekuatan yang menggelegar menyapu Anda. Setiap makhluk dalam kubus berukuran 15 kaki yang berasal dari Anda harus melakukan lemparan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk menerima kerusakan petir sebesar 2d8 dan didorong sejauh 10 kaki dari Anda. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan dan tidak didorong.\nSelain itu, objek tanpa jaminan yang sepenuhnya berada dalam area efek secara otomatis didorong sejauh 10 kaki dari Anda oleh efek mantra, dan mantra tersebut mengeluarkan ledakan menggelegar yang terdengar hingga jarak 300 kaki.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 1." },
      { name: "Unseen Servant", components: "V, S, M", desc: "Mantra ini menciptakan kekuatan yang tidak terlihat, tidak ada artinya, dan tidak berbentuk yang melakukan tugas-tugas sederhana sesuai perintah Anda hingga mantranya berakhir. Pelayan itu muncul di ruang kosong di tanah dalam jangkauannya. Ia memiliki AC 10, 1 hit point, dan Strength 2, dan tidak dapat menyerang. Jika poin hitnya turun menjadi 0, mantranya berakhir.\nSekali di setiap giliran Anda sebagai tindakan bonus, Anda dapat secara mental memerintahkan pelayan untuk bergerak hingga 15 kaki dan berinteraksi dengan suatu objek. Pelayan dapat melakukan tugas-tugas sederhana yang dapat dilakukan oleh pelayan manusia, seperti mengambil barang, membersihkan, memperbaiki, melipat pakaian, menyalakan api, menyajikan makanan, dan menuangkan anggur. Setelah Anda memberi perintah, pelayan akan menjalankan tugas dengan kemampuan terbaiknya hingga tugas selesai, lalu menunggu perintah Anda selanjutnya.\nJika Anda memerintahkan pelayan untuk melakukan tugas yang akan memindahkannya lebih dari 60 kaki dari Anda, mantranya akan berakhir." },
    ],
    Level2: [
      { name: "Animal Messenger", components: "V, S, M", desc: "Melalui mantra ini, Anda menggunakan binatang untuk menyampaikan pesan. Pilih binatang kecil yang dapat Anda lihat dalam jangkauannya, seperti tupai, blue jay, atau kelelawar. Anda menentukan lokasi, yang harus Anda kunjungi, dan penerima yang cocok dengan gambaran umum, seperti \"pria atau wanita berseragam penjaga kota\" atau \"kurcaci berambut merah yang memakai topi runcing\". Anda juga mengucapkan pesan hingga dua puluh lima kata. Binatang target melakukan perjalanan selama durasi mantra menuju lokasi yang ditentukan, menempuh jarak sekitar 50 mil per 24 jam untuk pembawa pesan terbang, atau 25 mil untuk hewan lain.\nSaat pembawa pesan tiba, ia menyampaikan pesan Anda kepada makhluk yang Anda gambarkan, meniru suara Anda. Utusan itu hanya berbicara kepada makhluk yang cocok dengan deskripsi yang Anda berikan. Jika pembawa pesan tidak mencapai tujuannya sebelum mantranya berakhir, pesannya akan hilang, dan binatang itu akan kembali ke tempat Anda mengucapkan mantra ini.\nJika Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, durasi mantra bertambah 48 jam untuk setiap slot level di atas 2." },
      { name: "Blindness/Deafness", components: "V", desc: "Anda bisa membutakan atau menulikan musuh. Pilih satu makhluk yang dapat Anda lihat dalam jangkauan untuk melakukan penyelamatan konstitusi. Jika gagal, target akan menjadi buta atau tuli (pilihan Anda) selama durasi tersebut. Di akhir setiap giliran, target dapat melakukan penyelamatan konstitusi. Jika berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Calm Emotions", components: "V, S", desc: "Anda berusaha menekan emosi yang kuat dalam sekelompok orang. Setiap humanoid dalam bola berradius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan harus melakukan lemparan penyelamatan karisma; makhluk dapat memilih untuk gagal dalam penyelamatan ini jika ia menginginkannya. Jika makhluk gagal dalam penyelamatannya, pilih salah satu dari dua efek berikut. Anda dapat menekan efek apa pun yang menyebabkan target terpesona atau ketakutan. Saat mantra ini berakhir, semua efek yang ditekan akan dilanjutkan, asalkan durasinya belum habis untuk sementara waktu.\nAlternatifnya, Anda dapat membuat target acuh tak acuh terhadap makhluk pilihan Anda yang dimusuhinya. Ketidakpedulian ini berakhir jika target diserang atau disakiti oleh mantra atau jika ia menyaksikan salah satu temannya disakiti. Saat mantranya berakhir, makhluk itu menjadi bermusuhan lagi, kecuali GM mengatur sebaliknya." },
      { name: "Detect Thoughts", components: "V, S, M", desc: "Selama itu, Anda bisa membaca pikiran makhluk tertentu. Saat Anda merapal mantra dan melakukan tindakan di setiap belokan hingga mantra berakhir, Anda dapat memfokuskan pikiran Anda pada satu makhluk yang dapat Anda lihat dalam jarak 30 kaki dari Anda. Jika makhluk yang Anda pilih memiliki Kecerdasan 3 atau lebih rendah atau tidak dapat berbicara bahasa apa pun, makhluk tersebut tidak terpengaruh.\nAwalnya Anda mempelajari pemikiran permukaan makhluk itu - apa yang paling ada dalam pikirannya pada saat itu. Sebagai suatu tindakan, Anda dapat mengalihkan perhatian Anda ke pikiran makhluk lain atau mencoba menyelidiki lebih dalam pikiran makhluk yang sama. Jika Anda menyelidiki lebih dalam, target harus melakukan lemparan penyelamatan Kebijaksanaan. Jika gagal, Anda mendapatkan wawasan tentang alasannya (jika ada), keadaan emosinya, dan sesuatu yang terlintas dalam pikirannya (seperti sesuatu yang dikhawatirkan, disukai, atau dibencinya). Jika berhasil maka mantranya berakhir. Apa pun yang terjadi, target tahu bahwa Anda sedang menyelidiki pikirannya, dan kecuali Anda mengalihkan perhatian Anda ke pikiran makhluk lain, makhluk itu dapat menggunakan tindakannya pada gilirannya untuk melakukan pemeriksaan Intelijen yang ditentang oleh pemeriksaan Intelijen Anda; jika berhasil, mantranya berakhir.\nPertanyaan yang ditujukan secara verbal pada makhluk target secara alami membentuk alur pemikirannya, jadi mantra ini sangat efektif sebagai bagian dari interogasi.\nAnda juga dapat menggunakan mantra ini untuk mendeteksi keberadaan makhluk berpikir yang tidak dapat Anda lihat. Saat Anda mengucapkan mantra atau sebagai tindakan Anda selama durasi tersebut, Anda dapat mencari pikiran dalam jarak 30 kaki dari Anda. Mantranya dapat menembus penghalang, tetapi batu setinggi 2 kaki, logam apa pun setinggi 2 inci selain timah, atau lembaran timah tipis menghalangi Anda. Anda tidak dapat mendeteksi makhluk dengan Kecerdasan 3 atau lebih rendah atau makhluk yang tidak bisa berbicara bahasa apa pun.\nSetelah Anda mendeteksi keberadaan suatu makhluk dengan cara ini, Anda dapat membaca pikirannya selama sisa durasi seperti yang dijelaskan di atas, meskipun Anda tidak dapat melihatnya, tetapi ia harus tetap berada dalam jangkauan." },
      { name: "Enhance Ability", components: "V, S, M", desc: "Anda menyentuh makhluk dan memberinya peningkatan ajaib. Pilih salah satu dari efek berikut; target mendapatkan efek itu hingga mantranya berakhir.\n***Daya Tahan Beruang.*** Targetnya memiliki keunggulan dalam pemeriksaan konstitusi. Ia juga mendapatkan 2d6 poin hit sementara, yang hilang saat mantranya berakhir.\n***Kekuatan Banteng.*** Target memiliki keunggulan dalam pemeriksaan kekuatan, dan daya dukungnya berlipat ganda.\n***Rahmat Kucing.*** Target memiliki keunggulan dalam pemeriksaan ketangkasan. Ia juga tidak menerima kerusakan jika terjatuh dari ketinggian 20 kaki atau kurang jika tidak dilumpuhkan.\n***Kemegahan Elang.*** Target memiliki keunggulan dalam pemeriksaan Karisma.\n***Kelicikan Rubah.*** Targetnya memiliki keunggulan dalam pemeriksaan intelijen.\n***Kebijaksanaan Burung Hantu.*** Target memiliki keuntungan dalam pemeriksaan kebijaksanaan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Enthrall", components: "V, S", desc: "Anda merangkai rangkaian kata-kata yang mengganggu, menyebabkan makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan dan yang dapat mendengar Anda melakukan penyelamatan yang bijaksana. Makhluk apa pun yang tidak dapat dipesona akan berhasil dalam lemparan penyelamatan ini secara otomatis, dan jika Anda atau teman Anda melawan makhluk tersebut, ia memiliki keuntungan dalam penyelamatan tersebut. Jika penyelamatan gagal, target memiliki kelemahan pada pemeriksaan Kebijaksanaan (Persepsi) yang dilakukan untuk mengenali makhluk apa pun selain Anda hingga mantranya berakhir atau hingga target tidak dapat lagi mendengar Anda. Mantra berakhir jika Anda tidak mampu atau tidak dapat berbicara lagi." },
      { name: "Heat Metal", components: "V, S, M", desc: "Pilih benda logam buatan pabrik, seperti senjata logam atau baju besi logam berat atau sedang, yang dapat Anda lihat dalam jangkauan. Anda menyebabkan objek bersinar merah membara. Makhluk apa pun yang melakukan kontak fisik dengan objek akan menerima kerusakan api 2d8 saat Anda mengucapkan mantra. Hingga mantranya berakhir, Anda dapat menggunakan aksi bonus pada setiap giliran berikutnya untuk menimbulkan kerusakan ini lagi.\nJika makhluk memegang atau memakai benda tersebut dan menerima kerusakan darinya, makhluk tersebut harus berhasil melakukan penyelamatan konstitusi dengan melempar atau menjatuhkan benda tersebut jika bisa. Jika tidak menjatuhkan objek, ia mempunyai kerugian pada serangan dan pemeriksaan kemampuan hingga awal giliran Anda berikutnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 2." },
      { name: "Hold Person", components: "V, S, M", desc: "Pilih humanoid yang dapat Anda lihat dalam jangkauan. Target harus berhasil melakukan penyelamatan kebijaksanaan atau menjadi lumpuh selama jangka waktu tersebut. Di akhir setiap giliran, target dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, mantranya berakhir tepat sasaran.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu humanoid tambahan untuk setiap slot level di atas 2. Humanoid harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkannya." },
      { name: "Invisibility", components: "V, S, M", desc: "Makhluk yang Anda sentuh menjadi tidak terlihat sampai mantranya berakhir. Apapun yang dikenakan atau dibawa oleh target tidak akan terlihat selama berada pada orang yang menjadi target. Mantra berakhir untuk target yang menyerang atau mengeluarkan mantra.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Knock", components: "V", desc: "Pilih objek yang dapat Anda lihat dalam jangkauan. Benda tersebut dapat berupa pintu, kotak, peti, satu set borgol, gembok, atau benda lain yang mengandung sarana duniawi atau magis yang menghalangi akses.\nTarget yang ditahan dengan kunci biasa atau yang tertahan atau terpalang akan menjadi tidak terkunci, tidak tertahan, atau tidak tertahan. Jika objek memiliki beberapa kunci, hanya satu yang terbuka.\nJika Anda memilih target yang ditutup dengan kunci misterius, mantra itu akan ditekan selama 10 menit, selama waktu tersebut target dapat dibuka dan ditutup secara normal.\nSaat Anda mengucapkan mantranya, ketukan keras, terdengar dari jarak 300 kaki, berasal dari objek target." },
      { name: "Lesser Restoration", components: "V, S", desc: "Anda menyentuh suatu makhluk dan dapat mengakhiri satu penyakit atau satu kondisi yang menimpanya. Kondisinya bisa menjadi buta, tuli, lumpuh, atau keracunan." },
      { name: "Locate Animals or Plants", components: "V, S, M", desc: "Jelaskan atau beri nama jenis binatang atau tumbuhan tertentu. Berkonsentrasi pada suara alam di sekitar Anda, Anda mempelajari arah dan jarak ke makhluk atau tumbuhan terdekat dalam jarak 5 mil, jika ada." },
      { name: "Locate Object", components: "V, S, M", desc: "Jelaskan atau beri nama suatu objek yang Anda kenal. Anda merasakan arah ke lokasi objek, selama objek tersebut berada dalam jarak 1.000 kaki dari Anda. Jika suatu benda bergerak, maka diketahui arah pergerakannya.\nMantra tersebut dapat menemukan lokasi objek tertentu yang Anda kenal, selama Anda telah melihatnya dari dekat--dalam jarak 30 kaki--setidaknya sekali. Alternatifnya, mantra tersebut dapat menemukan lokasi objek terdekat dari jenis tertentu, seperti jenis pakaian, perhiasan, furnitur, perkakas, atau senjata tertentu.\nMantra ini tidak dapat menemukan lokasi suatu objek jika ada timah tebal, bahkan lembaran tipis, menghalangi jalur langsung antara Anda dan objek tersebut." },
      { name: "Magic Mouth", components: "V, S, M", desc: "Anda menanam pesan ke suatu objek dalam jangkauan mantra. Pesan tersebut diungkapkan secara verbal ketika kondisi pemicu terpenuhi. Pilihlah benda yang Anda lihat, dan tidak dipakai atau dibawa oleh makhluk lain. Kemudian ucapkan pesannya, yang tidak boleh lebih dari 25 kata tetapi mendengarkannya bisa memakan waktu hingga 10 menit. Terakhir, tentukan keadaan yang memicu mantra untuk menyampaikan pesan Anda.\nKetika kondisi ini terpenuhi, mulut ajaib muncul pada objek dan mengartikulasikan pesan yang meniru suara Anda, nada yang sama yang digunakan selama penanaman pesan. Jika objek yang dipilih memiliki mulut atau sesuatu yang mendekat seperti mulut patung, mulut ajaib akan hidup pada titik ini, memberikan ilusi bahwa kata-kata tersebut berasal dari mulut objek.\nSaat Anda mengucapkan mantra ini, Anda dapat memutuskan bahwa mantra tersebut berakhir saat pesan terkirim atau mantra tersebut dapat bertahan dan mengulangi pesan tersebut kapan pun keadaan terjadi.\nKeadaan pemicunya bisa bersifat umum atau sedetail yang Anda inginkan, namun harus didasarkan pada kondisi visual atau suara yang terjadi dalam jarak 30 kaki dari objek. Misalnya, Anda dapat menginstruksikan mulut untuk berbicara ketika makhluk apa pun bergerak dalam jarak 30 kaki dari objek atau ketika bel perak berbunyi dalam jarak 30 kaki dari objek tersebut." },
      { name: "See Invisibility", components: "V, S, M", desc: "Selama durasi mantra, Anda melihat makhluk dan objek tak terlihat seolah-olah terlihat, dan Anda dapat melihat melalui Ethereal. Benda dan makhluk halus tampak tembus cahaya." },
      { name: "Shatter", components: "V, S, M", desc: "Suara dering keras yang tiba-tiba, sangat intens, muncul dari titik pilihan Anda dalam jangkauan. Setiap makhluk dalam bola berradius 10 kaki yang berpusat pada titik tersebut harus melakukan penyelamatan Konstitusi. Makhluk menerima kerusakan guntur 3d8 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil. Makhluk yang terbuat dari bahan anorganik seperti batu, kristal, atau logam memiliki kelemahan dalam penyelamatan ini.\nBenda non-magis yang tidak dipakai atau dibawa juga akan mengalami kerusakan jika berada dalam area mantra.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan mantra meningkat sebesar 1d8 untuk setiap level slot mantra 2 yang lebih tinggi." },
      { name: "Silence", components: "V, S", desc: "Selama durasi tersebut, tidak ada suara yang dapat dihasilkan di dalam atau melewati bola berradius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan. Makhluk atau benda apa pun yang seluruhnya berada di dalam bola kebal terhadap kerusakan akibat petir, dan makhluk menjadi tuli saat berada sepenuhnya di dalamnya.\nMerapalkan mantra yang mencakup komponen verbal tidak mungkin dilakukan di sana." },
      { name: "Suggestion", components: "V, M", desc: "Anda menyarankan suatu rangkaian aktivitas (terbatas pada satu atau dua kalimat) dan secara ajaib memengaruhi makhluk yang dapat Anda lihat dalam jangkauan yang dapat mendengar dan memahami Anda. Makhluk yang tidak bisa dipesona akan kebal terhadap efek ini. Saran tersebut harus diungkapkan sedemikian rupa agar tindakan yang diambil terdengar masuk akal. Meminta makhluk itu untuk menusuk dirinya sendiri, melemparkan dirinya ke tombak, mengorbankan dirinya sendiri, atau melakukan tindakan berbahaya lainnya akan mengakhiri mantranya.\nTargetnya harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, ia akan melakukan tindakan yang Anda jelaskan dengan kemampuan terbaiknya. Tindakan yang disarankan dapat berlanjut sepanjang durasi. Jika aktivitas yang disarankan dapat diselesaikan dalam waktu yang lebih singkat, mantra akan berakhir saat subjek menyelesaikan apa yang diminta.\nAnda juga dapat menentukan kondisi yang akan memicu aktivitas khusus selama durasi tersebut. Misalnya, Anda mungkin menyarankan agar seorang kesatria memberikan kuda perangnya kepada pengemis pertama yang ditemuinya. Jika kondisi tidak terpenuhi sebelum mantra berakhir, aktivitas tidak akan dilakukan.\nJika Anda atau salah satu teman Anda merusak target, mantranya akan berakhir." },
      { name: "Zone of Truth", components: "V, S", desc: "Anda menciptakan zona ajaib yang melindungi dari penipuan dalam bola berradius 15 kaki yang berpusat pada titik pilihan Anda dalam jangkauan. Hingga mantranya berakhir, makhluk yang memasuki area mantra untuk pertama kalinya pada suatu giliran atau memulai gilirannya di sana harus melakukan lemparan penyelamatan Karisma. Jika penyelamatan gagal, makhluk tidak dapat mengucapkan kebohongan yang disengaja saat berada dalam radius. Anda tahu apakah setiap makhluk berhasil atau gagal dalam penyelamatannya.\nMakhluk yang terkena dampak menyadari mantra tersebut dan dengan demikian dapat menghindari menjawab pertanyaan yang biasanya ditanggapi dengan kebohongan. Makhluk seperti itu bisa saja tetap mengelak dalam menjawab selama masih dalam batas-batas kebenaran." },
    ],
    Level3: [
      { name: "Bestow Curse", components: "V, S", desc: "Anda menyentuh makhluk, dan makhluk itu harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau menjadi terkutuk selama durasi mantra. Saat Anda mengucapkan mantra ini, pilih sifat kutukan dari opsi berikut:\n- Pilih satu skor kemampuan. Saat dikutuk, target memiliki kelemahan pada pemeriksaan kemampuan dan penyelamatan yang dilakukan dengan skor kemampuan tersebut.\n- Saat dikutuk, target memiliki kelemahan saat serangan bergulir ke arahmu.\n- Saat dikutuk, target harus melakukan lemparan penyelamatan kebijaksanaan di awal setiap putarannya. Jika gagal, tindakannya sia-sia dan tidak melakukan apa-apa.\n- Saat target dikutuk, serangan dan mantramu memberikan tambahan kerusakan nekrotik sebesar 1d8 ke target.\nMantra penghapus kutukan mengakhiri efek ini. Berdasarkan pilihan GM, Anda dapat memilih efek kutukan alternatif, tetapi efek kutukan tersebut tidak boleh lebih kuat dari yang dijelaskan di atas. GM mempunyai keputusan akhir mengenai dampak kutukan tersebut.\nLevel Tinggi: Jika Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, durasinya adalah konsentrasi, hingga 10 menit. Jika Anda menggunakan slot mantra level 5 atau lebih tinggi, durasinya adalah 8 jam. Jika Anda menggunakan slot mantra level 7 atau lebih tinggi, durasinya adalah 24 jam. Jika Anda menggunakan slot mantra level 9, mantra tersebut bertahan hingga dihilangkan. Menggunakan slot mantra level 5 atau lebih tinggi memberikan durasi yang tidak memerlukan konsentrasi." },
      { name: "Clairvoyance", components: "V, S, M", desc: "Anda membuat sensor tak kasat mata dalam jangkauan di lokasi yang familier bagi Anda (tempat yang pernah Anda kunjungi atau lihat sebelumnya) atau di lokasi jelas yang asing bagi Anda (seperti di balik pintu, di sudut, atau di rerimbunan pepohonan). Sensor tetap di tempatnya selama durasi tersebut, dan tidak dapat diserang atau berinteraksi dengannya.\nSaat Anda merapal mantra, Anda memilih melihat atau mendengar. Anda dapat menggunakan indra yang dipilih melalui sensor seolah-olah Anda berada di ruangnya. Saat tindakan Anda, Anda dapat beralih antara melihat dan mendengar.\nMakhluk yang dapat melihat sensor (seperti makhluk yang mendapat manfaat dari melihat tembus pandang atau penglihatan nyata) melihat bola bercahaya dan tidak berwujud seukuran kepalan tangan Anda." },
      { name: "Dispel Magic", components: "V, S", desc: "Pilih satu makhluk, objek, atau efek magis dalam jangkauan. Mantra level 3 atau lebih rendah pada target akan berakhir. Untuk setiap mantra level 4 atau lebih tinggi pada target, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika pemeriksaan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda secara otomatis mengakhiri efek mantra pada target jika level mantra sama dengan atau kurang dari level slot mantra yang Anda gunakan." },
      { name: "Fear", components: "V, S, M", desc: "Anda memproyeksikan gambaran khayalan tentang ketakutan terburuk suatu makhluk. Setiap makhluk dalam kerucut setinggi 30 kaki harus berhasil menyelamatkan lemparan atau menjatuhkan apa pun yang dipegangnya dan menjadi ketakutan selama itu.\nSaat ketakutan dengan mantra ini, makhluk harus mengambil tindakan Dash dan menjauh dari Anda melalui rute teraman yang tersedia di setiap belokannya, kecuali tidak ada tempat untuk bergerak. Jika makhluk tersebut mengakhiri gilirannya di lokasi yang tidak terlihat oleh Anda, makhluk tersebut dapat melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan berhasil, mantra untuk makhluk itu berakhir." },
      { name: "Glyph of Warding", components: "V, S, M", desc: "Saat Anda mengucapkan mantra ini, Anda menuliskan mesin terbang yang membahayakan makhluk lain, baik di permukaan (seperti meja atau bagian lantai atau dinding) atau di dalam objek yang dapat ditutup (seperti buku, gulungan, atau peti harta karun) untuk menyembunyikan mesin terbang tersebut. Jika Anda memilih suatu permukaan, mesin terbang tersebut dapat menutupi area permukaan yang diameternya tidak lebih dari 10 kaki. Jika Anda memilih suatu benda, benda itu harus tetap berada di tempatnya; jika objek dipindahkan lebih dari 10 kaki dari tempat Anda mengucapkan mantra ini, mesin terbangnya rusak, dan mantranya berakhir tanpa terpicu.\nMesin terbang tersebut hampir tidak terlihat dan memerlukan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap penyimpanan mantra DC Anda agar dapat ditemukan.\nAnda memutuskan apa yang memicu mesin terbang saat Anda mengucapkan mantranya. Untuk mesin terbang yang tertulis di suatu permukaan, pemicu yang paling umum adalah menyentuh atau berdiri di atas mesin terbang tersebut, memindahkan objek lain yang menutupi mesin terbang tersebut, mendekati dalam jarak tertentu dari mesin terbang tersebut, atau memanipulasi objek yang di atasnya mesin terbang tersebut ditorehkan. Untuk mesin terbang yang tertulis di dalam suatu objek, pemicu paling umum termasuk membuka objek tersebut, mendekati objek dalam jarak tertentu, atau melihat atau membaca mesin terbang tersebut. Setelah mesin terbang dipicu, mantra ini berakhir.\nAnda dapat menyempurnakan pemicunya lebih lanjut sehingga mantranya hanya aktif dalam keadaan tertentu atau berdasarkan karakteristik fisik (seperti tinggi atau berat), jenis makhluk (misalnya, lingkungan dapat diatur untuk memengaruhi penyimpangan atau tenggelam), atau penyelarasan. Anda juga dapat mengatur kondisi untuk makhluk yang tidak memicu mesin terbang, misalnya makhluk yang mengucapkan kata sandi tertentu.\nSaat Anda menuliskan mesin terbang, pilih *rune eksplosif* atau *mesin terbang mantra*.\n***Rune Peledak.*** Saat dipicu, mesin terbang tersebut meletus dengan energi magis dalam bola radius 20 kaki yang berpusat pada mesin terbang tersebut. Bola itu menyebar ke berbagai sudut. Setiap makhluk di area tersebut harus melakukan lemparan penyelamatan Dexterity. Makhluk menerima 5d8 kerusakan asam, dingin, api, kilat, atau guntur pada lemparan penyelamatan yang gagal (pilihan Anda saat membuat mesin terbang), atau setengah dari kerusakan pada lemparan penyelamatan yang berhasil.\n***Spell Glyph.*** Anda dapat menyimpan mantra level 3 atau lebih rendah yang telah disiapkan di mesin terbang dengan melemparkannya sebagai bagian dari pembuatan mesin terbang. Mantra tersebut harus menargetkan satu makhluk atau suatu area. Mantra yang disimpan tidak memiliki efek langsung saat digunakan dengan cara ini. Saat mesin terbang dipicu, mantra yang disimpan akan dilemparkan. Jika mantra memiliki target, mantra tersebut menargetkan makhluk yang memicu mesin terbang tersebut. Jika mantra mempengaruhi suatu area, area tersebut berpusat pada makhluk tersebut. Jika mantra tersebut memanggil makhluk bermusuhan atau membuat objek atau jebakan berbahaya, mereka akan muncul sedekat mungkin dengan penyusup dan menyerangnya. Jika mantra membutuhkan konsentrasi, mantra itu bertahan hingga durasi penuhnya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan mesin terbang rune eksplosif meningkat sebesar 1d8 untuk setiap level slot di atas 3. Jika Anda membuat mesin terbang mantra, Anda dapat menyimpan mantra apa pun hingga tingkat yang sama dengan slot yang Anda gunakan untuk mesin terbang penangkal." },
      { name: "Hypnotic Pattern", components: "S, M", desc: "Anda membuat pola warna yang berputar-putar yang terjalin di udara di dalam kubus berukuran 30 kaki dalam jangkauan. Pola itu muncul sesaat dan menghilang. Setiap makhluk di area tersebut yang melihat pola tersebut harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, makhluk itu menjadi terpesona selama durasi tersebut. Saat terpesona oleh mantra ini, makhluk itu tidak berdaya dan memiliki kecepatan 0.\nMantra berakhir untuk makhluk yang terkena dampak jika ia mengalami kerusakan atau jika orang lain menggunakan tindakan untuk mengguncang makhluk itu dari pingsannya." },
      { name: "Major Image", components: "V, S, M", desc: "Anda membuat gambar suatu benda, makhluk, atau fenomena nyata lainnya yang ukurannya tidak lebih besar dari kubus berukuran 20 kaki. Gambar muncul di tempat yang dapat Anda lihat dalam jangkauan dan berlangsung selama durasi tersebut. Tampaknya benar-benar nyata, termasuk suara, bau, dan suhu yang sesuai dengan benda yang digambarkan. Anda tidak dapat menciptakan panas atau dingin yang cukup untuk menyebabkan kerusakan, suara yang cukup keras untuk menyebabkan kerusakan akibat petir atau membuat tuli makhluk, atau bau yang dapat membuat makhluk sakit (seperti bau troglodyte).\nSelama Anda berada dalam jangkauan ilusi, Anda dapat menggunakan tindakan Anda untuk menyebabkan gambar berpindah ke tempat lain dalam jangkauan. Saat gambar berpindah lokasi, Anda dapat mengubah tampilannya sehingga gerakannya tampak natural pada gambar. Misalnya, jika Anda membuat gambar makhluk dan memindahkannya, Anda dapat mengubah gambar tersebut sehingga tampak seperti sedang berjalan. Demikian pula, Anda dapat menyebabkan ilusi mengeluarkan suara yang berbeda pada waktu yang berbeda, bahkan membuatnya melakukan percakapan, misalnya.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika suatu makhluk mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut, dan kualitas indra lainnya menjadi samar bagi makhluk tersebut.\nLevel Tinggi: Saat Anda merapalkan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, mantra tersebut akan bertahan hingga hilang, tanpa memerlukan konsentrasi Anda." },
      { name: "Nondetection", components: "V, S, M", desc: "Selama durasi tersebut, Anda menyembunyikan target yang Anda sentuh dari sihir ramalan. Sasarannya dapat berupa makhluk yang bersedia atau suatu tempat atau benda yang berukuran tidak lebih dari 10 kaki dalam dimensi apa pun. Targetnya tidak dapat ditargetkan oleh sihir ramalan apa pun atau dirasakan melalui sensor penglihatan magis." },
      { name: "Plant Growth", components: "V, S", desc: "Mantra ini menyalurkan vitalitas ke tanaman di area tertentu. Ada dua kemungkinan penggunaan mantra ini, memberikan manfaat langsung atau jangka panjang.\nJika Anda mengucapkan mantra ini menggunakan 1 tindakan, pilih titik dalam jangkauan. Semua tanaman normal dalam radius 100 kaki yang berpusat pada titik tersebut menjadi lebat dan ditumbuhi tanaman. Makhluk yang bergerak melalui area tersebut harus menghabiskan 4 kaki gerakan untuk setiap 1 kaki yang digerakkannya.\nAnda dapat mengecualikan satu atau lebih area dengan ukuran berapa pun di dalam area mantra agar tidak terpengaruh.\nJika Anda mengucapkan mantra ini selama 8 jam, Anda memperkaya tanah. Semua tanaman dalam radius setengah mil yang berpusat pada suatu titik dalam jangkauan akan diperkaya selama 1 tahun. Tanaman menghasilkan dua kali jumlah makanan normal saat dipanen." },
      { name: "Sending", components: "V, S, M", desc: "Anda mengirim pesan singkat yang terdiri dari dua puluh lima kata atau kurang kepada makhluk yang Anda kenal. Makhluk itu mendengar pesan dalam pikirannya, mengenali Anda sebagai pengirimnya jika ia mengenal Anda, dan dapat segera menjawab dengan cara yang sama. Mantra ini memungkinkan makhluk dengan skor Intelegensi minimal 1 untuk memahami maksud pesan Anda.\nAnda dapat mengirim pesan melintasi jarak berapa pun dan bahkan ke alam eksistensi lain, namun jika target berada di alam yang berbeda dari Anda, ada kemungkinan 5 persen pesan tersebut tidak sampai." },
      { name: "Speak with Dead", components: "V, S, M", desc: "Anda memberikan kemiripan kehidupan dan kecerdasan pada mayat pilihan Anda dalam jangkauan, memungkinkannya menjawab pertanyaan yang Anda ajukan. Mayat itu pasti masih memiliki mulut dan tidak boleh menjadi undead. Mantra tersebut gagal jika mayat menjadi target mantra ini dalam 10 hari terakhir.\nHingga mantranya berakhir, Anda dapat menanyakan hingga lima pertanyaan kepada mayat tersebut. Mayat hanya mengetahui apa yang diketahuinya dalam kehidupan, termasuk bahasa yang diketahuinya. Jawaban biasanya singkat, samar, atau berulang-ulang, dan jenazah tidak berkewajiban untuk memberikan jawaban yang jujur ​​jika Anda memusuhinya atau jenazah mengakui Anda sebagai musuh. Mantra ini tidak mengembalikan jiwa makhluk ke tubuhnya, hanya roh yang menjiwainya. Dengan demikian, jenazah tidak dapat mempelajari informasi baru, tidak dapat memahami apa pun yang telah terjadi sejak ia meninggal, dan tidak dapat berspekulasi tentang kejadian di masa depan." },
      { name: "Speak with Plants", components: "V, S", desc: "Anda mengilhami tanaman dalam jarak 30 kaki dari Anda dengan perasaan dan animasi terbatas, memberi mereka kemampuan untuk berkomunikasi dengan Anda dan mengikuti perintah sederhana Anda. Anda dapat menanyakan tanaman tentang kejadian di area mantra dalam satu hari terakhir, mendapatkan informasi tentang makhluk yang telah lewat, cuaca, dan keadaan lainnya.\nAnda juga dapat mengubah medan sulit yang disebabkan oleh pertumbuhan tanaman (seperti semak belukar dan semak belukar) menjadi medan biasa yang bertahan lama. Atau Anda dapat mengubah medan biasa yang terdapat tanaman menjadi medan sulit yang bertahan lama, menyebabkan tanaman merambat dan dahan menghalangi pengejar, misalnya.\nPabrik mungkin dapat melakukan tugas lain atas nama Anda, sesuai kebijakan GM. Mantra tersebut tidak memungkinkan tanaman untuk mencabut dirinya sendiri dan bergerak, tetapi mereka dapat dengan bebas memindahkan cabang, sulur, dan batang.\nJika ada makhluk tumbuhan di area tersebut, Anda dapat berkomunikasi dengannya seolah-olah Anda memiliki bahasa yang sama, namun Anda tidak memperoleh kemampuan magis untuk memengaruhinya.\nMantra ini dapat menyebabkan tanaman yang diciptakan oleh mantra entangle melepaskan makhluk yang tertahan." },
      { name: "Stinking Cloud", components: "V, S, M", desc: "Anda membuat bola gas berwarna kuning dengan radius 20 kaki yang berpusat pada suatu titik dalam jangkauan. Awan menyebar ke segala penjuru, dan wilayahnya sangat tertutup. Awan tetap berada di udara selama itu.\nSetiap makhluk yang sepenuhnya berada di dalam awan pada awal gilirannya harus melakukan penyelamatan konstitusi terhadap racun. Jika penyelamatan gagal, makhluk itu mengeluarkan aksinya yang berubah menjadi muntah-muntah dan terhuyung-huyung. Makhluk yang tidak perlu bernapas atau kebal terhadap racun otomatis berhasil dalam penyelamatan ini.\nAngin sedang (setidaknya 10 mil per jam) menyebarkan awan setelah 4 putaran. Angin kencang (setidaknya 20 mil per jam) menyebarkannya setelah 1 putaran." },
      { name: "Tiny Hut", components: "V, S, M", desc: "Kubah gaya tak bergerak dengan radius 10 kaki muncul di sekitar dan di atas Anda dan tetap diam selama jangka waktu tersebut. Mantranya berakhir jika Anda meninggalkan areanya.\nSembilan makhluk berukuran sedang atau lebih kecil dapat masuk ke dalam kubah bersama Anda. Mantra gagal jika areanya mencakup makhluk yang lebih besar atau lebih dari sembilan makhluk. Makhluk dan objek di dalam kubah saat Anda mengucapkan mantra ini dapat bergerak melewatinya dengan bebas. Semua makhluk dan benda lain dilarang melewatinya. Mantra dan efek magis lainnya tidak dapat menembus kubah atau dilemparkan ke dalamnya. Suasana di dalam ruangan nyaman dan kering, tidak peduli cuaca di luar.\nHingga mantranya berakhir, Anda dapat memerintahkan interior menjadi remang-remang atau gelap. Kubahnya buram dari luar, warna apa pun yang Anda pilih, tetapi transparan dari dalam." },
      { name: "Tongues", components: "V, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk memahami bahasa lisan apa pun yang didengarnya. Terlebih lagi, ketika target berbicara, makhluk apa pun yang mengetahui setidaknya satu bahasa dan dapat mendengar target akan memahami apa yang dikatakannya." },
    ],
    Level4: [
      { name: "Compulsion", components: "V, S", desc: "Makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan dan yang dapat mendengar, Anda harus melakukan lemparan penyelamatan yang bijaksana. Target secara otomatis berhasil dalam lemparan penyelamatan ini jika tidak dapat dipesona. Jika penyelamatan gagal, target akan terpengaruh oleh mantra ini. Hingga mantranya berakhir, Anda dapat menggunakan aksi bonus di setiap giliran Anda untuk menentukan arah horizontal bagi Anda. Setiap target yang terkena dampak harus menggunakan gerakannya sebanyak mungkin untuk bergerak ke arah tersebut pada giliran berikutnya. Ia dapat mengambil tindakan apa pun sebelum bergerak. Setelah bergerak dengan cara ini, ia dapat membuat Wisdom lain menyimpan untuk mencoba mengakhiri efeknya.\nTarget tidak dipaksa untuk berpindah ke tempat yang jelas-jelas mematikan, seperti kebakaran atau lubang, namun akan memicu peluang serangan untuk bergerak ke arah yang ditentukan." },
      { name: "Confusion", components: "V, S, M", desc: "Mantra ini menyerang dan memutarbalikkan pikiran makhluk, menimbulkan delusi dan memicu tindakan yang tidak terkendali. Setiap makhluk dalam bola berradius 10 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan harus berhasil melakukan lemparan penyelamatan Kebijaksanaan saat Anda mengucapkan mantra ini atau terpengaruh olehnya.\nTarget yang terpengaruh tidak dapat bereaksi dan harus melempar d10 di awal setiap giliran untuk menentukan perilakunya pada giliran tersebut.\n| d10 | Perilaku |\n|---|---|\n| 1 | Makhluk itu menggunakan seluruh gerakannya untuk bergerak ke arah yang acak. Untuk menentukan arah, putar d8 dan tetapkan arah pada setiap permukaan dadu. Makhluk itu tidak mengambil tindakan pada giliran ini. |\n| 2-6 | Makhluk itu tidak bergerak atau mengambil tindakan pada giliran ini. |\n| 7-8 | Makhluk itu menggunakan aksinya untuk melakukan serangan jarak dekat terhadap makhluk yang ditentukan secara acak dalam jangkauannya. Jika tidak ada makhluk dalam jangkauannya, makhluk itu tidak akan melakukan apa pun pada giliran ini. |\n| 9-10 | Makhluk itu dapat bertindak dan bergerak dengan normal. |\nDi akhir setiap giliran, target yang terkena dampak dapat melakukan lemparan penyelamatan Wisdom. Jika berhasil, efek ini berakhir untuk target tersebut.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, radius bola bertambah 5 kaki untuk setiap slot level di atas 4." },
      { name: "Dimension Door", components: "V", desc: "Anda berteleportasi dari lokasi Anda saat ini ke tempat lain dalam jangkauan. Anda tiba di tempat yang diinginkan. Ini bisa berupa tempat yang bisa Anda lihat, yang bisa Anda visualisasikan, atau yang bisa Anda gambarkan dengan menyatakan jarak dan arah, seperti \"200 kaki lurus ke bawah\" atau \"ke atas ke arah barat laut dengan sudut 45 derajat, 300 kaki\".\nAnda boleh membawa barang selama beratnya tidak melebihi apa yang dapat Anda bawa. Anda juga dapat membawa satu makhluk berukuran Anda atau lebih kecil yang membawa perlengkapan sesuai daya dukungnya. Makhluk itu harus berada dalam jarak 5 kaki dari Anda saat Anda mengucapkan mantra ini.\nJika Anda akan tiba di tempat yang sudah ditempati oleh suatu benda atau makhluk, Anda dan makhluk apa pun yang bepergian bersama Anda masing-masing akan menerima kerusakan kekuatan 4d6, dan mantra tersebut gagal untuk memindahkan Anda." },
      { name: "Freedom of Movement", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia. Selama durasi tersebut, pergerakan target tidak terpengaruh oleh medan yang sulit, dan mantra serta efek magis lainnya tidak dapat mengurangi kecepatan target atau menyebabkan target menjadi lumpuh atau tertahan.\nTarget juga dapat menggunakan gerakan sejauh 5 kaki untuk secara otomatis melarikan diri dari pengekangan non-magis, seperti borgol atau makhluk yang digenggamnya. Terakhir, berada di bawah air tidak memberikan penalti pada pergerakan atau serangan target." },
      { name: "Greater Invisibility", components: "V, S", desc: "Anda atau makhluk yang Anda sentuh menjadi tidak terlihat sampai mantranya berakhir. Apapun yang dikenakan atau dibawa oleh target tidak akan terlihat selama berada pada orang yang menjadi target." },
      { name: "Hallucinatory Terrain", components: "V, S, M", desc: "Anda membuat medan alami dalam kubus berukuran 150 kaki dalam jangkauan tampilan, suara, dan aroma seperti medan alami lainnya. Dengan demikian, lapangan terbuka atau jalan dapat dibuat menyerupai rawa, bukit, jurang, atau medan lain yang sulit atau tidak dapat dilalui. Sebuah kolam dapat dibuat tampak seperti padang rumput, jurang seperti lereng yang landai, atau selokan yang dipenuhi bebatuan seperti jalan yang lebar dan mulus. Struktur, peralatan, dan makhluk yang diproduksi di dalam area tersebut tidak berubah tampilannya.\nKarakteristik sentuhan medan tidak berubah, sehingga makhluk yang memasuki area tersebut kemungkinan besar dapat melihat melalui ilusi. Jika perbedaannya tidak terlihat jelas jika disentuh, makhluk yang memeriksa ilusi dengan cermat dapat mencoba melakukan pemeriksaan Intelijen (Investigasi) terhadap mantra Anda, simpan DC untuk tidak mempercayainya. Makhluk yang memahami ilusi apa adanya, melihatnya sebagai gambaran samar yang ditumpangkan di medan." },
      { name: "Locate Creature", components: "V, S, M", desc: "Jelaskan atau beri nama makhluk yang Anda kenal. Anda merasakan arah ke lokasi makhluk itu, selama makhluk itu berada dalam jarak 1.000 kaki dari Anda. Jika makhluk itu bergerak, Anda mengetahui arah pergerakannya.\nMantra ini dapat menemukan lokasi makhluk tertentu yang Anda kenal, atau makhluk terdekat dari jenis tertentu (seperti manusia atau unicorn), selama Anda pernah melihat makhluk tersebut dari dekat--dalam jarak 30 kaki--setidaknya sekali. Jika makhluk yang Anda gambarkan atau beri nama berada dalam bentuk yang berbeda, seperti berada di bawah pengaruh mantra polimorf, mantra ini tidak akan menemukan lokasi makhluk tersebut.\nMantra ini tidak dapat menemukan lokasi makhluk jika air yang mengalir selebar 10 kaki menghalangi jalur langsung antara Anda dan makhluk tersebut." },
      { name: "Polymorph", components: "V, S, M", desc: "Mantra ini mengubah makhluk yang dapat Anda lihat dalam jangkauan menjadi bentuk baru. Makhluk yang tidak mau harus melakukan lemparan penyelamatan yang bijaksana untuk menghindari dampaknya. Seorang pengubah bentuk secara otomatis berhasil dalam lemparan penyelamatan ini.\nTransformasi berlangsung selama durasi tersebut, atau hingga target turun menjadi 0 poin hit atau mati. Bentuk baru dapat berupa monster apa pun yang peringkat tantangannya sama dengan atau lebih kecil dari target (atau level target, jika tidak memiliki peringkat tantangan). Statistik permainan target, termasuk skor kemampuan mental, digantikan oleh statistik binatang yang dipilih. Ia mempertahankan keselarasan dan kepribadiannya.\nTargetnya mengasumsikan titik sasaran dari bentuk barunya. Ketika ia kembali ke bentuk normalnya, makhluk itu kembali ke jumlah titik serangan yang dimilikinya sebelum ia bertransformasi. Jika poin serangannya kembali karena poin hitnya turun menjadi 0, kerusakan berlebih akan kembali ke bentuk normalnya. Selama kerusakan berlebih tidak mengurangi bentuk normal makhluk itu menjadi 0 poin serangan, ia tidak akan pingsan.\nTindakan yang dapat dilakukan makhluk ini terbatas karena sifat dari bentuk barunya, dan ia tidak dapat berbicara, merapal mantra, atau melakukan tindakan lain apa pun yang memerlukan tangan atau ucapan.\nPerlengkapan target menyatu ke dalam bentuk baru. Makhluk itu tidak dapat mengaktifkan, menggunakan, menggunakan, atau memanfaatkan peralatan apa pun." },
    ],
    Level5: [
      { name: "Animate Objects", components: "V, S", desc: "Objek menjadi hidup sesuai perintah Anda. Pilih hingga sepuluh benda non-magis dalam jangkauan yang tidak dipakai atau dibawa. Target sedang dihitung sebagai dua objek, Target besar dihitung sebagai empat objek, Target besar dihitung sebagai delapan objek. Anda tidak dapat menganimasikan objek apa pun yang lebih besar dari Huge. Setiap target bernyawa dan menjadi makhluk di bawah kendali Anda hingga mantra berakhir atau hingga poin hit berkurang menjadi 0.\nSebagai tindakan bonus, Anda dapat secara mental memerintahkan makhluk apa pun yang Anda buat dengan mantra ini jika makhluk itu berada dalam jarak 500 kaki dari Anda (jika Anda mengendalikan beberapa makhluk, Anda dapat memerintahkan salah satu atau semuanya secara bersamaan, memberikan perintah yang sama kepada masing-masing makhluk). Anda memutuskan tindakan apa yang akan diambil makhluk itu dan ke mana ia akan bergerak pada giliran berikutnya, atau Anda dapat mengeluarkan perintah umum, seperti menjaga ruangan atau koridor tertentu. Jika Anda tidak mengeluarkan perintah, makhluk itu hanya akan mempertahankan diri dari makhluk musuh. Setelah diberi perintah, makhluk tersebut terus mengikutinya hingga tugasnya selesai.\n##### Statistik Objek Animasi\n| Ukuran | HP | AC | Serangan | Str | Dex |\n|---|---|---|---|---|---|\n| Kecil | 20 | 18 | +8 untuk menyerang, 1d4 + 4 kerusakan | 4 | 18 |\n| Kecil | 25 | 16 | +6 untuk menyerang, 1d8 + 2 kerusakan | 6 | 14 |\n| Sedang | 40 | 13 | +5 untuk menyerang, 2d6 + 1 kerusakan | 10 | 12 |\n| Besar | 50 | 10 | +6 untuk menyerang, 2d10 + 2 kerusakan | 14 | 10 |\n| Besar | 80 | 10 | +8 untuk menyerang, 2d12 + 4 kerusakan | 18 | 6 |\nObjek animasi adalah konstruksi dengan AC, titik pukulan, serangan, Kekuatan, dan Ketangkasan yang ditentukan oleh ukurannya. Konstitusinya 10 dan Kecerdasan dan Kebijaksanaannya 3, dan Karismanya 1. Kecepatannya 30 kaki; jika benda tersebut tidak memiliki kaki atau pelengkap lain yang dapat digunakan untuk bergerak, ia malah memiliki kecepatan terbang 30 kaki dan dapat melayang. Jika benda tersebut terpasang erat pada suatu permukaan atau benda yang lebih besar, seperti rantai yang dibaut ke dinding, kecepatannya adalah 0. Benda tersebut mempunyai penglihatan buta dengan radius 30 kaki dan buta melebihi jarak tersebut. Ketika objek yang dianimasikan turun ke 0 titik hit, ia kembali ke bentuk objek aslinya, dan sisa kerusakan akan dibawa ke bentuk objek aslinya.\nJika Anda memerintahkan suatu objek untuk menyerang, ia dapat melakukan satu serangan jarak dekat terhadap makhluk dalam jarak 5 kaki darinya. Itu membuat serangan bantingan dengan bonus serangan dan kerusakan pukulan yang ditentukan oleh ukurannya. GM mungkin memutuskan bahwa objek tertentu menimbulkan kerusakan tebasan atau tusukan berdasarkan bentuknya.\nJika Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, Anda dapat menganimasikan dua objek tambahan untuk setiap slot level di atas 5." },
      { name: "Awaken", components: "V, S, M", desc: "Setelah menghabiskan waktu casting menelusuri jalur magis di dalam batu permata yang berharga, Anda menyentuh binatang atau tumbuhan yang besar atau lebih kecil. Target tidak boleh memiliki skor Intelijen atau Intelijen 3 atau kurang. Target memperoleh Kecerdasan 10. Target juga memperoleh kemampuan berbicara satu bahasa yang Anda tahu. Jika targetnya adalah tumbuhan, ia memperoleh kemampuan untuk menggerakkan anggota badan, akar, tanaman merambat, tanaman merambat, dan sebagainya, dan ia memperoleh indra yang mirip dengan manusia. GM Anda memilih statistik yang sesuai untuk tanaman yang terbangun, seperti statistik untuk semak yang terbangun atau pohon yang terbangun.\nBinatang atau tumbuhan yang terbangun akan terpesona oleh Anda selama 30 hari atau sampai Anda atau teman Anda melakukan sesuatu yang berbahaya terhadapnya. Ketika kondisi terpesona berakhir, makhluk yang terbangun memilih apakah akan tetap bersahabat dengan Anda, berdasarkan cara Anda memperlakukannya saat ia terpesona." },
      { name: "Dominate Person", components: "V, S", desc: "Anda mencoba memperdaya humanoid yang dapat Anda lihat dalam jangkauan. Ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Jika Anda atau makhluk yang bersahabat dengan Anda melawannya, ia memiliki keuntungan dalam penyelamatan.\nMeskipun targetnya terpesona, Anda memiliki hubungan telepati dengannya selama Anda berdua berada di alam eksistensi yang sama. Anda dapat menggunakan tautan telepati ini untuk mengeluarkan perintah kepada makhluk itu saat Anda sadar (tidak perlu tindakan apa pun), yang akan dipatuhinya sebaik mungkin. Anda dapat menentukan tindakan yang sederhana dan umum, seperti \"Serang makhluk itu\", \"Lari ke sana\", atau \"Ambil objek itu\". Jika makhluk tersebut menyelesaikan perintahnya dan tidak menerima arahan lebih lanjut dari Anda, ia akan mempertahankan dan mempertahankan dirinya dengan kemampuan terbaiknya.\nAnda dapat menggunakan tindakan Anda untuk mengambil kendali total dan tepat terhadap target. Hingga akhir giliran Anda berikutnya, makhluk itu hanya mengambil tindakan yang Anda pilih, dan tidak melakukan apa pun yang tidak Anda izinkan. Selama waktu ini Anda juga dapat menyebabkan makhluk tersebut menggunakan reaksi, namun hal ini mengharuskan Anda menggunakan reaksi Anda sendiri juga.\nSetiap kali target menerima kerusakan, ia membuat lemparan penyelamatan kebijaksanaan baru terhadap mantra tersebut. Jika lemparan penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 6, durasinya adalah konsentrasi, hingga 10 menit. Jika menggunakan slot spell level 7, durasinya adalah konsentrasi, maksimal 1 jam. Saat Anda menggunakan slot mantra level 8 atau lebih tinggi, durasinya adalah konsentrasi, hingga 8 jam." },
      { name: "Dream", components: "V, S, M", desc: "Mantra ini membentuk mimpi makhluk. Pilih makhluk yang Anda kenal sebagai target mantra ini. Targetnya harus berada pada alam eksistensi yang sama dengan Anda. Makhluk yang tidak tidur, seperti elf, tidak dapat dihubungi dengan mantra ini. Anda, atau makhluk yang ingin Anda sentuh, memasuki kondisi trance, bertindak sebagai pembawa pesan.\nSaat berada dalam kondisi trance, pembawa pesan sadar akan sekelilingnya, namun tidak dapat mengambil tindakan atau bergerak.\nJika target tertidur, pembawa pesan muncul dalam mimpi target dan dapat berkomunikasi dengan target selama target tetap tertidur, selama durasi mantra. Pembawa pesan juga dapat membentuk lingkungan mimpi, menciptakan pemandangan alam, objek, dan gambar lainnya. Pembawa pesan dapat keluar dari kondisi trance kapan saja, mengakhiri efek mantranya lebih awal. Target mengingat mimpinya dengan sempurna saat bangun tidur. Jika target terjaga saat Anda merapal mantra, pembawa pesan mengetahuinya, dan dapat mengakhiri trance (dan mantranya) atau menunggu target tertidur, dan pada saat itulah pembawa pesan muncul dalam mimpi target.\nAnda dapat membuat pengirim pesan tampak mengerikan dan menakutkan bagi targetnya. Jika Anda melakukannya, pembawa pesan dapat menyampaikan pesan yang tidak lebih dari sepuluh kata dan kemudian target harus melakukan penyelamatan yang bijaksana. Jika penyelamatan gagal, gema monstrositas fantastik menimbulkan mimpi buruk yang berlangsung selama durasi tidur target dan mencegah target mendapatkan manfaat apa pun dari istirahat tersebut. Selain itu, ketika target terbangun, ia akan menerima 3d6 psychic damage.\nJika Anda memiliki bagian tubuh, seikat rambut, potongan kuku, atau bagian serupa dari tubuh target, target melakukan penyelamatan dengan merugikan." },
      { name: "Geas", components: "V", desc: "Anda memberikan perintah magis pada makhluk yang dapat Anda lihat dalam jangkauan, memaksanya untuk melakukan suatu layanan atau menahan diri dari tindakan atau aktivitas tertentu sesuai keputusan Anda. Jika makhluk itu dapat memahami Anda, ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Meskipun makhluk itu terpesona oleh Anda, dibutuhkan 5d10 kerusakan psikis setiap kali ia bertindak berlawanan dengan instruksi Anda, tetapi tidak lebih dari sekali setiap hari. Makhluk yang tidak dapat memahami Anda tidak terpengaruh oleh mantra tersebut.\nAnda dapat mengeluarkan perintah apa pun yang Anda pilih, selain aktivitas yang akan mengakibatkan kematian. Jika Anda mengeluarkan perintah bunuh diri, mantranya akan berakhir.\nAnda dapat mengakhiri mantra lebih awal dengan menggunakan tindakan untuk mengabaikannya. Mantra penghilang kutukan, pemulihan lebih besar, atau harapan juga mengakhirinya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau 8, durasinya adalah 1 tahun. Saat Anda merapal mantra ini menggunakan slot mantra level 9, mantra tersebut akan bertahan hingga diakhiri oleh salah satu mantra yang disebutkan di atas." },
      { name: "Greater Restoration", components: "V, S, M", desc: "Anda mengilhami makhluk yang Anda sentuh dengan energi positif untuk menghilangkan efek yang melemahkan. Anda dapat mengurangi tingkat kelelahan target sebanyak satu, atau mengakhiri salah satu efek berikut pada target:\n- Satu efek yang membuat target terpesona atau membatu\n- Satu kutukan, termasuk attunement target pada item sihir terkutuk\n- Pengurangan apa pun pada salah satu skor kemampuan target\n- Satu efek mengurangi maksimum hit point target" },
      { name: "Hold Monster", components: "V, S, M", desc: "Pilih makhluk yang dapat Anda lihat dan jangkau. Target harus melakukan lemparan penyelamatan Kebijaksanaan atau menjadi lumpuh selama durasi mantra. Mantra ini tidak berpengaruh terhadap undead. Di akhir setiap putaran, target dapat melakukan penyelamatan baru atas Kebijaksanaan. Jika berhasil, mantranya berakhir untuk makhluk itu.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan lokasi level 6 atau lebih tinggi, Anda dapat menargetkan makhluk tambahan untuk setiap level lokasi di luar lokasi kelima. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Legend Lore", components: "V, S, M", desc: "Sebutkan atau jelaskan seseorang, tempat, atau benda. Mantra ini mengingatkan Anda ringkasan singkat tentang pengetahuan penting tentang benda yang Anda beri nama. Pengetahuan tersebut bisa berupa cerita terkini, cerita yang terlupakan, atau bahkan pengetahuan rahasia yang belum pernah diketahui secara luas. Jika benda yang Anda beri nama tidak memiliki arti penting dalam legenda, Anda tidak memperoleh informasi. Semakin banyak informasi yang Anda miliki tentang suatu hal, semakin tepat dan rinci informasi yang Anda terima.\nInformasi yang Anda pelajari akurat tetapi mungkin disajikan dalam bahasa kiasan. Contohnya, jika Anda memiliki kapak ajaib misterius di tangan, mantranya mungkin akan menghasilkan informasi berikut: \"Celakalah pelaku kejahatan yang tangannya menyentuh kapak, karena gagang kapak pun dapat mengiris tangan si jahat. Hanya Anak Batu sejati, kekasih dan kekasih Moradin, yang dapat membangkitkan kekuatan kapak yang sebenarnya, dan hanya dengan kata suci *Rudnogg* di bibir.\"" },
      { name: "Mass Cure Wounds", components: "V, S", desc: "Gelombang energi penyembuhan mengalir dari titik pilihan Anda dalam jangkauan. Pilih hingga enam makhluk dalam bola radius 30 kaki yang berpusat pada titik tersebut. Setiap target mendapatkan kembali poin hit sebesar 3d8 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, penyembuhan meningkat sebesar 1d8 untuk setiap slot level di atas 5." },
      { name: "Mislead", components: "S", desc: "Anda menjadi tidak terlihat pada saat yang sama ketika kembaran ilusi Anda muncul di tempat Anda berdiri. Penggandaan berlangsung selama durasi tersebut, tetapi tembus pandang berakhir jika Anda menyerang atau membaca mantra.\nAnda dapat menggunakan tindakan Anda untuk menggerakkan ilusi Anda dua kali lipat kecepatan Anda dan membuatnya memberi isyarat, berbicara, dan berperilaku dengan cara apa pun yang Anda pilih.\nAnda dapat melihat melalui matanya dan mendengar melalui telinganya seolah-olah Anda berada di tempatnya. Pada setiap giliran Anda sebagai tindakan bonus, Anda dapat beralih dari menggunakan indra Anda ke indra Anda sendiri, atau kembali lagi. Saat Anda menggunakan indranya, Anda menjadi buta dan tuli terhadap lingkungan sekitar Anda." },
      { name: "Modify Memory", components: "V, S", desc: "Anda mencoba membentuk kembali ingatan makhluk lain. Satu makhluk yang dapat Anda lihat harus melakukan lemparan penyelamat yang bijaksana. Jika Anda melawan makhluk itu, ia memiliki keuntungan dalam lemparan penyelamatan. Jika penyimpanan gagal, target akan terpesona oleh Anda selama durasi tersebut. Target yang terpesona tidak berdaya dan tidak menyadari lingkungan sekitarnya, meskipun ia masih dapat mendengar Anda. Jika terkena kerusakan atau menjadi sasaran mantra lain, mantra ini berakhir, dan tidak ada ingatan target yang diubah.\nSelama pesona ini bertahan, Anda dapat memengaruhi ingatan target tentang peristiwa yang dialaminya dalam 24 jam terakhir dan berlangsung tidak lebih dari 10 menit. Anda dapat secara permanen menghilangkan seluruh memori peristiwa tersebut, memungkinkan target mengingat peristiwa tersebut dengan kejelasan sempurna dan detail yang tepat, mengubah memorinya atas detail peristiwa tersebut, atau membuat memori mengenai beberapa peristiwa lainnya.\nAnda harus berbicara dengan target untuk menjelaskan bagaimana ingatannya terpengaruh, dan target harus dapat memahami bahasa Anda agar ingatan yang dimodifikasi dapat berakar. Pikirannya mengisi setiap celah dalam detail deskripsi Anda. Jika mantranya berakhir sebelum Anda selesai mendeskripsikan ingatan yang dimodifikasi, ingatan makhluk itu tidak berubah. Jika tidak, ingatan yang dimodifikasi akan tetap ada saat mantranya berakhir.\nMemori yang dimodifikasi tidak serta merta memengaruhi perilaku makhluk, terutama jika memori tersebut bertentangan dengan kecenderungan, keselarasan, atau kepercayaan alami makhluk tersebut. Memori modifikasi yang tidak logis, seperti menanamkan memori tentang betapa senangnya makhluk itu menyiram dirinya sendiri dengan asam, diabaikan, mungkin sebagai mimpi buruk. GM mungkin menganggap memori yang dimodifikasi terlalu tidak masuk akal untuk mempengaruhi makhluk secara signifikan.\nMantra penghilang kutukan atau mantra pemulihan yang lebih besar yang diberikan pada target akan memulihkan ingatan sebenarnya makhluk itu.\nLevel Tinggi: Jika Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, Anda dapat mengubah ingatan target tentang peristiwa yang terjadi hingga 7 hari yang lalu (level 6), 30 hari yang lalu (level 7), 1 tahun yang lalu (level 8), atau kapan pun di masa lalu makhluk itu (level 9)." },
      { name: "Planar Binding", components: "V, S, M", desc: "Dengan mantra ini, Anda mencoba untuk mengikat benda langit, elemen, makhluk, atau iblis ke dalam layanan Anda. Makhluk itu harus berada dalam jangkauan selama seluruh perapalan mantra. (Biasanya, makhluk tersebut pertama kali dipanggil ke tengah lingkaran sihir terbalik agar tetap terjebak saat mantra ini digunakan.) Setelah menyelesaikan casting, target harus melakukan lemparan penyelamatan karisma. Jika penyimpanan gagal, itu pasti akan membantu Anda selama durasi tersebut. Jika makhluk itu dipanggil atau diciptakan oleh mantra lain, durasi mantra tersebut diperpanjang agar sesuai dengan durasi mantra ini.\nMakhluk yang terikat harus mengikuti instruksi Anda dengan kemampuan terbaiknya. Anda mungkin memerintahkan makhluk tersebut untuk menemani Anda berpetualang, menjaga lokasi, atau menyampaikan pesan. Makhluk itu mematuhi instruksi Anda, tetapi jika makhluk itu memusuhi Anda, ia berusaha memutarbalikkan kata-kata Anda untuk mencapai tujuannya sendiri. Jika makhluk tersebut melaksanakan instruksi Anda sepenuhnya sebelum mantranya berakhir, ia akan mendatangi Anda untuk melaporkan fakta ini jika Anda berada di alam keberadaan yang sama. Jika Anda berada di alam eksistensi lain, ia akan kembali ke tempat Anda mengikatnya dan tetap di sana hingga mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra dengan level yang lebih tinggi, durasinya meningkat menjadi 10 hari dengan slot level 6, menjadi 30 hari dengan slot level 7, menjadi 180 hari dengan slot level 8, dan menjadi satu tahun dan satu hari dengan slot mantra level 9." },
      { name: "Raise Dead", components: "V, S, M", desc: "Anda menghidupkan kembali makhluk mati yang Anda sentuh, asalkan sudah mati tidak lebih dari 10 hari. Jika jiwa makhluk tersebut bersedia dan bebas untuk bergabung kembali dengan tubuhnya, makhluk tersebut akan hidup kembali dengan 1 poin pukulan.\nMantra ini juga menetralkan segala racun dan menyembuhkan penyakit non-magis yang menyerang makhluk tersebut pada saat ia mati. Namun mantra ini tidak menghilangkan penyakit magis, kutukan, atau efek serupa; jika ini tidak dihilangkan terlebih dahulu sebelum merapal mantra, itu akan berlaku saat makhluk itu hidup kembali. Mantra itu tidak bisa menghidupkan kembali makhluk undead.\nMantra ini menutup semua luka mematikan, namun tidak memulihkan bagian tubuh yang hilang. Jika makhluk itu kekurangan bagian tubuh atau organ yang tidak terpisahkan untuk kelangsungan hidupnya--kepalanya, misalnya--mantranya otomatis gagal.\nBangkit dari kematian adalah sebuah cobaan berat. Target menerima penalti -4 untuk semua serangan, lemparan penyelamatan, dan pemeriksaan kemampuan. Setiap target menyelesaikan istirahat panjang, penaltinya berkurang 1 hingga hilang." },
      { name: "Scrying", components: "V, S, M", desc: "Anda dapat melihat dan mendengar makhluk tertentu yang Anda pilih yang berada pada alam eksistensi yang sama dengan Anda. Target harus melakukan lemparan penyelamatan yang bijaksana, yang dimodifikasi oleh seberapa baik Anda mengenal target dan jenis hubungan fisik yang Anda miliki dengannya. Jika target mengetahui Anda merapalkan mantra ini, target dapat gagal melakukan penyelamatan secara sukarela jika ingin diamati.\n| Pengetahuan | Simpan Pengubah |\n|---|---|\n| Bekas (Anda pernah mendengar tentang targetnya) | +5 |\n| Langsung (Anda sudah memenuhi target) | +0 |\n| Familiar (Anda tahu targetnya dengan baik) | -5 |\n\n| Koneksi | Simpan Pengubah |\n|---|---|\n| Kemiripan atau gambar | -2 |\n| Kepemilikan atau pakaian | -4 |\n| Bagian badan, seikat rambut, secuil kuku, atau sejenisnya | -10 |\nJika penyelamatan berhasil, target tidak terpengaruh, dan Anda tidak dapat menggunakan mantra ini lagi selama 24 jam.\nJika penyelamatan gagal, mantra tersebut menciptakan sensor tak terlihat dalam jarak 10 kaki dari target. Anda dapat melihat dan mendengar melalui sensor seolah-olah Anda berada di sana. Sensor bergerak mengikuti target, tetap berada dalam jarak 10 kaki selama durasi tersebut. Makhluk yang dapat melihat objek tak kasat mata melihat sensornya sebagai bola bercahaya seukuran kepalan tangan Anda.\nDaripada mengincar makhluk, kamu bisa memilih lokasi yang pernah kamu lihat sebelumnya sebagai target mantra ini. Ketika Anda melakukannya, sensor muncul di lokasi tersebut dan tidak bergerak." },
      { name: "Seeming", components: "V, S", desc: "Mantra ini memungkinkan Anda mengubah penampilan sejumlah makhluk yang dapat Anda lihat dalam jangkauan. Anda memberikan setiap target yang Anda pilih penampilan baru dan ilusi. Target yang tidak bersedia dapat melakukan lemparan penyelamatan karisma, dan jika berhasil, ia tidak terpengaruh oleh mantra ini.\nMantra ini menyamarkan penampilan fisik serta pakaian, baju besi, senjata, dan perlengkapan. Anda dapat membuat setiap makhluk tampak 1 kaki lebih pendek atau lebih tinggi dan tampak kurus, gemuk, atau di antara keduanya. Anda tidak dapat mengubah tipe tubuh target, jadi Anda harus memilih bentuk yang memiliki susunan dasar anggota tubuh yang sama. Jika tidak, sejauh mana ilusi itu terserah Anda. Mantra tersebut bertahan selama durasi tersebut, kecuali Anda menggunakan tindakan Anda untuk menghilangkannya lebih cepat.\nPerubahan yang dilakukan oleh mantra ini gagal memenuhi pemeriksaan fisik. Misalnya, jika Anda menggunakan mantra ini untuk menambahkan topi ke pakaian makhluk, benda akan melewati topi tersebut, dan siapa pun yang menyentuhnya tidak akan merasakan apa pun atau akan merasakan kepala dan rambut makhluk tersebut. Jika Anda menggunakan mantra ini untuk terlihat lebih kurus dari Anda, tangan seseorang yang mengulurkan tangan untuk menyentuh Anda akan menabrak Anda saat tangan itu tampak masih di udara.\nMakhluk dapat menggunakan aksinya untuk memeriksa target dan melakukan pemeriksaan Intelijen (Investigasi) terhadap mantra penyelamatan DC Anda. Jika berhasil, ia akan menyadari bahwa targetnya sedang menyamar." },
      { name: "Teleportation Circle", components: "V, M", desc: "Saat Anda mengucapkan mantra, Anda menggambar lingkaran berdiameter 10 kaki di tanah bertuliskan sigil yang menghubungkan lokasi Anda ke lingkaran teleportasi permanen pilihan Anda yang urutan sigilnya Anda ketahui dan berada pada bidang keberadaan yang sama dengan Anda. Portal berkilauan terbuka di dalam lingkaran yang Anda gambar dan tetap terbuka hingga akhir giliran Anda berikutnya. Makhluk apa pun yang memasuki portal langsung muncul dalam jarak 5 kaki dari lingkaran tujuan atau di ruang kosong terdekat jika ruang tersebut terisi.\nBanyak kuil besar, guild, dan tempat penting lainnya memiliki lingkaran teleportasi permanen yang tertulis di suatu tempat dalam batasnya. Setiap lingkaran tersebut mencakup rangkaian sigil unik--rangkaian rune magis yang disusun dalam pola tertentu. Saat pertama kali mendapatkan kemampuan untuk merapal mantra ini, Anda mempelajari rangkaian sigil untuk dua tujuan di Bidang Material, yang ditentukan oleh GM. Anda dapat mempelajari urutan sigil tambahan selama petualangan Anda. Anda dapat memasukkan urutan sigil baru ke memori setelah mempelajarinya selama 1 menit.\nAnda dapat membuat lingkaran teleportasi permanen dengan menggunakan mantra ini di lokasi yang sama setiap hari selama satu tahun. Anda tidak perlu menggunakan lingkaran untuk berteleportasi saat Anda mengucapkan mantra dengan cara ini." },
    ],
    Level6: [
      { name: "Eyebite", components: "V, S", desc: "Selama durasi mantranya, matamu menjadi kehampaan bertinta yang dipenuhi kekuatan menakutkan. Satu makhluk pilihan Anda dalam jarak 60 kaki dari Anda yang dapat Anda lihat harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau terpengaruh oleh salah satu efek pilihan Anda berikut selama durasi tersebut. Pada setiap giliranmu hingga mantra berakhir, kamu dapat menggunakan tindakanmu untuk menargetkan makhluk lain tetapi tidak dapat menargetkan makhluk lagi jika makhluk tersebut berhasil melakukan penyelamatan terhadap casting eyebite ini.\n***Tidur.*** Target jatuh pingsan. Ia akan bangun jika ia mengalami kerusakan atau jika makhluk lain menggunakan aksinya untuk membangunkan orang yang tidur.\n***Panik.*** Targetnya takut padamu. Di setiap belokannya, makhluk yang ketakutan harus mengambil tindakan Dash dan menjauh dari Anda melalui rute teraman dan terpendek yang tersedia, kecuali tidak ada tempat untuk bergerak. Jika target berpindah ke tempat setidaknya 60 kaki dari Anda di mana ia tidak dapat lagi melihat Anda, efek ini akan berakhir.\n***Muak.*** Target memiliki kelemahan pada serangan dan pemeriksaan kemampuan. Di akhir setiap putarannya, ia dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, efeknya berakhir." },
      { name: "Find the Path", components: "V, S, M", desc: "Mantra ini memungkinkan Anda menemukan rute fisik terpendek dan paling langsung ke lokasi tetap tertentu yang Anda kenal di alam keberadaan yang sama. Jika Anda menyebutkan tujuan di alam eksistensi lain, tujuan yang bergerak (seperti benteng bergerak), atau tujuan yang tidak spesifik (seperti \"sarang naga hijau\"), mantranya akan gagal.\nSelama Anda berada di alam eksistensi yang sama dengan tujuan, Anda tahu seberapa jauh jaraknya dan ke arah mana letaknya. Saat Anda bepergian ke sana, setiap kali Anda dihadapkan pada pilihan jalur di sepanjang jalan, Anda secara otomatis menentukan jalur mana yang merupakan rute terpendek dan paling langsung (tetapi belum tentu rute teraman) ke tujuan." },
      { name: "Guards and Wards", components: "V, S, M", desc: "Anda membuat lingkungan yang melindungi luas lantai hingga 2.500 kaki persegi (luas 50 kaki persegi, atau seratus persegi 5 kaki atau dua puluh lima persegi 10 kaki). Area yang dikurung bisa setinggi 20 kaki, dan dibentuk sesuai keinginan. Anda dapat menangkal beberapa tingkat benteng dengan membagi area di antara mereka, selama Anda dapat berjalan ke setiap area yang berdekatan saat Anda merapal mantra.\nSaat Anda mengucapkan mantra ini, Anda dapat menentukan individu yang tidak terpengaruh oleh salah satu atau semua efek yang Anda pilih. Anda juga dapat menentukan kata sandi yang, jika diucapkan dengan lantang, membuat pembicara kebal terhadap efek ini.\nPenjaga dan lingkungan menciptakan efek berikut di dalam area yang dilindungi.\n***Koridor.*** Kabut memenuhi semua koridor yang dilindungi, membuatnya sangat tertutup. Selain itu, di setiap persimpangan atau percabangan yang menawarkan pilihan arah, terdapat kemungkinan 50 persen bahwa makhluk selain Anda akan percaya bahwa ia berjalan ke arah yang berlawanan dengan yang dipilihnya.\n***Pintu.*** Semua pintu di area yang dilindungi dikunci secara ajaib, seolah-olah disegel oleh mantra kunci misterius. Selain itu, Anda dapat menutupi hingga sepuluh pintu dengan ilusi (setara dengan fungsi objek ilusi dari mantra ilusi minor) untuk membuatnya tampak sebagai bagian dinding yang polos.\n***Tangga.*** Jaring mengisi semua tangga di area yang dilindungi dari atas ke bawah, sebagai mantra web. Untaian ini akan tumbuh kembali dalam 10 menit jika dibakar atau dirobek selama penjaga dan pelindung masih ada.\n***Efek Mantra Lainnya.*** Anda dapat menempatkan salah satu efek magis berikut pilihan Anda di dalam area pertahanan benteng.\n- Tempatkan lampu menari di empat koridor. Anda dapat menentukan program sederhana yang akan diulangi lampunya selama penjaga dan penjaga masih ada.\n- Tempatkan mulut ajaib di dua lokasi.\n- Tempatkan awan bau di dua lokasi. Uapnya muncul di tempat yang Anda tentukan; mereka kembali dalam waktu 10 menit jika disebarkan oleh angin selama penjaga dan penjaga masih ada.\n- Tempatkan hembusan angin yang konstan pada satu koridor atau ruangan.\n- Tempatkan saran di satu lokasi. Anda memilih area hingga 5 kaki persegi, dan makhluk apa pun yang masuk atau melewati area tersebut menerima saran secara mental.\nSeluruh area yang dilindungi memancarkan sihir. Pemeran sihir penghilang pada efek tertentu, jika berhasil, hanya menghilangkan efek itu.\nAnda dapat membuat struktur yang dijaga dan dilindungi secara permanen dengan merapalkan mantra ini di sana setiap hari selama satu tahun." },
      { name: "Irresistible Dance", components: "V", desc: "Pilih satu makhluk yang dapat Anda lihat dalam jangkauan. Target memulai tarian komik di tempat: menyeret, menghentakkan kaki, dan melompat-lompat selama durasi tersebut. Makhluk yang tidak bisa dimantrai akan kebal terhadap mantra ini.\nMakhluk yang menari harus menggunakan seluruh gerakannya untuk menari tanpa meninggalkan ruangnya dan memiliki kelemahan pada ketangkasan, penyelamatan lemparan dan lemparan serangan. Meskipun target terpengaruh oleh mantra ini, makhluk lain memiliki keuntungan dalam serangan yang melawannya. Sebagai aksinya, makhluk yang menari melakukan lemparan penyelamatan kebijaksanaan untuk mendapatkan kembali kendali atas dirinya. Jika penyelamatan berhasil, mantranya berakhir." },
      { name: "Mass Suggestion", components: "V, M", desc: "Anda menyarankan serangkaian aktivitas (terbatas pada satu atau dua kalimat) dan secara ajaib memengaruhi hingga dua belas makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan dan yang dapat mendengar serta memahami Anda. Makhluk yang tidak bisa dipesona akan kebal terhadap efek ini. Saran tersebut harus diungkapkan sedemikian rupa agar tindakan yang diambil terdengar masuk akal. Meminta makhluk itu untuk menusuk dirinya sendiri, melemparkan dirinya ke tombak, mengorbankan dirinya sendiri, atau melakukan tindakan berbahaya lainnya secara otomatis meniadakan efek mantranya.\nSetiap target harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, ia akan melakukan tindakan yang Anda jelaskan dengan kemampuan terbaiknya. Tindakan yang disarankan dapat berlanjut sepanjang durasi. Jika aktivitas yang disarankan dapat diselesaikan dalam waktu yang lebih singkat, mantra akan berakhir saat subjek menyelesaikan apa yang diminta.\nAnda juga dapat menentukan kondisi yang akan memicu aktivitas khusus selama durasi tersebut. Misalnya, Anda mungkin menyarankan agar sekelompok tentara memberikan seluruh uangnya kepada pengemis pertama yang mereka temui. Jika kondisi tidak terpenuhi sebelum mantra berakhir, aktivitas tidak dilakukan.\nJika Anda atau salah satu teman Anda merusak makhluk yang terkena mantra ini, mantra untuk makhluk itu akan berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7, durasinya adalah 10 hari. Saat Anda menggunakan slot mantra level 8, durasinya adalah 30 hari. Saat Anda menggunakan slot mantra level 9, durasinya adalah satu tahun dan satu hari." },
      { name: "Programmed Illusion", components: "V, S, M", desc: "Anda menciptakan ilusi suatu objek, makhluk, atau fenomena lain yang terlihat dalam jangkauan yang aktif ketika kondisi tertentu terjadi. Ilusi itu tidak terlihat sampai saat itu. Ukurannya tidak boleh lebih besar dari kubus berukuran 30 kaki, dan saat Anda mengucapkan mantra, Andalah yang memutuskan bagaimana perilaku ilusi dan suara apa yang dihasilkannya. Pertunjukan bernaskah ini dapat bertahan hingga 5 menit.\nKetika kondisi yang Anda tentukan terjadi, ilusi muncul dan bekerja sesuai dengan cara yang Anda gambarkan. Setelah ilusi selesai tampil, ilusi tersebut menghilang dan tetap tidak aktif selama 10 menit. Setelah itu, ilusi dapat diaktifkan kembali.\nKondisi pemicunya bisa bersifat umum atau sedetail yang Anda inginkan, namun harus didasarkan pada kondisi visual atau suara yang terjadi dalam jarak 30 kaki dari area tersebut. Misalnya, Anda dapat menciptakan ilusi diri Anda sendiri untuk muncul dan memperingatkan orang lain yang mencoba membuka pintu yang terperangkap, atau Anda dapat mengatur ilusi agar terpicu hanya ketika makhluk mengucapkan kata atau frasa yang benar.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk dapat mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut, dan suara apa pun yang dihasilkannya akan terdengar hampa bagi makhluk tersebut." },
      { name: "True Seeing", components: "V, S, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk melihat segala sesuatu sebagaimana adanya. Selama durasi tersebut, makhluk tersebut memiliki penglihatan yang sebenarnya, mengetahui pintu rahasia yang disembunyikan oleh sihir, dan dapat melihat ke dalam Alam Ethereal, semuanya hingga jarak 120 kaki." },
    ],
    Level7: [
      { name: "Arcane Sword", components: "V, S, M", desc: "Anda membuat bidang kekuatan berbentuk pedang yang melayang dalam jangkauan. Itu berlangsung selama durasi tersebut.\nSaat pedang muncul, Anda melakukan serangan mantra jarak dekat terhadap target pilihan Anda dalam jarak 5 kaki dari pedang. Saat terkena, target menerima kerusakan kekuatan 3d10. Hingga mantranya berakhir, Anda dapat menggunakan aksi bonus di setiap giliran Anda untuk menggerakkan pedang hingga 20 kaki ke tempat yang dapat Anda lihat dan ulangi serangan ini terhadap target yang sama atau berbeda." },
      { name: "Etherealness", components: "V, S", desc: "Anda melangkah ke wilayah perbatasan Pesawat Ethereal, di area yang tumpang tindih dengan pesawat Anda saat ini. Anda tetap berada di Border Ethereal selama atau sampai Anda menggunakan tindakan Anda untuk menghilangkan mantranya. Selama waktu ini, Anda dapat bergerak ke segala arah. Jika Anda bergerak ke atas atau ke bawah, setiap gerakan membutuhkan satu kaki ekstra. Anda dapat melihat dan mendengar pesawat asal Anda, tetapi segala sesuatu di sana tampak abu-abu, dan Anda tidak dapat melihat apa pun yang jaraknya lebih dari 60 kaki.\nSelama berada di Alam Ethereal, Anda hanya dapat mempengaruhi dan dipengaruhi oleh makhluk lain di alam tersebut. Makhluk yang tidak berada di Alam Ethereal tidak dapat melihat Anda dan tidak dapat berinteraksi dengan Anda, kecuali jika kemampuan atau sihir khusus memberi mereka kemampuan untuk melakukannya.\nAnda mengabaikan semua objek dan efek yang tidak ada di Alam Ethereal, memungkinkan Anda bergerak melalui objek yang Anda lihat di bidang asal Anda.\nKetika mantranya berakhir, kamu segera kembali ke pesawat asalmu di tempat yang kamu tempati saat ini. Jika Anda menempati tempat yang sama dengan benda padat atau makhluk saat hal ini terjadi, Anda akan segera diarahkan ke ruang kosong terdekat yang dapat Anda tempati dan menerima kerusakan kekuatan yang setara dengan dua kali jumlah kaki yang Anda gerakkan.\nMantra ini tidak berpengaruh jika kamu mengucapkannya saat kamu berada di Alam Ethereal atau di alam yang tidak membatasinya, seperti salah satu Alam Luar.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 8 atau lebih tinggi, Anda dapat menargetkan hingga tiga makhluk yang bersedia (termasuk Anda) untuk setiap slot level di atas 7. Makhluk tersebut harus berada dalam jarak 10 kaki dari Anda saat Anda mengucapkan mantra." },
      { name: "Forcecage", components: "V, S, M", desc: "Penjara berbentuk kubus yang tidak bergerak, tidak terlihat, dan terdiri dari kekuatan magis muncul di sekitar area yang Anda pilih dalam jangkauannya. Penjara bisa berupa sangkar atau kotak padat, sesuai pilihan Anda.\nPenjara berbentuk sangkar bisa berukuran hingga 20 kaki di sisinya dan terbuat dari jeruji berdiameter 1/2 inci dengan jarak 1/2 inci.\nPenjara berbentuk kotak bisa memiliki tinggi hingga 10 kaki di sisinya, menciptakan penghalang kokoh yang mencegah benda apa pun melewatinya dan memblokir mantra apa pun yang dilemparkan ke dalam atau keluar dari area tersebut.\nSaat Anda mengucapkan mantra, makhluk apa pun yang sepenuhnya berada di dalam area kandang akan terperangkap. Makhluk yang hanya berada sebagian di dalam area, atau yang terlalu besar untuk dapat masuk ke dalam area, akan didorong menjauh dari pusat area hingga mereka benar-benar berada di luar area.\nMakhluk yang berada di dalam sangkar tidak bisa keluar darinya dengan cara non-magis. Jika makhluk tersebut mencoba menggunakan teleportasi atau perjalanan antarplanar untuk meninggalkan kandang, ia harus melakukan lemparan penyelamatan karisma terlebih dahulu. Jika berhasil, makhluk itu dapat menggunakan sihir itu untuk keluar dari kandang. Jika gagal, makhluk tersebut tidak dapat keluar dari kandang dan menyia-nyiakan penggunaan mantra atau efeknya. Sangkar itu juga meluas hingga ke Alam Ethereal, menghalangi perjalanan halus.\nMantra ini tidak bisa dihilangkan dengan sihir dispel." },
      { name: "Magnificent Mansion", components: "V, S, M", desc: "Anda membayangkan hunian ekstradimensi dalam jangkauan yang bertahan selama durasi tersebut. Anda memilih di mana salah satu pintu masuknya berada. Pintu masuknya berkilau samar dan lebarnya 5 kaki dan tinggi 10 kaki. Anda dan makhluk apa pun yang Anda tunjuk saat mengucapkan mantra dapat memasuki tempat tinggal ekstradimensi selama portalnya tetap terbuka. Anda dapat membuka atau menutup portal jika Anda berada dalam jarak 30 kaki darinya. Saat ditutup, portal tidak terlihat.\nDi luar portal terdapat serambi megah dengan banyak ruangan di luarnya. Suasananya bersih, segar, dan hangat.\nAnda dapat membuat denah lantai apa pun yang Anda suka, tetapi ruangannya tidak boleh melebihi 50 kubus, setiap kubus berukuran 10 kaki di setiap sisinya. Tempat ini dilengkapi perabotan dan dekorasi sesuai pilihan Anda. Ini berisi makanan yang cukup untuk menyajikan jamuan sembilan hidangan untuk hingga 100 orang. Staf yang terdiri dari 100 pelayan yang hampir transparan melayani semua yang masuk. Anda yang menentukan penampilan visual para pelayan ini dan pakaian mereka. Mereka sepenuhnya patuh pada perintah Anda. Setiap pelayan bisa melakukan tugas apa pun yang bisa dilakukan oleh pelayan manusia biasa, tapi mereka tidak bisa menyerang atau melakukan tindakan apa pun yang secara langsung akan membahayakan makhluk lain. Dengan demikian para pelayan dapat mengambil sesuatu, membersihkan, memperbaiki, melipat pakaian, menyalakan api, menyajikan makanan, menuangkan anggur, dan sebagainya. Para pelayan bisa pergi kemana saja di dalam mansion tapi tidak bisa meninggalkannya. Perabotan dan benda lain yang diciptakan oleh mantra ini akan menghilang menjadi asap jika dikeluarkan dari mansion. Saat mantranya berakhir, makhluk apa pun di dalam ruang ekstradimensi akan diusir ke ruang terbuka terdekat dengan pintu masuk." },
      { name: "Mirage Arcane", components: "V, S", desc: "Anda membuat medan di area seluas 1 mil persegi terlihat, terdengar, tercium, dan bahkan terasa seperti medan lainnya. Namun, bentuk umum medannya tetap sama. Lahan terbuka atau jalan dapat dibuat menyerupai rawa, bukit, jurang, atau medan lain yang sulit atau tidak dapat dilalui. Sebuah kolam dapat dibuat tampak seperti padang rumput, jurang seperti lereng yang landai, atau selokan yang dipenuhi bebatuan seperti jalan yang lebar dan mulus.\nDemikian pula, Anda dapat mengubah tampilan struktur, atau menambahkannya jika tidak ada. Mantra itu tidak menyamarkan, menyembunyikan, atau menambah makhluk.\nIlusi mencakup elemen pendengaran, visual, sentuhan, dan penciuman, sehingga dapat mengubah permukaan tanah yang bersih menjadi medan yang sulit (atau sebaliknya) atau menghambat pergerakan melalui area tersebut. Setiap bagian dari medan ilusi (seperti batu atau tongkat) yang dikeluarkan dari area mantra akan segera menghilang.\nMakhluk dengan penglihatan sejati dapat melihat melalui ilusi ke bentuk sebenarnya dari medan tersebut; namun, semua elemen ilusi lainnya tetap ada, jadi meskipun makhluk tersebut menyadari kehadiran ilusi tersebut, makhluk tersebut masih dapat berinteraksi secara fisik dengan ilusi tersebut." },
      { name: "Project Image", components: "V, S, M", desc: "Anda membuat salinan ilusi diri Anda yang bertahan selama itu. Salinannya dapat muncul di lokasi mana pun dalam jangkauan yang pernah Anda lihat sebelumnya, terlepas dari hambatan yang ada. Ilusi tersebut tampak dan terdengar seperti Anda, namun tidak berwujud. Jika ilusi mengalami kerusakan, ilusi itu akan hilang dan mantranya berakhir.\nAnda dapat menggunakan tindakan Anda untuk menggerakkan ilusi ini hingga dua kali kecepatan Anda, dan membuatnya memberi isyarat, berbicara, dan berperilaku sesuai pilihan Anda. Itu meniru tingkah laku Anda dengan sempurna.\nAnda dapat melihat melalui matanya dan mendengar melalui telinganya seolah-olah Anda berada di ruangnya. Pada giliran Anda sebagai tindakan bonus, Anda dapat beralih dari menggunakan indra Anda ke menggunakan indra Anda sendiri, atau kembali lagi. Saat Anda menggunakan indranya, Anda menjadi buta dan tuli terhadap lingkungan sekitar Anda.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk dapat mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut, dan suara apa pun yang dihasilkannya akan terdengar hampa bagi makhluk tersebut." },
      { name: "Regenerate", components: "V, S, M", desc: "Anda menyentuh makhluk dan merangsang kemampuan penyembuhan alaminya. Target mendapatkan kembali 4d8 + 15 poin hit. Selama durasi mantra, target mendapatkan kembali 1 poin hit di awal setiap putarannya (10 poin hit setiap menit).\nAnggota tubuh target yang terputus (jari tangan, kaki, ekor, dan sebagainya), jika ada, akan dipulihkan setelah 2 menit. Jika Anda memiliki bagian yang terputus dan menempelkannya pada tunggul, mantra tersebut secara instan menyebabkan anggota tubuh tersebut terikat pada tunggul." },
      { name: "Resurrection", components: "V, S, M", desc: "Anda menyentuh makhluk mati yang telah mati tidak lebih dari satu abad, yang tidak mati karena usia tua, dan itu bukanlah mayat hidup. Jika jiwanya bebas dan berkeinginan, target akan hidup kembali dengan segala hit pointnya.\nMantra ini menetralkan segala racun dan menyembuhkan penyakit normal yang menyerang makhluk itu ketika mati. Namun, hal ini tidak menghilangkan penyakit magis, kutukan, dan sejenisnya; jika efek tersebut tidak dihilangkan sebelum merapal mantra, efek tersebut akan menimpa target saat mantra tersebut kembali hidup.\nMantra ini menutup semua luka mematikan dan memulihkan bagian tubuh yang hilang.\nBangkit dari kematian adalah sebuah cobaan berat. Target menerima penalti -4 untuk semua serangan, lemparan penyelamatan, dan pemeriksaan kemampuan. Setiap target menyelesaikan istirahat panjang, penaltinya berkurang 1 hingga hilang.\nMengucapkan mantra ini untuk menghidupkan kembali makhluk yang telah mati selama satu tahun atau lebih akan sangat membebani Anda. Sampai Anda menyelesaikan istirahat panjang, Anda tidak dapat merapal mantra lagi, dan Anda memiliki kerugian pada semua serangan, pemeriksaan kemampuan, dan penyelamatan lemparan." },
      { name: "Symbol", components: "V, S, M", desc: "Saat Anda mengucapkan mantra ini, Anda menuliskan mesin terbang yang berbahaya baik di permukaan (seperti bagian lantai, dinding, atau meja) atau di dalam objek yang dapat ditutup untuk menyembunyikan mesin terbang tersebut (seperti buku, gulungan, atau peti harta karun). Jika Anda memilih suatu permukaan, mesin terbang tersebut dapat menutupi area permukaan yang diameternya tidak lebih dari 10 kaki. Jika Anda memilih suatu benda, benda itu harus tetap berada di tempatnya; jika objek dipindahkan lebih dari 10 kaki dari tempat Anda mengucapkan mantra ini, mesin terbangnya rusak, dan mantranya berakhir tanpa terpicu.\nMesin terbang itu hampir tidak terlihat, memerlukan pemeriksaan Intelijen (Investigasi) terhadap mantra Anda, simpan DC untuk menemukannya.\nAnda memutuskan apa yang memicu mesin terbang saat Anda mengucapkan mantranya. Untuk mesin terbang yang tertulis di suatu permukaan, pemicu yang paling umum adalah menyentuh atau menginjak mesin terbang tersebut, memindahkan benda lain yang menutupinya, mendekat dalam jarak tertentu, atau memanipulasi benda yang menahannya. Untuk mesin terbang yang tertulis di dalam suatu objek, pemicu paling umum adalah membuka objek, mendekat dalam jarak tertentu, atau melihat atau membaca mesin terbang tersebut.\nAnda dapat menyempurnakan pemicunya lebih lanjut sehingga mantranya hanya diaktifkan dalam keadaan tertentu atau berdasarkan karakteristik fisik makhluk (seperti tinggi atau berat), atau jenis fisiknya (misalnya, lingkungan dapat diatur untuk memengaruhi perempuan tua atau pengubah bentuk). Anda juga dapat menentukan makhluk yang tidak memicu mesin terbang, seperti makhluk yang mengucapkan kata sandi tertentu.\nSaat Anda menuliskan mesin terbang, pilih salah satu opsi di bawah untuk efeknya. Setelah dipicu, mesin terbang tersebut bersinar, mengisi bola berradius 60 kaki dengan cahaya redup selama 10 menit, setelah itu mantranya berakhir. Setiap makhluk di dalam bola ketika mesin terbang aktif ditargetkan oleh efeknya, seperti halnya makhluk yang memasuki bola untuk pertama kalinya pada suatu belokan atau mengakhiri gilirannya di sana.\n***Kematian.*** Setiap target harus melakukan lemparan penyelamatan konstitusi, menerima 10d 10 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\n***Perselisihan.*** Setiap target harus melakukan penyelamatan konstitusi. Pada penyelamatan yang gagal, target bertengkar dan berdebat dengan makhluk lain selama 1 menit. Selama waktu ini, ia tidak mampu melakukan komunikasi yang berarti dan memiliki kelemahan dalam serangan dan pemeriksaan kemampuan.\n***Fear.*** Setiap target harus melakukan lemparan penyelamatan yang bijaksana dan menjadi ketakutan selama 1 menit jika penyelamatan gagal. Saat ketakutan, target menjatuhkan apa pun yang dipegangnya dan harus menjauh setidaknya 30 kaki dari mesin terbang di setiap belokannya, jika memungkinkan.\n***Keputusasaan.*** Setiap target harus melakukan lemparan penyelamatan karisma. Pada penyelamatan yang gagal, target diliputi keputusasaan selama 1 menit. Selama waktu ini, ia tidak dapat menyerang atau menargetkan makhluk apa pun dengan kemampuan, mantra, atau efek magis berbahaya lainnya.\n***Kegilaan.*** Setiap target harus melakukan penyelamatan intelijen. Jika penyelamatan gagal, target menjadi gila selama 1 menit. Makhluk gila tidak bisa mengambil tindakan, tidak bisa mengerti apa yang dikatakan makhluk lain, tidak bisa membaca, dan hanya berbicara omong kosong. GM mengontrol pergerakannya, yang tidak menentu.\n***Sakit.*** Setiap target harus melakukan lemparan penyelamatan konstitusi dan menjadi tidak berdaya dengan rasa sakit yang menyiksa selama 1 menit jika penyelamatan gagal.\n***Tidur.*** Setiap target harus melakukan lemparan penyelamatan kebijaksanaan dan jatuh pingsan selama 10 menit karena penyelamatan yang gagal. Makhluk akan terbangun jika ia menerima kerusakan atau jika seseorang menggunakan suatu tindakan untuk mengguncang atau menamparnya hingga terbangun.\n***Menakjubkan.*** Setiap target harus melakukan lemparan penyelamatan yang bijaksana dan terkena stun selama 1 menit jika penyelamatan gagal." },
      { name: "Teleport", components: "V", desc: "Mantra ini secara instan memindahkan Anda dan hingga delapan makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan, atau satu objek yang dapat Anda lihat dalam jangkauan, ke tujuan yang Anda pilih. Jika Anda menargetkan suatu objek, objek tersebut harus dapat masuk seluruhnya ke dalam kubus berukuran 10 kaki, dan objek tersebut tidak dapat dipegang atau dibawa oleh makhluk yang tidak mau.\nTujuan yang Anda pilih harus Anda ketahui, dan harus berada pada alam eksistensi yang sama dengan Anda. Keakraban Anda dengan tujuan menentukan apakah Anda berhasil sampai di sana. GM menggulung d100 dan melihat tabel.\n| Keakraban | Kecelakaan | Daerah Serupa | Melenceng dari Sasaran | Sesuai Sasaran |\n|---|---|---|---|---|\n| Lingkaran permanen | -- | -- | -- | 01-100 |\n| Objek terkait | -- | -- | -- | 01-100 |\n| Sangat akrab | 01-05 | 06-13 | 14-24 | 25-100 |\n| Terlihat santai | 01-33 | 34-43 | 44-53 | 54-100 |\n| Dilihat sekali | 01-43 | 44-53 | 54-73 | 74-100 |\n| Deskripsi | 01-43 | 44-53 | 54-73 | 74-100 |\n| Tujuan salah | 01-50 | 51-100 | -- | -- |\n***Familiarity.*** \"Lingkaran permanen\" artinya lingkaran teleportasi permanen yang urutan sigilnya sudah kalian ketahui.\n\"Benda terkait\" berarti Anda memiliki benda yang diambil dari tujuan yang diinginkan dalam enam bulan terakhir, seperti buku dari perpustakaan penyihir, sprei dari kamar kerajaan, atau bongkahan marmer dari makam rahasia lich.\n\"Sangat familier\" adalah tempat yang sering Anda kunjungi, tempat yang telah Anda pelajari dengan cermat, atau tempat yang dapat Anda lihat saat Anda merapal mantra.\n\"Dilihat secara santai\" adalah suatu tempat yang pernah Anda lihat lebih dari sekali tetapi tidak terlalu Anda kenal.\n\"Dilihat sekali\" adalah tempat yang pernah Anda lihat, mungkin menggunakan sihir.\n\"Deskripsi\" adalah suatu tempat yang lokasi dan penampakannya Anda ketahui melalui deskripsi orang lain, mungkin dari peta.\n\"Tujuan palsu\" adalah tempat yang tidak ada. Mungkin Anda mencoba memindai tempat suci musuh tetapi malah melihat ilusi, atau Anda mencoba berteleportasi ke lokasi familiar yang sudah tidak ada lagi.\n***Tepat Target.*** Anda dan grup Anda (atau objek target) muncul di tempat yang Anda inginkan.\n***Diluar Target.*** Anda dan grup Anda (atau objek target) muncul pada jarak acak dari tujuan dalam arah acak. Jarak yang melenceng dari sasaran adalah 1d10 x 1d10 persen dari jarak yang hendak ditempuh. Misalnya, jika Anda mencoba menempuh jarak 120 mil, mendarat melenceng, dan mendapatkan angka 5 dan 3 pada dua D10, maka Anda akan melenceng 15 persen, atau 18 mil. GM menentukan arah keluar target secara acak dengan memutar d8 dan menetapkan 1 sebagai utara, 2 sebagai timur laut, 3 sebagai timur, dan seterusnya di sekitar titik kompas.  Jika Anda berteleportasi ke kota pesisir dan terdampar sejauh 18 mil di laut, Anda bisa mendapat masalah.\n***Area Serupa.*** Anda dan grup Anda (atau objek target) berakhir di area berbeda yang secara visual atau tematis mirip dengan area target. Jika Anda menuju laboratorium di rumah, misalnya, Anda mungkin akan berakhir di laboratorium penyihir lain atau di toko perlengkapan alkimia yang memiliki banyak peralatan dan perlengkapan yang sama dengan laboratorium Anda. Umumnya, Anda muncul di tempat terdekat yang serupa, tetapi karena mantranya tidak memiliki batasan jangkauan, Anda mungkin bisa berakhir di mana saja di pesawat.\n***Kecelakaan.*** Sihir tak terduga dari mantra ini mengakibatkan perjalanan yang sulit. Setiap makhluk yang berteleportasi (atau objek target) menerima kerusakan kekuatan 3d10, dan GM memutar ulang meja untuk melihat di mana Anda berakhir (beberapa kecelakaan dapat terjadi, menimbulkan kerusakan setiap kali)." },
    ],
    Level8: [
      { name: "Dominate Monster", components: "V, S", desc: "Anda mencoba memperdaya makhluk yang dapat Anda lihat dalam jangkauan. Ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Jika Anda atau makhluk yang bersahabat dengan Anda melawannya, ia memiliki keuntungan dalam penyelamatan.\nMeskipun makhluk itu terpesona, Anda memiliki hubungan telepati dengannya selama Anda berdua berada di alam eksistensi yang sama. Anda dapat menggunakan tautan telepati ini untuk mengeluarkan perintah kepada makhluk itu saat Anda sadar (tidak perlu tindakan apa pun), yang akan dipatuhinya sebaik mungkin. Anda dapat menentukan tindakan yang sederhana dan umum, seperti \"Serang makhluk itu\", \"Lari ke sana\", atau \"Ambil objek itu\". Jika makhluk tersebut menyelesaikan perintahnya dan tidak menerima arahan lebih lanjut dari Anda, ia akan mempertahankan dan mempertahankan dirinya dengan kemampuan terbaiknya.\nAnda dapat menggunakan tindakan Anda untuk mengambil kendali total dan tepat terhadap target. Hingga akhir giliran Anda berikutnya, makhluk itu hanya mengambil tindakan yang Anda pilih, dan tidak melakukan apa pun yang tidak Anda izinkan. Selama waktu ini, Anda juga dapat menyebabkan makhluk tersebut menggunakan reaksi, namun hal ini mengharuskan Anda menggunakan reaksi Anda sendiri juga.\nSetiap kali target menerima kerusakan, ia membuat lemparan penyelamatan kebijaksanaan baru terhadap mantra tersebut. Jika lemparan penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini dengan slot mantra level 9, durasinya adalah konsentrasi, hingga 8 jam." },
      { name: "Feeblemind", components: "V, S, M", desc: "Anda meledakkan pikiran makhluk yang dapat Anda lihat dalam jangkauan, mencoba menghancurkan kecerdasan dan kepribadiannya. Target menerima kerusakan psikis 4d6 dan harus melakukan lemparan penyelamatan intelijen.\nJika penyelamatan gagal, skor Kecerdasan dan Karisma makhluk tersebut menjadi 1. Makhluk tersebut tidak dapat merapal mantra, mengaktifkan item sihir, memahami bahasa, atau berkomunikasi dengan cara apa pun yang dapat dimengerti. Namun, makhluk itu dapat mengidentifikasi teman-temannya, mengikuti mereka, dan bahkan melindungi mereka.\nPada akhir setiap 30 hari, makhluk itu dapat mengulangi penyelamatannya terhadap mantra ini. Jika berhasil dalam lemparan penyelamatannya, mantranya berakhir.\nMantra ini juga dapat diakhiri dengan pemulihan, penyembuhan, atau keinginan yang lebih besar." },
      { name: "Glibness", components: "V", desc: "Sampai mantranya berakhir, saat Anda melakukan pemeriksaan Karisma, Anda dapat mengganti angka yang Anda keluarkan dengan 15. Selain itu, apa pun yang Anda katakan, sihir yang akan menentukan apakah Anda mengatakan yang sebenarnya menunjukkan bahwa Anda jujur." },
      { name: "Mind Blank", components: "V, S", desc: "Sampai mantranya berakhir, satu makhluk yang Anda sentuh akan kebal terhadap kerusakan psikis, efek apa pun yang dapat merasakan emosinya atau membaca pikirannya, mantra ramalan, dan kondisi terpesona. Mantra tersebut bahkan menggagalkan mantra keinginan dan mantra atau efek dengan kekuatan serupa yang digunakan untuk mempengaruhi pikiran target atau untuk mendapatkan informasi tentang target." },
      { name: "Power Word Stun", components: "V", desc: "Anda mengucapkan kata-kata yang memiliki kekuatan yang dapat menguasai pikiran satu makhluk yang dapat Anda lihat dalam jangkauannya, membuatnya tercengang. Jika target memiliki 150 poin hit atau kurang, target akan terkena stun. Kalau tidak, mantranya tidak akan berpengaruh.\nTarget yang terkena stun harus melakukan penyelamatan konstitusi di akhir setiap giliran. Jika penyelamatan berhasil, efek menakjubkan ini berakhir." },
    ],
    Level9: [
      { name: "Foresight", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia dan memberikan kemampuan terbatas untuk melihat masa depan. Selama durasi, target tidak dapat terkejut dan memiliki keunggulan dalam serangan, pengecekan kemampuan, dan penyelamatan lemparan. Selain itu, makhluk lain memiliki kelemahan dalam serangan berguling terhadap target selama durasi tersebut.\nMantra ini akan langsung berakhir jika kamu mengucapkannya lagi sebelum durasinya berakhir." },
      { name: "Power Word Kill", components: "V", desc: "Anda mengucapkan kata-kata kekuatan yang dapat memaksa satu makhluk yang Anda lihat dalam jangkauannya untuk mati seketika. Jika makhluk yang Anda pilih memiliki 100 poin hit atau kurang, ia akan mati. Kalau tidak, mantranya tidak akan berpengaruh." },
      { name: "True Polymorph", components: "V, S, M", desc: "Pilih satu makhluk atau objek non-magis yang dapat Anda lihat dalam jangkauannya. Anda mengubah makhluk menjadi makhluk lain, makhluk menjadi benda, atau benda menjadi makhluk (benda tersebut tidak boleh dipakai atau dibawa oleh makhluk lain). Transformasi berlangsung selama durasi tersebut, atau hingga target turun menjadi 0 poin hit atau mati. Jika Anda berkonsentrasi pada mantra ini selama durasi penuh, transformasinya menjadi permanen.\nPengubah bentuk tidak terpengaruh oleh mantra ini. Makhluk yang enggan dapat melakukan lemparan penyelamatan kebijaksanaan, dan jika berhasil, ia tidak terpengaruh oleh mantra ini.\n***Makhluk menjadi Makhluk.*** Jika Anda mengubah makhluk menjadi jenis makhluk lain, bentuk baru dapat berupa jenis apa pun yang Anda pilih yang peringkat tantangannya sama dengan atau lebih kecil dari target (atau levelnya, jika target tidak memiliki peringkat tantangan). Statistik permainan target, termasuk skor kemampuan mental, digantikan oleh statistik bentuk baru. Ia mempertahankan keselarasan dan kepribadiannya.\nTarget tersebut mengambil titik serangan dari bentuk barunya, dan ketika kembali ke bentuk normalnya, makhluk tersebut kembali ke jumlah titik serangan yang dimilikinya sebelum ia bertransformasi. Jika poin serangannya kembali karena poin hitnya turun menjadi 0, kerusakan berlebih akan kembali ke bentuk normalnya. Selama kerusakan berlebih tidak mengurangi bentuk normal makhluk itu menjadi 0 poin serangan, ia tidak akan pingsan.\nTindakan yang dapat dilakukan makhluk ini terbatas karena sifat dari bentuk barunya, dan ia tidak dapat berbicara, merapal mantra, atau melakukan tindakan lain apa pun yang memerlukan tangan atau ucapan kecuali jika bentuk barunya mampu melakukan tindakan tersebut.\nPerlengkapan target menyatu ke dalam bentuk baru. Makhluk itu tidak dapat mengaktifkan, menggunakan, menggunakan, atau memanfaatkan peralatan apa pun.\n***Objek menjadi Makhluk.*** Anda dapat mengubah suatu objek menjadi makhluk apa pun, asalkan ukuran makhluk tersebut tidak lebih besar dari ukuran objek dan peringkat tantangan makhluk tersebut adalah 9 atau lebih rendah. Makhluk itu ramah terhadap Anda dan teman Anda. Ia bertindak pada setiap giliran Anda. Anda memutuskan tindakan apa yang diperlukan dan bagaimana tindakannya. GM memiliki statistik makhluk itu dan menentukan semua tindakan dan pergerakannya.\nJika mantranya menjadi permanen, Anda tidak lagi mengendalikan makhluk itu. Itu mungkin tetap bersahabat dengan Anda, tergantung bagaimana Anda memperlakukannya.\n***Makhluk menjadi Objek.*** Jika Anda mengubah makhluk menjadi objek, ia akan berubah bersama apa pun yang dikenakan dan dibawanya ke dalam bentuk tersebut. Statistik makhluk itu menjadi milik objeknya, dan makhluk itu tidak memiliki ingatan tentang waktu yang dihabiskan dalam bentuk ini, setelah mantranya berakhir dan kembali ke bentuk normalnya." },
    ],
  },
  Cleric: {
    Cantrips: [
      { name: "Guidance", components: "V, S", desc: "Anda menyentuh satu makhluk yang bersedia. Sekali sebelum mantra berakhir, target dapat melempar d4 dan menambahkan nomor yang dilempar ke satu pemeriksaan kemampuan pilihannya. Itu bisa melempar dadu sebelum atau sesudah melakukan pemeriksaan kemampuan. Mantra itu kemudian berakhir." },
      { name: "Light", components: "V, M", desc: "Anda menyentuh satu objek yang ukurannya tidak lebih besar dari 10 kaki dalam dimensi apa pun. Hingga mantranya berakhir, objek tersebut memancarkan cahaya terang dalam radius 20 kaki dan cahaya redup dalam radius tambahan 20 kaki. Lampunya bisa diwarnai sesuka Anda. Menutupi objek sepenuhnya dengan sesuatu yang buram menghalangi cahaya. Mantra berakhir jika Anda mengucapkannya lagi atau mengabaikannya sebagai suatu tindakan.\nJika Anda mengincar benda yang dipegang atau dikenakan oleh makhluk musuh, makhluk tersebut harus berhasil melakukan lemparan penyelamatan ketangkasan untuk menghindari mantranya." },
      { name: "Mending", components: "V, S, M", desc: "Mantra ini memperbaiki satu kerusakan atau robekan pada benda yang Anda sentuh, seperti kunci rusak, jubah robek, atau kantong anggur yang bocor. Selama patah atau robeknya tidak lebih dari 1 kaki di dimensi mana pun, Anda memperbaikinya, tanpa meninggalkan bekas kerusakan sebelumnya.\nMantra ini secara fisik dapat memperbaiki item atau konstruksi sihir, tetapi mantra tersebut tidak dapat memulihkan sihir ke objek tersebut." },
      { name: "Resistance", components: "V, S, M", desc: "Anda menyentuh satu makhluk yang bersedia. Sekali sebelum mantra berakhir, target dapat melempar d4 dan menambahkan nomor yang dilempar ke satu lemparan penyelamatan pilihannya. Ia dapat melempar dadu sebelum atau sesudah melakukan lemparan penyelamatan. Mantra itu kemudian berakhir." },
      { name: "Sacred Flame", components: "V, S", desc: "Cahaya seperti api menyinari makhluk yang dapat Anda lihat dalam jangkauannya. Target harus berhasil melakukan lemparan hemat ketangkasan atau menerima kerusakan radiasi 1d8. Target tidak mendapatkan manfaat dari perlindungan atas penyelamatan ini.\nKerusakan mantra meningkat sebesar 1d8 ketika Anda mencapai level 5 (2d8), level 11 (3d8), dan level 17 (4d8)." },
      { name: "Spare the Dying", components: "V, S", desc: "Anda menyentuh makhluk hidup yang memiliki 0 poin hit. Makhluk itu menjadi stabil. Mantra ini tidak berpengaruh pada undead atau konstruksi." },
      { name: "Thaumaturgy", components: "V", desc: "Anda mewujudkan keajaiban kecil, tanda kekuatan supernatural, dalam jangkauan. Anda membuat salah satu efek magis berikut dalam jangkauan.\n- Suara Anda menggelegar hingga tiga kali lebih keras dari biasanya selama 1 menit.\n- Anda menyebabkan nyala api berkedip, mencerahkan, meredupkan, atau berubah warna selama 1 menit.\n- Anda menyebabkan getaran yang tidak berbahaya di tanah selama 1 menit.\n- Anda membuat suara seketika yang berasal dari titik pilihan Anda dalam jangkauan, seperti gemuruh guntur, jeritan burung gagak, atau bisikan yang tidak menyenangkan.\n- Anda secara instan menyebabkan pintu atau jendela yang tidak terkunci terbuka atau tertutup rapat.\n- Anda mengubah tampilan mata Anda selama 1 menit.\nJika Anda mengucapkan mantra ini beberapa kali, Anda dapat mengaktifkan hingga tiga efek 1 menitnya sekaligus, dan Anda dapat mengabaikan efek tersebut sebagai tindakan." },
    ],
    Level1: [
      { name: "Bane", components: "V, S, M", desc: "Hingga tiga makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan harus melakukan lemparan yang menghemat karisma. Setiap kali target yang gagal melakukan lemparan penyelamatan ini melakukan serangan lemparan atau lemparan penyelamatan sebelum mantra berakhir, target harus melempar d4 dan mengurangi jumlah yang diperoleh dari lemparan serangan atau lemparan penyelamatan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 1." },
      { name: "Bless", components: "V, S, M", desc: "Anda memberkati hingga tiga makhluk pilihan Anda dalam jangkauan. Setiap kali target melakukan roll serangan atau lemparan penyelamatan sebelum mantra berakhir, target dapat melempar d4 dan menambahkan nomor yang dilempar ke lemparan serangan atau lemparan penyelamatan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 1." },
      { name: "Command", components: "V", desc: "Anda mengucapkan perintah satu kata kepada makhluk yang dapat Anda lihat dalam jangkauan. Target harus berhasil dalam lemparan penyelamatan yang bijaksana atau mengikuti perintah pada giliran berikutnya. Mantra tersebut tidak berpengaruh jika targetnya adalah undead, jika targetnya tidak memahami bahasa Anda, atau jika perintah Anda secara langsung membahayakan targetnya.\nBeberapa perintah umum dan efeknya mengikuti. Anda mungkin mengeluarkan perintah selain yang dijelaskan di sini. Jika Anda melakukannya, GM akan menentukan bagaimana target berperilaku. Jika target tidak dapat mengikuti perintah Anda, mantranya berakhir.\n***Pendekatan.*** Target bergerak ke arah Anda melalui rute terpendek dan paling langsung, mengakhiri gilirannya jika bergerak dalam jarak 5 kaki dari Anda.\n***Jatuhkan.*** Target menjatuhkan apa pun yang dipegangnya dan kemudian mengakhiri gilirannya.\n***Lari.*** Target menghabiskan gilirannya menjauh dari Anda dengan cara tercepat yang tersedia.\n***Grovel.*** Targetnya tiarap dan kemudian mengakhiri gilirannya.\n***Berhenti.*** Target tidak bergerak dan tidak mengambil tindakan. Makhluk terbang akan tetap terbang asalkan mampu melakukannya. Jika ia harus bergerak agar tetap tinggi, ia terbang dengan jarak minimum yang diperlukan untuk tetap berada di udara.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat memengaruhi satu makhluk tambahan untuk setiap slot level di atas 1. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Create or Destroy Water", components: "V, S, M", desc: "Anda bisa menciptakan atau menghancurkan air.\n***Buat Air.*** Anda membuat hingga 10 galon air bersih dalam jangkauan dalam wadah terbuka. Alternatifnya, air jatuh sebagai hujan dalam kubus berukuran 30 kaki dalam jangkauannya.\n***Hancurkan Air.*** Anda menghancurkan hingga 10 galon air dalam wadah terbuka dalam jangkauan. Alternatifnya, Anda menghancurkan kabut dalam kubus berukuran 30 kaki dalam jangkauan.\nLevel Tinggi: Saat Anda mengucapkan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda membuat atau menghancurkan 10 galon air tambahan, atau ukuran kubus bertambah 5 kaki, untuk setiap slot level di atas 1." },
      { name: "Cure Wounds", components: "V, S", desc: "Makhluk yang Anda sentuh mendapatkan kembali sejumlah poin hit yang setara dengan 1d8 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, penyembuhan meningkat sebesar 1d8 untuk setiap slot level di atas 1." },
      { name: "Detect Evil and Good", components: "V, S", desc: "Untuk durasinya, Anda mengetahui apakah ada aberration, Celestial, Elemental, Fey, Fiend, atau Undead dalam jarak 30 kaki dari Anda, serta di mana makhluk itu berada. Demikian pula, Anda mengetahui jika ada tempat atau benda dalam jarak 30 kaki dari Anda yang telah disucikan atau dinodai secara ajaib.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Detect Magic", components: "V, S", desc: "Selama durasi tersebut, Anda merasakan kehadiran sihir dalam jarak 30 kaki dari Anda. Jika Anda merasakan sihir dengan cara ini, Anda dapat menggunakan tindakan Anda untuk melihat aura samar di sekitar makhluk atau objek apa pun yang terlihat di area yang mengandung sihir, dan Anda mempelajari sekolah sihirnya, jika ada.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Detect Poison and Disease", components: "V, S, M", desc: "Selama durasi tersebut, Anda dapat merasakan keberadaan dan lokasi racun, makhluk beracun, dan penyakit dalam jarak 30 kaki dari Anda. Anda juga mengidentifikasi jenis racun, makhluk beracun, atau penyakit dalam setiap kasus.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Guiding Bolt", components: "V, S", desc: "Kilatan cahaya melesat ke arah makhluk pilihan Anda dalam jangkauan. Lakukan serangan mantra jarak jauh terhadap target. Saat terkena, target menerima kerusakan radiasi sebesar 4d6, dan serangan berikutnya yang dilakukan terhadap target ini sebelum akhir giliran Anda berikutnya memiliki keuntungan, berkat cahaya redup mistis yang berkilauan pada target hingga saat itu.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 1." },
      { name: "Healing Word", components: "V", desc: "Makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan mendapatkan kembali poin hit yang setara dengan 1d4 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, penyembuhan meningkat sebesar 1d4 untuk setiap slot level di atas 1." },
      { name: "Inflict Wounds", components: "V, S", desc: "Lakukan serangan mantra jarak dekat terhadap makhluk yang bisa Anda jangkau. Saat terkena, target menerima 3d10 kerusakan nekrotik.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, kerusakan meningkat sebesar 1d10 untuk setiap slot level di atas 1." },
      { name: "Protection from Evil and Good", components: "V, S, M", desc: "Hingga mantranya berakhir, satu makhluk yang Anda sentuh akan terlindungi dari jenis makhluk tertentu: aberasi, surgawi, elemen, fey, iblis, dan undead.\nPerlindungan memberikan beberapa manfaat. Makhluk dengan tipe seperti itu mempunyai kelemahan dalam serangan roll terhadap target. Targetnya juga tidak bisa terpesona, ditakuti, atau dirasuki oleh mereka. Jika target sudah terpesona, ketakutan, atau dirasuki oleh makhluk tersebut, target mempunyai keuntungan pada setiap lemparan penyelamatan baru terhadap efek yang relevan." },
      { name: "Purify Food and Drink", components: "V, S", desc: "Semua makanan dan minuman non-magis dalam radius 5 kaki yang berpusat pada titik pilihan Anda dalam jangkauan dimurnikan dan bebas dari racun dan penyakit." },
      { name: "Sanctuary", components: "V, S, M", desc: "Anda menangkal makhluk dalam jangkauan dari serangan. Sampai mantranya berakhir, makhluk mana pun yang mengincar makhluk yang dilindungi dengan serangan atau mantra berbahaya harus terlebih dahulu melakukan lemparan penyelamatan kebijaksanaan. Jika penyelamatan gagal, makhluk tersebut harus memilih target baru atau kehilangan serangan atau mantranya. Mantra ini tidak melindungi makhluk yang dilindungi dari efek area, seperti ledakan bola api.\nJika makhluk yang dilindungi melakukan serangan atau merapal mantra yang mengenai makhluk musuh, mantra ini berakhir." },
      { name: "Shield of Faith", components: "V, S, M", desc: "Bidang berkilauan muncul dan mengelilingi makhluk pilihan Anda dalam jangkauan, memberinya bonus +2 AC selama durasi tersebut." },
    ],
    Level2: [
      { name: "Aid", components: "V, S, M", desc: "Mantra Anda memperkuat sekutu Anda dengan ketangguhan dan keteguhan hati. Pilih hingga tiga makhluk dalam jangkauan. Hit point maksimum dan hit point saat ini setiap target meningkat sebesar 5 selama durasi tersebut.\nSaat Anda mengucapkan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, poin hit target meningkat sebanyak 5 tambahan untuk setiap level slot di atas level 2." },
      { name: "Augury", components: "V, S, M", desc: "Dengan melemparkan tongkat bertatahkan permata, menggulung tulang naga, meletakkan kartu hiasan, atau menggunakan alat ramalan lainnya, Anda menerima pertanda dari entitas dunia lain tentang hasil dari tindakan tertentu yang Anda rencanakan untuk diambil dalam 30 menit ke depan. GM memilih dari kemungkinan pertanda berikut:\n- Ya ampun, untuk hasil yang bagus\n- Celakalah, untuk hasil yang buruk\n- Suka dan duka, untuk hasil yang baik dan buruk\n- Tidak ada, untuk hasil yang tidak terlalu baik atau buruk\nMantra tersebut tidak memperhitungkan kemungkinan keadaan yang dapat mengubah hasil, seperti penggunaan mantra tambahan atau kehilangan atau perolehan rekan.\nJika Anda merapal mantra dua kali atau lebih sebelum menyelesaikan istirahat panjang berikutnya, ada peluang kumulatif 25 persen untuk setiap casting setelah yang pertama Anda mendapatkan pembacaan acak. GM melakukan hal ini secara rahasia." },
      { name: "Blindness/Deafness", components: "V", desc: "Anda bisa membutakan atau menulikan musuh. Pilih satu makhluk yang dapat Anda lihat dalam jangkauan untuk melakukan penyelamatan konstitusi. Jika gagal, target akan menjadi buta atau tuli (pilihan Anda) selama durasi tersebut. Di akhir setiap giliran, target dapat melakukan penyelamatan konstitusi. Jika berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Calm Emotions", components: "V, S", desc: "Anda berusaha menekan emosi yang kuat dalam sekelompok orang. Setiap humanoid dalam bola berradius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan harus melakukan lemparan penyelamatan karisma; makhluk dapat memilih untuk gagal dalam penyelamatan ini jika ia menginginkannya. Jika makhluk gagal dalam penyelamatannya, pilih salah satu dari dua efek berikut. Anda dapat menekan efek apa pun yang menyebabkan target terpesona atau ketakutan. Saat mantra ini berakhir, semua efek yang ditekan akan dilanjutkan, asalkan durasinya belum habis untuk sementara waktu.\nAlternatifnya, Anda dapat membuat target acuh tak acuh terhadap makhluk pilihan Anda yang dimusuhinya. Ketidakpedulian ini berakhir jika target diserang atau disakiti oleh mantra atau jika ia menyaksikan salah satu temannya disakiti. Saat mantranya berakhir, makhluk itu menjadi bermusuhan lagi, kecuali GM mengatur sebaliknya." },
      { name: "Continual Flame", components: "V, S, M", desc: "Nyala api, yang kecerahannya setara dengan obor, muncul dari benda yang Anda sentuh. Efeknya terlihat seperti nyala api biasa, namun tidak menimbulkan panas dan tidak menggunakan oksigen. Nyala api yang terus-menerus dapat ditutupi atau disembunyikan tetapi tidak dapat dipadamkan atau dipadamkan." },
      { name: "Enhance Ability", components: "V, S, M", desc: "Anda menyentuh makhluk dan memberinya peningkatan ajaib. Pilih salah satu dari efek berikut; target mendapatkan efek itu hingga mantranya berakhir.\n***Daya Tahan Beruang.*** Targetnya memiliki keunggulan dalam pemeriksaan konstitusi. Ia juga mendapatkan 2d6 poin hit sementara, yang hilang saat mantranya berakhir.\n***Kekuatan Banteng.*** Target memiliki keunggulan dalam pemeriksaan kekuatan, dan daya dukungnya berlipat ganda.\n***Rahmat Kucing.*** Target memiliki keunggulan dalam pemeriksaan ketangkasan. Ia juga tidak menerima kerusakan jika terjatuh dari ketinggian 20 kaki atau kurang jika tidak dilumpuhkan.\n***Kemegahan Elang.*** Target memiliki keunggulan dalam pemeriksaan Karisma.\n***Kelicikan Rubah.*** Targetnya memiliki keunggulan dalam pemeriksaan intelijen.\n***Kebijaksanaan Burung Hantu.*** Target memiliki keuntungan dalam pemeriksaan kebijaksanaan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Find Traps", components: "V, S", desc: "Anda merasakan adanya jebakan apa pun dalam jangkauan yang berada dalam jarak pandang. Jebakan, untuk tujuan mantra ini, mencakup segala sesuatu yang dapat menimbulkan efek tiba-tiba atau tidak terduga yang Anda anggap berbahaya atau tidak diinginkan, yang secara khusus dimaksudkan oleh penciptanya. Dengan demikian, mantra tersebut akan mendeteksi area yang terkena mantra alarm, mesin terbang penangkal, atau jebakan lubang mekanis, namun tidak akan mengungkapkan kelemahan alami di lantai, langit-langit yang tidak stabil, atau lubang pembuangan yang tersembunyi.\nMantra ini hanya mengungkapkan bahwa ada jebakan. Anda tidak mempelajari lokasi setiap jebakan, namun Anda mempelajari sifat umum bahaya yang ditimbulkan oleh jebakan yang Anda rasakan." },
      { name: "Gentle Repose", components: "V, S, M", desc: "Anda menyentuh mayat atau sisa-sisa lainnya. Selama durasi tersebut, target terlindungi dari pembusukan dan tidak bisa menjadi undead.\nMantra ini juga secara efektif memperpanjang batas waktu untuk membangkitkan target dari kematian, karena hari-hari yang dihabiskan di bawah pengaruh mantra ini tidak dihitung terhadap batas waktu mantra seperti membangkitkan orang mati." },
      { name: "Hold Person", components: "V, S, M", desc: "Pilih humanoid yang dapat Anda lihat dalam jangkauan. Target harus berhasil melakukan penyelamatan kebijaksanaan atau menjadi lumpuh selama jangka waktu tersebut. Di akhir setiap giliran, target dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, mantranya berakhir tepat sasaran.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu humanoid tambahan untuk setiap slot level di atas 2. Humanoid harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkannya." },
      { name: "Lesser Restoration", components: "V, S", desc: "Anda menyentuh suatu makhluk dan dapat mengakhiri satu penyakit atau satu kondisi yang menimpanya. Kondisinya bisa menjadi buta, tuli, lumpuh, atau keracunan." },
      { name: "Locate Object", components: "V, S, M", desc: "Jelaskan atau beri nama suatu objek yang Anda kenal. Anda merasakan arah ke lokasi objek, selama objek tersebut berada dalam jarak 1.000 kaki dari Anda. Jika suatu benda bergerak, maka diketahui arah pergerakannya.\nMantra tersebut dapat menemukan lokasi objek tertentu yang Anda kenal, selama Anda telah melihatnya dari dekat--dalam jarak 30 kaki--setidaknya sekali. Alternatifnya, mantra tersebut dapat menemukan lokasi objek terdekat dari jenis tertentu, seperti jenis pakaian, perhiasan, furnitur, perkakas, atau senjata tertentu.\nMantra ini tidak dapat menemukan lokasi suatu objek jika ada timah tebal, bahkan lembaran tipis, menghalangi jalur langsung antara Anda dan objek tersebut." },
      { name: "Prayer of Healing", components: "V", desc: "Hingga enam makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan, masing-masing mendapatkan kembali poin hit yang setara dengan 2d8 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, penyembuhan meningkat sebesar 1d8 untuk setiap slot level di atas 2." },
      { name: "Protection from Poison", components: "V, S", desc: "Anda menyentuh makhluk. Jika diracuni, Anda menetralisir racunnya. Jika lebih dari satu racun menimpa target, Anda menetralisir satu racun yang Anda tahu ada, atau Anda menetralisir satu racun secara acak.\nSelama durasi tersebut, target memiliki keuntungan dalam menyimpan lemparan agar tidak terkena racun, dan memiliki ketahanan terhadap kerusakan akibat racun." },
      { name: "Silence", components: "V, S", desc: "Selama durasi tersebut, tidak ada suara yang dapat dihasilkan di dalam atau melewati bola berradius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan. Makhluk atau benda apa pun yang seluruhnya berada di dalam bola kebal terhadap kerusakan akibat petir, dan makhluk menjadi tuli saat berada sepenuhnya di dalamnya.\nMerapalkan mantra yang mencakup komponen verbal tidak mungkin dilakukan di sana." },
      { name: "Spiritual Weapon", components: "V, S", desc: "Anda membuat senjata spektral mengambang dalam jangkauan yang bertahan selama atau hingga Anda mengucapkan mantra ini lagi. Saat Anda merapal mantra, Anda dapat melakukan serangan mantra jarak dekat terhadap makhluk dalam jarak 5 kaki dari senjata. Saat terkena, target menerima kekuatan kerusakan sebesar 1d8 + pengubah kemampuan perapalan mantra Anda.\nSebagai aksi bonus pada giliran Anda, Anda dapat menggerakkan senjata hingga jarak 20 kaki dan mengulangi serangan terhadap makhluk dalam jarak 5 kaki darinya.\nSenjata itu bisa berbentuk apa pun yang Anda pilih. Ulama dewa yang diasosiasikan dengan senjata tertentu (seperti St. Cuthbert dikenal dengan tongkatnya dan Thor karena palunya) membuat efek mantra ini menyerupai senjata itu.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap dua level slot di atas level 2." },
      { name: "Warding Bond", components: "V, S, M", desc: "Mantra ini melindungi makhluk yang ingin Anda sentuh dan menciptakan hubungan mistik antara Anda dan target hingga mantranya berakhir. Saat target berada dalam jarak 60 kaki dari Anda, ia memperoleh bonus +1 untuk AC dan penyelamatan lemparan, serta memiliki ketahanan terhadap semua kerusakan. Selain itu, setiap kali menerima kerusakan, Anda menerima jumlah kerusakan yang sama.\nMantra berakhir jika poin hit Anda turun hingga 0 atau jika Anda dan target terpisah lebih dari 60 kaki.\nItu juga berakhir jika mantra itu diucapkan lagi pada salah satu makhluk yang terhubung. Anda juga dapat mengabaikan mantra tersebut sebagai suatu tindakan." },
      { name: "Zone of Truth", components: "V, S", desc: "Anda menciptakan zona ajaib yang melindungi dari penipuan dalam bola berradius 15 kaki yang berpusat pada titik pilihan Anda dalam jangkauan. Hingga mantranya berakhir, makhluk yang memasuki area mantra untuk pertama kalinya pada suatu giliran atau memulai gilirannya di sana harus melakukan lemparan penyelamatan Karisma. Jika penyelamatan gagal, makhluk tidak dapat mengucapkan kebohongan yang disengaja saat berada dalam radius. Anda tahu apakah setiap makhluk berhasil atau gagal dalam penyelamatannya.\nMakhluk yang terkena dampak menyadari mantra tersebut dan dengan demikian dapat menghindari menjawab pertanyaan yang biasanya ditanggapi dengan kebohongan. Makhluk seperti itu bisa saja tetap mengelak dalam menjawab selama masih dalam batas-batas kebenaran." },
    ],
    Level3: [
      { name: "Animate Dead", components: "V, S, M", desc: "Mantra ini menciptakan pelayan undead. Pilih tumpukan tulang atau mayat humanoid Sedang atau Kecil dalam jangkauan. Mantra Anda mengilhami target dengan mimikri kehidupan yang buruk, mengangkatnya sebagai makhluk undead. Targetnya menjadi kerangka jika Anda memilih tulang atau zombie jika Anda memilih mayat (GM memiliki statistik permainan makhluk tersebut).\nDi setiap giliran Anda, Anda dapat menggunakan tindakan bonus untuk secara mental memerintahkan makhluk apa pun yang Anda buat dengan mantra ini jika makhluk itu berada dalam jarak 60 kaki dari Anda (jika Anda mengendalikan beberapa makhluk, Anda dapat memerintahkan salah satu atau semuanya secara bersamaan, mengeluarkan perintah yang sama untuk masing-masing makhluk). Anda memutuskan tindakan apa yang akan diambil makhluk itu dan ke mana ia akan bergerak pada giliran berikutnya, atau Anda dapat mengeluarkan perintah umum, seperti menjaga ruangan atau koridor tertentu. Jika Anda tidak mengeluarkan perintah, makhluk itu hanya akan mempertahankan diri dari makhluk musuh. Setelah diberi perintah, makhluk tersebut terus mengikutinya hingga tugasnya selesai.\nMakhluk itu berada di bawah kendali Anda selama 24 jam, setelah itu ia berhenti mematuhi perintah apa pun yang Anda berikan. Untuk mempertahankan kendali atas makhluk tersebut selama 24 jam berikutnya, Anda harus mengucapkan mantra ini lagi pada makhluk tersebut sebelum periode 24 jam saat ini berakhir. Penggunaan mantra ini menegaskan kembali kendali Anda atas hingga empat makhluk yang telah Anda animasikan dengan mantra ini, daripada menganimasikan makhluk baru.\nSaat Anda mengucapkan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda menganimasikan atau menegaskan kembali kendali atas dua makhluk undead tambahan untuk setiap slot level di atas 3. Masing-masing makhluk tersebut pasti berasal dari bangkai atau tumpukan tulang yang berbeda-beda." },
      { name: "Beacon of Hope", components: "V, S", desc: "Mantra ini memberikan harapan dan vitalitas. Pilih sejumlah makhluk dalam jangkauan. Selama durasi tersebut, setiap target memiliki keuntungan pada lemparan penyelamatan kebijaksanaan dan lemparan penyelamatan kematian, dan mendapatkan kembali jumlah poin serangan maksimum yang mungkin diperoleh dari penyembuhan apa pun." },
      { name: "Bestow Curse", components: "V, S", desc: "Anda menyentuh makhluk, dan makhluk itu harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau menjadi terkutuk selama durasi mantra. Saat Anda mengucapkan mantra ini, pilih sifat kutukan dari opsi berikut:\n- Pilih satu skor kemampuan. Saat dikutuk, target memiliki kelemahan pada pemeriksaan kemampuan dan penyelamatan yang dilakukan dengan skor kemampuan tersebut.\n- Saat dikutuk, target memiliki kelemahan saat serangan bergulir ke arahmu.\n- Saat dikutuk, target harus melakukan lemparan penyelamatan kebijaksanaan di awal setiap putarannya. Jika gagal, tindakannya sia-sia dan tidak melakukan apa-apa.\n- Saat target dikutuk, serangan dan mantramu memberikan tambahan kerusakan nekrotik sebesar 1d8 ke target.\nMantra penghapus kutukan mengakhiri efek ini. Berdasarkan pilihan GM, Anda dapat memilih efek kutukan alternatif, tetapi efek kutukan tersebut tidak boleh lebih kuat dari yang dijelaskan di atas. GM mempunyai keputusan akhir mengenai dampak kutukan tersebut.\nLevel Tinggi: Jika Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, durasinya adalah konsentrasi, hingga 10 menit. Jika Anda menggunakan slot mantra level 5 atau lebih tinggi, durasinya adalah 8 jam. Jika Anda menggunakan slot mantra level 7 atau lebih tinggi, durasinya adalah 24 jam. Jika Anda menggunakan slot mantra level 9, mantra tersebut bertahan hingga dihilangkan. Menggunakan slot mantra level 5 atau lebih tinggi memberikan durasi yang tidak memerlukan konsentrasi." },
      { name: "Clairvoyance", components: "V, S, M", desc: "Anda membuat sensor tak kasat mata dalam jangkauan di lokasi yang familier bagi Anda (tempat yang pernah Anda kunjungi atau lihat sebelumnya) atau di lokasi jelas yang asing bagi Anda (seperti di balik pintu, di sudut, atau di rerimbunan pepohonan). Sensor tetap di tempatnya selama durasi tersebut, dan tidak dapat diserang atau berinteraksi dengannya.\nSaat Anda merapal mantra, Anda memilih melihat atau mendengar. Anda dapat menggunakan indra yang dipilih melalui sensor seolah-olah Anda berada di ruangnya. Saat tindakan Anda, Anda dapat beralih antara melihat dan mendengar.\nMakhluk yang dapat melihat sensor (seperti makhluk yang mendapat manfaat dari melihat tembus pandang atau penglihatan nyata) melihat bola bercahaya dan tidak berwujud seukuran kepalan tangan Anda." },
      { name: "Create Food and Water", components: "V, S", desc: "Anda menghasilkan 45 pon makanan dan 30 galon air di tanah atau di dalam wadah dalam jangkauan, cukup untuk menopang hingga lima belas humanoid atau lima kuda selama 24 jam. Makanannya hambar namun bergizi, dan akan rusak jika tidak dimakan setelah 24 jam. Airnya bersih dan tidak busuk." },
      { name: "Daylight", components: "V, S", desc: "Bola cahaya dengan radius 60 kaki menyebar dari titik yang Anda pilih dalam jangkauannya. Bola tersebut memiliki cahaya terang dan memancarkan cahaya redup sejauh 60 kaki.\nJika Anda memilih suatu titik pada suatu benda yang Anda pegang atau yang tidak sedang dipakai atau dibawa, cahaya akan bersinar dari benda tersebut dan bergerak bersamanya. Menutupi seluruh objek yang terkena dengan benda buram, seperti mangkuk atau helm, akan menghalangi cahaya.\nJika salah satu area mantra ini tumpang tindih dengan area kegelapan yang diciptakan oleh mantra level 3 atau lebih rendah, mantra yang menciptakan kegelapan tersebut akan hilang." },
      { name: "Dispel Magic", components: "V, S", desc: "Pilih satu makhluk, objek, atau efek magis dalam jangkauan. Mantra level 3 atau lebih rendah pada target akan berakhir. Untuk setiap mantra level 4 atau lebih tinggi pada target, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika pemeriksaan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda secara otomatis mengakhiri efek mantra pada target jika level mantra sama dengan atau kurang dari level slot mantra yang Anda gunakan." },
      { name: "Glyph of Warding", components: "V, S, M", desc: "Saat Anda mengucapkan mantra ini, Anda menuliskan mesin terbang yang membahayakan makhluk lain, baik di permukaan (seperti meja atau bagian lantai atau dinding) atau di dalam objek yang dapat ditutup (seperti buku, gulungan, atau peti harta karun) untuk menyembunyikan mesin terbang tersebut. Jika Anda memilih suatu permukaan, mesin terbang tersebut dapat menutupi area permukaan yang diameternya tidak lebih dari 10 kaki. Jika Anda memilih suatu benda, benda itu harus tetap berada di tempatnya; jika objek dipindahkan lebih dari 10 kaki dari tempat Anda mengucapkan mantra ini, mesin terbangnya rusak, dan mantranya berakhir tanpa terpicu.\nMesin terbang tersebut hampir tidak terlihat dan memerlukan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap penyimpanan mantra DC Anda agar dapat ditemukan.\nAnda memutuskan apa yang memicu mesin terbang saat Anda mengucapkan mantranya. Untuk mesin terbang yang tertulis di suatu permukaan, pemicu yang paling umum adalah menyentuh atau berdiri di atas mesin terbang tersebut, memindahkan objek lain yang menutupi mesin terbang tersebut, mendekati dalam jarak tertentu dari mesin terbang tersebut, atau memanipulasi objek yang di atasnya mesin terbang tersebut ditorehkan. Untuk mesin terbang yang tertulis di dalam suatu objek, pemicu paling umum termasuk membuka objek tersebut, mendekati objek dalam jarak tertentu, atau melihat atau membaca mesin terbang tersebut. Setelah mesin terbang dipicu, mantra ini berakhir.\nAnda dapat menyempurnakan pemicunya lebih lanjut sehingga mantranya hanya aktif dalam keadaan tertentu atau berdasarkan karakteristik fisik (seperti tinggi atau berat), jenis makhluk (misalnya, lingkungan dapat diatur untuk memengaruhi penyimpangan atau tenggelam), atau penyelarasan. Anda juga dapat mengatur kondisi untuk makhluk yang tidak memicu mesin terbang, misalnya makhluk yang mengucapkan kata sandi tertentu.\nSaat Anda menuliskan mesin terbang, pilih *rune eksplosif* atau *mesin terbang mantra*.\n***Rune Peledak.*** Saat dipicu, mesin terbang tersebut meletus dengan energi magis dalam bola radius 20 kaki yang berpusat pada mesin terbang tersebut. Bola itu menyebar ke berbagai sudut. Setiap makhluk di area tersebut harus melakukan lemparan penyelamatan Dexterity. Makhluk menerima 5d8 kerusakan asam, dingin, api, kilat, atau guntur pada lemparan penyelamatan yang gagal (pilihan Anda saat membuat mesin terbang), atau setengah dari kerusakan pada lemparan penyelamatan yang berhasil.\n***Spell Glyph.*** Anda dapat menyimpan mantra level 3 atau lebih rendah yang telah disiapkan di mesin terbang dengan melemparkannya sebagai bagian dari pembuatan mesin terbang. Mantra tersebut harus menargetkan satu makhluk atau suatu area. Mantra yang disimpan tidak memiliki efek langsung saat digunakan dengan cara ini. Saat mesin terbang dipicu, mantra yang disimpan akan dilemparkan. Jika mantra memiliki target, mantra tersebut menargetkan makhluk yang memicu mesin terbang tersebut. Jika mantra mempengaruhi suatu area, area tersebut berpusat pada makhluk tersebut. Jika mantra tersebut memanggil makhluk bermusuhan atau membuat objek atau jebakan berbahaya, mereka akan muncul sedekat mungkin dengan penyusup dan menyerangnya. Jika mantra membutuhkan konsentrasi, mantra itu bertahan hingga durasi penuhnya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan mesin terbang rune eksplosif meningkat sebesar 1d8 untuk setiap level slot di atas 3. Jika Anda membuat mesin terbang mantra, Anda dapat menyimpan mantra apa pun hingga tingkat yang sama dengan slot yang Anda gunakan untuk mesin terbang penangkal." },
      { name: "Magic Circle", components: "V, S, M", desc: "Anda membuat silinder energi magis dengan radius 10 kaki dan tinggi 20 kaki yang berpusat pada suatu titik di tanah yang dapat Anda lihat dalam jangkauan. Rune bercahaya muncul setiap kali silinder berpotongan dengan lantai atau permukaan lainnya.\nPilih satu atau lebih jenis makhluk berikut: selestial, elemental, fey, iblis, atau undead. Lingkaran mempengaruhi makhluk dari tipe yang dipilih dengan cara berikut:\n- Makhluk itu tidak bisa dengan sukarela memasuki silinder dengan cara non-magis. Jika makhluk tersebut mencoba menggunakan teleportasi atau perjalanan antarplanar untuk melakukannya, ia harus berhasil melakukan lemparan penyelamatan karisma terlebih dahulu.\n- Makhluk tersebut memiliki kelemahan dalam serangan berguling terhadap target di dalam silinder.\n- Target di dalam silinder tidak dapat dipesona, ditakuti, atau dirasuki oleh makhluk tersebut.\nSaat Anda mengucapkan mantra ini, Anda dapat memilih untuk membuat sihirnya beroperasi ke arah sebaliknya, mencegah makhluk bertipe tertentu meninggalkan silinder dan melindungi target di luarnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, durasinya bertambah 1 jam untuk setiap slot level di atas 3." },
      { name: "Mass Healing Word", components: "V", desc: "Saat Anda mengucapkan kata-kata pemulihan, hingga enam makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan mendapatkan kembali poin serangan yang setara dengan 1d4 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, penyembuhan meningkat sebesar 1d4 untuk setiap slot level di atas 3." },
      { name: "Meld Into Stone", components: "V, S", desc: "Anda melangkah ke dalam benda atau permukaan batu yang cukup besar untuk menampung tubuh Anda sepenuhnya, menyatukan diri Anda dan semua peralatan yang Anda bawa dengan batu tersebut selama durasi tersebut. Dengan menggunakan gerakan Anda, Anda melangkah ke dalam batu pada titik yang dapat Anda sentuh. Tidak ada satu pun dari kehadiran Anda yang terlihat atau terdeteksi oleh indera non-magis.\nSaat menyatu dengan batu, Anda tidak dapat melihat apa yang terjadi di luarnya, dan pemeriksaan Kebijaksanaan (Persepsi) apa pun yang Anda lakukan untuk mendengar suara di luarnya dibuat dengan kerugian. Anda tetap sadar akan berlalunya waktu dan dapat merapal mantra pada diri Anda sendiri saat menyatu di dalam batu. Anda dapat menggunakan gerakan Anda untuk meninggalkan batu tempat Anda memasukkannya, yang mengakhiri mantranya. Jika tidak, Anda tidak bisa bergerak.\nKerusakan fisik kecil pada batu tidak membahayakan Anda, tetapi kehancuran sebagian atau perubahan bentuknya (sejauh Anda tidak lagi muat di dalamnya) mengeluarkan Anda dan menyebabkan kerusakan 6d6 pada Anda. Penghancuran total batu tersebut (atau transmutasi menjadi zat lain) akan mengeluarkan Anda dan menyebabkan 50 kerusakan besar pada Anda. Jika diusir, Anda akan rawan terjatuh di ruang kosong yang paling dekat dengan tempat Anda pertama kali masuk." },
      { name: "Protection From Energy", components: "V, S", desc: "Selama durasi tersebut, makhluk yang Anda sentuh memiliki ketahanan terhadap satu jenis kerusakan pilihan Anda: asam, dingin, api, kilat, atau guntur." },
      { name: "Remove Curse", components: "V, S", desc: "Dengan sentuhan Anda, semua kutukan yang memengaruhi satu makhluk atau objek berakhir. Jika benda tersebut merupakan benda sihir terkutuk, kutukannya tetap ada, tetapi mantranya merusak attunement pemiliknya terhadap benda tersebut sehingga dapat dikeluarkan atau dibuang." },
      { name: "Revivify", components: "V, S, M", desc: "Anda menyentuh makhluk yang telah mati dalam satu menit terakhir. Makhluk itu hidup kembali dengan 1 hit point. Mantra ini tidak dapat menghidupkan kembali makhluk yang mati karena usia tua, juga tidak dapat memulihkan bagian tubuh yang hilang." },
      { name: "Sending", components: "V, S, M", desc: "Anda mengirim pesan singkat yang terdiri dari dua puluh lima kata atau kurang kepada makhluk yang Anda kenal. Makhluk itu mendengar pesan dalam pikirannya, mengenali Anda sebagai pengirimnya jika ia mengenal Anda, dan dapat segera menjawab dengan cara yang sama. Mantra ini memungkinkan makhluk dengan skor Intelegensi minimal 1 untuk memahami maksud pesan Anda.\nAnda dapat mengirim pesan melintasi jarak berapa pun dan bahkan ke alam eksistensi lain, namun jika target berada di alam yang berbeda dari Anda, ada kemungkinan 5 persen pesan tersebut tidak sampai." },
      { name: "Speak with Dead", components: "V, S, M", desc: "Anda memberikan kemiripan kehidupan dan kecerdasan pada mayat pilihan Anda dalam jangkauan, memungkinkannya menjawab pertanyaan yang Anda ajukan. Mayat itu pasti masih memiliki mulut dan tidak boleh menjadi undead. Mantra tersebut gagal jika mayat menjadi target mantra ini dalam 10 hari terakhir.\nHingga mantranya berakhir, Anda dapat menanyakan hingga lima pertanyaan kepada mayat tersebut. Mayat hanya mengetahui apa yang diketahuinya dalam kehidupan, termasuk bahasa yang diketahuinya. Jawaban biasanya singkat, samar, atau berulang-ulang, dan jenazah tidak berkewajiban untuk memberikan jawaban yang jujur ​​jika Anda memusuhinya atau jenazah mengakui Anda sebagai musuh. Mantra ini tidak mengembalikan jiwa makhluk ke tubuhnya, hanya roh yang menjiwainya. Dengan demikian, jenazah tidak dapat mempelajari informasi baru, tidak dapat memahami apa pun yang telah terjadi sejak ia meninggal, dan tidak dapat berspekulasi tentang kejadian di masa depan." },
      { name: "Spirit Guardians", components: "V, S, M", desc: "Anda memanggil roh untuk melindungi Anda. Mereka terbang mengelilingi Anda hingga jarak 15 kaki selama durasi tersebut. Jika Anda baik atau netral, bentuk spektralnya tampak seperti malaikat atau anggun (pilihan Anda). Jika Anda jahat, mereka tampak jahat.\nSaat Anda mengucapkan mantra ini, Anda dapat menentukan sejumlah makhluk yang Anda lihat tidak terpengaruh olehnya. Kecepatan makhluk yang terkena dampak akan berkurang setengahnya di area tersebut, dan saat makhluk tersebut memasuki area tersebut untuk pertama kalinya pada suatu belokan atau memulai belokannya di sana, ia harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, makhluk tersebut menerima kerusakan radiasi 3d8 (jika Anda baik atau netral) atau kerusakan nekrotik 3d8 (jika Anda jahat). Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 3." },
      { name: "Tongues", components: "V, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk memahami bahasa lisan apa pun yang didengarnya. Terlebih lagi, ketika target berbicara, makhluk apa pun yang mengetahui setidaknya satu bahasa dan dapat mendengar target akan memahami apa yang dikatakannya." },
      { name: "Water Walk", components: "V, S, M", desc: "Mantra ini memberikan kemampuan untuk bergerak melintasi permukaan cair apa pun--seperti air, asam, lumpur, salju, pasir hisap, atau lava--seolah-olah permukaan tersebut adalah tanah padat yang tidak berbahaya (makhluk yang melintasi lava cair masih dapat menerima kerusakan akibat panas). Hingga sepuluh makhluk yang dapat Anda lihat dalam jangkauan mendapatkan kemampuan ini selama durasi tersebut.\nJika Anda menargetkan makhluk yang terendam dalam cairan, mantranya akan membawa target ke permukaan cairan dengan kecepatan 60 kaki per putaran." },
    ],
    Level4: [
      { name: "Arcane Eye", components: "V, S, M", desc: "Anda menciptakan mata ajaib yang tidak terlihat dalam jangkauan yang melayang di udara selama durasi tersebut.\nAnda secara mental menerima informasi visual dari mata, yang memiliki penglihatan normal dan penglihatan gelap hingga jarak 30 kaki. Mata bisa melihat ke segala arah.\nSebagai tindakan, Anda bisa menggerakkan mata hingga 30 kaki ke segala arah. Tidak ada batasan seberapa jauh mata dapat bergerak dari Anda, namun mata tidak dapat memasuki alam eksistensi lain. Sebuah penghalang padat menghalangi pergerakan mata, namun mata dapat melewati lubang berdiameter sekecil 1 inci." },
      { name: "Banishment", components: "V, S, M", desc: "Anda mencoba mengirim satu makhluk yang dapat Anda lihat dalam jangkauannya ke alam eksistensi lain. Targetnya harus berhasil dalam penyelamatan karisma atau diasingkan.\nJika targetnya berasal dari alam eksistensi yang Anda tempati, Anda membuang target tersebut ke demiplane yang tidak berbahaya. Saat berada di sana, targetnya tidak berdaya. Target tetap di sana sampai mantranya berakhir, pada saat itu target muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi.\nJika target berasal dari alam eksistensi yang berbeda dari tempat Anda berada, target akan dibuang dengan suara letupan samar, dan kembali ke alam asalnya. Jika mantra berakhir sebelum 1 menit berlalu, target akan muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi. Jika tidak, targetnya tidak akan kembali.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 4." },
      { name: "Control Water", components: "V, S, M", desc: "Hingga mantranya berakhir, Anda mengontrol air yang berdiri sendiri di dalam area yang Anda pilih, yaitu kubus dengan tinggi hingga 100 kaki di sisinya. Anda dapat memilih salah satu efek berikut saat menggunakan mantra ini. Sebagai tindakan pada giliran Anda, Anda dapat mengulangi efek yang sama atau memilih efek yang berbeda.\n***Banjir.*** Anda menyebabkan permukaan air di semua genangan air di area tersebut naik sebanyak 20 kaki. Jika wilayah tersebut termasuk pantai, maka air banjir akan meluap ke daratan kering.\nJika Anda memilih suatu area di perairan yang luas, Anda malah menciptakan gelombang setinggi 20 kaki yang bergerak dari satu sisi area ke sisi lainnya dan kemudian jatuh. Kendaraan besar atau kecil apa pun yang berada di jalur gelombang akan terbawa ke sisi lain. Kendaraan besar atau kecil apa pun yang terkena gelombang mempunyai peluang 25 persen untuk terbalik.\nKetinggian air tetap tinggi hingga mantra berakhir atau Anda memilih efek lain. Jika efek ini menghasilkan gelombang, gelombang tersebut akan berulang pada awal giliran Anda berikutnya selama efek banjir berlangsung.\n***Bagian Air.*** Anda menyebabkan air di area tersebut menjauh dan membuat parit. Parit tersebut membentang melintasi area mantra, dan air yang terpisah membentuk dinding di kedua sisinya. Parit tetap ada sampai mantranya berakhir atau Anda memilih efek yang berbeda. Air kemudian perlahan-lahan mengisi parit selama putaran berikutnya sampai ketinggian air kembali normal.\n***Aliran Pengalihan.*** Anda menyebabkan air yang mengalir di area tersebut bergerak ke arah yang Anda pilih, meskipun air harus mengalir melewati rintangan, ke atas tembok, atau ke arah lain yang tidak terduga. Air di area tersebut bergerak saat Anda mengarahkannya, tetapi setelah bergerak melampaui area mantra, air tersebut melanjutkan alirannya berdasarkan kondisi medan. Air terus bergerak ke arah yang Anda pilih hingga mantranya berakhir atau Anda memilih efek yang berbeda.\n***Whirlpool.*** Efek ini memerlukan badan air setidaknya 50 kaki persegi dan kedalaman 25 kaki. Anda menyebabkan pusaran air terbentuk di tengah area. Pusaran air tersebut membentuk pusaran dengan lebar dasar 5 kaki, lebar bagian atas hingga 50 kaki, dan tinggi 25 kaki. Makhluk atau benda apa pun di dalam air dan dalam jarak 25 kaki dari pusaran akan ditarik sejauh 10 kaki ke arahnya. Makhluk dapat berenang menjauh dari pusaran dengan melakukan pemeriksaan Kekuatan (Atletik) terhadap mantra Anda, simpan DC.\nKetika makhluk memasuki pusaran untuk pertama kalinya pada suatu belokan atau memulai belokannya di sana, ia harus melakukan lemparan yang menghemat kekuatan. Jika penyelamatan gagal, makhluk itu menerima kerusakan sebesar 2d8 dan terjebak dalam pusaran hingga mantranya berakhir. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan, dan tidak terjebak dalam pusaran. Makhluk yang terjebak dalam pusaran dapat menggunakan aksinya untuk mencoba berenang menjauh dari pusaran seperti dijelaskan di atas, namun memiliki kelemahan pada pemeriksaan Kekuatan (Atletik) untuk melakukannya.\nPertama kali setiap putaran suatu benda memasuki pusaran, benda tersebut menerima kerusakan pukulan sebesar 2d8; kerusakan ini terjadi setiap putarannya tetap berada di pusaran." },
      { name: "Death Ward", components: "V, S", desc: "Anda menyentuh makhluk dan memberinya perlindungan dari kematian.\nPertama kali target turun menjadi 0 poin hit akibat menerima kerusakan, target malah turun menjadi 1 poin hit, dan mantra berakhir.\nJika mantra masih berlaku saat target terkena efek yang akan membunuhnya secara instan tanpa menimbulkan kerusakan, efek tersebut akan dinegasikan terhadap target, dan mantra akan berakhir." },
      { name: "Freedom of Movement", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia. Selama durasi tersebut, pergerakan target tidak terpengaruh oleh medan yang sulit, dan mantra serta efek magis lainnya tidak dapat mengurangi kecepatan target atau menyebabkan target menjadi lumpuh atau tertahan.\nTarget juga dapat menggunakan gerakan sejauh 5 kaki untuk secara otomatis melarikan diri dari pengekangan non-magis, seperti borgol atau makhluk yang digenggamnya. Terakhir, berada di bawah air tidak memberikan penalti pada pergerakan atau serangan target." },
      { name: "Guardian of Faith", components: "V", desc: "Penjaga spektral besar muncul dan melayang selama durasi di ruang kosong pilihan Anda yang dapat Anda lihat dalam jangkauan. Penjaga menempati ruang itu dan tidak terlihat jelas kecuali pedang dan perisai berkilau yang dihiasi simbol keilahian Anda.\nMakhluk apa pun yang memusuhi Anda yang bergerak ke jarak 10 kaki dari penjaga untuk pertama kalinya pada suatu giliran harus berhasil dalam lemparan penyelamatan ketangkasan. Makhluk itu menerima 20 damage besar pada penyelamatan yang gagal, atau setengah damage pada penyelamatan yang berhasil. Penjaga menghilang ketika telah memberikan total 60 kerusakan." },
      { name: "Locate Creature", components: "V, S, M", desc: "Jelaskan atau beri nama makhluk yang Anda kenal. Anda merasakan arah ke lokasi makhluk itu, selama makhluk itu berada dalam jarak 1.000 kaki dari Anda. Jika makhluk itu bergerak, Anda mengetahui arah pergerakannya.\nMantra ini dapat menemukan lokasi makhluk tertentu yang Anda kenal, atau makhluk terdekat dari jenis tertentu (seperti manusia atau unicorn), selama Anda pernah melihat makhluk tersebut dari dekat--dalam jarak 30 kaki--setidaknya sekali. Jika makhluk yang Anda gambarkan atau beri nama berada dalam bentuk yang berbeda, seperti berada di bawah pengaruh mantra polimorf, mantra ini tidak akan menemukan lokasi makhluk tersebut.\nMantra ini tidak dapat menemukan lokasi makhluk jika air yang mengalir selebar 10 kaki menghalangi jalur langsung antara Anda dan makhluk tersebut." },
      { name: "Stone Shape", components: "V, S, M", desc: "Anda menyentuh benda batu berukuran sedang atau lebih kecil atau bagian batu tidak lebih dari 5 kaki dalam dimensi apa pun dan membentuknya menjadi bentuk apa pun yang sesuai dengan tujuan Anda. Jadi, misalnya, Anda dapat membentuk sebuah batu besar menjadi senjata, berhala, atau peti, atau membuat jalan kecil melewati dinding, asalkan tebal dinding tersebut kurang dari 5 kaki. Anda juga bisa membentuk pintu batu atau kusennya untuk menutup pintu. Objek yang Anda buat dapat memiliki hingga dua engsel dan satu kait, tetapi detail mekanis yang lebih halus tidak mungkin dilakukan." },
    ],
    Level5: [
      { name: "Commune", components: "V, S, M", desc: "Anda menghubungi dewa Anda atau wakil ilahi dan menanyakan hingga tiga pertanyaan yang dapat dijawab dengan ya atau tidak. Anda harus mengajukan pertanyaan Anda sebelum mantranya berakhir. Anda menerima jawaban yang benar untuk setiap pertanyaan.\nMakhluk ilahi belum tentu mahatahu, jadi Anda mungkin menerima jawaban \"tidak jelas\" jika pertanyaan berkaitan dengan informasi yang berada di luar pengetahuan dewa. Dalam kasus di mana jawaban satu kata bisa menyesatkan atau bertentangan dengan kepentingan dewa, GM mungkin akan menawarkan kalimat pendek sebagai jawabannya.\nJika Anda merapal mantra dua kali atau lebih sebelum menyelesaikan istirahat panjang berikutnya, ada kemungkinan kumulatif 25 persen untuk setiap casting setelah yang pertama Anda tidak mendapat jawaban. GM melakukan hal ini secara rahasia." },
      { name: "Contagion", components: "V, S", desc: "Sentuhanmu menimbulkan penyakit. Lakukan serangan mantra jarak dekat terhadap makhluk dalam jangkauan Anda. Saat terkena serangan, Anda menimpa makhluk itu dengan penyakit pilihan Anda dari salah satu penyakit yang dijelaskan di bawah ini.\nDi akhir setiap giliran sasaran, ia harus melakukan lemparan penyelamatan konstitusi. Setelah gagal dalam tiga kali penyelamatan ini, efek penyakit bertahan selama tersebut, dan makhluk tersebut berhenti melakukan penyelamatan tersebut. Setelah berhasil melakukan tiga lemparan penyelamatan ini, makhluk itu pulih dari penyakitnya, dan mantranya berakhir.\nKarena mantra ini menyebabkan penyakit alami pada targetnya, efek apa pun yang menghilangkan penyakit atau memperbaiki efek penyakit berlaku padanya.\n***Penyakit yang Membutakan.*** Rasa sakit mencengkeram pikiran makhluk itu, dan matanya berubah menjadi putih susu. Makhluk tersebut memiliki kelemahan pada pemeriksaan kebijaksanaan dan lemparan penyelamatan kebijaksanaan dan menjadi buta.\n***Demam Kotoran.*** Demam yang mengamuk melanda tubuh makhluk itu. Makhluk tersebut memiliki kelemahan dalam pemeriksaan kekuatan, lemparan hemat kekuatan, dan serangan lemparan yang menggunakan Kekuatan.\n***Daging Busuk.*** Daging makhluk itu membusuk. Makhluk ini memiliki kelemahan pada pemeriksaan Karisma dan kerentanan terhadap semua kerusakan.\n***Mindfire.*** Pikiran makhluk itu menjadi meriang. Makhluk tersebut memiliki kelemahan dalam pemeriksaan intelijen dan lemparan penyelamatan intelijen, dan makhluk tersebut berperilaku seolah-olah berada di bawah pengaruh mantra kebingungan selama pertempuran.\n***Kejang.*** Makhluk itu diliputi gemetar. Makhluk tersebut memiliki kelemahan pada dexterity check, dexterity saving throw, dan serangan roll yang menggunakan Dexterity.\n***Slimy Doom.*** Makhluk itu mulai mengeluarkan darah tak terkendali. Makhluk itu memiliki kelemahan dalam pemeriksaan konstitusi dan penyelamatan konstitusi. Selain itu, setiap kali makhluk tersebut menerima kerusakan, ia akan terkena stun hingga akhir giliran berikutnya." },
      { name: "Dispel Evil and Good", components: "V, S, M", desc: "Energi yang berkilauan mengelilingi dan melindungi Anda dari makhluk jahat, mayat hidup, dan makhluk yang berasal dari luar Alam Material. Selama durasi tersebut, Celestial, Elemental, Fey, Fiend, dan Undead memiliki kelemahan dalam serangan terhadap Anda.\nAnda dapat mengakhiri mantra lebih awal dengan menggunakan salah satu fungsi khusus berikut.\n***Hancurkan Pesona.*** Sebagai tindakan Anda, Anda menyentuh makhluk yang dapat Anda jangkau yang terpesona, ketakutan, atau dirasuki oleh makhluk surgawi, elemen, makhluk jahat, iblis, atau mayat hidup. Makhluk yang Anda sentuh tidak lagi terpesona, ditakuti, atau dirasuki oleh makhluk tersebut.\n***Pemberhentian.*** Sebagai tindakan Anda, lakukan serangan mantra jarak dekat terhadap benda langit, elemen, makhluk halus, iblis, atau mayat hidup yang dapat Anda jangkau. Jika terjadi tabrakan, Anda mencoba untuk mengarahkan makhluk itu kembali ke pesawat asalnya. Makhluk tersebut harus berhasil dalam penyelamatan karisma atau dikirim kembali ke pesawat asalnya (jika belum ada). Jika mereka tidak berada di pesawat asal, mayat hidup dikirim ke Shadowfell, dan mereka dikirim ke Feywild." },
      { name: "Flame Strike", components: "V, S, M", desc: "Kolom vertikal api ilahi mengaum turun dari langit di lokasi yang Anda tentukan. Setiap makhluk dalam silinder dengan radius 10 kaki dan tinggi 40 kaki yang berpusat pada suatu titik dalam jangkauan harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan api sebesar 4d6 dan kerusakan radiasi sebesar 4d6 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, damage api atau damage radiasi (pilihan Anda) meningkat sebesar 1d6 untuk setiap level slot di atas 5." },
      { name: "Geas", components: "V", desc: "Anda memberikan perintah magis pada makhluk yang dapat Anda lihat dalam jangkauan, memaksanya untuk melakukan suatu layanan atau menahan diri dari tindakan atau aktivitas tertentu sesuai keputusan Anda. Jika makhluk itu dapat memahami Anda, ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Meskipun makhluk itu terpesona oleh Anda, dibutuhkan 5d10 kerusakan psikis setiap kali ia bertindak berlawanan dengan instruksi Anda, tetapi tidak lebih dari sekali setiap hari. Makhluk yang tidak dapat memahami Anda tidak terpengaruh oleh mantra tersebut.\nAnda dapat mengeluarkan perintah apa pun yang Anda pilih, selain aktivitas yang akan mengakibatkan kematian. Jika Anda mengeluarkan perintah bunuh diri, mantranya akan berakhir.\nAnda dapat mengakhiri mantra lebih awal dengan menggunakan tindakan untuk mengabaikannya. Mantra penghilang kutukan, pemulihan lebih besar, atau harapan juga mengakhirinya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau 8, durasinya adalah 1 tahun. Saat Anda merapal mantra ini menggunakan slot mantra level 9, mantra tersebut akan bertahan hingga diakhiri oleh salah satu mantra yang disebutkan di atas." },
      { name: "Greater Restoration", components: "V, S, M", desc: "Anda mengilhami makhluk yang Anda sentuh dengan energi positif untuk menghilangkan efek yang melemahkan. Anda dapat mengurangi tingkat kelelahan target sebanyak satu, atau mengakhiri salah satu efek berikut pada target:\n- Satu efek yang membuat target terpesona atau membatu\n- Satu kutukan, termasuk attunement target pada item sihir terkutuk\n- Pengurangan apa pun pada salah satu skor kemampuan target\n- Satu efek mengurangi maksimum hit point target" },
      { name: "Hallow", components: "V, S, M", desc: "Anda menyentuh suatu titik dan memasukkan kekuatan suci (atau tidak suci) ke area di sekitarnya. Area tersebut dapat memiliki radius hingga 60 kaki, dan mantranya gagal jika radius tersebut mencakup area yang sudah terkena efek mantra hallow. Daerah yang terkena dampak tunduk pada efek berikut.\nPertama, benda langit, unsur, fey, iblis, dan mayat hidup tidak dapat memasuki area tersebut, dan makhluk tersebut juga tidak dapat memikat, menakuti, atau merasuki makhluk di dalamnya. Makhluk apa pun yang terpesona, ketakutan, atau kerasukan oleh makhluk tersebut tidak lagi terpesona, ketakutan, atau kerasukan saat memasuki area tersebut. Anda dapat mengecualikan satu atau lebih jenis makhluk tersebut dari efek ini.\nKedua, Anda dapat mengikat efek ekstra pada area tersebut. Pilih efek dari daftar berikut, atau pilih efek yang ditawarkan oleh GM. Beberapa dampak ini berlaku pada makhluk di area tersebut; Anda dapat menentukan apakah efeknya berlaku untuk semua makhluk, makhluk yang mengikuti dewa atau pemimpin tertentu, atau makhluk dengan jenis tertentu, seperti bijih atau troll. Saat makhluk yang terkena dampak memasuki area mantra untuk pertama kalinya pada giliran atau memulai giliran di sana, ia dapat melakukan lemparan penyelamatan karisma. Jika berhasil, makhluk tersebut mengabaikan efek tambahan hingga meninggalkan area tersebut.\n***Keberanian.*** Makhluk yang terkena dampak tidak dapat merasa takut saat berada di area tersebut.\n***Kegelapan.*** Kegelapan memenuhi area tersebut. Cahaya normal, serta cahaya magis yang diciptakan oleh mantra dengan level lebih rendah dari slot yang Anda gunakan untuk merapal mantra ini, tidak dapat menerangi area tersebut.\n***Siang hari.*** Cahaya terang memenuhi area tersebut. Kegelapan magis yang diciptakan oleh mantra dengan level lebih rendah dari slot yang Anda gunakan untuk merapal mantra ini tidak dapat memadamkan cahaya.\n***Perlindungan Energi.*** Makhluk yang terkena dampak di area tersebut memiliki ketahanan terhadap satu jenis kerusakan pilihan Anda, kecuali pukulan gada, penusukan, atau tebasan.\n***Kerentanan Energi.*** Makhluk yang terkena dampak di area tersebut memiliki kerentanan terhadap satu jenis kerusakan pilihan Anda, kecuali pukulan gada, penusukan, atau tebasan.\n***Istirahat Abadi.*** Mayat yang dikuburkan di area tersebut tidak dapat diubah menjadi undead.\n***Gangguan Ekstradimensi.*** Makhluk yang terkena dampak tidak dapat bergerak atau melakukan perjalanan menggunakan teleportasi atau dengan cara ekstradimensi atau antarplanar.\n***Takut.*** Makhluk yang terkena dampak ketakutan saat berada di area tersebut.\n***Diam.*** Tidak ada suara yang keluar dari dalam area tersebut, dan tidak ada suara yang dapat mencapai ke dalamnya.\n***Lidah.*** Makhluk yang terkena dampak dapat berkomunikasi dengan makhluk lain di area tersebut, meskipun mereka tidak memiliki bahasa yang sama." },
      { name: "Insect Plague", components: "V, S, M", desc: "Belalang yang berkerumun dan menggigit memenuhi bola dengan radius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauannya. Bola itu menyebar ke berbagai sudut. Bola tersebut tetap ada selama durasi tersebut, dan areanya sedikit tertutup. Area bola tersebut merupakan medan yang sulit.\nKetika area tersebut muncul, setiap makhluk di dalamnya harus melakukan penyelamatan konstitusi. Makhluk menerima kerusakan menusuk 4d10 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil. Makhluk juga harus melakukan lemparan penyelamatan ini ketika memasuki area mantra untuk pertama kalinya pada suatu giliran atau mengakhiri gilirannya di sana.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kerusakan meningkat sebesar 1d10 untuk setiap slot level di atas 5." },
      { name: "Legend Lore", components: "V, S, M", desc: "Sebutkan atau jelaskan seseorang, tempat, atau benda. Mantra ini mengingatkan Anda ringkasan singkat tentang pengetahuan penting tentang benda yang Anda beri nama. Pengetahuan tersebut bisa berupa cerita terkini, cerita yang terlupakan, atau bahkan pengetahuan rahasia yang belum pernah diketahui secara luas. Jika benda yang Anda beri nama tidak memiliki arti penting dalam legenda, Anda tidak memperoleh informasi. Semakin banyak informasi yang Anda miliki tentang suatu hal, semakin tepat dan rinci informasi yang Anda terima.\nInformasi yang Anda pelajari akurat tetapi mungkin disajikan dalam bahasa kiasan. Contohnya, jika Anda memiliki kapak ajaib misterius di tangan, mantranya mungkin akan menghasilkan informasi berikut: \"Celakalah pelaku kejahatan yang tangannya menyentuh kapak, karena gagang kapak pun dapat mengiris tangan si jahat. Hanya Anak Batu sejati, kekasih dan kekasih Moradin, yang dapat membangkitkan kekuatan kapak yang sebenarnya, dan hanya dengan kata suci *Rudnogg* di bibir.\"" },
      { name: "Mass Cure Wounds", components: "V, S", desc: "Gelombang energi penyembuhan mengalir dari titik pilihan Anda dalam jangkauan. Pilih hingga enam makhluk dalam bola radius 30 kaki yang berpusat pada titik tersebut. Setiap target mendapatkan kembali poin hit sebesar 3d8 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, penyembuhan meningkat sebesar 1d8 untuk setiap slot level di atas 5." },
      { name: "Planar Binding", components: "V, S, M", desc: "Dengan mantra ini, Anda mencoba untuk mengikat benda langit, elemen, makhluk, atau iblis ke dalam layanan Anda. Makhluk itu harus berada dalam jangkauan selama seluruh perapalan mantra. (Biasanya, makhluk tersebut pertama kali dipanggil ke tengah lingkaran sihir terbalik agar tetap terjebak saat mantra ini digunakan.) Setelah menyelesaikan casting, target harus melakukan lemparan penyelamatan karisma. Jika penyimpanan gagal, itu pasti akan membantu Anda selama durasi tersebut. Jika makhluk itu dipanggil atau diciptakan oleh mantra lain, durasi mantra tersebut diperpanjang agar sesuai dengan durasi mantra ini.\nMakhluk yang terikat harus mengikuti instruksi Anda dengan kemampuan terbaiknya. Anda mungkin memerintahkan makhluk tersebut untuk menemani Anda berpetualang, menjaga lokasi, atau menyampaikan pesan. Makhluk itu mematuhi instruksi Anda, tetapi jika makhluk itu memusuhi Anda, ia berusaha memutarbalikkan kata-kata Anda untuk mencapai tujuannya sendiri. Jika makhluk tersebut melaksanakan instruksi Anda sepenuhnya sebelum mantranya berakhir, ia akan mendatangi Anda untuk melaporkan fakta ini jika Anda berada di alam keberadaan yang sama. Jika Anda berada di alam eksistensi lain, ia akan kembali ke tempat Anda mengikatnya dan tetap di sana hingga mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra dengan level yang lebih tinggi, durasinya meningkat menjadi 10 hari dengan slot level 6, menjadi 30 hari dengan slot level 7, menjadi 180 hari dengan slot level 8, dan menjadi satu tahun dan satu hari dengan slot mantra level 9." },
      { name: "Raise Dead", components: "V, S, M", desc: "Anda menghidupkan kembali makhluk mati yang Anda sentuh, asalkan sudah mati tidak lebih dari 10 hari. Jika jiwa makhluk tersebut bersedia dan bebas untuk bergabung kembali dengan tubuhnya, makhluk tersebut akan hidup kembali dengan 1 poin pukulan.\nMantra ini juga menetralkan segala racun dan menyembuhkan penyakit non-magis yang menyerang makhluk tersebut pada saat ia mati. Namun mantra ini tidak menghilangkan penyakit magis, kutukan, atau efek serupa; jika ini tidak dihilangkan terlebih dahulu sebelum merapal mantra, itu akan berlaku saat makhluk itu hidup kembali. Mantra itu tidak bisa menghidupkan kembali makhluk undead.\nMantra ini menutup semua luka mematikan, namun tidak memulihkan bagian tubuh yang hilang. Jika makhluk itu kekurangan bagian tubuh atau organ yang tidak terpisahkan untuk kelangsungan hidupnya--kepalanya, misalnya--mantranya otomatis gagal.\nBangkit dari kematian adalah sebuah cobaan berat. Target menerima penalti -4 untuk semua serangan, lemparan penyelamatan, dan pemeriksaan kemampuan. Setiap target menyelesaikan istirahat panjang, penaltinya berkurang 1 hingga hilang." },
      { name: "Scrying", components: "V, S, M", desc: "Anda dapat melihat dan mendengar makhluk tertentu yang Anda pilih yang berada pada alam eksistensi yang sama dengan Anda. Target harus melakukan lemparan penyelamatan yang bijaksana, yang dimodifikasi oleh seberapa baik Anda mengenal target dan jenis hubungan fisik yang Anda miliki dengannya. Jika target mengetahui Anda merapalkan mantra ini, target dapat gagal melakukan penyelamatan secara sukarela jika ingin diamati.\n| Pengetahuan | Simpan Pengubah |\n|---|---|\n| Bekas (Anda pernah mendengar tentang targetnya) | +5 |\n| Langsung (Anda sudah memenuhi target) | +0 |\n| Familiar (Anda tahu targetnya dengan baik) | -5 |\n\n| Koneksi | Simpan Pengubah |\n|---|---|\n| Kemiripan atau gambar | -2 |\n| Kepemilikan atau pakaian | -4 |\n| Bagian badan, seikat rambut, secuil kuku, atau sejenisnya | -10 |\nJika penyelamatan berhasil, target tidak terpengaruh, dan Anda tidak dapat menggunakan mantra ini lagi selama 24 jam.\nJika penyelamatan gagal, mantra tersebut menciptakan sensor tak terlihat dalam jarak 10 kaki dari target. Anda dapat melihat dan mendengar melalui sensor seolah-olah Anda berada di sana. Sensor bergerak mengikuti target, tetap berada dalam jarak 10 kaki selama durasi tersebut. Makhluk yang dapat melihat objek tak kasat mata melihat sensornya sebagai bola bercahaya seukuran kepalan tangan Anda.\nDaripada mengincar makhluk, kamu bisa memilih lokasi yang pernah kamu lihat sebelumnya sebagai target mantra ini. Ketika Anda melakukannya, sensor muncul di lokasi tersebut dan tidak bergerak." },
    ],
    Level6: [
      { name: "Blade Barrier", components: "V, S", desc: "Anda membuat dinding vertikal dari pisau tajam dan berputar yang terbuat dari energi magis. Dinding muncul dalam jangkauan dan bertahan selama durasi tersebut. Anda dapat membuat dinding lurus dengan panjang hingga 100 kaki, tinggi 20 kaki, dan tebal 5 kaki, atau dinding melingkar dengan diameter hingga 60 kaki, tinggi 20 kaki, dan tebal 5 kaki. Dinding tersebut memberikan tiga perempat perlindungan bagi makhluk di belakangnya, dan ruangannya merupakan medan yang sulit.\nSaat makhluk memasuki area dinding untuk pertama kalinya pada suatu belokan atau memulai belokannya di sana, makhluk tersebut harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk itu menerima kerusakan tebasan 6d10. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan." },
      { name: "Create Undead", components: "V, S, M", desc: "Anda hanya bisa mengucapkan mantra ini di malam hari. Pilih hingga tiga mayat humanoid Sedang atau Kecil dalam jangkauan. Setiap mayat menjadi hantu di bawah kendali Anda. (GM memiliki statistik permainan untuk makhluk-makhluk ini.)\nSebagai tindakan bonus di setiap giliran Anda, Anda dapat secara mental memerintahkan makhluk apa pun yang Anda animasikan dengan mantra ini jika makhluk itu berada dalam jarak 120 kaki dari Anda (jika Anda mengendalikan beberapa makhluk, Anda dapat memerintahkan salah satu atau semuanya secara bersamaan, mengeluarkan perintah yang sama untuk masing-masing makhluk). Anda memutuskan tindakan apa yang akan diambil makhluk itu dan ke mana ia akan bergerak pada giliran berikutnya, atau Anda dapat mengeluarkan perintah umum, seperti menjaga ruangan atau koridor tertentu. Jika Anda tidak mengeluarkan perintah, makhluk itu hanya akan mempertahankan diri dari makhluk musuh. Setelah diberi perintah, makhluk tersebut terus mengikutinya hingga tugasnya selesai.\nMakhluk itu berada di bawah kendali Anda selama 24 jam, setelah itu ia berhenti mematuhi perintah apa pun yang Anda berikan. Untuk mempertahankan kendali atas makhluk tersebut selama 24 jam berikutnya, Anda harus mengucapkan mantra ini pada makhluk tersebut sebelum periode 24 jam saat ini berakhir. Penggunaan mantra ini menegaskan kembali kendali Anda atas hingga tiga makhluk yang telah Anda animasikan dengan mantra ini, daripada menganimasikan makhluk baru.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 7, Anda dapat menghidupkan atau menegaskan kembali kendali atas empat hantu. Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat 8, Anda dapat menganimasikan atau menegaskan kembali kendali atas lima ghoul atau dua ghast atau wight. Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat 9, Anda dapat menganimasikan atau menegaskan kembali kendali atas enam hantu, tiga hantu atau bobot, atau dua mumi." },
      { name: "Find the Path", components: "V, S, M", desc: "Mantra ini memungkinkan Anda menemukan rute fisik terpendek dan paling langsung ke lokasi tetap tertentu yang Anda kenal di alam keberadaan yang sama. Jika Anda menyebutkan tujuan di alam eksistensi lain, tujuan yang bergerak (seperti benteng bergerak), atau tujuan yang tidak spesifik (seperti \"sarang naga hijau\"), mantranya akan gagal.\nSelama Anda berada di alam eksistensi yang sama dengan tujuan, Anda tahu seberapa jauh jaraknya dan ke arah mana letaknya. Saat Anda bepergian ke sana, setiap kali Anda dihadapkan pada pilihan jalur di sepanjang jalan, Anda secara otomatis menentukan jalur mana yang merupakan rute terpendek dan paling langsung (tetapi belum tentu rute teraman) ke tujuan." },
      { name: "Forbiddance", components: "V, S, M", desc: "Anda membuat penghalang terhadap perjalanan ajaib yang melindungi luas lantai hingga 40.000 kaki persegi hingga ketinggian 30 kaki di atas lantai. Selama durasi tersebut, makhluk tidak dapat berteleportasi ke area tersebut atau menggunakan portal, seperti yang dibuat oleh mantra gerbang, untuk memasuki area tersebut. Mantra tersebut melindungi area tersebut dari perjalanan planar, dan oleh karena itu mencegah makhluk mengakses area tersebut melalui Pesawat Astral, Pesawat Ethereal, Feywild, Shadowfell, atau mantra pergeseran pesawat.\nSelain itu, mantranya merusak jenis makhluk yang Anda pilih saat Anda menggunakannya. Pilih satu atau lebih dari yang berikut ini: selestial, elemen, fey, iblis, dan undead. Saat makhluk yang dipilih memasuki area mantra untuk pertama kalinya pada suatu giliran atau memulai gilirannya di sana, makhluk tersebut menerima 5d10 kerusakan radiasi atau nekrotik (pilihan Anda saat menggunakan mantra ini).\nSaat Anda mengucapkan mantra ini, Anda dapat menentukan kata sandi. Makhluk yang mengucapkan kata sandi saat memasuki area tersebut tidak menerima kerusakan dari mantranya.\nArea mantra tidak boleh tumpang tindih dengan area mantra larangan lainnya. Jika Anda merapal larangan setiap hari selama 30 hari di lokasi yang sama, mantranya akan bertahan hingga hilang, dan komponen material akan dikonsumsi pada casting terakhir." },
      { name: "Harm", components: "V, S", desc: "Anda menyebarkan penyakit mematikan pada makhluk yang dapat Anda lihat dalam jangkauannya. Targetnya harus melakukan penyelamatan konstitusi. Pada penyelamatan yang gagal, dibutuhkan 14d6 kerusakan nekrotik, atau setengah dari kerusakan pada penyelamatan yang berhasil. Kerusakan tidak dapat mengurangi poin hit target di bawah 1. Jika target gagal dalam penyelamatan, poin maksimum hitnya berkurang selama 1 jam dengan jumlah yang sama dengan kerusakan nekrotik yang diterimanya. Efek apa pun yang menghilangkan penyakit memungkinkan titik serangan maksimum suatu makhluk kembali normal sebelum waktu tersebut berlalu." },
      { name: "Heal", components: "V, S", desc: "Pilih makhluk yang dapat Anda lihat dalam jangkauan. Gelombang energi positif menyapu makhluk itu, menyebabkannya mendapatkan kembali 70 poin serangan. Mantra ini juga mengakhiri kebutaan, tuli, dan penyakit apa pun yang menyerang target. Mantra ini tidak berpengaruh pada konstruksi atau undead.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, jumlah penyembuhan meningkat sebesar 10 untuk setiap slot level di atas 6." },
      { name: "Heroes' Feast", components: "V, S, M", desc: "Anda mengadakan pesta besar, termasuk makanan dan minuman yang lezat. Pesta tersebut membutuhkan waktu 1 jam untuk dikonsumsi dan hilang pada akhir waktu tersebut, dan efek menguntungkannya tidak akan terlihat sampai jam tersebut selesai. Hingga dua belas makhluk lain dapat mengambil bagian dalam pesta itu.\nMakhluk yang ikut serta dalam pesta itu memperoleh beberapa manfaat. Makhluk itu sembuh dari segala penyakit dan racun, menjadi kebal terhadap racun dan ketakutan, dan memanfaatkan semua kebijaksanaan yang menyelamatkan dengan manfaat. Hit point maksimumnya juga meningkat 2 hari 10, dan memperoleh jumlah hit point yang sama. Manfaat ini berlaku selama 24 jam." },
      { name: "Planar Ally", components: "V, S", desc: "Anda memohon bantuan dari entitas dunia lain. Makhluk tersebut harus Anda ketahui: dewa, primordial, pangeran iblis, atau makhluk lain yang memiliki kekuatan kosmis. Entitas tersebut mengirimkan makhluk surgawi, elemen, atau iblis yang setia kepadanya untuk membantu Anda, membuat makhluk tersebut muncul di ruang kosong dalam jangkauannya. Jika Anda mengetahui nama makhluk tertentu, Anda dapat mengucapkan nama tersebut saat mengucapkan mantra ini untuk meminta makhluk tersebut, meskipun Anda mungkin akan mendapatkan makhluk lain (pilihan GM).\nKetika makhluk itu muncul, ia tidak mempunyai paksaan untuk berperilaku tertentu. Anda dapat meminta makhluk tersebut untuk melakukan suatu layanan dengan imbalan pembayaran, namun ia tidak wajib melakukannya. Tugas yang diminta dapat berkisar dari yang sederhana (menerbangkan kami melintasi jurang, atau membantu kami berperang) hingga yang kompleks (memata-matai musuh, atau melindungi kami selama terjun ke ruang bawah tanah). Anda harus bisa berkomunikasi dengan makhluk itu untuk menawar jasanya.\nPembayaran dapat dilakukan dalam berbagai bentuk. Makhluk surgawi mungkin memerlukan sumbangan emas atau benda sihir dalam jumlah besar ke kuil sekutu, sementara iblis mungkin memerlukan pengorbanan hidup atau hadiah harta karun. Beberapa makhluk mungkin menukar layanan mereka dengan misi yang Anda lakukan.\nSebagai aturan praktis, suatu tugas yang dapat diukur dalam hitungan menit memerlukan pembayaran senilai 100 gp per menit. Tugas yang diukur dalam jam memerlukan 1.000 gp per jam. Dan tugas yang diukur dalam hari (hingga 10 hari) membutuhkan 10.000 gp per hari. GM dapat menyesuaikan pembayaran ini berdasarkan keadaan saat Anda mengucapkan mantra. Jika tugas tersebut sejalan dengan etos makhluk tersebut, pembayarannya mungkin dikurangi setengahnya atau bahkan dihapuskan. Tugas yang tidak berbahaya biasanya hanya memerlukan setengah pembayaran yang disarankan, sedangkan tugas yang sangat berbahaya mungkin memerlukan hadiah yang lebih besar. Makhluk jarang menerima tugas yang terkesan bunuh diri.\nSetelah makhluk tersebut menyelesaikan tugasnya, atau ketika durasi layanan yang disepakati berakhir, makhluk tersebut kembali ke pesawat asalnya setelah melapor kembali kepada Anda, jika sesuai dengan tugas tersebut dan jika memungkinkan. Jika Anda tidak dapat menyepakati harga layanan makhluk tersebut, makhluk tersebut segera kembali ke pesawat asalnya.\nMakhluk yang terdaftar untuk bergabung dengan grup Anda dihitung sebagai anggotanya, menerima seluruh poin pengalaman yang diberikan." },
      { name: "True Seeing", components: "V, S, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk melihat segala sesuatu sebagaimana adanya. Selama durasi tersebut, makhluk tersebut memiliki penglihatan yang sebenarnya, mengetahui pintu rahasia yang disembunyikan oleh sihir, dan dapat melihat ke dalam Alam Ethereal, semuanya hingga jarak 120 kaki." },
      { name: "Word of Recall", components: "V", desc: "Anda dan hingga lima makhluk yang bersedia dalam jarak 5 kaki dari Anda langsung berteleportasi ke tempat perlindungan yang telah ditentukan sebelumnya. Anda dan makhluk apa pun yang berteleportasi bersama Anda muncul di ruang kosong terdekat dengan tempat yang Anda tentukan saat menyiapkan tempat perlindungan (lihat di bawah). Jika Anda mengucapkan mantra ini tanpa menyiapkan tempat perlindungan terlebih dahulu, mantra tersebut tidak akan berpengaruh.\nAnda harus menentukan tempat perlindungan dengan mengucapkan mantra ini di suatu lokasi, seperti kuil, yang didedikasikan atau terkait erat dengan dewa Anda. Jika Anda mencoba mengucapkan mantra dengan cara ini di area yang tidak didedikasikan untuk dewa Anda, mantra tersebut tidak akan berpengaruh." },
    ],
    Level7: [
      { name: "Conjure Celestial", components: "V, S", desc: "Anda memanggil surgawi dengan peringkat tantangan 4 atau lebih rendah, yang muncul di ruang kosong yang dapat Anda lihat dalam jangkauan. Celestial menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nMakhluk surgawi bersahabat dengan Anda dan teman Anda selama ini. Gulung inisiatif untuk para kahyangan, yang mempunyai giliran tersendiri. Ia mematuhi perintah verbal apa pun yang Anda keluarkan (Anda tidak perlu melakukan tindakan apa pun), selama perintah tersebut tidak melanggar kesejajarannya. Jika Anda tidak mengeluarkan perintah apa pun kepada makhluk angkasa, ia akan mempertahankan diri dari makhluk yang bermusuhan, namun sebaliknya tidak akan mengambil tindakan apa pun.\nGM mempunyai statistik langit.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 9, Anda memanggil surgawi dengan peringkat tantangan 5 atau lebih rendah." },
      { name: "Divine Word", components: "V", desc: "Anda mengucapkan firman ilahi, yang dipenuhi dengan kekuatan yang membentuk dunia pada awal penciptaan. Pilih sejumlah makhluk yang dapat Anda lihat dalam jangkauan. Setiap makhluk yang dapat mendengar Anda harus melakukan lemparan penyelamatan Karisma. Jika penyelamatan gagal, makhluk akan menerima efek berdasarkan poin hitnya saat ini:\n- 50 hit point atau kurang: tuli selama 1 menit\n- 40 hit point atau kurang: memekakkan telinga dan membutakan selama 10 menit\n- 30 hit point atau kurang: membutakan, memekakkan telinga, dan membuat pingsan selama 1 jam\n- 20 poin hit atau kurang: terbunuh seketika\nTerlepas dari titik serangannya saat ini, benda angkasa, elemen, fey, atau iblis yang gagal dalam penyelamatannya akan dipaksa kembali ke bidang asalnya (jika belum ada) dan tidak dapat kembali ke pesawat Anda saat ini selama 24 jam dengan cara apa pun kecuali mantra harapan." },
      { name: "Etherealness", components: "V, S", desc: "Anda melangkah ke wilayah perbatasan Pesawat Ethereal, di area yang tumpang tindih dengan pesawat Anda saat ini. Anda tetap berada di Border Ethereal selama atau sampai Anda menggunakan tindakan Anda untuk menghilangkan mantranya. Selama waktu ini, Anda dapat bergerak ke segala arah. Jika Anda bergerak ke atas atau ke bawah, setiap gerakan membutuhkan satu kaki ekstra. Anda dapat melihat dan mendengar pesawat asal Anda, tetapi segala sesuatu di sana tampak abu-abu, dan Anda tidak dapat melihat apa pun yang jaraknya lebih dari 60 kaki.\nSelama berada di Alam Ethereal, Anda hanya dapat mempengaruhi dan dipengaruhi oleh makhluk lain di alam tersebut. Makhluk yang tidak berada di Alam Ethereal tidak dapat melihat Anda dan tidak dapat berinteraksi dengan Anda, kecuali jika kemampuan atau sihir khusus memberi mereka kemampuan untuk melakukannya.\nAnda mengabaikan semua objek dan efek yang tidak ada di Alam Ethereal, memungkinkan Anda bergerak melalui objek yang Anda lihat di bidang asal Anda.\nKetika mantranya berakhir, kamu segera kembali ke pesawat asalmu di tempat yang kamu tempati saat ini. Jika Anda menempati tempat yang sama dengan benda padat atau makhluk saat hal ini terjadi, Anda akan segera diarahkan ke ruang kosong terdekat yang dapat Anda tempati dan menerima kerusakan kekuatan yang setara dengan dua kali jumlah kaki yang Anda gerakkan.\nMantra ini tidak berpengaruh jika kamu mengucapkannya saat kamu berada di Alam Ethereal atau di alam yang tidak membatasinya, seperti salah satu Alam Luar.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 8 atau lebih tinggi, Anda dapat menargetkan hingga tiga makhluk yang bersedia (termasuk Anda) untuk setiap slot level di atas 7. Makhluk tersebut harus berada dalam jarak 10 kaki dari Anda saat Anda mengucapkan mantra." },
      { name: "Fire Storm", components: "V, S", desc: "Badai yang terdiri dari lembaran api yang menderu muncul di lokasi yang Anda pilih dalam jangkauannya. Area badai terdiri dari sepuluh kubus berukuran 10 kaki, yang dapat Anda atur sesuai keinginan. Setiap kubus harus memiliki setidaknya satu sisi yang berdekatan dengan sisi kubus lainnya. Setiap makhluk di area tersebut harus melakukan lemparan penyelamatan ketangkasan. Dibutuhkan 7d10 kerusakan akibat kebakaran pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nApi merusak benda-benda di area tersebut dan menyulut benda-benda mudah terbakar yang tidak dipakai atau dibawa. Jika Anda memilih, kehidupan tanaman di area tersebut tidak terpengaruh oleh mantra ini." },
      { name: "Plane Shift", components: "V, S, M", desc: "Anda dan hingga delapan makhluk bersedia yang bergandengan tangan dalam lingkaran akan dipindahkan ke alam eksistensi lain. Anda dapat menentukan tujuan target secara umum, seperti Kota Kuningan di Alam Elemen Api atau istana Dispater di Sembilan Neraka tingkat kedua, dan Anda muncul di atau dekat tujuan tersebut. Jika Anda mencoba mencapai Kota Kuningan, misalnya, Anda mungkin tiba di Jalan Baja, sebelum Gerbang Abu, atau melihat kota dari seberang Lautan Api, sesuai kebijaksanaan GM.\nAlternatifnya, jika Anda mengetahui urutan sigil lingkaran teleportasi di alam eksistensi lain, mantra ini dapat membawa Anda ke lingkaran itu. Jika lingkaran teleportasi terlalu kecil untuk menampung semua makhluk yang Anda pindahkan, mereka akan muncul di ruang kosong terdekat di sebelah lingkaran.\nAnda dapat menggunakan mantra ini untuk mengusir makhluk yang tidak mau ke pesawat lain. Pilih makhluk dalam jangkauan Anda dan lakukan serangan mantra jarak dekat terhadapnya. Saat terkena, makhluk tersebut harus melakukan lemparan penyelamatan karisma. Jika makhluk tersebut gagal dalam penyelamatan ini, ia akan dipindahkan ke lokasi acak di alam keberadaan yang Anda tentukan. Makhluk yang dipindahkan harus menemukan jalannya sendiri kembali ke alam keberadaan Anda saat ini." },
      { name: "Regenerate", components: "V, S, M", desc: "Anda menyentuh makhluk dan merangsang kemampuan penyembuhan alaminya. Target mendapatkan kembali 4d8 + 15 poin hit. Selama durasi mantra, target mendapatkan kembali 1 poin hit di awal setiap putarannya (10 poin hit setiap menit).\nAnggota tubuh target yang terputus (jari tangan, kaki, ekor, dan sebagainya), jika ada, akan dipulihkan setelah 2 menit. Jika Anda memiliki bagian yang terputus dan menempelkannya pada tunggul, mantra tersebut secara instan menyebabkan anggota tubuh tersebut terikat pada tunggul." },
      { name: "Resurrection", components: "V, S, M", desc: "Anda menyentuh makhluk mati yang telah mati tidak lebih dari satu abad, yang tidak mati karena usia tua, dan itu bukanlah mayat hidup. Jika jiwanya bebas dan berkeinginan, target akan hidup kembali dengan segala hit pointnya.\nMantra ini menetralkan segala racun dan menyembuhkan penyakit normal yang menyerang makhluk itu ketika mati. Namun, hal ini tidak menghilangkan penyakit magis, kutukan, dan sejenisnya; jika efek tersebut tidak dihilangkan sebelum merapal mantra, efek tersebut akan menimpa target saat mantra tersebut kembali hidup.\nMantra ini menutup semua luka mematikan dan memulihkan bagian tubuh yang hilang.\nBangkit dari kematian adalah sebuah cobaan berat. Target menerima penalti -4 untuk semua serangan, lemparan penyelamatan, dan pemeriksaan kemampuan. Setiap target menyelesaikan istirahat panjang, penaltinya berkurang 1 hingga hilang.\nMengucapkan mantra ini untuk menghidupkan kembali makhluk yang telah mati selama satu tahun atau lebih akan sangat membebani Anda. Sampai Anda menyelesaikan istirahat panjang, Anda tidak dapat merapal mantra lagi, dan Anda memiliki kerugian pada semua serangan, pemeriksaan kemampuan, dan penyelamatan lemparan." },
      { name: "Symbol", components: "V, S, M", desc: "Saat Anda mengucapkan mantra ini, Anda menuliskan mesin terbang yang berbahaya baik di permukaan (seperti bagian lantai, dinding, atau meja) atau di dalam objek yang dapat ditutup untuk menyembunyikan mesin terbang tersebut (seperti buku, gulungan, atau peti harta karun). Jika Anda memilih suatu permukaan, mesin terbang tersebut dapat menutupi area permukaan yang diameternya tidak lebih dari 10 kaki. Jika Anda memilih suatu benda, benda itu harus tetap berada di tempatnya; jika objek dipindahkan lebih dari 10 kaki dari tempat Anda mengucapkan mantra ini, mesin terbangnya rusak, dan mantranya berakhir tanpa terpicu.\nMesin terbang itu hampir tidak terlihat, memerlukan pemeriksaan Intelijen (Investigasi) terhadap mantra Anda, simpan DC untuk menemukannya.\nAnda memutuskan apa yang memicu mesin terbang saat Anda mengucapkan mantranya. Untuk mesin terbang yang tertulis di suatu permukaan, pemicu yang paling umum adalah menyentuh atau menginjak mesin terbang tersebut, memindahkan benda lain yang menutupinya, mendekat dalam jarak tertentu, atau memanipulasi benda yang menahannya. Untuk mesin terbang yang tertulis di dalam suatu objek, pemicu paling umum adalah membuka objek, mendekat dalam jarak tertentu, atau melihat atau membaca mesin terbang tersebut.\nAnda dapat menyempurnakan pemicunya lebih lanjut sehingga mantranya hanya diaktifkan dalam keadaan tertentu atau berdasarkan karakteristik fisik makhluk (seperti tinggi atau berat), atau jenis fisiknya (misalnya, lingkungan dapat diatur untuk memengaruhi perempuan tua atau pengubah bentuk). Anda juga dapat menentukan makhluk yang tidak memicu mesin terbang, seperti makhluk yang mengucapkan kata sandi tertentu.\nSaat Anda menuliskan mesin terbang, pilih salah satu opsi di bawah untuk efeknya. Setelah dipicu, mesin terbang tersebut bersinar, mengisi bola berradius 60 kaki dengan cahaya redup selama 10 menit, setelah itu mantranya berakhir. Setiap makhluk di dalam bola ketika mesin terbang aktif ditargetkan oleh efeknya, seperti halnya makhluk yang memasuki bola untuk pertama kalinya pada suatu belokan atau mengakhiri gilirannya di sana.\n***Kematian.*** Setiap target harus melakukan lemparan penyelamatan konstitusi, menerima 10d 10 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\n***Perselisihan.*** Setiap target harus melakukan penyelamatan konstitusi. Pada penyelamatan yang gagal, target bertengkar dan berdebat dengan makhluk lain selama 1 menit. Selama waktu ini, ia tidak mampu melakukan komunikasi yang berarti dan memiliki kelemahan dalam serangan dan pemeriksaan kemampuan.\n***Fear.*** Setiap target harus melakukan lemparan penyelamatan yang bijaksana dan menjadi ketakutan selama 1 menit jika penyelamatan gagal. Saat ketakutan, target menjatuhkan apa pun yang dipegangnya dan harus menjauh setidaknya 30 kaki dari mesin terbang di setiap belokannya, jika memungkinkan.\n***Keputusasaan.*** Setiap target harus melakukan lemparan penyelamatan karisma. Pada penyelamatan yang gagal, target diliputi keputusasaan selama 1 menit. Selama waktu ini, ia tidak dapat menyerang atau menargetkan makhluk apa pun dengan kemampuan, mantra, atau efek magis berbahaya lainnya.\n***Kegilaan.*** Setiap target harus melakukan penyelamatan intelijen. Jika penyelamatan gagal, target menjadi gila selama 1 menit. Makhluk gila tidak bisa mengambil tindakan, tidak bisa mengerti apa yang dikatakan makhluk lain, tidak bisa membaca, dan hanya berbicara omong kosong. GM mengontrol pergerakannya, yang tidak menentu.\n***Sakit.*** Setiap target harus melakukan lemparan penyelamatan konstitusi dan menjadi tidak berdaya dengan rasa sakit yang menyiksa selama 1 menit jika penyelamatan gagal.\n***Tidur.*** Setiap target harus melakukan lemparan penyelamatan kebijaksanaan dan jatuh pingsan selama 10 menit karena penyelamatan yang gagal. Makhluk akan terbangun jika ia menerima kerusakan atau jika seseorang menggunakan suatu tindakan untuk mengguncang atau menamparnya hingga terbangun.\n***Menakjubkan.*** Setiap target harus melakukan lemparan penyelamatan yang bijaksana dan terkena stun selama 1 menit jika penyelamatan gagal." },
    ],
    Level8: [
      { name: "Antimagic Field", components: "V, S, M", desc: "Bola antisihir tak kasat mata dengan radius 10 kaki mengelilingi Anda. Area ini terpisah dari energi magis yang menyelimuti multiverse. Di dalam bola, mantra tidak dapat digunakan, makhluk yang dipanggil menghilang, dan bahkan item sihir menjadi biasa saja. Sampai mantranya berakhir, bola itu bergerak bersama Anda, berpusat pada Anda.\nMantra dan efek magis lainnya, kecuali yang diciptakan oleh artefak atau dewa, ditekan di dalam bola dan tidak dapat menonjol ke dalamnya. Slot yang digunakan untuk merapalkan mantra yang ditekan akan dikonsumsi. Saat suatu efek ditekan, efek tersebut tidak berfungsi, namun waktu yang dihabiskan untuk menekannya dihitung berdasarkan durasinya.\n***Efek Bertarget.*** Mantra dan efek magis lainnya, seperti misil ajaib dan pesona orang, yang menargetkan makhluk atau objek di dalam bola tidak berpengaruh pada target tersebut.\n***Area Sihir.*** Area mantra atau efek magis lain, seperti bola api, tidak dapat diperluas hingga ke dalam bola. Jika bola itu tumpang tindih dengan area sihir, bagian dari area yang ditutupi oleh bola itu akan ditekan. Misalnya, nyala api yang dihasilkan oleh dinding api dipadamkan di dalam bola, sehingga menciptakan celah di dinding jika tumpang tindihnya cukup besar.\n***Mantra.*** Mantra aktif atau efek magis lainnya pada makhluk atau objek di dalam bola akan ditekan saat makhluk atau objek tersebut berada di dalamnya.\n***Item Ajaib.*** Properti dan kekuatan item sihir ditekan di dalam bola. Misalnya, pedang panjang +1 di dalam bola berfungsi sebagai pedang panjang non-magis.\nProperti dan kekuatan senjata sihir akan ditekan jika digunakan terhadap target di dalam bola atau digunakan oleh penyerang di dalam bola. Jika senjata ajaib atau amunisi ajaib sepenuhnya meninggalkan bola (misalnya, jika Anda menembakkan panah ajaib atau melemparkan tombak ajaib ke target di luar bola), keajaiban item tersebut tidak lagi ditekan segera setelah keluar.\n***Perjalanan Ajaib.*** Teleportasi dan perjalanan planar gagal bekerja di dalam bola, baik bola tersebut adalah tujuan atau titik keberangkatan untuk perjalanan ajaib tersebut. Portal ke lokasi, dunia, atau bidang eksistensi lain, serta bukaan ke ruang ekstradimensi seperti yang diciptakan oleh mantra trik tali, ditutup sementara saat berada di dalam bola.\n***Makhluk dan Benda.*** Makhluk atau benda yang dipanggil atau diciptakan oleh sihir untuk sementara menghilang dari keberadaannya di dalam bola. Makhluk seperti itu langsung muncul kembali setelah ruang yang ditempati makhluk tersebut tidak lagi berada di dalam bola.\n***Sihir Penghilang.*** Mantra dan efek magis seperti sihir penghilang tidak berpengaruh pada bola. Demikian pula, bola yang diciptakan oleh mantra medan antisihir yang berbeda tidak saling meniadakan." },
      { name: "Control Weather", components: "V, S, M", desc: "Anda mengendalikan cuaca dalam jarak 5 mil dari Anda selama durasi tersebut. Anda harus berada di luar ruangan untuk mengucapkan mantra ini. Pindah ke tempat di mana Anda tidak memiliki jalur yang jelas ke langit akan mengakhiri mantranya lebih awal.\nSaat Anda merapal mantra, Anda mengubah kondisi cuaca saat ini, yang ditentukan oleh GM berdasarkan iklim dan musim. Anda dapat mengubah curah hujan, suhu, dan angin. Diperlukan waktu 1 hari 4 x 10 menit agar kondisi baru dapat diterapkan. Setelah mereka melakukannya, Anda dapat mengubah kondisinya lagi. Saat mantra berakhir, cuaca berangsur-angsur kembali normal.\nSaat Anda mengubah kondisi cuaca, temukan kondisi terkini pada tabel berikut dan ubah tahapannya satu per satu, naik atau turun. Saat mengubah arah angin, Anda dapat mengubah arahnya.\n##### Curah hujan\n| Tahap | Kondisi |\n|---|---|\n| 1 | Jelas |\n| 2 | Awan terang |\n| 3 | Mendung atau kabut tanah |\n| 4 | Hujan, hujan es, atau salju |\n| 5 | Hujan deras, hujan es, atau badai salju |\n##### Suhu\n| Tahap | Kondisi |\n|---|---|\n| 1 | Panas yang tak tertahankan |\n| 2 | Panas |\n| 3 | Hangat |\n| 4 | Keren |\n| 5 | Dingin |\n| 6 | Dingin Arktik |\n##### Angin\n| Tahap | Kondisi |\n|---|---|\n| 1 | Tenang |\n| 2 | Angin sedang |\n| 3 | Angin kencang |\n| 4 | Angin kencang |\n| 5 | Badai |" },
      { name: "Earthquake", components: "V, S, M", desc: "Anda menciptakan gangguan seismik pada suatu titik di permukaan tanah yang dapat Anda lihat dalam jangkauannya. Selama durasi tersebut, getaran hebat melanda tanah dalam lingkaran radius 100 kaki yang berpusat di titik tersebut dan mengguncang makhluk serta bangunan yang bersentuhan dengan tanah di area tersebut.\nTanah di kawasan tersebut menjadi medan yang sulit. Setiap makhluk di tanah yang sedang berkonsentrasi harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, konsentrasi makhluk itu terganggu.\nSaat Anda mengucapkan mantra ini dan di akhir setiap giliran yang Anda habiskan untuk berkonsentrasi padanya, setiap makhluk di tanah di area tersebut harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk itu rawan terbentur.\nSpell ini dapat memberikan efek tambahan tergantung pada medan di area tersebut, seperti yang ditentukan oleh GM.\ncelah. Celah terbuka di seluruh area mantra pada awal giliran berikutnya setelah Anda mengucapkan mantra. Sebanyak 1d6 celah tersebut terbuka di lokasi yang dipilih oleh GM. Masing-masing memiliki kedalaman 1d10 x 10 kaki, lebar 10 kaki, dan memanjang dari satu tepi area mantra ke sisi yang berlawanan. Makhluk yang berdiri di tempat celah terbuka harus berhasil melakukan lemparan penyelamatan ketangkasan atau jatuh. Makhluk yang berhasil menyelamatkan bergerak dengan tepi celah saat celah terbuka.\nRetakan yang terbuka di bawah suatu struktur menyebabkan struktur tersebut runtuh secara otomatis (lihat di bawah).\nStruktur. Getaran tersebut menimbulkan 50 kerusakan besar pada struktur apa pun yang bersentuhan dengan tanah di area tersebut saat Anda merapal mantra dan di awal setiap giliran hingga mantra berakhir. Jika suatu struktur turun hingga 0 titik serangan, struktur tersebut akan runtuh dan berpotensi merusak makhluk di sekitarnya. Makhluk yang berada dalam jarak setengah dari tinggi bangunan harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk itu menerima kerusakan akibat pukulan 5d6, rawan terkena pukulan, dan terkubur di reruntuhan, memerlukan pemeriksaan Kekuatan (Atletik) DC 20 sebagai tindakan untuk melarikan diri. GM dapat mengatur DC lebih tinggi atau lebih rendah, tergantung pada sifat puing-puingnya. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan dan tidak rawan atau terkubur." },
      { name: "Holy Aura", components: "V, S, M", desc: "Cahaya Ilahi memancar dari Anda dan menyatu dalam pancaran cahaya lembut dalam radius 30 kaki di sekitar Anda. Makhluk pilihan Anda dalam radius tersebut saat Anda mengucapkan mantra ini akan memancarkan cahaya redup dalam radius 5 kaki dan memiliki keuntungan pada semua lemparan penyelamatan, dan makhluk lain memiliki kelemahan pada serangan yang melawan mereka hingga mantra berakhir. Selain itu, ketika iblis atau undead menyerang makhluk yang terkena dampak dengan serangan jarak dekat, auranya bersinar dengan cahaya cemerlang. Penyerang harus berhasil melakukan penyelamatan konstitusi atau menjadi buta sampai mantranya berakhir." },
    ],
    Level9: [
      { name: "Astral Projection", components: "V, S, M", desc: "Anda dan hingga delapan makhluk yang bersedia dalam jangkauan memproyeksikan tubuh astral Anda ke Alam Astral (mantranya gagal dan castingnya sia-sia jika Anda sudah berada di Alam Astral itu). Badan material yang Anda tinggalkan tidak sadarkan diri dan dalam keadaan mati suri; tidak membutuhkan makanan atau udara dan tidak menua.\nTubuh astral Anda hampir menyerupai wujud fana Anda dalam segala hal, meniru statistik permainan dan harta benda Anda. Perbedaan utamanya adalah penambahan tali keperakan yang memanjang dari antara tulang belikat dan berjalan di belakang Anda, memudar hingga tidak terlihat setelah 1 kaki. Tali ini adalah tambatan Anda pada tubuh material Anda. Selama tambatannya tetap utuh, Anda dapat menemukan jalan pulang. Jika kabelnya terputus--sesuatu yang dapat terjadi hanya jika efeknya secara spesifik dinyatakan demikian--jiwa dan tubuh Anda terpisah, membunuh Anda seketika.\nBentuk astral Anda dapat dengan bebas melakukan perjalanan melalui Alam Astral dan dapat melewati portal yang mengarah ke alam lain mana pun. Jika Anda memasuki pesawat baru atau kembali ke pesawat yang Anda naiki saat merapal mantra ini, tubuh dan harta benda Anda akan dipindahkan melalui tali perak, memungkinkan Anda untuk masuk kembali ke tubuh Anda saat Anda memasuki pesawat baru. Bentuk astral Anda adalah inkarnasi terpisah. Kerusakan atau dampak lain apa pun yang terjadi padanya tidak berpengaruh pada tubuh fisik Anda, juga tidak bertahan saat Anda kembali menggunakannya.\nMantra berakhir untuk Anda dan teman Anda saat Anda menggunakan tindakan Anda untuk mengabaikannya. Ketika mantranya berakhir, makhluk yang terkena dampak kembali ke tubuh fisiknya, dan dia terbangun.\nMantra ini mungkin juga berakhir lebih awal untuk Anda atau salah satu teman Anda. Mantra sihir penghilang yang berhasil digunakan terhadap tubuh astral atau fisik akan mengakhiri mantra untuk makhluk itu. Jika tubuh asli makhluk atau bentuk astralnya turun menjadi 0 poin serangan, mantra untuk makhluk tersebut berakhir. Jika mantranya berakhir dan tali peraknya masih utuh, tali tersebut akan menarik bentuk astral makhluk itu kembali ke tubuhnya, mengakhiri keadaan mati suri.\nJika Anda dikembalikan ke tubuh Anda sebelum waktunya, teman Anda tetap dalam bentuk astral dan harus menemukan jalan kembali ke tubuh mereka sendiri, biasanya dengan penurunan hingga 0 poin serangan." },
      { name: "Gate", components: "V, S, M", desc: "Anda membayangkan sebuah portal yang menghubungkan ruang kosong yang dapat Anda lihat dalam jangkauan ke lokasi yang tepat di alam eksistensi yang berbeda. Portalnya berupa bukaan melingkar, yang bisa Anda buat dengan diameter 5 hingga 20 kaki. Anda dapat mengarahkan portal ke arah mana pun yang Anda pilih. Portal ini bertahan selama durasi tersebut.\nPortal ini memiliki bagian depan dan belakang pada setiap bidang tempat ia muncul. Perjalanan melalui portal hanya mungkin dilakukan dengan bergerak melalui bagian depannya. Apa pun yang melakukan hal itu akan langsung dipindahkan ke pesawat lain, muncul di ruang kosong yang paling dekat dengan portal.\nDewa dan penguasa planar lainnya dapat mencegah portal yang dibuat oleh mantra ini terbuka di hadapan mereka atau di mana pun dalam domain mereka.\nSaat Anda mengucapkan mantra ini, Anda dapat mengucapkan nama makhluk tertentu (nama samaran, gelar, atau nama panggilan tidak berfungsi). Jika makhluk itu berada di pesawat selain yang Anda naiki, portal akan terbuka di sekitar makhluk yang disebutkan dan menarik makhluk itu melewatinya ke ruang kosong terdekat di sisi portal Anda. Anda tidak mendapatkan kekuatan khusus atas makhluk itu, dan ia bebas bertindak sesuai keinginan GM. Ia mungkin pergi, menyerang Anda, atau membantu Anda." },
      { name: "Mass Heal", components: "V, S", desc: "Banjir energi penyembuhan mengalir dari Anda ke makhluk-makhluk yang terluka di sekitar Anda. Anda memulihkan hingga 700 poin hit, dibagi sesuai pilihan Anda di antara sejumlah makhluk yang dapat Anda lihat dalam jangkauan. Makhluk yang disembuhkan dengan mantra ini juga sembuh dari segala penyakit dan segala akibat yang membuat mereka menjadi buta atau tuli. Mantra ini tidak berpengaruh pada undead atau konstruksi." },
      { name: "True Resurrection", components: "V, S, M", desc: "Anda menyentuh makhluk yang telah mati tidak lebih dari 200 tahun dan mati karena alasan apapun kecuali usia tua. Jika jiwa makhluk itu bebas dan berkehendak, maka makhluk itu akan hidup kembali dengan segala hit pointnya.\nMantra ini menutup semua luka, menetralkan racun apa pun, menyembuhkan semua penyakit, dan menghilangkan kutukan apa pun yang menimpa makhluk itu ketika mati. Mantra tersebut menggantikan organ dan anggota tubuh yang rusak atau hilang.\nMantra tersebut bahkan dapat memberikan tubuh baru jika yang asli sudah tidak ada lagi, dalam hal ini Anda harus menyebutkan nama makhluk tersebut. Makhluk itu kemudian muncul di ruang kosong yang Anda pilih dalam jarak 10 kaki dari Anda." },
    ],
  },
  Druid: {
    Cantrips: [
      { name: "Druidcraft", components: "V, S", desc: "Berbisik kepada roh alam, Anda menciptakan salah satu dari efek berikut dalam 'jangkauan':\n- Anda menciptakan efek sensorik kecil dan tidak berbahaya yang memprediksi cuaca di lokasi Anda selama 24 jam ke depan. Efeknya mungkin terwujud dalam bentuk bola emas untuk langit cerah, awan untuk hujan, kepingan salju yang berjatuhan untuk salju, dan sebagainya. Efek ini bertahan selama 1 putaran.\n- Anda langsung membuat bunga mekar, biji terbuka, atau kuncup daun mekar.\n- Anda menciptakan efek sensorik seketika yang tidak berbahaya, seperti daun-daun berguguran, hembusan angin, suara binatang kecil, atau suara sigung yang samar-samar. Efeknya harus sesuai dengan kubus setinggi 5 kaki.\n- Anda langsung menyalakan atau mematikan lilin, obor, atau api unggun kecil." },
      { name: "Guidance", components: "V, S", desc: "Anda menyentuh satu makhluk yang bersedia. Sekali sebelum mantra berakhir, target dapat melempar d4 dan menambahkan nomor yang dilempar ke satu pemeriksaan kemampuan pilihannya. Itu bisa melempar dadu sebelum atau sesudah melakukan pemeriksaan kemampuan. Mantra itu kemudian berakhir." },
      { name: "Mending", components: "V, S, M", desc: "Mantra ini memperbaiki satu kerusakan atau robekan pada benda yang Anda sentuh, seperti kunci rusak, jubah robek, atau kantong anggur yang bocor. Selama patah atau robeknya tidak lebih dari 1 kaki di dimensi mana pun, Anda memperbaikinya, tanpa meninggalkan bekas kerusakan sebelumnya.\nMantra ini secara fisik dapat memperbaiki item atau konstruksi sihir, tetapi mantra tersebut tidak dapat memulihkan sihir ke objek tersebut." },
      { name: "Poison Spray", components: "V, S", desc: "Anda mengulurkan tangan Anda ke arah makhluk yang dapat Anda lihat dalam jangkauan dan mengeluarkan kepulan gas berbahaya dari telapak tangan Anda. Makhluk itu harus berhasil melakukan penyelamatan konstitusi atau menerima kerusakan racun 1d12.\nKerusakan mantra ini meningkat sebesar 1d12 ketika Anda mencapai level 5 (2d12), level 11 (3d12), dan level 17 (4d12)." },
      { name: "Produce Flame", components: "V, S", desc: "Nyala api yang berkedip-kedip muncul di tangan Anda. Nyala api tetap berada di sana selama jangka waktu tersebut dan tidak membahayakan Anda maupun peralatan Anda. Nyala api memancarkan cahaya terang dalam radius 10 kaki dan cahaya redup dalam radius 10 kaki tambahan. Mantra berakhir jika Anda mengabaikannya sebagai suatu tindakan atau jika Anda mengucapkannya lagi.\nAnda juga dapat menyerang dengan api, meskipun hal itu akan mengakhiri mantranya. Saat Anda mengucapkan mantra ini, atau sebagai tindakan di giliran selanjutnya, Anda dapat melemparkan api ke makhluk dalam jarak 30 kaki dari Anda. Lakukan serangan mantra jarak jauh. Saat terkena, target menerima 1d8 damage api.\nKerusakan mantra ini meningkat sebesar 1d8 ketika Anda mencapai level 5 (2d8), level 11 (3d8), dan level 17 (4d8)." },
      { name: "Resistance", components: "V, S, M", desc: "Anda menyentuh satu makhluk yang bersedia. Sekali sebelum mantra berakhir, target dapat melempar d4 dan menambahkan nomor yang dilempar ke satu lemparan penyelamatan pilihannya. Ia dapat melempar dadu sebelum atau sesudah melakukan lemparan penyelamatan. Mantra itu kemudian berakhir." },
      { name: "Shillelagh", components: "V, S, M", desc: "Kayu tongkat pemukul atau tongkat seperempat yang Anda pegang dipenuhi dengan kekuatan alam. Untuk durasinya, kamu bisa menggunakan kemampuan spellcastingmu alih-alih Strength untuk serangan dan damage roll dari serangan jarak dekat menggunakan senjata itu, dan damage senjata tersebut menjadi d8. Senjatanya juga menjadi ajaib, jika belum. Mantranya berakhir jika Anda mengucapkannya lagi atau jika Anda melepaskan senjatanya." },
    ],
    Level1: [
      { name: "Animal Friendship", components: "V, S, M", desc: "Mantra ini memungkinkan Anda meyakinkan binatang bahwa Anda tidak bermaksud jahat. Pilih binatang yang dapat Anda lihat dalam jangkauan. Ia harus melihat dan mendengar Anda. Jika Intelijen binatang itu 4 atau lebih tinggi, mantranya gagal. Jika tidak, binatang itu harus berhasil dalam lemparan penyelamatan kebijaksanaan atau terpesona oleh Anda selama durasi mantra tersebut. Jika Anda atau salah satu teman Anda melukai target, mantranya akan berakhir." },
      { name: "Charm Person", components: "V, S", desc: "Anda mencoba memikat humanoid yang dapat Anda lihat dalam jangkauan. Ia harus melakukan lemparan penyelamatan yang bijaksana, dan melakukannya dengan keuntungan jika Anda atau teman Anda melawannya. Jika gagal dalam lemparan penyelamatan, ia akan terpesona oleh Anda hingga mantranya berakhir atau hingga Anda atau teman Anda melakukan sesuatu yang membahayakannya. Makhluk yang terpesona menganggap Anda sebagai kenalan yang ramah. Saat mantranya berakhir, makhluk itu tahu bahwa dia terpesona oleh Anda.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 1. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Create or Destroy Water", components: "V, S, M", desc: "Anda bisa menciptakan atau menghancurkan air.\n***Buat Air.*** Anda membuat hingga 10 galon air bersih dalam jangkauan dalam wadah terbuka. Alternatifnya, air jatuh sebagai hujan dalam kubus berukuran 30 kaki dalam jangkauannya.\n***Hancurkan Air.*** Anda menghancurkan hingga 10 galon air dalam wadah terbuka dalam jangkauan. Alternatifnya, Anda menghancurkan kabut dalam kubus berukuran 30 kaki dalam jangkauan.\nLevel Tinggi: Saat Anda mengucapkan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda membuat atau menghancurkan 10 galon air tambahan, atau ukuran kubus bertambah 5 kaki, untuk setiap slot level di atas 1." },
      { name: "Cure Wounds", components: "V, S", desc: "Makhluk yang Anda sentuh mendapatkan kembali sejumlah poin hit yang setara dengan 1d8 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, penyembuhan meningkat sebesar 1d8 untuk setiap slot level di atas 1." },
      { name: "Detect Magic", components: "V, S", desc: "Selama durasi tersebut, Anda merasakan kehadiran sihir dalam jarak 30 kaki dari Anda. Jika Anda merasakan sihir dengan cara ini, Anda dapat menggunakan tindakan Anda untuk melihat aura samar di sekitar makhluk atau objek apa pun yang terlihat di area yang mengandung sihir, dan Anda mempelajari sekolah sihirnya, jika ada.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Detect Poison and Disease", components: "V, S, M", desc: "Selama durasi tersebut, Anda dapat merasakan keberadaan dan lokasi racun, makhluk beracun, dan penyakit dalam jarak 30 kaki dari Anda. Anda juga mengidentifikasi jenis racun, makhluk beracun, atau penyakit dalam setiap kasus.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Entangle", components: "V, S", desc: "Gulma dan tanaman merambat yang tumbuh dari tanah dalam jarak 20 kaki persegi mulai dari suatu titik dalam jangkauan. Selama ini tanaman tersebut mengubah tanah di kawasan tersebut menjadi medan yang sulit.\nMakhluk di area saat Anda mengucapkan mantra harus berhasil melakukan lemparan yang menghemat kekuatan atau ditahan oleh tanaman yang menjerat hingga mantra berakhir. Makhluk yang tertahan oleh tanaman dapat menggunakan aksinya untuk melakukan pemeriksaan Kekuatan terhadap mantra penyelamatan DC Anda. Jika berhasil, ia membebaskan dirinya sendiri.\nSaat mantranya berakhir, tanaman yang disulap akan layu." },
      { name: "Faerie Fire", components: "V", desc: "Setiap objek dalam kubus berukuran 20 kaki dalam jangkauan digambarkan dengan cahaya biru, hijau, atau ungu (pilihan Anda). Makhluk apa pun di area saat mantra diucapkan juga akan terkena cahaya jika gagal dalam lemparan penyelamatan ketangkasan. Selama durasi tersebut, objek dan makhluk yang terkena dampak mengeluarkan cahaya redup dalam radius 10 kaki.\nSerangan apa pun terhadap makhluk atau objek yang terkena dampak memiliki keuntungan jika penyerang dapat melihatnya, dan makhluk atau objek yang terkena dampak tidak mendapatkan keuntungan karena tidak terlihat." },
      { name: "Fog Cloud", components: "V, S", desc: "Anda membuat bola kabut dengan radius 20 kaki yang berpusat pada suatu titik dalam jangkauan. Bola itu menyebar ke berbagai sudut, dan areanya sangat tertutup. Itu berlangsung selama atau sampai angin dengan kecepatan sedang atau lebih besar (setidaknya 10 mil per jam) membubarkannya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, radius kabut bertambah 20 kaki untuk setiap slot level di atas 1." },
      { name: "Goodberry", components: "V, S, M", desc: "Hingga sepuluh buah beri muncul di tangan Anda dan diresapi dengan sihir selama durasi tersebut. Makhluk dapat menggunakan aksinya untuk memakan satu buah beri. Memakan buah beri memulihkan 1 titik pukulan, dan buah beri tersebut memberikan nutrisi yang cukup untuk menopang makhluk selama sehari.\nBuah beri kehilangan potensinya jika tidak dikonsumsi dalam waktu 24 jam setelah mantra ini diucapkan." },
      { name: "Healing Word", components: "V", desc: "Makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan mendapatkan kembali poin hit yang setara dengan 1d4 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, penyembuhan meningkat sebesar 1d4 untuk setiap slot level di atas 1." },
      { name: "Jump", components: "V, S, M", desc: "Anda menyentuh makhluk. Jarak lompatan makhluk itu menjadi tiga kali lipat hingga mantranya berakhir." },
      { name: "Longstrider", components: "V, S, M", desc: "Anda menyentuh makhluk. Kecepatan target meningkat 10 kaki hingga mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot mantra di atas level 1." },
      { name: "Purify Food and Drink", components: "V, S", desc: "Semua makanan dan minuman non-magis dalam radius 5 kaki yang berpusat pada titik pilihan Anda dalam jangkauan dimurnikan dan bebas dari racun dan penyakit." },
      { name: "Speak with Animals", components: "V, S", desc: "Anda memperoleh kemampuan untuk memahami dan berkomunikasi secara verbal dengan binatang selama durasi tersebut. Pengetahuan dan kesadaran banyak binatang dibatasi oleh kecerdasan mereka, tetapi minimal, binatang dapat memberi Anda informasi tentang lokasi dan monster terdekat, termasuk apa pun yang dapat mereka lihat atau rasakan dalam satu hari terakhir. Anda mungkin bisa membujuk seekor binatang untuk memberikan bantuan kecil kepada Anda, sesuai kebijaksanaan GM." },
      { name: "Thunderwave", components: "V, S", desc: "Gelombang kekuatan yang menggelegar menyapu Anda. Setiap makhluk dalam kubus berukuran 15 kaki yang berasal dari Anda harus melakukan lemparan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk menerima kerusakan petir sebesar 2d8 dan didorong sejauh 10 kaki dari Anda. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan dan tidak didorong.\nSelain itu, objek tanpa jaminan yang sepenuhnya berada dalam area efek secara otomatis didorong sejauh 10 kaki dari Anda oleh efek mantra, dan mantra tersebut mengeluarkan ledakan menggelegar yang terdengar hingga jarak 300 kaki.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 1." },
    ],
    Level2: [
      { name: "Animal Messenger", components: "V, S, M", desc: "Melalui mantra ini, Anda menggunakan binatang untuk menyampaikan pesan. Pilih binatang kecil yang dapat Anda lihat dalam jangkauannya, seperti tupai, blue jay, atau kelelawar. Anda menentukan lokasi, yang harus Anda kunjungi, dan penerima yang cocok dengan gambaran umum, seperti \"pria atau wanita berseragam penjaga kota\" atau \"kurcaci berambut merah yang memakai topi runcing\". Anda juga mengucapkan pesan hingga dua puluh lima kata. Binatang target melakukan perjalanan selama durasi mantra menuju lokasi yang ditentukan, menempuh jarak sekitar 50 mil per 24 jam untuk pembawa pesan terbang, atau 25 mil untuk hewan lain.\nSaat pembawa pesan tiba, ia menyampaikan pesan Anda kepada makhluk yang Anda gambarkan, meniru suara Anda. Utusan itu hanya berbicara kepada makhluk yang cocok dengan deskripsi yang Anda berikan. Jika pembawa pesan tidak mencapai tujuannya sebelum mantranya berakhir, pesannya akan hilang, dan binatang itu akan kembali ke tempat Anda mengucapkan mantra ini.\nJika Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, durasi mantra bertambah 48 jam untuk setiap slot level di atas 2." },
      { name: "Barkskin", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia. Hingga mantranya berakhir, kulit target akan terlihat kasar, seperti kulit kayu, dan AC target tidak boleh kurang dari 16, apa pun jenis armor yang dikenakannya." },
      { name: "Darkvision", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia memberinya kemampuan melihat dalam kegelapan. Selama durasinya, makhluk itu memiliki penglihatan gelap hingga jarak 60 kaki." },
      { name: "Enhance Ability", components: "V, S, M", desc: "Anda menyentuh makhluk dan memberinya peningkatan ajaib. Pilih salah satu dari efek berikut; target mendapatkan efek itu hingga mantranya berakhir.\n***Daya Tahan Beruang.*** Targetnya memiliki keunggulan dalam pemeriksaan konstitusi. Ia juga mendapatkan 2d6 poin hit sementara, yang hilang saat mantranya berakhir.\n***Kekuatan Banteng.*** Target memiliki keunggulan dalam pemeriksaan kekuatan, dan daya dukungnya berlipat ganda.\n***Rahmat Kucing.*** Target memiliki keunggulan dalam pemeriksaan ketangkasan. Ia juga tidak menerima kerusakan jika terjatuh dari ketinggian 20 kaki atau kurang jika tidak dilumpuhkan.\n***Kemegahan Elang.*** Target memiliki keunggulan dalam pemeriksaan Karisma.\n***Kelicikan Rubah.*** Targetnya memiliki keunggulan dalam pemeriksaan intelijen.\n***Kebijaksanaan Burung Hantu.*** Target memiliki keuntungan dalam pemeriksaan kebijaksanaan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Find Traps", components: "V, S", desc: "Anda merasakan adanya jebakan apa pun dalam jangkauan yang berada dalam jarak pandang. Jebakan, untuk tujuan mantra ini, mencakup segala sesuatu yang dapat menimbulkan efek tiba-tiba atau tidak terduga yang Anda anggap berbahaya atau tidak diinginkan, yang secara khusus dimaksudkan oleh penciptanya. Dengan demikian, mantra tersebut akan mendeteksi area yang terkena mantra alarm, mesin terbang penangkal, atau jebakan lubang mekanis, namun tidak akan mengungkapkan kelemahan alami di lantai, langit-langit yang tidak stabil, atau lubang pembuangan yang tersembunyi.\nMantra ini hanya mengungkapkan bahwa ada jebakan. Anda tidak mempelajari lokasi setiap jebakan, namun Anda mempelajari sifat umum bahaya yang ditimbulkan oleh jebakan yang Anda rasakan." },
      { name: "Flame Blade", components: "V, S, M", desc: "Anda membangkitkan pedang api di tangan Anda yang bebas. Bilahnya memiliki ukuran dan bentuk yang mirip dengan pedang, dan tahan lama. Jika Anda melepaskan bilahnya, bilahnya akan hilang, tetapi Anda dapat membangkitkan bilahnya lagi sebagai aksi bonus.\nAnda dapat menggunakan tindakan Anda untuk melakukan serangan mantra jarak dekat dengan pedang api. Saat terkena, target menerima kerusakan api 3d6.\nBilah yang menyala memancarkan cahaya terang dalam radius 10 kaki dan cahaya redup pada radius tambahan 10 kaki.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap dua slot level di atas 2." },
      { name: "Flaming Sphere", components: "V, S, M", desc: "Bola api berdiameter 5 kaki muncul di ruang kosong pilihan Anda dalam jangkauan dan bertahan selama durasi tersebut. Makhluk apa pun yang mengakhiri gilirannya dalam jarak 5 kaki dari bola harus melakukan lemparan penyelamatan ketangkasan. Makhluk itu menerima kerusakan api sebesar 2d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil.\nSebagai aksi bonus, Anda dapat memindahkan bola hingga 30 kaki. Jika Anda menabrakkan bola ke makhluk, makhluk itu harus melakukan lemparan penyelamatan terhadap kerusakan bola, dan bola berhenti bergerak pada belokan ini.\nSaat menggerakkan bola, Anda dapat mengarahkannya melewati penghalang setinggi 5 kaki dan melompati lubang selebar 10 kaki. Bola tersebut menyulut benda mudah terbakar yang tidak dipakai atau dibawa, dan memancarkan cahaya terang dalam radius 20 kaki dan cahaya redup dalam radius 20 kaki tambahan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 2." },
      { name: "Gust of Wind", components: "V, S, M", desc: "Garis angin kencang sepanjang 60 kaki dan lebar 10 kaki bertiup dari Anda ke arah yang Anda pilih selama durasi mantra. Setiap makhluk yang memulai gilirannya di garis harus berhasil melakukan lemparan hemat kekuatan atau didorong sejauh 15 kaki dari Anda ke arah yang mengikuti garis.\nMakhluk apa pun yang berada dalam barisan harus menghabiskan 2 kaki gerakan untuk setiap 1 kaki yang bergerak saat bergerak mendekati Anda.\nHembusan angin menyebarkan gas atau uap, dan memadamkan lilin, obor, dan nyala api serupa yang tidak terlindungi di area tersebut. Hal ini menyebabkan api yang terlindung, seperti api lentera, menari dengan liar dan memiliki peluang 50 persen untuk memadamkannya.\nSebagai tindakan bonus di setiap giliran Anda sebelum mantra berakhir, Anda dapat mengubah arah ledakan garis dari Anda." },
      { name: "Heat Metal", components: "V, S, M", desc: "Pilih benda logam buatan pabrik, seperti senjata logam atau baju besi logam berat atau sedang, yang dapat Anda lihat dalam jangkauan. Anda menyebabkan objek bersinar merah membara. Makhluk apa pun yang melakukan kontak fisik dengan objek akan menerima kerusakan api 2d8 saat Anda mengucapkan mantra. Hingga mantranya berakhir, Anda dapat menggunakan aksi bonus pada setiap giliran berikutnya untuk menimbulkan kerusakan ini lagi.\nJika makhluk memegang atau memakai benda tersebut dan menerima kerusakan darinya, makhluk tersebut harus berhasil melakukan penyelamatan konstitusi dengan melempar atau menjatuhkan benda tersebut jika bisa. Jika tidak menjatuhkan objek, ia mempunyai kerugian pada serangan dan pemeriksaan kemampuan hingga awal giliran Anda berikutnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 2." },
      { name: "Hold Person", components: "V, S, M", desc: "Pilih humanoid yang dapat Anda lihat dalam jangkauan. Target harus berhasil melakukan penyelamatan kebijaksanaan atau menjadi lumpuh selama jangka waktu tersebut. Di akhir setiap giliran, target dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, mantranya berakhir tepat sasaran.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu humanoid tambahan untuk setiap slot level di atas 2. Humanoid harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkannya." },
      { name: "Lesser Restoration", components: "V, S", desc: "Anda menyentuh suatu makhluk dan dapat mengakhiri satu penyakit atau satu kondisi yang menimpanya. Kondisinya bisa menjadi buta, tuli, lumpuh, atau keracunan." },
      { name: "Locate Animals or Plants", components: "V, S, M", desc: "Jelaskan atau beri nama jenis binatang atau tumbuhan tertentu. Berkonsentrasi pada suara alam di sekitar Anda, Anda mempelajari arah dan jarak ke makhluk atau tumbuhan terdekat dalam jarak 5 mil, jika ada." },
      { name: "Locate Object", components: "V, S, M", desc: "Jelaskan atau beri nama suatu objek yang Anda kenal. Anda merasakan arah ke lokasi objek, selama objek tersebut berada dalam jarak 1.000 kaki dari Anda. Jika suatu benda bergerak, maka diketahui arah pergerakannya.\nMantra tersebut dapat menemukan lokasi objek tertentu yang Anda kenal, selama Anda telah melihatnya dari dekat--dalam jarak 30 kaki--setidaknya sekali. Alternatifnya, mantra tersebut dapat menemukan lokasi objek terdekat dari jenis tertentu, seperti jenis pakaian, perhiasan, furnitur, perkakas, atau senjata tertentu.\nMantra ini tidak dapat menemukan lokasi suatu objek jika ada timah tebal, bahkan lembaran tipis, menghalangi jalur langsung antara Anda dan objek tersebut." },
      { name: "Moonbeam", components: "V, S, M", desc: "Seberkas cahaya pucat keperakan bersinar dalam radius 5 kaki, silinder setinggi 40 kaki yang berpusat pada suatu titik dalam jangkauan. Sampai mantranya berakhir, cahaya redup memenuhi silinder.\nSaat makhluk memasuki area mantra untuk pertama kalinya pada suatu belokan atau memulai gilirannya di sana, ia akan dilalap api hantu yang menyebabkan rasa sakit yang membakar, dan ia harus melakukan penyelamatan konstitusi. Dibutuhkan 2d10 damage besar pada penyelamatan yang gagal, atau setengah damage pada penyelamatan yang berhasil.\nSeorang pengubah bentuk melakukan penyelamatannya dengan posisi yang kurang menguntungkan. Jika gagal, ia juga langsung kembali ke bentuk aslinya dan tidak dapat mengambil bentuk lain hingga ia meninggalkan cahaya mantranya.\nDi setiap giliran Anda setelah mengucapkan mantra ini, Anda dapat menggunakan tindakan untuk memindahkan sinar sejauh 60 kaki ke segala arah.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan meningkat sebesar 1dl0 untuk setiap slot level di atas 2." },
      { name: "Pass Without Trace", components: "V, S, M", desc: "Selubung bayangan dan keheningan memancar dari Anda, menutupi Anda dan rekan Anda dari deteksi. Selama durasinya, setiap makhluk yang Anda pilih dalam jarak 30 kaki dari Anda (termasuk Anda) memiliki bonus +10 untuk pemeriksaan Dexterity (Stealth) dan tidak dapat dilacak kecuali dengan cara magis. Makhluk yang menerima bonus ini tidak meninggalkan jejak atau jejak lain dalam perjalanannya." },
      { name: "Protection from Poison", components: "V, S", desc: "Anda menyentuh makhluk. Jika diracuni, Anda menetralisir racunnya. Jika lebih dari satu racun menimpa target, Anda menetralisir satu racun yang Anda tahu ada, atau Anda menetralisir satu racun secara acak.\nSelama durasi tersebut, target memiliki keuntungan dalam menyimpan lemparan agar tidak terkena racun, dan memiliki ketahanan terhadap kerusakan akibat racun." },
      { name: "Spike Growth", components: "V, S, M", desc: "Tanah dalam radius 20 kaki yang berpusat pada suatu titik dalam jangkauannya berputar dan menumbuhkan paku dan duri yang keras. Daerah tersebut menjadi medan yang sulit selama ini. Saat makhluk bergerak ke dalam atau di dalam area tersebut, ia menerima kerusakan tusuk sebesar 2d4 untuk setiap 5 kaki yang ia tempuh.\nTransformasi tanah disamarkan agar terlihat alami. Makhluk apa pun yang tidak dapat melihat area tersebut pada saat mantra diucapkan dapat melakukan pemeriksaan Kebijaksanaan (Persepsi) terhadap mantra Anda, simpan DC untuk mengenali medan tersebut sebagai berbahaya sebelum memasukinya." },
    ],
    Level3: [
      { name: "Call Lightning", components: "V, S", desc: "Awan badai muncul dalam bentuk silinder setinggi 10 kaki dengan radius 60 kaki, berpusat pada suatu titik yang terlihat 100 kaki tepat di atas Anda. Mantra tersebut gagal jika Anda tidak dapat melihat titik di udara di mana awan badai dapat muncul (misalnya, jika Anda berada di ruangan yang tidak dapat menampung awan tersebut).\nSaat Anda mengucapkan mantra, pilih titik yang dapat Anda lihat dalam jangkauannya. Sambaran petir menyambar dari awan ke titik itu. Setiap makhluk dalam jarak 5 kaki dari titik tersebut harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan petir sebesar 3d10 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Di setiap giliran Anda hingga mantranya berakhir, Anda dapat menggunakan tindakan Anda untuk memanggil petir dengan cara ini lagi, menargetkan titik yang sama atau berbeda.\nJika Anda berada di luar ruangan dalam kondisi badai saat mengucapkan mantra ini, mantra ini memberi Anda kendali atas badai yang ada alih-alih membuat badai baru. Dalam kondisi seperti itu, kerusakan mantra meningkat sebesar 1d10.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan meningkat sebesar 1d10 untuk setiap slot level di atas 3." },
      { name: "Conjure Animals", components: "V, S", desc: "Anda memanggil roh-roh jahat yang berbentuk binatang buas dan muncul di ruang kosong yang dapat Anda lihat dalam jangkauan. Pilih salah satu opsi berikut untuk apa yang muncul:\n- Satu binatang dengan peringkat tantangan 2 atau lebih rendah\n- Dua binatang dengan peringkat tantangan 1 atau lebih rendah\n- Empat binatang dengan peringkat tantangan 1/2 atau lebih rendah\n- Delapan binatang dengan peringkat tantangan 1/4 atau lebih rendah\n- Setiap binatang juga dianggap ganas, dan menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nMakhluk yang dipanggil ramah terhadap Anda dan teman Anda. Gulung inisiatif untuk makhluk yang dipanggil sebagai kelompok, yang memiliki giliran tersendiri. Mereka mematuhi perintah verbal apa pun yang Anda berikan kepada mereka (Anda tidak perlu melakukan tindakan apa pun). Jika Anda tidak memberikan perintah apa pun kepada mereka, mereka mempertahankan diri dari makhluk bermusuhan, tetapi sebaliknya tidak mengambil tindakan.\nGM mempunyai statistik makhluk-makhluk itu.\nLevel Tinggi: Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat tinggi tertentu, Anda memilih salah satu opsi pemanggilan di atas, dan lebih banyak makhluk muncul: dua kali lebih banyak dengan slot level 5, tiga kali lebih banyak dengan slot level 7." },
      { name: "Create Food and Water", components: "V, S", desc: "Anda menghasilkan 45 pon makanan dan 30 galon air di tanah atau di dalam wadah dalam jangkauan, cukup untuk menopang hingga lima belas humanoid atau lima kuda selama 24 jam. Makanannya hambar namun bergizi, dan akan rusak jika tidak dimakan setelah 24 jam. Airnya bersih dan tidak busuk." },
      { name: "Daylight", components: "V, S", desc: "Bola cahaya dengan radius 60 kaki menyebar dari titik yang Anda pilih dalam jangkauannya. Bola tersebut memiliki cahaya terang dan memancarkan cahaya redup sejauh 60 kaki.\nJika Anda memilih suatu titik pada suatu benda yang Anda pegang atau yang tidak sedang dipakai atau dibawa, cahaya akan bersinar dari benda tersebut dan bergerak bersamanya. Menutupi seluruh objek yang terkena dengan benda buram, seperti mangkuk atau helm, akan menghalangi cahaya.\nJika salah satu area mantra ini tumpang tindih dengan area kegelapan yang diciptakan oleh mantra level 3 atau lebih rendah, mantra yang menciptakan kegelapan tersebut akan hilang." },
      { name: "Dispel Magic", components: "V, S", desc: "Pilih satu makhluk, objek, atau efek magis dalam jangkauan. Mantra level 3 atau lebih rendah pada target akan berakhir. Untuk setiap mantra level 4 atau lebih tinggi pada target, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika pemeriksaan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda secara otomatis mengakhiri efek mantra pada target jika level mantra sama dengan atau kurang dari level slot mantra yang Anda gunakan." },
      { name: "Plant Growth", components: "V, S", desc: "Mantra ini menyalurkan vitalitas ke tanaman di area tertentu. Ada dua kemungkinan penggunaan mantra ini, memberikan manfaat langsung atau jangka panjang.\nJika Anda mengucapkan mantra ini menggunakan 1 tindakan, pilih titik dalam jangkauan. Semua tanaman normal dalam radius 100 kaki yang berpusat pada titik tersebut menjadi lebat dan ditumbuhi tanaman. Makhluk yang bergerak melalui area tersebut harus menghabiskan 4 kaki gerakan untuk setiap 1 kaki yang digerakkannya.\nAnda dapat mengecualikan satu atau lebih area dengan ukuran berapa pun di dalam area mantra agar tidak terpengaruh.\nJika Anda mengucapkan mantra ini selama 8 jam, Anda memperkaya tanah. Semua tanaman dalam radius setengah mil yang berpusat pada suatu titik dalam jangkauan akan diperkaya selama 1 tahun. Tanaman menghasilkan dua kali jumlah makanan normal saat dipanen." },
      { name: "Protection From Energy", components: "V, S", desc: "Selama durasi tersebut, makhluk yang Anda sentuh memiliki ketahanan terhadap satu jenis kerusakan pilihan Anda: asam, dingin, api, kilat, atau guntur." },
      { name: "Sleet Storm", components: "V, S, M", desc: "Hingga mantranya berakhir, hujan beku dan hujan es akan turun dalam silinder setinggi 20 kaki dengan radius 40 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan. Area tersebut sangat tertutup, dan api yang terbuka di area tersebut telah padam.\nTanah di kawasan tersebut tertutup es licin sehingga menyulitkan medan. Saat makhluk memasuki area mantra untuk pertama kalinya pada suatu giliran atau memulai gilirannya di sana, ia harus melakukan lemparan penyelamatan ketangkasan. Pada penyelamatan yang gagal, ia menjadi rawan.\nJika makhluk sedang berkonsentrasi di area mantra, makhluk tersebut harus berhasil melakukan lemparan penyelamatan konstitusi terhadap penyelamatan mantra Anda DC atau kehilangan konsentrasi." },
      { name: "Speak with Plants", components: "V, S", desc: "Anda mengilhami tanaman dalam jarak 30 kaki dari Anda dengan perasaan dan animasi terbatas, memberi mereka kemampuan untuk berkomunikasi dengan Anda dan mengikuti perintah sederhana Anda. Anda dapat menanyakan tanaman tentang kejadian di area mantra dalam satu hari terakhir, mendapatkan informasi tentang makhluk yang telah lewat, cuaca, dan keadaan lainnya.\nAnda juga dapat mengubah medan sulit yang disebabkan oleh pertumbuhan tanaman (seperti semak belukar dan semak belukar) menjadi medan biasa yang bertahan lama. Atau Anda dapat mengubah medan biasa yang terdapat tanaman menjadi medan sulit yang bertahan lama, menyebabkan tanaman merambat dan dahan menghalangi pengejar, misalnya.\nPabrik mungkin dapat melakukan tugas lain atas nama Anda, sesuai kebijakan GM. Mantra tersebut tidak memungkinkan tanaman untuk mencabut dirinya sendiri dan bergerak, tetapi mereka dapat dengan bebas memindahkan cabang, sulur, dan batang.\nJika ada makhluk tumbuhan di area tersebut, Anda dapat berkomunikasi dengannya seolah-olah Anda memiliki bahasa yang sama, namun Anda tidak memperoleh kemampuan magis untuk memengaruhinya.\nMantra ini dapat menyebabkan tanaman yang diciptakan oleh mantra entangle melepaskan makhluk yang tertahan." },
      { name: "Water Breathing", components: "V, S, M", desc: "Mantra ini memberikan maksimal sepuluh makhluk yang bersedia berada dalam jangkauannya dan Anda dapat melihat, kemampuan bernapas di bawah air hingga akhir masa berlakunya. Makhluk yang terkena dampak juga mempertahankan pola pernapasan normalnya." },
      { name: "Water Walk", components: "V, S, M", desc: "Mantra ini memberikan kemampuan untuk bergerak melintasi permukaan cair apa pun--seperti air, asam, lumpur, salju, pasir hisap, atau lava--seolah-olah permukaan tersebut adalah tanah padat yang tidak berbahaya (makhluk yang melintasi lava cair masih dapat menerima kerusakan akibat panas). Hingga sepuluh makhluk yang dapat Anda lihat dalam jangkauan mendapatkan kemampuan ini selama durasi tersebut.\nJika Anda menargetkan makhluk yang terendam dalam cairan, mantranya akan membawa target ke permukaan cairan dengan kecepatan 60 kaki per putaran." },
      { name: "Wind Wall", components: "V, S, M", desc: "Dinding angin kencang muncul dari tanah pada titik yang Anda pilih dalam jangkauannya. Anda dapat membuat tembok dengan panjang hingga 50 kaki, tinggi 15 kaki, dan tebal 1 kaki. Anda dapat membentuk dinding dengan cara apa pun yang Anda pilih selama dinding tersebut membentuk satu jalur yang berkesinambungan di sepanjang tanah. Dinding itu bertahan selama itu.\nSaat tembok muncul, setiap makhluk di dalam areanya harus melakukan lemparan hemat kekuatan. Makhluk menerima kerusakan sebesar 3d8 jika penyelamatan gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nAngin kencang menghalangi kabut, asap, dan gas lainnya. Makhluk atau benda terbang yang berukuran kecil atau lebih kecil tidak dapat melewati dinding. Bahan longgar dan ringan yang dibawa ke dinding terbang ke atas. Anak panah, baut, dan proyektil biasa lainnya yang diluncurkan ke sasaran di balik tembok dibelokkan ke atas dan otomatis meleset. (Batu-batu besar yang dilemparkan oleh raksasa atau mesin pengepungan, dan proyektil serupa, tidak terpengaruh.) Makhluk dalam bentuk gas tidak dapat melewatinya." },
    ],
    Level4: [
      { name: "Blight", components: "V, S", desc: "Energi necromantic menyapu makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan, menguras kelembapan dan vitalitas darinya. Targetnya harus melakukan penyelamatan konstitusi. Target menerima 8d8 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nJika Anda menargetkan makhluk tumbuhan atau tumbuhan ajaib, lemparan penyelamatan akan merugikan, dan mantranya akan memberikan kerusakan maksimal padanya.\nJika Anda menargetkan tanaman non-magis yang bukan makhluk, seperti pohon atau semak, hal tersebut tidak akan menjadi solusi penyelamatan; itu hanya layu dan mati.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 ke atas, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas ke-4." },
      { name: "Confusion", components: "V, S, M", desc: "Mantra ini menyerang dan memutarbalikkan pikiran makhluk, menimbulkan delusi dan memicu tindakan yang tidak terkendali. Setiap makhluk dalam bola berradius 10 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan harus berhasil melakukan lemparan penyelamatan Kebijaksanaan saat Anda mengucapkan mantra ini atau terpengaruh olehnya.\nTarget yang terpengaruh tidak dapat bereaksi dan harus melempar d10 di awal setiap giliran untuk menentukan perilakunya pada giliran tersebut.\n| d10 | Perilaku |\n|---|---|\n| 1 | Makhluk itu menggunakan seluruh gerakannya untuk bergerak ke arah yang acak. Untuk menentukan arah, putar d8 dan tetapkan arah pada setiap permukaan dadu. Makhluk itu tidak mengambil tindakan pada giliran ini. |\n| 2-6 | Makhluk itu tidak bergerak atau mengambil tindakan pada giliran ini. |\n| 7-8 | Makhluk itu menggunakan aksinya untuk melakukan serangan jarak dekat terhadap makhluk yang ditentukan secara acak dalam jangkauannya. Jika tidak ada makhluk dalam jangkauannya, makhluk itu tidak akan melakukan apa pun pada giliran ini. |\n| 9-10 | Makhluk itu dapat bertindak dan bergerak dengan normal. |\nDi akhir setiap giliran, target yang terkena dampak dapat melakukan lemparan penyelamatan Wisdom. Jika berhasil, efek ini berakhir untuk target tersebut.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, radius bola bertambah 5 kaki untuk setiap slot level di atas 4." },
      { name: "Conjure Minor Elementals", components: "V, S", desc: "Anda memanggil elemen yang muncul di ruang kosong yang dapat Anda lihat dalam jangkauan. Anda memilih salah satu opsi berikut untuk apa yang muncul:\n- Satu elemen tantangan dengan peringkat 2 atau lebih rendah\n- Dua elemen dengan peringkat tantangan 1 atau lebih rendah\n- Empat elemen dengan peringkat tantangan 1/2 atau lebih rendah\n- Delapan elemen dengan peringkat tantangan 1/4 atau lebih rendah.\nElemen yang dipanggil oleh mantra ini menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nMakhluk yang dipanggil ramah terhadap Anda dan teman Anda. Gulung inisiatif untuk makhluk yang dipanggil sebagai kelompok, yang memiliki giliran tersendiri. Mereka mematuhi perintah verbal apa pun yang Anda berikan kepada mereka (Anda tidak perlu melakukan tindakan apa pun). Jika Anda tidak memberikan perintah apa pun kepada mereka, mereka mempertahankan diri dari makhluk bermusuhan, tetapi sebaliknya tidak mengambil tindakan.\nGM mempunyai statistik makhluk-makhluk itu.\nLevel Tinggi: Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat tinggi tertentu, Anda memilih salah satu opsi pemanggilan di atas, dan lebih banyak makhluk muncul: dua kali lebih banyak dengan slot level 6 dan tiga kali lebih banyak dengan slot level 8." },
      { name: "Conjure Woodland Beings", components: "V, S, M", desc: "Anda memanggil makhluk-makhluk jahat yang muncul di ruang kosong yang dapat Anda lihat dalam jangkauan. Pilih salah satu opsi berikut untuk apa yang muncul:\n- Satu makhluk dengan peringkat tantangan 2 atau lebih rendah\n- Dua makhluk buas dengan peringkat tantangan 1 atau lebih rendah\n- Empat makhluk buas dengan peringkat tantangan 1/2 atau lebih rendah\n- Delapan makhluk buas dengan peringkat tantangan 1/4 atau lebih rendah\nMakhluk yang dipanggil menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nMakhluk yang dipanggil ramah terhadap Anda dan teman Anda. Gulung inisiatif untuk makhluk yang dipanggil sebagai kelompok, yang mempunyai giliran masing-masing. Mereka mematuhi perintah verbal apa pun yang Anda berikan kepada mereka (Anda tidak perlu melakukan tindakan apa pun). Jika Anda tidak memberikan perintah apa pun kepada mereka, mereka mempertahankan diri dari makhluk bermusuhan, tetapi sebaliknya tidak mengambil tindakan.\nGM mempunyai statistik makhluk-makhluk itu.\nLevel Tinggi: Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat tinggi tertentu, Anda memilih salah satu opsi pemanggilan di atas, dan lebih banyak makhluk muncul: dua kali lebih banyak dengan slot level 6 dan tiga kali lebih banyak dengan slot level 8." },
      { name: "Control Water", components: "V, S, M", desc: "Hingga mantranya berakhir, Anda mengontrol air yang berdiri sendiri di dalam area yang Anda pilih, yaitu kubus dengan tinggi hingga 100 kaki di sisinya. Anda dapat memilih salah satu efek berikut saat menggunakan mantra ini. Sebagai tindakan pada giliran Anda, Anda dapat mengulangi efek yang sama atau memilih efek yang berbeda.\n***Banjir.*** Anda menyebabkan permukaan air di semua genangan air di area tersebut naik sebanyak 20 kaki. Jika wilayah tersebut termasuk pantai, maka air banjir akan meluap ke daratan kering.\nJika Anda memilih suatu area di perairan yang luas, Anda malah menciptakan gelombang setinggi 20 kaki yang bergerak dari satu sisi area ke sisi lainnya dan kemudian jatuh. Kendaraan besar atau kecil apa pun yang berada di jalur gelombang akan terbawa ke sisi lain. Kendaraan besar atau kecil apa pun yang terkena gelombang mempunyai peluang 25 persen untuk terbalik.\nKetinggian air tetap tinggi hingga mantra berakhir atau Anda memilih efek lain. Jika efek ini menghasilkan gelombang, gelombang tersebut akan berulang pada awal giliran Anda berikutnya selama efek banjir berlangsung.\n***Bagian Air.*** Anda menyebabkan air di area tersebut menjauh dan membuat parit. Parit tersebut membentang melintasi area mantra, dan air yang terpisah membentuk dinding di kedua sisinya. Parit tetap ada sampai mantranya berakhir atau Anda memilih efek yang berbeda. Air kemudian perlahan-lahan mengisi parit selama putaran berikutnya sampai ketinggian air kembali normal.\n***Aliran Pengalihan.*** Anda menyebabkan air yang mengalir di area tersebut bergerak ke arah yang Anda pilih, meskipun air harus mengalir melewati rintangan, ke atas tembok, atau ke arah lain yang tidak terduga. Air di area tersebut bergerak saat Anda mengarahkannya, tetapi setelah bergerak melampaui area mantra, air tersebut melanjutkan alirannya berdasarkan kondisi medan. Air terus bergerak ke arah yang Anda pilih hingga mantranya berakhir atau Anda memilih efek yang berbeda.\n***Whirlpool.*** Efek ini memerlukan badan air setidaknya 50 kaki persegi dan kedalaman 25 kaki. Anda menyebabkan pusaran air terbentuk di tengah area. Pusaran air tersebut membentuk pusaran dengan lebar dasar 5 kaki, lebar bagian atas hingga 50 kaki, dan tinggi 25 kaki. Makhluk atau benda apa pun di dalam air dan dalam jarak 25 kaki dari pusaran akan ditarik sejauh 10 kaki ke arahnya. Makhluk dapat berenang menjauh dari pusaran dengan melakukan pemeriksaan Kekuatan (Atletik) terhadap mantra Anda, simpan DC.\nKetika makhluk memasuki pusaran untuk pertama kalinya pada suatu belokan atau memulai belokannya di sana, ia harus melakukan lemparan yang menghemat kekuatan. Jika penyelamatan gagal, makhluk itu menerima kerusakan sebesar 2d8 dan terjebak dalam pusaran hingga mantranya berakhir. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan, dan tidak terjebak dalam pusaran. Makhluk yang terjebak dalam pusaran dapat menggunakan aksinya untuk mencoba berenang menjauh dari pusaran seperti dijelaskan di atas, namun memiliki kelemahan pada pemeriksaan Kekuatan (Atletik) untuk melakukannya.\nPertama kali setiap putaran suatu benda memasuki pusaran, benda tersebut menerima kerusakan pukulan sebesar 2d8; kerusakan ini terjadi setiap putarannya tetap berada di pusaran." },
      { name: "Divination", components: "V, S, M", desc: "Sihir dan persembahan Anda menghubungkan Anda dengan dewa atau pelayan dewa. Anda mengajukan satu pertanyaan mengenai tujuan, peristiwa, atau aktivitas tertentu yang akan terjadi dalam 7 hari. GM menawarkan jawaban yang jujur. Jawabannya mungkin berupa kalimat pendek, sajak samar, atau pertanda.\nMantra tersebut tidak memperhitungkan kemungkinan keadaan yang dapat mengubah hasil, seperti penggunaan mantra tambahan atau kehilangan atau perolehan rekan.\nJika Anda merapal mantra dua kali atau lebih sebelum menyelesaikan istirahat panjang berikutnya, ada peluang kumulatif 25 persen untuk setiap casting setelah yang pertama Anda mendapatkan pembacaan acak. GM melakukan hal ini secara rahasia." },
      { name: "Dominate Beast", components: "V, S", desc: "Anda mencoba memperdaya makhluk yang dapat Anda lihat dalam jangkauan. Ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Jika Anda atau makhluk yang bersahabat dengan Anda melawannya, ia memiliki keuntungan dalam penyelamatan.\nMeskipun makhluk itu terpesona, Anda memiliki hubungan telepati dengannya selama Anda berdua berada di alam eksistensi yang sama. Anda dapat menggunakan tautan telepati ini untuk mengeluarkan perintah kepada makhluk itu saat Anda sadar (tidak perlu tindakan apa pun), yang akan dipatuhinya sebaik mungkin. Anda dapat menentukan tindakan yang sederhana dan umum, seperti \"Serang makhluk itu\", \"Lari ke sana\", atau \"Ambil objek itu\". Jika makhluk tersebut menyelesaikan perintahnya dan tidak menerima arahan lebih lanjut dari Anda, ia akan mempertahankan dan mempertahankan dirinya dengan kemampuan terbaiknya.\nAnda dapat menggunakan tindakan Anda untuk mengambil kendali total dan tepat terhadap target. Hingga akhir giliran Anda berikutnya, makhluk itu hanya mengambil tindakan yang Anda pilih, dan tidak melakukan apa pun yang tidak Anda izinkan. Selama waktu ini, Anda juga dapat menyebabkan makhluk tersebut menggunakan reaksi, namun hal ini mengharuskan Anda menggunakan reaksi Anda sendiri juga. Setiap kali target menerima kerusakan, ia membuat lemparan penyelamatan kebijaksanaan baru terhadap mantra tersebut. Jika lemparan penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini dengan slot mantra level 9, durasinya adalah konsentrasi, hingga 8 jam." },
      { name: "Freedom of Movement", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia. Selama durasi tersebut, pergerakan target tidak terpengaruh oleh medan yang sulit, dan mantra serta efek magis lainnya tidak dapat mengurangi kecepatan target atau menyebabkan target menjadi lumpuh atau tertahan.\nTarget juga dapat menggunakan gerakan sejauh 5 kaki untuk secara otomatis melarikan diri dari pengekangan non-magis, seperti borgol atau makhluk yang digenggamnya. Terakhir, berada di bawah air tidak memberikan penalti pada pergerakan atau serangan target." },
      { name: "Giant Insect", components: "V, S", desc: "Anda mengubah hingga sepuluh kelabang, tiga laba-laba, lima tawon, atau satu kalajengking dalam jangkauan menjadi versi raksasa dari bentuk alaminya selama tersebut. Kelabang menjadi kelabang raksasa, laba-laba menjadi laba-laba raksasa, tawon menjadi tawon raksasa, dan kalajengking menjadi kalajengking raksasa.\nSetiap makhluk mematuhi perintah verbal Anda, dan dalam pertempuran, mereka bertindak berdasarkan giliran Anda di setiap putaran. GM memiliki statistik makhluk-makhluk ini dan menentukan tindakan serta pergerakan mereka.\nMakhluk akan tetap berada dalam ukuran raksasanya selama durasi tersebut, hingga poin hitnya turun menjadi 0, atau hingga Anda menggunakan suatu tindakan untuk menghilangkan efeknya.\nGM mungkin mengizinkan Anda memilih target yang berbeda. Misalnya, jika Anda mengubah seekor lebah, versi raksasanya mungkin memiliki statistik yang sama dengan tawon raksasa." },
      { name: "Hallucinatory Terrain", components: "V, S, M", desc: "Anda membuat medan alami dalam kubus berukuran 150 kaki dalam jangkauan tampilan, suara, dan aroma seperti medan alami lainnya. Dengan demikian, lapangan terbuka atau jalan dapat dibuat menyerupai rawa, bukit, jurang, atau medan lain yang sulit atau tidak dapat dilalui. Sebuah kolam dapat dibuat tampak seperti padang rumput, jurang seperti lereng yang landai, atau selokan yang dipenuhi bebatuan seperti jalan yang lebar dan mulus. Struktur, peralatan, dan makhluk yang diproduksi di dalam area tersebut tidak berubah tampilannya.\nKarakteristik sentuhan medan tidak berubah, sehingga makhluk yang memasuki area tersebut kemungkinan besar dapat melihat melalui ilusi. Jika perbedaannya tidak terlihat jelas jika disentuh, makhluk yang memeriksa ilusi dengan cermat dapat mencoba melakukan pemeriksaan Intelijen (Investigasi) terhadap mantra Anda, simpan DC untuk tidak mempercayainya. Makhluk yang memahami ilusi apa adanya, melihatnya sebagai gambaran samar yang ditumpangkan di medan." },
      { name: "Ice Storm", components: "V, S, M", desc: "Hujan es sekeras batu menghantam tanah dalam silinder dengan radius 20 kaki dan tinggi 40 kaki yang berpusat pada suatu titik dalam jangkauan. Setiap makhluk di dalam silinder harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima 2d8 kerusakan pukulan dan 4d6 kerusakan dingin pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nHujan es mengubah area pengaruh badai menjadi medan yang sulit hingga akhir giliran Anda berikutnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, kerusakan pukulan meningkat sebesar 1d8 untuk setiap level slot di atas 4." },
      { name: "Locate Creature", components: "V, S, M", desc: "Jelaskan atau beri nama makhluk yang Anda kenal. Anda merasakan arah ke lokasi makhluk itu, selama makhluk itu berada dalam jarak 1.000 kaki dari Anda. Jika makhluk itu bergerak, Anda mengetahui arah pergerakannya.\nMantra ini dapat menemukan lokasi makhluk tertentu yang Anda kenal, atau makhluk terdekat dari jenis tertentu (seperti manusia atau unicorn), selama Anda pernah melihat makhluk tersebut dari dekat--dalam jarak 30 kaki--setidaknya sekali. Jika makhluk yang Anda gambarkan atau beri nama berada dalam bentuk yang berbeda, seperti berada di bawah pengaruh mantra polimorf, mantra ini tidak akan menemukan lokasi makhluk tersebut.\nMantra ini tidak dapat menemukan lokasi makhluk jika air yang mengalir selebar 10 kaki menghalangi jalur langsung antara Anda dan makhluk tersebut." },
      { name: "Polymorph", components: "V, S, M", desc: "Mantra ini mengubah makhluk yang dapat Anda lihat dalam jangkauan menjadi bentuk baru. Makhluk yang tidak mau harus melakukan lemparan penyelamatan yang bijaksana untuk menghindari dampaknya. Seorang pengubah bentuk secara otomatis berhasil dalam lemparan penyelamatan ini.\nTransformasi berlangsung selama durasi tersebut, atau hingga target turun menjadi 0 poin hit atau mati. Bentuk baru dapat berupa monster apa pun yang peringkat tantangannya sama dengan atau lebih kecil dari target (atau level target, jika tidak memiliki peringkat tantangan). Statistik permainan target, termasuk skor kemampuan mental, digantikan oleh statistik binatang yang dipilih. Ia mempertahankan keselarasan dan kepribadiannya.\nTargetnya mengasumsikan titik sasaran dari bentuk barunya. Ketika ia kembali ke bentuk normalnya, makhluk itu kembali ke jumlah titik serangan yang dimilikinya sebelum ia bertransformasi. Jika poin serangannya kembali karena poin hitnya turun menjadi 0, kerusakan berlebih akan kembali ke bentuk normalnya. Selama kerusakan berlebih tidak mengurangi bentuk normal makhluk itu menjadi 0 poin serangan, ia tidak akan pingsan.\nTindakan yang dapat dilakukan makhluk ini terbatas karena sifat dari bentuk barunya, dan ia tidak dapat berbicara, merapal mantra, atau melakukan tindakan lain apa pun yang memerlukan tangan atau ucapan.\nPerlengkapan target menyatu ke dalam bentuk baru. Makhluk itu tidak dapat mengaktifkan, menggunakan, menggunakan, atau memanfaatkan peralatan apa pun." },
      { name: "Stone Shape", components: "V, S, M", desc: "Anda menyentuh benda batu berukuran sedang atau lebih kecil atau bagian batu tidak lebih dari 5 kaki dalam dimensi apa pun dan membentuknya menjadi bentuk apa pun yang sesuai dengan tujuan Anda. Jadi, misalnya, Anda dapat membentuk sebuah batu besar menjadi senjata, berhala, atau peti, atau membuat jalan kecil melewati dinding, asalkan tebal dinding tersebut kurang dari 5 kaki. Anda juga bisa membentuk pintu batu atau kusennya untuk menutup pintu. Objek yang Anda buat dapat memiliki hingga dua engsel dan satu kait, tetapi detail mekanis yang lebih halus tidak mungkin dilakukan." },
      { name: "Stoneskin", components: "V, S, M", desc: "Mantra ini mengubah daging makhluk yang Anda sentuh menjadi sekeras batu. Hingga mantranya berakhir, target memiliki ketahanan terhadap pukulan non-magis, tusukan, dan tebasan." },
      { name: "Wall of Fire", components: "V, S, M", desc: "Anda membuat dinding api pada permukaan padat dalam jangkauan. Anda dapat membuat tembok dengan panjang hingga 60 kaki, tinggi 20 kaki, dan tebal 1 kaki, atau dinding melingkar dengan diameter hingga 20 kaki, tinggi 20 kaki, dan tebal 1 kaki. Dindingnya buram dan tahan lama.\nSaat tembok muncul, setiap makhluk di dalam areanya harus melakukan lemparan penyelamatan Dexterity. Jika penyelamatan gagal, makhluk akan menerima kerusakan api sebesar 5d8, atau setengah kerusakan jika penyelamatan berhasil.\nSatu sisi dinding, yang Anda pilih saat mengucapkan mantra ini, menimbulkan kerusakan api 5d8 pada setiap makhluk yang mengakhiri gilirannya dalam jarak 10 kaki dari sisi itu atau di dalam dinding. Makhluk menerima kerusakan yang sama saat memasuki dinding untuk pertama kalinya pada suatu belokan atau mengakhiri belokannya di sana. Sisi lain tembok tidak menimbulkan kerusakan.\nSisi lain tembok tidak menimbulkan kerusakan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 4." },
    ],
    Level5: [
      { name: "Antilife Shell", components: "V, S", desc: "Sebuah penghalang berkilauan memanjang dari Anda dalam radius 10 kaki dan bergerak bersama Anda, tetap berpusat pada Anda dan melindungi makhluk selain undead dan konstruksi. Penghalang tersebut bertahan selama durasi tersebut.\nPenghalang tersebut mencegah makhluk yang terkena dampak melewati atau mencapainya. Makhluk yang terkena dampak dapat merapal mantra atau melakukan serangan dengan senjata jarak jauh atau menjangkau senjata melalui penghalang.\nJika Anda bergerak sehingga makhluk yang terkena dampak terpaksa melewati penghalang, mantranya akan berakhir." },
      { name: "Awaken", components: "V, S, M", desc: "Setelah menghabiskan waktu casting menelusuri jalur magis di dalam batu permata yang berharga, Anda menyentuh binatang atau tumbuhan yang besar atau lebih kecil. Target tidak boleh memiliki skor Intelijen atau Intelijen 3 atau kurang. Target memperoleh Kecerdasan 10. Target juga memperoleh kemampuan berbicara satu bahasa yang Anda tahu. Jika targetnya adalah tumbuhan, ia memperoleh kemampuan untuk menggerakkan anggota badan, akar, tanaman merambat, tanaman merambat, dan sebagainya, dan ia memperoleh indra yang mirip dengan manusia. GM Anda memilih statistik yang sesuai untuk tanaman yang terbangun, seperti statistik untuk semak yang terbangun atau pohon yang terbangun.\nBinatang atau tumbuhan yang terbangun akan terpesona oleh Anda selama 30 hari atau sampai Anda atau teman Anda melakukan sesuatu yang berbahaya terhadapnya. Ketika kondisi terpesona berakhir, makhluk yang terbangun memilih apakah akan tetap bersahabat dengan Anda, berdasarkan cara Anda memperlakukannya saat ia terpesona." },
      { name: "Commune With Nature", components: "V, S", desc: "Anda sebentar menjadi satu dengan alam dan mendapatkan pengetahuan tentang wilayah sekitarnya. Di alam terbuka, mantranya memberi Anda pengetahuan tentang daratan dalam jarak 3 mil dari Anda. Di gua dan lingkungan alami bawah tanah lainnya, radius dibatasi hingga 300 kaki. Mantra tidak berfungsi jika alam telah digantikan oleh konstruksi, seperti di ruang bawah tanah dan kota.\nAnda langsung mendapatkan pengetahuan hingga tiga fakta pilihan Anda tentang salah satu subjek berikut yang berkaitan dengan area tersebut:\n- medan dan badan air\n- tumbuhan, mineral, hewan, atau manusia yang lazim\n- makhluk surgawi, fey, iblis, elemental, atau undead yang kuat\n- pengaruh dari alam eksistensi lain\n- bangunan\nMisalnya, Anda dapat menentukan lokasi undead yang kuat di area tersebut, lokasi sumber utama air minum yang aman, dan lokasi kota terdekat." },
      { name: "Conjure Elemental", components: "V, S, M", desc: "Anda memanggil pelayan unsur. Pilih area udara, tanah, api, atau air yang memenuhi kubus berukuran 10 kaki dalam jangkauannya. Elemen tantangan dengan peringkat 5 atau lebih rendah yang sesuai dengan area yang Anda pilih muncul di ruang kosong dalam jarak 10 kaki darinya. Misalnya, elemen api muncul dari api unggun, dan elemen tanah muncul dari tanah. Elemental menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nElementalnya ramah terhadap Anda dan teman Anda selama ini. Gulung inisiatif untuk elemen yang memiliki giliran sendiri. Ia mematuhi perintah verbal apa pun yang Anda berikan padanya (Anda tidak perlu melakukan tindakan apa pun). Jika Anda tidak memberikan perintah apa pun kepada elemen tersebut, ia akan mempertahankan diri dari makhluk musuh, namun sebaliknya tidak akan melakukan tindakan apa pun.\nJika konsentrasimu terganggu, elemennya tidak hilang. Sebaliknya, Anda kehilangan kendali atas elemen tersebut, ia menjadi bermusuhan terhadap Anda dan teman Anda, dan mungkin menyerang. Elemental yang tidak terkontrol tidak dapat Anda hilangkan, dan menghilang 1 jam setelah Anda memanggilnya.\nGM memiliki statistik unsur.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, peringkat tantangan meningkat sebesar 1 untuk setiap slot level di atas 5." },
      { name: "Contagion", components: "V, S", desc: "Sentuhanmu menimbulkan penyakit. Lakukan serangan mantra jarak dekat terhadap makhluk dalam jangkauan Anda. Saat terkena serangan, Anda menimpa makhluk itu dengan penyakit pilihan Anda dari salah satu penyakit yang dijelaskan di bawah ini.\nDi akhir setiap giliran sasaran, ia harus melakukan lemparan penyelamatan konstitusi. Setelah gagal dalam tiga kali penyelamatan ini, efek penyakit bertahan selama tersebut, dan makhluk tersebut berhenti melakukan penyelamatan tersebut. Setelah berhasil melakukan tiga lemparan penyelamatan ini, makhluk itu pulih dari penyakitnya, dan mantranya berakhir.\nKarena mantra ini menyebabkan penyakit alami pada targetnya, efek apa pun yang menghilangkan penyakit atau memperbaiki efek penyakit berlaku padanya.\n***Penyakit yang Membutakan.*** Rasa sakit mencengkeram pikiran makhluk itu, dan matanya berubah menjadi putih susu. Makhluk tersebut memiliki kelemahan pada pemeriksaan kebijaksanaan dan lemparan penyelamatan kebijaksanaan dan menjadi buta.\n***Demam Kotoran.*** Demam yang mengamuk melanda tubuh makhluk itu. Makhluk tersebut memiliki kelemahan dalam pemeriksaan kekuatan, lemparan hemat kekuatan, dan serangan lemparan yang menggunakan Kekuatan.\n***Daging Busuk.*** Daging makhluk itu membusuk. Makhluk ini memiliki kelemahan pada pemeriksaan Karisma dan kerentanan terhadap semua kerusakan.\n***Mindfire.*** Pikiran makhluk itu menjadi meriang. Makhluk tersebut memiliki kelemahan dalam pemeriksaan intelijen dan lemparan penyelamatan intelijen, dan makhluk tersebut berperilaku seolah-olah berada di bawah pengaruh mantra kebingungan selama pertempuran.\n***Kejang.*** Makhluk itu diliputi gemetar. Makhluk tersebut memiliki kelemahan pada dexterity check, dexterity saving throw, dan serangan roll yang menggunakan Dexterity.\n***Slimy Doom.*** Makhluk itu mulai mengeluarkan darah tak terkendali. Makhluk itu memiliki kelemahan dalam pemeriksaan konstitusi dan penyelamatan konstitusi. Selain itu, setiap kali makhluk tersebut menerima kerusakan, ia akan terkena stun hingga akhir giliran berikutnya." },
      { name: "Geas", components: "V", desc: "Anda memberikan perintah magis pada makhluk yang dapat Anda lihat dalam jangkauan, memaksanya untuk melakukan suatu layanan atau menahan diri dari tindakan atau aktivitas tertentu sesuai keputusan Anda. Jika makhluk itu dapat memahami Anda, ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Meskipun makhluk itu terpesona oleh Anda, dibutuhkan 5d10 kerusakan psikis setiap kali ia bertindak berlawanan dengan instruksi Anda, tetapi tidak lebih dari sekali setiap hari. Makhluk yang tidak dapat memahami Anda tidak terpengaruh oleh mantra tersebut.\nAnda dapat mengeluarkan perintah apa pun yang Anda pilih, selain aktivitas yang akan mengakibatkan kematian. Jika Anda mengeluarkan perintah bunuh diri, mantranya akan berakhir.\nAnda dapat mengakhiri mantra lebih awal dengan menggunakan tindakan untuk mengabaikannya. Mantra penghilang kutukan, pemulihan lebih besar, atau harapan juga mengakhirinya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau 8, durasinya adalah 1 tahun. Saat Anda merapal mantra ini menggunakan slot mantra level 9, mantra tersebut akan bertahan hingga diakhiri oleh salah satu mantra yang disebutkan di atas." },
      { name: "Greater Restoration", components: "V, S, M", desc: "Anda mengilhami makhluk yang Anda sentuh dengan energi positif untuk menghilangkan efek yang melemahkan. Anda dapat mengurangi tingkat kelelahan target sebanyak satu, atau mengakhiri salah satu efek berikut pada target:\n- Satu efek yang membuat target terpesona atau membatu\n- Satu kutukan, termasuk attunement target pada item sihir terkutuk\n- Pengurangan apa pun pada salah satu skor kemampuan target\n- Satu efek mengurangi maksimum hit point target" },
      { name: "Insect Plague", components: "V, S, M", desc: "Belalang yang berkerumun dan menggigit memenuhi bola dengan radius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauannya. Bola itu menyebar ke berbagai sudut. Bola tersebut tetap ada selama durasi tersebut, dan areanya sedikit tertutup. Area bola tersebut merupakan medan yang sulit.\nKetika area tersebut muncul, setiap makhluk di dalamnya harus melakukan penyelamatan konstitusi. Makhluk menerima kerusakan menusuk 4d10 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil. Makhluk juga harus melakukan lemparan penyelamatan ini ketika memasuki area mantra untuk pertama kalinya pada suatu giliran atau mengakhiri gilirannya di sana.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kerusakan meningkat sebesar 1d10 untuk setiap slot level di atas 5." },
      { name: "Mass Cure Wounds", components: "V, S", desc: "Gelombang energi penyembuhan mengalir dari titik pilihan Anda dalam jangkauan. Pilih hingga enam makhluk dalam bola radius 30 kaki yang berpusat pada titik tersebut. Setiap target mendapatkan kembali poin hit sebesar 3d8 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, penyembuhan meningkat sebesar 1d8 untuk setiap slot level di atas 5." },
      { name: "Planar Binding", components: "V, S, M", desc: "Dengan mantra ini, Anda mencoba untuk mengikat benda langit, elemen, makhluk, atau iblis ke dalam layanan Anda. Makhluk itu harus berada dalam jangkauan selama seluruh perapalan mantra. (Biasanya, makhluk tersebut pertama kali dipanggil ke tengah lingkaran sihir terbalik agar tetap terjebak saat mantra ini digunakan.) Setelah menyelesaikan casting, target harus melakukan lemparan penyelamatan karisma. Jika penyimpanan gagal, itu pasti akan membantu Anda selama durasi tersebut. Jika makhluk itu dipanggil atau diciptakan oleh mantra lain, durasi mantra tersebut diperpanjang agar sesuai dengan durasi mantra ini.\nMakhluk yang terikat harus mengikuti instruksi Anda dengan kemampuan terbaiknya. Anda mungkin memerintahkan makhluk tersebut untuk menemani Anda berpetualang, menjaga lokasi, atau menyampaikan pesan. Makhluk itu mematuhi instruksi Anda, tetapi jika makhluk itu memusuhi Anda, ia berusaha memutarbalikkan kata-kata Anda untuk mencapai tujuannya sendiri. Jika makhluk tersebut melaksanakan instruksi Anda sepenuhnya sebelum mantranya berakhir, ia akan mendatangi Anda untuk melaporkan fakta ini jika Anda berada di alam keberadaan yang sama. Jika Anda berada di alam eksistensi lain, ia akan kembali ke tempat Anda mengikatnya dan tetap di sana hingga mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra dengan level yang lebih tinggi, durasinya meningkat menjadi 10 hari dengan slot level 6, menjadi 30 hari dengan slot level 7, menjadi 180 hari dengan slot level 8, dan menjadi satu tahun dan satu hari dengan slot mantra level 9." },
      { name: "Reincarnate", components: "V, S, M", desc: "Anda menyentuh humanoid mati atau sepotong humanoid mati. Asalkan makhluk tersebut telah mati tidak lebih dari 10 hari, mantranya akan membentuk tubuh dewasa baru untuknya dan kemudian memanggil jiwa untuk memasuki tubuh tersebut. Jika jiwa target tidak bebas atau tidak mau melakukannya, mantranya akan gagal.\nSihir tersebut membentuk tubuh baru untuk dihuni makhluk tersebut, yang kemungkinan besar menyebabkan ras makhluk tersebut berubah. GM melakukan roll ke 100 dan melihat tabel berikut untuk menentukan bentuk apa yang diambil makhluk tersebut ketika dihidupkan kembali, atau GM yang memilih suatu bentuk.\n| d100 | Ras |\n|---|---|\n| 01-04 | Lahir Naga |\n| 05-13 | Kurcaci, bukit |\n| 14-21 | Kurcaci, gunung |\n| 22-25 | Peri, gelap |\n| 26-34 | Peri, tinggi |\n| 35-42 | Peri, kayu |\n| 43-46 | Gnome, hutan |\n| 47-52 | Kurcaci, batu |\n| 53-56 | Setengah peri |\n| 57-60 | Setengah Orc |\n| 61-68 | Halfling, kaki ringan |\n| 69-76 | Setengah, gagah |\n| 77-96 | Manusia |\n| 97-00 | Menggelikan |\nMakhluk yang bereinkarnasi mengingat kembali kehidupan dan pengalaman sebelumnya. Ia mempertahankan kemampuan yang dimilikinya dalam bentuk aslinya, kecuali ia menukar ras aslinya dengan ras baru dan mengubah ciri rasnya sesuai dengan itu." },
      { name: "Scrying", components: "V, S, M", desc: "Anda dapat melihat dan mendengar makhluk tertentu yang Anda pilih yang berada pada alam eksistensi yang sama dengan Anda. Target harus melakukan lemparan penyelamatan yang bijaksana, yang dimodifikasi oleh seberapa baik Anda mengenal target dan jenis hubungan fisik yang Anda miliki dengannya. Jika target mengetahui Anda merapalkan mantra ini, target dapat gagal melakukan penyelamatan secara sukarela jika ingin diamati.\n| Pengetahuan | Simpan Pengubah |\n|---|---|\n| Bekas (Anda pernah mendengar tentang targetnya) | +5 |\n| Langsung (Anda sudah memenuhi target) | +0 |\n| Familiar (Anda tahu targetnya dengan baik) | -5 |\n\n| Koneksi | Simpan Pengubah |\n|---|---|\n| Kemiripan atau gambar | -2 |\n| Kepemilikan atau pakaian | -4 |\n| Bagian badan, seikat rambut, secuil kuku, atau sejenisnya | -10 |\nJika penyelamatan berhasil, target tidak terpengaruh, dan Anda tidak dapat menggunakan mantra ini lagi selama 24 jam.\nJika penyelamatan gagal, mantra tersebut menciptakan sensor tak terlihat dalam jarak 10 kaki dari target. Anda dapat melihat dan mendengar melalui sensor seolah-olah Anda berada di sana. Sensor bergerak mengikuti target, tetap berada dalam jarak 10 kaki selama durasi tersebut. Makhluk yang dapat melihat objek tak kasat mata melihat sensornya sebagai bola bercahaya seukuran kepalan tangan Anda.\nDaripada mengincar makhluk, kamu bisa memilih lokasi yang pernah kamu lihat sebelumnya sebagai target mantra ini. Ketika Anda melakukannya, sensor muncul di lokasi tersebut dan tidak bergerak." },
      { name: "Tree Stride", components: "V, S", desc: "Anda memperoleh kemampuan untuk memasuki pohon dan berpindah dari dalam pohon ke dalam pohon lain yang sejenis dalam jarak 500 kaki. Kedua pohon tersebut harus hidup dan setidaknya berukuran sama dengan Anda. Anda harus menggunakan gerakan 5 kaki untuk memasuki pohon. Anda langsung mengetahui lokasi semua pohon lain yang sejenis dalam jarak 500 kaki dan, sebagai bagian dari gerakan yang digunakan untuk memasuki pohon, Anda dapat masuk ke salah satu pohon tersebut atau keluar dari pohon tempat Anda berada. Anda muncul di tempat pilihan Anda dalam jarak 5 kaki dari pohon tujuan, menggunakan gerakan 5 kaki lainnya. Jika Anda tidak punya gerakan lagi, Anda muncul dalam jarak 5 kaki dari pohon yang Anda masuki.\nAnda dapat menggunakan kemampuan transportasi ini satu kali per putaran selama durasi tersebut. Anda harus mengakhiri setiap belokan di luar pohon." },
      { name: "Wall of Stone", components: "V, S, M", desc: "Dinding batu padat non-magis muncul pada titik yang Anda pilih dalam jangkauan. Dindingnya setebal 6 inci dan terdiri dari sepuluh panel berukuran 10 kaki kali 10 kaki. Setiap panel harus berdekatan dengan setidaknya satu panel lainnya. Sebagai alternatif, Anda dapat membuat panel berukuran 10 kaki kali 20 kaki yang tebalnya hanya 3 inci.\nJika dinding menembus ruang makhluk saat muncul, makhluk tersebut akan terdorong ke salah satu sisi dinding (pilihan Anda). Jika makhluk dikelilingi di semua sisi oleh dinding (atau dinding dan permukaan padat lainnya), makhluk itu dapat melakukan lemparan penyelamatan ketangkasan. Jika berhasil, ia dapat menggunakan reaksinya untuk menaikkan kecepatannya sehingga tidak lagi tertutup oleh tembok.\nDinding bisa memiliki bentuk apa pun yang Anda inginkan, meski tidak bisa menempati ruang yang sama dengan makhluk atau benda. Dinding tidak harus vertikal atau bertumpu pada fondasi yang kokoh. Namun, ia harus menyatu dan didukung secara kokoh oleh batu yang sudah ada. Jadi, kamu bisa menggunakan mantra ini untuk menjembatani jurang atau membuat tanjakan.\nJika Anda membuat bentang yang panjangnya lebih dari 20 kaki, Anda harus membagi dua ukuran setiap panel untuk membuat penyangga. Anda dapat membentuk dinding secara kasar untuk membuat crenellations, benteng, dan sebagainya.\nDinding merupakan suatu benda yang terbuat dari batu yang dapat dirusak dan ditembus. Setiap panel memiliki ketebalan AC 15 dan 30 titik hit per inci. Mengurangi panel menjadi 0 titik hit akan menghancurkannya dan mungkin menyebabkan panel yang terhubung runtuh sesuai kebijakan GM.\nJika Anda mempertahankan konsentrasi pada mantra ini selama durasinya, tembok menjadi permanen dan tidak dapat dihilangkan. Jika tidak, tembok itu akan hilang saat mantranya berakhir." },
    ],
    Level6: [
      { name: "Conjure Fey", components: "V, S", desc: "Anda memanggil makhluk berbulu dengan peringkat tantangan 6 atau lebih rendah, atau roh berbulu yang berbentuk binatang dengan peringkat tantangan 6 atau lebih rendah. Itu muncul di ruang kosong yang dapat Anda lihat dalam jangkauan. Makhluk fey menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nMakhluk berbulu itu bersahabat dengan Anda dan teman Anda selama ini. Gulung inisiatif untuk makhluk yang mempunyai gilirannya sendiri. Ia mematuhi perintah verbal apa pun yang Anda keluarkan (Anda tidak perlu melakukan tindakan apa pun), selama perintah tersebut tidak melanggar kesejajarannya. Jika Anda tidak memberikan perintah apa pun kepada makhluk berbulu itu, ia akan mempertahankan diri dari makhluk bermusuhan, tetapi sebaliknya tidak mengambil tindakan apa pun.\nJika konsentrasimu terganggu, makhluk berbulu itu tidak akan hilang. Sebaliknya, Anda kehilangan kendali atas makhluk berbulu itu, ia menjadi bermusuhan terhadap Anda dan teman Anda, dan mungkin menyerang. Makhluk berbulu yang tidak terkendali tidak dapat Anda hilangkan, dan ia menghilang 1 jam setelah Anda memanggilnya.\nGM mempunyai statistik makhluk buas itu.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, peringkat tantangan meningkat sebesar 1 untuk setiap slot level di atas 6." },
      { name: "Find the Path", components: "V, S, M", desc: "Mantra ini memungkinkan Anda menemukan rute fisik terpendek dan paling langsung ke lokasi tetap tertentu yang Anda kenal di alam keberadaan yang sama. Jika Anda menyebutkan tujuan di alam eksistensi lain, tujuan yang bergerak (seperti benteng bergerak), atau tujuan yang tidak spesifik (seperti \"sarang naga hijau\"), mantranya akan gagal.\nSelama Anda berada di alam eksistensi yang sama dengan tujuan, Anda tahu seberapa jauh jaraknya dan ke arah mana letaknya. Saat Anda bepergian ke sana, setiap kali Anda dihadapkan pada pilihan jalur di sepanjang jalan, Anda secara otomatis menentukan jalur mana yang merupakan rute terpendek dan paling langsung (tetapi belum tentu rute teraman) ke tujuan." },
      { name: "Heal", components: "V, S", desc: "Pilih makhluk yang dapat Anda lihat dalam jangkauan. Gelombang energi positif menyapu makhluk itu, menyebabkannya mendapatkan kembali 70 poin serangan. Mantra ini juga mengakhiri kebutaan, tuli, dan penyakit apa pun yang menyerang target. Mantra ini tidak berpengaruh pada konstruksi atau undead.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, jumlah penyembuhan meningkat sebesar 10 untuk setiap slot level di atas 6." },
      { name: "Heroes' Feast", components: "V, S, M", desc: "Anda mengadakan pesta besar, termasuk makanan dan minuman yang lezat. Pesta tersebut membutuhkan waktu 1 jam untuk dikonsumsi dan hilang pada akhir waktu tersebut, dan efek menguntungkannya tidak akan terlihat sampai jam tersebut selesai. Hingga dua belas makhluk lain dapat mengambil bagian dalam pesta itu.\nMakhluk yang ikut serta dalam pesta itu memperoleh beberapa manfaat. Makhluk itu sembuh dari segala penyakit dan racun, menjadi kebal terhadap racun dan ketakutan, dan memanfaatkan semua kebijaksanaan yang menyelamatkan dengan manfaat. Hit point maksimumnya juga meningkat 2 hari 10, dan memperoleh jumlah hit point yang sama. Manfaat ini berlaku selama 24 jam." },
      { name: "Move Earth", components: "V, S, M", desc: "Pilih area medan yang tidak lebih besar dari 40 kaki pada sisi yang berada dalam jangkauan. Anda dapat membentuk kembali tanah, pasir, atau tanah liat di area tersebut dengan cara apa pun yang Anda pilih selama durasi tersebut. Anda dapat menaikkan atau menurunkan ketinggian area, membuat atau mengisi parit, mendirikan atau meratakan dinding, atau membentuk pilar. Besarnya perubahan tersebut tidak boleh melebihi setengah dimensi terbesar wilayah tersebut. Jadi, jika Anda mempengaruhi persegi berukuran 40 kaki, Anda dapat membuat pilar setinggi 20 kaki, menaikkan atau menurunkan ketinggian persegi hingga 20 kaki, menggali parit sedalam 20 kaki, dan seterusnya. Diperlukan waktu 10 menit agar perubahan ini selesai.\nDi akhir setiap 10 menit yang Anda habiskan untuk berkonsentrasi pada mantranya, Anda dapat memilih area medan baru untuk dipengaruhi.\nKarena transformasi medan terjadi secara perlahan, makhluk di area tersebut biasanya tidak dapat terjebak atau terluka oleh pergerakan tanah.\nMantra ini tidak dapat memanipulasi batu alam atau konstruksi batu. Batuan dan struktur bergeser untuk mengakomodasi medan baru. Jika cara Anda membentuk medan membuat struktur menjadi tidak stabil, maka struktur tersebut mungkin akan runtuh.\nDemikian pula mantra ini tidak mempengaruhi pertumbuhan tanaman secara langsung. Bumi yang dipindahkan membawa serta tanaman apa pun." },
      { name: "Sunbeam", components: "V, S, M", desc: "Seberkas cahaya cemerlang memancar dari tangan Anda dalam garis selebar 5 kaki dan panjang 60 kaki. Setiap makhluk dalam barisan harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk akan menerima kerusakan radiasi sebesar 6d8 dan menjadi buta hingga giliran Anda berikutnya. Jika penyelamatan berhasil, dibutuhkan setengah kerusakan dan tidak dibutakan oleh mantra ini. Mayat hidup dan cairan merembes memiliki kelemahan dalam lemparan penyelamatan ini.\nAnda dapat membuat garis pancaran baru sebagai tindakan Anda di giliran mana pun hingga mantranya berakhir.\nSelama itu, secercah cahaya cemerlang bersinar di tangan Anda. Ini memancarkan cahaya terang dalam radius 30 kaki dan cahaya redup untuk tambahan 30 kaki. Cahaya ini adalah sinar matahari." },
      { name: "Transport via Plants", components: "V, S", desc: "Mantra ini menciptakan hubungan magis antara tumbuhan mati berukuran besar atau lebih besar dalam jangkauannya dan tumbuhan lain, pada jarak berapa pun, di alam keberadaan yang sama. Anda pasti pernah melihat atau menyentuh tanaman tujuan setidaknya satu kali sebelumnya. Selama durasi tersebut, makhluk apa pun dapat masuk ke tanaman target dan keluar dari tanaman tujuan dengan menggunakan gerakan sejauh 5 kaki." },
      { name: "Wall of Thorns", components: "V, S, M", desc: "Anda membuat dinding dari sikat yang keras, lentur, dan kusut yang dipenuhi duri setajam jarum. Dinding muncul dalam jangkauan pada permukaan padat dan bertahan selama durasi tersebut. Anda memilih untuk membuat tembok dengan panjang hingga 60 kaki, tinggi 10 kaki, dan tebal 5 kaki atau lingkaran yang memiliki diameter 20 kaki dan tinggi hingga 20 kaki dan tebal 5 kaki. Dinding menghalangi pandangan.\nSaat tembok muncul, setiap makhluk di dalam areanya harus melakukan lemparan penyelamatan ketangkasan. Pada penyelamatan yang gagal, makhluk tersebut menerima kerusakan penusuk sebesar 7d8, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nMakhluk dapat bergerak menembus dinding, meskipun perlahan dan menyakitkan. Untuk setiap 1 kaki makhluk bergerak menembus dinding, ia harus menghabiskan 4 kaki gerakannya. Selanjutnya, saat pertama kali makhluk memasuki dinding pada suatu belokan atau mengakhiri belokannya di sana, makhluk tersebut harus melakukan lemparan penyelamatan ketangkasan. Dibutuhkan 7d8 pemotongan kerusakan pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, kedua jenis kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 6." },
      { name: "Wind Walk", components: "V, S, M", desc: "Anda dan hingga sepuluh makhluk yang dapat Anda lihat dalam jangkauan mengambil bentuk gas selama durasi tersebut, muncul sebagai gumpalan awan. Sedangkan dalam bentuk awan ini, makhluk memiliki kecepatan terbang 300 kaki dan memiliki ketahanan terhadap kerusakan senjata non-magis. Satu-satunya tindakan yang dapat dilakukan makhluk dalam bentuk ini adalah tindakan Dash atau kembali ke bentuk normalnya. Mengembalikan membutuhkan waktu 1 menit, selama waktu tersebut makhluk tidak berdaya dan tidak dapat bergerak. Hingga mantranya berakhir, makhluk dapat kembali ke bentuk awan, yang juga memerlukan transformasi 1 menit.\nJika makhluk berada dalam bentuk awan dan terbang saat efeknya berakhir, makhluk tersebut akan turun sejauh 60 kaki per putaran selama 1 menit hingga mendarat, dan hal ini dilakukan dengan aman. Jika tidak dapat mendarat setelah 1 menit, makhluk tersebut akan terjatuh pada jarak yang tersisa." },
    ],
    Level7: [
      { name: "Fire Storm", components: "V, S", desc: "Badai yang terdiri dari lembaran api yang menderu muncul di lokasi yang Anda pilih dalam jangkauannya. Area badai terdiri dari sepuluh kubus berukuran 10 kaki, yang dapat Anda atur sesuai keinginan. Setiap kubus harus memiliki setidaknya satu sisi yang berdekatan dengan sisi kubus lainnya. Setiap makhluk di area tersebut harus melakukan lemparan penyelamatan ketangkasan. Dibutuhkan 7d10 kerusakan akibat kebakaran pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nApi merusak benda-benda di area tersebut dan menyulut benda-benda mudah terbakar yang tidak dipakai atau dibawa. Jika Anda memilih, kehidupan tanaman di area tersebut tidak terpengaruh oleh mantra ini." },
      { name: "Mirage Arcane", components: "V, S", desc: "Anda membuat medan di area seluas 1 mil persegi terlihat, terdengar, tercium, dan bahkan terasa seperti medan lainnya. Namun, bentuk umum medannya tetap sama. Lahan terbuka atau jalan dapat dibuat menyerupai rawa, bukit, jurang, atau medan lain yang sulit atau tidak dapat dilalui. Sebuah kolam dapat dibuat tampak seperti padang rumput, jurang seperti lereng yang landai, atau selokan yang dipenuhi bebatuan seperti jalan yang lebar dan mulus.\nDemikian pula, Anda dapat mengubah tampilan struktur, atau menambahkannya jika tidak ada. Mantra itu tidak menyamarkan, menyembunyikan, atau menambah makhluk.\nIlusi mencakup elemen pendengaran, visual, sentuhan, dan penciuman, sehingga dapat mengubah permukaan tanah yang bersih menjadi medan yang sulit (atau sebaliknya) atau menghambat pergerakan melalui area tersebut. Setiap bagian dari medan ilusi (seperti batu atau tongkat) yang dikeluarkan dari area mantra akan segera menghilang.\nMakhluk dengan penglihatan sejati dapat melihat melalui ilusi ke bentuk sebenarnya dari medan tersebut; namun, semua elemen ilusi lainnya tetap ada, jadi meskipun makhluk tersebut menyadari kehadiran ilusi tersebut, makhluk tersebut masih dapat berinteraksi secara fisik dengan ilusi tersebut." },
      { name: "Plane Shift", components: "V, S, M", desc: "Anda dan hingga delapan makhluk bersedia yang bergandengan tangan dalam lingkaran akan dipindahkan ke alam eksistensi lain. Anda dapat menentukan tujuan target secara umum, seperti Kota Kuningan di Alam Elemen Api atau istana Dispater di Sembilan Neraka tingkat kedua, dan Anda muncul di atau dekat tujuan tersebut. Jika Anda mencoba mencapai Kota Kuningan, misalnya, Anda mungkin tiba di Jalan Baja, sebelum Gerbang Abu, atau melihat kota dari seberang Lautan Api, sesuai kebijaksanaan GM.\nAlternatifnya, jika Anda mengetahui urutan sigil lingkaran teleportasi di alam eksistensi lain, mantra ini dapat membawa Anda ke lingkaran itu. Jika lingkaran teleportasi terlalu kecil untuk menampung semua makhluk yang Anda pindahkan, mereka akan muncul di ruang kosong terdekat di sebelah lingkaran.\nAnda dapat menggunakan mantra ini untuk mengusir makhluk yang tidak mau ke pesawat lain. Pilih makhluk dalam jangkauan Anda dan lakukan serangan mantra jarak dekat terhadapnya. Saat terkena, makhluk tersebut harus melakukan lemparan penyelamatan karisma. Jika makhluk tersebut gagal dalam penyelamatan ini, ia akan dipindahkan ke lokasi acak di alam keberadaan yang Anda tentukan. Makhluk yang dipindahkan harus menemukan jalannya sendiri kembali ke alam keberadaan Anda saat ini." },
      { name: "Regenerate", components: "V, S, M", desc: "Anda menyentuh makhluk dan merangsang kemampuan penyembuhan alaminya. Target mendapatkan kembali 4d8 + 15 poin hit. Selama durasi mantra, target mendapatkan kembali 1 poin hit di awal setiap putarannya (10 poin hit setiap menit).\nAnggota tubuh target yang terputus (jari tangan, kaki, ekor, dan sebagainya), jika ada, akan dipulihkan setelah 2 menit. Jika Anda memiliki bagian yang terputus dan menempelkannya pada tunggul, mantra tersebut secara instan menyebabkan anggota tubuh tersebut terikat pada tunggul." },
      { name: "Reverse Gravity", components: "V, S, M", desc: "Mantra ini membalikkan gravitasi dalam silinder dengan radius 50 kaki dan tinggi 100 kaki yang berpusat pada suatu titik dalam jangkauan. Semua makhluk dan benda yang entah bagaimana tidak tertambat ke tanah di area tersebut akan jatuh ke atas dan mencapai puncak area saat Anda mengucapkan mantra ini. Makhluk dapat melakukan lemparan hemat ketangkasan untuk meraih benda tetap yang dapat dijangkaunya, sehingga terhindar dari terjatuh.\nJika ada benda padat (seperti langit-langit) yang ditemui pada musim gugur ini, benda dan makhluk yang jatuh akan menghantamnya seperti yang terjadi pada saat jatuh ke bawah pada umumnya. Jika suatu benda atau makhluk mencapai puncak area tersebut tanpa menabrak apa pun, benda atau makhluk tersebut akan tetap berada di sana, sedikit terombang-ambing, selama durasi tersebut.\nDi akhir durasi, objek dan makhluk yang terkena dampak akan terjatuh kembali." },
    ],
    Level8: [
      { name: "Animal Shapes", components: "V, S", desc: "Sihirmu mengubah orang lain menjadi binatang buas. Pilih sejumlah makhluk yang bersedia Anda lihat dalam jangkauan. Anda mengubah setiap target menjadi binatang besar atau kecil dengan peringkat tantangan 4 atau lebih rendah. Pada giliran berikutnya, Anda dapat menggunakan tindakan Anda untuk mengubah makhluk yang terkena dampak menjadi bentuk baru.\nTransformasi berlangsung selama durasi setiap target, atau hingga target turun menjadi 0 poin hit atau mati. Anda dapat memilih bentuk yang berbeda untuk setiap target. Statistik permainan target digantikan oleh statistik binatang yang dipilih, meskipun target tetap mempertahankan keselarasan dan skor Intelijen, Kebijaksanaan, dan Karisma. Target mengambil hit point dari bentuk barunya, dan ketika kembali ke bentuk normalnya, ia kembali ke jumlah hit point yang dimilikinya sebelum bertransformasi. Jika poin serangannya kembali karena poin hitnya turun menjadi 0, kerusakan berlebih akan kembali ke bentuk normalnya. Selama kerusakan berlebih tidak mengurangi bentuk normal makhluk itu menjadi 0 poin serangan, ia tidak akan pingsan. Tindakan yang dapat dilakukan makhluk ini terbatas karena sifat dari bentuk barunya, dan ia tidak dapat berbicara atau merapal mantra.\nPerlengkapan target menyatu ke dalam bentuk baru. Target tidak dapat mengaktifkan, menggunakan, atau memanfaatkan peralatan apa pun." },
      { name: "Antipathy/Sympathy", components: "V, S, M", desc: "Mantra ini menarik atau mengusir makhluk pilihan Anda. Anda menargetkan sesuatu dalam jangkauan, baik objek atau makhluk yang besar atau lebih kecil, atau area yang tidak lebih besar dari kubus berukuran 200 kaki. Kemudian tentukan jenis makhluk cerdas, seperti naga merah, goblin, atau vampir. Anda menginvestasikan target dengan aura yang menarik atau mengusir makhluk tertentu selama durasi tersebut. Pilih antipati atau simpati sebagai efek aura.\n***Antipati.*** Pesona menyebabkan makhluk dari jenis yang Anda tunjuk merasakan dorongan kuat untuk meninggalkan area tersebut dan menghindari target. Ketika makhluk tersebut dapat melihat targetnya atau berada dalam jarak 60 kaki darinya, makhluk tersebut harus berhasil melakukan lemparan penyelamatan yang bijaksana atau menjadi ketakutan. Makhluk itu tetap ketakutan ketika ia dapat melihat targetnya atau berada dalam jarak 60 kaki darinya. Saat ditakuti oleh targetnya, makhluk tersebut harus menggunakan gerakannya untuk berpindah ke tempat aman terdekat dimana ia tidak dapat melihat targetnya. Jika makhluk tersebut bergerak lebih dari 60 kaki dari target dan tidak dapat melihatnya, makhluk tersebut tidak lagi ketakutan, namun makhluk tersebut menjadi ketakutan lagi jika ia dapat melihat kembali target atau bergerak dalam jarak 60 kaki dari target.\n***Simpati.*** Pesona menyebabkan makhluk tertentu merasakan dorongan kuat untuk mendekati target dalam jarak 60 kaki atau mampu melihatnya. Ketika makhluk tersebut dapat melihat target atau berada dalam jarak 60 kaki darinya, makhluk tersebut harus berhasil melakukan lemparan penyelamatan yang bijaksana atau menggunakan gerakannya pada setiap putarannya untuk memasuki area tersebut atau bergerak dalam jangkauan target. Ketika makhluk itu sudah melakukannya, ia tidak bisa rela menjauh dari sasarannya.\nJika target memberikan damage atau melukai makhluk yang terkena, makhluk yang terkena dapat melakukan lemparan penyelamatan kebijaksanaan untuk mengakhiri efeknya, seperti dijelaskan di bawah.\n***Mengakhiri Efeknya.*** Jika makhluk yang terkena dampak mengakhiri gilirannya saat tidak berada dalam jarak 60 kaki dari target atau dapat melihatnya, makhluk tersebut melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan berhasil, makhluk tersebut tidak lagi terpengaruh oleh target dan menganggap perasaan jijik atau tertarik sebagai sesuatu yang ajaib. Selain itu, makhluk yang terkena mantra diperbolehkan melakukan lemparan penyelamatan kebijaksanaan lagi setiap 24 jam selama mantranya masih ada.\nMakhluk yang berhasil menyelamatkan diri dari efek ini akan kebal terhadapnya selama 1 menit, setelah itu makhluk tersebut dapat terpengaruh lagi." },
      { name: "Control Weather", components: "V, S, M", desc: "Anda mengendalikan cuaca dalam jarak 5 mil dari Anda selama durasi tersebut. Anda harus berada di luar ruangan untuk mengucapkan mantra ini. Pindah ke tempat di mana Anda tidak memiliki jalur yang jelas ke langit akan mengakhiri mantranya lebih awal.\nSaat Anda merapal mantra, Anda mengubah kondisi cuaca saat ini, yang ditentukan oleh GM berdasarkan iklim dan musim. Anda dapat mengubah curah hujan, suhu, dan angin. Diperlukan waktu 1 hari 4 x 10 menit agar kondisi baru dapat diterapkan. Setelah mereka melakukannya, Anda dapat mengubah kondisinya lagi. Saat mantra berakhir, cuaca berangsur-angsur kembali normal.\nSaat Anda mengubah kondisi cuaca, temukan kondisi terkini pada tabel berikut dan ubah tahapannya satu per satu, naik atau turun. Saat mengubah arah angin, Anda dapat mengubah arahnya.\n##### Curah hujan\n| Tahap | Kondisi |\n|---|---|\n| 1 | Jelas |\n| 2 | Awan terang |\n| 3 | Mendung atau kabut tanah |\n| 4 | Hujan, hujan es, atau salju |\n| 5 | Hujan deras, hujan es, atau badai salju |\n##### Suhu\n| Tahap | Kondisi |\n|---|---|\n| 1 | Panas yang tak tertahankan |\n| 2 | Panas |\n| 3 | Hangat |\n| 4 | Keren |\n| 5 | Dingin |\n| 6 | Dingin Arktik |\n##### Angin\n| Tahap | Kondisi |\n|---|---|\n| 1 | Tenang |\n| 2 | Angin sedang |\n| 3 | Angin kencang |\n| 4 | Angin kencang |\n| 5 | Badai |" },
      { name: "Earthquake", components: "V, S, M", desc: "Anda menciptakan gangguan seismik pada suatu titik di permukaan tanah yang dapat Anda lihat dalam jangkauannya. Selama durasi tersebut, getaran hebat melanda tanah dalam lingkaran radius 100 kaki yang berpusat di titik tersebut dan mengguncang makhluk serta bangunan yang bersentuhan dengan tanah di area tersebut.\nTanah di kawasan tersebut menjadi medan yang sulit. Setiap makhluk di tanah yang sedang berkonsentrasi harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, konsentrasi makhluk itu terganggu.\nSaat Anda mengucapkan mantra ini dan di akhir setiap giliran yang Anda habiskan untuk berkonsentrasi padanya, setiap makhluk di tanah di area tersebut harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk itu rawan terbentur.\nSpell ini dapat memberikan efek tambahan tergantung pada medan di area tersebut, seperti yang ditentukan oleh GM.\ncelah. Celah terbuka di seluruh area mantra pada awal giliran berikutnya setelah Anda mengucapkan mantra. Sebanyak 1d6 celah tersebut terbuka di lokasi yang dipilih oleh GM. Masing-masing memiliki kedalaman 1d10 x 10 kaki, lebar 10 kaki, dan memanjang dari satu tepi area mantra ke sisi yang berlawanan. Makhluk yang berdiri di tempat celah terbuka harus berhasil melakukan lemparan penyelamatan ketangkasan atau jatuh. Makhluk yang berhasil menyelamatkan bergerak dengan tepi celah saat celah terbuka.\nRetakan yang terbuka di bawah suatu struktur menyebabkan struktur tersebut runtuh secara otomatis (lihat di bawah).\nStruktur. Getaran tersebut menimbulkan 50 kerusakan besar pada struktur apa pun yang bersentuhan dengan tanah di area tersebut saat Anda merapal mantra dan di awal setiap giliran hingga mantra berakhir. Jika suatu struktur turun hingga 0 titik serangan, struktur tersebut akan runtuh dan berpotensi merusak makhluk di sekitarnya. Makhluk yang berada dalam jarak setengah dari tinggi bangunan harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk itu menerima kerusakan akibat pukulan 5d6, rawan terkena pukulan, dan terkubur di reruntuhan, memerlukan pemeriksaan Kekuatan (Atletik) DC 20 sebagai tindakan untuk melarikan diri. GM dapat mengatur DC lebih tinggi atau lebih rendah, tergantung pada sifat puing-puingnya. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan dan tidak rawan atau terkubur." },
      { name: "Feeblemind", components: "V, S, M", desc: "Anda meledakkan pikiran makhluk yang dapat Anda lihat dalam jangkauan, mencoba menghancurkan kecerdasan dan kepribadiannya. Target menerima kerusakan psikis 4d6 dan harus melakukan lemparan penyelamatan intelijen.\nJika penyelamatan gagal, skor Kecerdasan dan Karisma makhluk tersebut menjadi 1. Makhluk tersebut tidak dapat merapal mantra, mengaktifkan item sihir, memahami bahasa, atau berkomunikasi dengan cara apa pun yang dapat dimengerti. Namun, makhluk itu dapat mengidentifikasi teman-temannya, mengikuti mereka, dan bahkan melindungi mereka.\nPada akhir setiap 30 hari, makhluk itu dapat mengulangi penyelamatannya terhadap mantra ini. Jika berhasil dalam lemparan penyelamatannya, mantranya berakhir.\nMantra ini juga dapat diakhiri dengan pemulihan, penyembuhan, atau keinginan yang lebih besar." },
      { name: "Sunburst", components: "V, S, M", desc: "Sinar matahari yang cemerlang bersinar dalam radius 60 kaki yang berpusat pada titik yang Anda pilih dalam jangkauannya. Setiap makhluk dalam terang itu harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk akan menerima kerusakan radiasi 12d6 dan menjadi buta selama 1 menit. Jika penyelamatan berhasil, dibutuhkan setengah kerusakan dan tidak dibutakan oleh mantra ini. Mayat hidup dan cairan merembes memiliki kelemahan dalam lemparan penyelamatan ini.\nMakhluk yang dibutakan oleh mantra ini melakukan lemparan penyelamatan konstitusi lainnya di akhir setiap putarannya. Jika penyelamatan berhasil, ia tidak lagi dibutakan.\nMantra ini menghilangkan kegelapan apa pun di areanya yang diciptakan oleh mantra." },
    ],
    Level9: [
      { name: "Foresight", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia dan memberikan kemampuan terbatas untuk melihat masa depan. Selama durasi, target tidak dapat terkejut dan memiliki keunggulan dalam serangan, pengecekan kemampuan, dan penyelamatan lemparan. Selain itu, makhluk lain memiliki kelemahan dalam serangan berguling terhadap target selama durasi tersebut.\nMantra ini akan langsung berakhir jika kamu mengucapkannya lagi sebelum durasinya berakhir." },
      { name: "Shapechange", components: "V, S, M", desc: "Anda mengambil bentuk makhluk yang berbeda selama durasi tersebut. Bentuk barunya bisa berupa makhluk apa pun dengan peringkat tantangan yang sama dengan level Anda atau lebih rendah. Makhluk itu tidak bisa berupa konstruksi atau undead, dan Anda pasti pernah melihat makhluk semacam itu setidaknya sekali. Anda berubah menjadi contoh rata-rata dari makhluk itu, makhluk tanpa tingkat kelas atau sifat Spellcasting.\nStatistik permainan Anda digantikan oleh statistik makhluk yang dipilih, meskipun Anda tetap mempertahankan keselarasan dan skor Kecerdasan, Kebijaksanaan, dan Karisma Anda. Anda juga mempertahankan semua keterampilan dan kemahiran menyimpan lemparan Anda, selain mendapatkan keterampilan makhluk itu. Jika makhluk tersebut memiliki kemahiran yang sama dengan Anda dan bonus yang tercantum dalam statistiknya lebih tinggi dari Anda, gunakan bonus makhluk tersebut sebagai pengganti Anda. Anda tidak dapat menggunakan aksi legendaris atau aksi sarang apa pun dalam bentuk baru.\nAnda mengasumsikan hit point dan Hit Dice dari bentuk baru. Ketika Anda kembali ke bentuk normal, Anda kembali ke jumlah poin hit yang Anda miliki sebelum Anda bertransformasi. Jika Anda kembali karena poin hit turun ke 0, kerusakan berlebih akan berpindah ke bentuk normal Anda. Selama kerusakan berlebih tidak mengurangi bentuk normalmu menjadi 0 poin serangan, kamu tidak akan pingsan.\nAnda tetap dapat memanfaatkan fitur apa pun dari kelas, ras, atau sumber lain dan dapat menggunakannya, asalkan formulir baru Anda secara fisik mampu melakukannya. Anda tidak dapat menggunakan indra khusus apa pun yang Anda miliki (misalnya, penglihatan gelap) kecuali jika bentuk baru Anda juga memiliki indera tersebut. Anda hanya dapat berbicara jika makhluk tersebut dapat berbicara secara normal.\nSaat Anda bertransformasi, Anda memilih apakah perlengkapan Anda jatuh ke tanah, menyatu menjadi bentuk baru, atau aus karenanya. Peralatan yang dipakai berfungsi seperti biasa. GM menentukan apakah praktis bagi wujud baru untuk memakai peralatan, berdasarkan bentuk dan ukuran makhluk tersebut. Peralatan Anda tidak berubah bentuk atau ukuran untuk menyesuaikan dengan bentuk baru, dan peralatan apa pun yang tidak dapat dipakai oleh bentuk baru harus jatuh ke tanah atau bergabung ke dalam bentuk baru Anda. Peralatan yang digabungkan tidak berpengaruh pada kondisi tersebut.\nSelama durasi mantra ini, Anda dapat menggunakan tindakan Anda untuk mengambil bentuk berbeda dengan mengikuti batasan dan aturan yang sama untuk bentuk aslinya, dengan satu pengecualian: jika bentuk baru Anda memiliki poin hit lebih banyak daripada formulir saat ini, poin hit Anda tetap pada nilainya saat ini." },
      { name: "Storm of Vengeance", components: "V, S", desc: "Awan badai yang bergejolak terbentuk, berpusat pada suatu titik yang dapat Anda lihat dan menyebar hingga radius 360 kaki. Kilat menyambar di kawasan itu, guntur menggelegar, dan angin kencang menderu-deru. Setiap makhluk di bawah awan (tidak lebih dari 5.000 kaki di bawah awan) ketika muncul harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk menerima kerusakan petir sebesar 2d6 dan menjadi tuli selama 5 menit.\nSetiap putaran Anda mempertahankan konsentrasi pada mantra ini, badai menghasilkan efek tambahan pada giliran Anda.\n***Putaran 2.*** Hujan asam turun dari awan. Setiap makhluk dan objek di bawah awan menerima 1d6 kerusakan asam.\n***Putaran 3.*** Anda memanggil enam sambaran petir dari awan untuk menyerang enam makhluk atau objek pilihan Anda di bawah awan. Makhluk atau objek tertentu tidak dapat terkena lebih dari satu baut. Makhluk yang terkena serangan harus melakukan lemparan penyelamatan ketangkasan. Makhluk itu menerima 10d6 kerusakan petir pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\n***Putaran 4.*** Hujan es turun dari awan. Setiap makhluk di bawah awan menerima kerusakan sebesar 2d6.\n***Putaran 5-10.*** Hembusan angin dan hujan beku menyerang area di bawah awan. Daerah tersebut menjadi medan yang sulit dan sangat tertutup. Setiap makhluk di sana menerima 1d6 kerusakan dingin. Serangan senjata jarak jauh di area tersebut tidak mungkin dilakukan. Angin dan hujan dianggap sebagai gangguan parah untuk menjaga konsentrasi mantra. Terakhir, hembusan angin kencang (berkisar antara 20 hingga 50 mil per jam) secara otomatis menyebarkan kabut, kabut, dan fenomena serupa di area tersebut, baik yang bersifat duniawi maupun magis." },
      { name: "True Resurrection", components: "V, S, M", desc: "Anda menyentuh makhluk yang telah mati tidak lebih dari 200 tahun dan mati karena alasan apapun kecuali usia tua. Jika jiwa makhluk itu bebas dan berkehendak, maka makhluk itu akan hidup kembali dengan segala hit pointnya.\nMantra ini menutup semua luka, menetralkan racun apa pun, menyembuhkan semua penyakit, dan menghilangkan kutukan apa pun yang menimpa makhluk itu ketika mati. Mantra tersebut menggantikan organ dan anggota tubuh yang rusak atau hilang.\nMantra tersebut bahkan dapat memberikan tubuh baru jika yang asli sudah tidak ada lagi, dalam hal ini Anda harus menyebutkan nama makhluk tersebut. Makhluk itu kemudian muncul di ruang kosong yang Anda pilih dalam jarak 10 kaki dari Anda." },
    ],
  },
  Paladin: {
    Cantrips: [],
    Level1: [
      { name: "Bless", components: "V, S, M", desc: "Anda memberkati hingga tiga makhluk pilihan Anda dalam jangkauan. Setiap kali target melakukan roll serangan atau lemparan penyelamatan sebelum mantra berakhir, target dapat melempar d4 dan menambahkan nomor yang dilempar ke lemparan serangan atau lemparan penyelamatan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 1." },
      { name: "Command", components: "V", desc: "Anda mengucapkan perintah satu kata kepada makhluk yang dapat Anda lihat dalam jangkauan. Target harus berhasil dalam lemparan penyelamatan yang bijaksana atau mengikuti perintah pada giliran berikutnya. Mantra tersebut tidak berpengaruh jika targetnya adalah undead, jika targetnya tidak memahami bahasa Anda, atau jika perintah Anda secara langsung membahayakan targetnya.\nBeberapa perintah umum dan efeknya mengikuti. Anda mungkin mengeluarkan perintah selain yang dijelaskan di sini. Jika Anda melakukannya, GM akan menentukan bagaimana target berperilaku. Jika target tidak dapat mengikuti perintah Anda, mantranya berakhir.\n***Pendekatan.*** Target bergerak ke arah Anda melalui rute terpendek dan paling langsung, mengakhiri gilirannya jika bergerak dalam jarak 5 kaki dari Anda.\n***Jatuhkan.*** Target menjatuhkan apa pun yang dipegangnya dan kemudian mengakhiri gilirannya.\n***Lari.*** Target menghabiskan gilirannya menjauh dari Anda dengan cara tercepat yang tersedia.\n***Grovel.*** Targetnya tiarap dan kemudian mengakhiri gilirannya.\n***Berhenti.*** Target tidak bergerak dan tidak mengambil tindakan. Makhluk terbang akan tetap terbang asalkan mampu melakukannya. Jika ia harus bergerak agar tetap tinggi, ia terbang dengan jarak minimum yang diperlukan untuk tetap berada di udara.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat memengaruhi satu makhluk tambahan untuk setiap slot level di atas 1. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Cure Wounds", components: "V, S", desc: "Makhluk yang Anda sentuh mendapatkan kembali sejumlah poin hit yang setara dengan 1d8 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, penyembuhan meningkat sebesar 1d8 untuk setiap slot level di atas 1." },
      { name: "Detect Evil and Good", components: "V, S", desc: "Untuk durasinya, Anda mengetahui apakah ada aberration, Celestial, Elemental, Fey, Fiend, atau Undead dalam jarak 30 kaki dari Anda, serta di mana makhluk itu berada. Demikian pula, Anda mengetahui jika ada tempat atau benda dalam jarak 30 kaki dari Anda yang telah disucikan atau dinodai secara ajaib.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Detect Magic", components: "V, S", desc: "Selama durasi tersebut, Anda merasakan kehadiran sihir dalam jarak 30 kaki dari Anda. Jika Anda merasakan sihir dengan cara ini, Anda dapat menggunakan tindakan Anda untuk melihat aura samar di sekitar makhluk atau objek apa pun yang terlihat di area yang mengandung sihir, dan Anda mempelajari sekolah sihirnya, jika ada.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Detect Poison and Disease", components: "V, S, M", desc: "Selama durasi tersebut, Anda dapat merasakan keberadaan dan lokasi racun, makhluk beracun, dan penyakit dalam jarak 30 kaki dari Anda. Anda juga mengidentifikasi jenis racun, makhluk beracun, atau penyakit dalam setiap kasus.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Divine Favor", components: "V, S", desc: "Doa Anda memberdayakan Anda dengan pancaran ilahi. Hingga mantranya berakhir, serangan senjata Anda menghasilkan kerusakan tambahan sebesar 1d4 saat terkena." },
      { name: "Heroism", components: "V, S", desc: "Makhluk rela yang Anda sentuh dipenuhi dengan keberanian. Hingga mantranya berakhir, makhluk itu kebal terhadap rasa takut dan memperoleh poin serangan sementara yang setara dengan pengubah kemampuan merapal mantra Anda di awal setiap giliran. Saat mantra berakhir, target kehilangan sisa poin hit sementara dari mantra ini." },
      { name: "Protection from Evil and Good", components: "V, S, M", desc: "Hingga mantranya berakhir, satu makhluk yang Anda sentuh akan terlindungi dari jenis makhluk tertentu: aberasi, surgawi, elemen, fey, iblis, dan undead.\nPerlindungan memberikan beberapa manfaat. Makhluk dengan tipe seperti itu mempunyai kelemahan dalam serangan roll terhadap target. Targetnya juga tidak bisa terpesona, ditakuti, atau dirasuki oleh mereka. Jika target sudah terpesona, ketakutan, atau dirasuki oleh makhluk tersebut, target mempunyai keuntungan pada setiap lemparan penyelamatan baru terhadap efek yang relevan." },
      { name: "Purify Food and Drink", components: "V, S", desc: "Semua makanan dan minuman non-magis dalam radius 5 kaki yang berpusat pada titik pilihan Anda dalam jangkauan dimurnikan dan bebas dari racun dan penyakit." },
      { name: "Shield of Faith", components: "V, S, M", desc: "Bidang berkilauan muncul dan mengelilingi makhluk pilihan Anda dalam jangkauan, memberinya bonus +2 AC selama durasi tersebut." },
    ],
    Level2: [
      { name: "Aid", components: "V, S, M", desc: "Mantra Anda memperkuat sekutu Anda dengan ketangguhan dan keteguhan hati. Pilih hingga tiga makhluk dalam jangkauan. Hit point maksimum dan hit point saat ini setiap target meningkat sebesar 5 selama durasi tersebut.\nSaat Anda mengucapkan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, poin hit target meningkat sebanyak 5 tambahan untuk setiap level slot di atas level 2." },
      { name: "Branding Smite", components: "V", desc: "Lain kali Anda memukul makhluk dengan serangan senjata sebelum mantra ini berakhir, senjata tersebut bersinar dengan cahaya astral saat Anda menyerang. Serangan tersebut memberikan damage tambahan sebesar 2d6 pada target, yang menjadi terlihat jika tidak terlihat, dan target memancarkan cahaya redup dalam radius 5 kaki dan tidak dapat menjadi tidak terlihat hingga mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan tambahan meningkat sebesar 1d6 untuk setiap slot level di atas 2." },
      { name: "Find Steed", components: "V, S", desc: "Anda memanggil roh yang mengambil bentuk kuda yang sangat cerdas, kuat, dan setia, sehingga menciptakan ikatan jangka panjang dengannya. Muncul di ruang kosong dalam jangkauan, kudanya mengambil bentuk yang Anda pilih, seperti kuda perang, kuda poni, unta, rusa, atau mastiff. (GM Anda mungkin mengizinkan hewan lain untuk dipanggil sebagai tunggangan.) Kuda tersebut memiliki statistik dari bentuk yang dipilih, meskipun ia adalah selestial, fey, atau iblis (pilihan Anda) dan bukan tipe normalnya. Selain itu, jika kuda Anda memiliki Intelijen 5 atau kurang, Intelijennya menjadi 6, dan ia memperoleh kemampuan untuk memahami satu bahasa pilihan yang Anda gunakan.\nKuda Anda berfungsi sebagai tunggangan, baik dalam pertempuran maupun di luar, dan Anda memiliki ikatan naluriah dengannya yang memungkinkan Anda bertarung sebagai unit yang mulus. Saat menaiki kudamu, kamu dapat membuat mantra apa pun yang kamu gunakan untuk menargetkan hanya kamu yang juga menargetkan kudamu.\nKetika kudanya turun ke 0 hit point, ia menghilang, tidak meninggalkan bentuk fisik apa pun. Anda juga dapat mengabaikan kuda Anda kapan saja sebagai suatu tindakan, sehingga menyebabkannya menghilang. Apa pun kasusnya, merapal mantra ini lagi akan memanggil kuda yang sama, memulihkan titik serangan maksimumnya.\nSaat kuda Anda berada dalam jarak 1 mil dari Anda, Anda dapat berkomunikasi dengannya secara telepati.\nAnda tidak dapat memiliki lebih dari satu kuda yang terikat oleh mantra ini dalam satu waktu. Sebagai suatu tindakan, Anda dapat melepaskan kuda dari ikatannya kapan saja, menyebabkannya menghilang." },
      { name: "Lesser Restoration", components: "V, S", desc: "Anda menyentuh suatu makhluk dan dapat mengakhiri satu penyakit atau satu kondisi yang menimpanya. Kondisinya bisa menjadi buta, tuli, lumpuh, atau keracunan." },
      { name: "Locate Object", components: "V, S, M", desc: "Jelaskan atau beri nama suatu objek yang Anda kenal. Anda merasakan arah ke lokasi objek, selama objek tersebut berada dalam jarak 1.000 kaki dari Anda. Jika suatu benda bergerak, maka diketahui arah pergerakannya.\nMantra tersebut dapat menemukan lokasi objek tertentu yang Anda kenal, selama Anda telah melihatnya dari dekat--dalam jarak 30 kaki--setidaknya sekali. Alternatifnya, mantra tersebut dapat menemukan lokasi objek terdekat dari jenis tertentu, seperti jenis pakaian, perhiasan, furnitur, perkakas, atau senjata tertentu.\nMantra ini tidak dapat menemukan lokasi suatu objek jika ada timah tebal, bahkan lembaran tipis, menghalangi jalur langsung antara Anda dan objek tersebut." },
      { name: "Magic Weapon", components: "V, S", desc: "Anda menyentuh senjata non-magis. Hingga mantranya berakhir, senjata itu menjadi senjata ajaib dengan bonus +1 untuk gulungan serangan dan gulungan kerusakan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, bonusnya meningkat menjadi +2. Saat Anda menggunakan slot mantra level 6 atau lebih tinggi, bonus meningkat menjadi +3." },
      { name: "Protection from Poison", components: "V, S", desc: "Anda menyentuh makhluk. Jika diracuni, Anda menetralisir racunnya. Jika lebih dari satu racun menimpa target, Anda menetralisir satu racun yang Anda tahu ada, atau Anda menetralisir satu racun secara acak.\nSelama durasi tersebut, target memiliki keuntungan dalam menyimpan lemparan agar tidak terkena racun, dan memiliki ketahanan terhadap kerusakan akibat racun." },
      { name: "Zone of Truth", components: "V, S", desc: "Anda menciptakan zona ajaib yang melindungi dari penipuan dalam bola berradius 15 kaki yang berpusat pada titik pilihan Anda dalam jangkauan. Hingga mantranya berakhir, makhluk yang memasuki area mantra untuk pertama kalinya pada suatu giliran atau memulai gilirannya di sana harus melakukan lemparan penyelamatan Karisma. Jika penyelamatan gagal, makhluk tidak dapat mengucapkan kebohongan yang disengaja saat berada dalam radius. Anda tahu apakah setiap makhluk berhasil atau gagal dalam penyelamatannya.\nMakhluk yang terkena dampak menyadari mantra tersebut dan dengan demikian dapat menghindari menjawab pertanyaan yang biasanya ditanggapi dengan kebohongan. Makhluk seperti itu bisa saja tetap mengelak dalam menjawab selama masih dalam batas-batas kebenaran." },
    ],
    Level3: [
      { name: "Create Food and Water", components: "V, S", desc: "Anda menghasilkan 45 pon makanan dan 30 galon air di tanah atau di dalam wadah dalam jangkauan, cukup untuk menopang hingga lima belas humanoid atau lima kuda selama 24 jam. Makanannya hambar namun bergizi, dan akan rusak jika tidak dimakan setelah 24 jam. Airnya bersih dan tidak busuk." },
      { name: "Daylight", components: "V, S", desc: "Bola cahaya dengan radius 60 kaki menyebar dari titik yang Anda pilih dalam jangkauannya. Bola tersebut memiliki cahaya terang dan memancarkan cahaya redup sejauh 60 kaki.\nJika Anda memilih suatu titik pada suatu benda yang Anda pegang atau yang tidak sedang dipakai atau dibawa, cahaya akan bersinar dari benda tersebut dan bergerak bersamanya. Menutupi seluruh objek yang terkena dengan benda buram, seperti mangkuk atau helm, akan menghalangi cahaya.\nJika salah satu area mantra ini tumpang tindih dengan area kegelapan yang diciptakan oleh mantra level 3 atau lebih rendah, mantra yang menciptakan kegelapan tersebut akan hilang." },
      { name: "Dispel Magic", components: "V, S", desc: "Pilih satu makhluk, objek, atau efek magis dalam jangkauan. Mantra level 3 atau lebih rendah pada target akan berakhir. Untuk setiap mantra level 4 atau lebih tinggi pada target, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika pemeriksaan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda secara otomatis mengakhiri efek mantra pada target jika level mantra sama dengan atau kurang dari level slot mantra yang Anda gunakan." },
      { name: "Magic Circle", components: "V, S, M", desc: "Anda membuat silinder energi magis dengan radius 10 kaki dan tinggi 20 kaki yang berpusat pada suatu titik di tanah yang dapat Anda lihat dalam jangkauan. Rune bercahaya muncul setiap kali silinder berpotongan dengan lantai atau permukaan lainnya.\nPilih satu atau lebih jenis makhluk berikut: selestial, elemental, fey, iblis, atau undead. Lingkaran mempengaruhi makhluk dari tipe yang dipilih dengan cara berikut:\n- Makhluk itu tidak bisa dengan sukarela memasuki silinder dengan cara non-magis. Jika makhluk tersebut mencoba menggunakan teleportasi atau perjalanan antarplanar untuk melakukannya, ia harus berhasil melakukan lemparan penyelamatan karisma terlebih dahulu.\n- Makhluk tersebut memiliki kelemahan dalam serangan berguling terhadap target di dalam silinder.\n- Target di dalam silinder tidak dapat dipesona, ditakuti, atau dirasuki oleh makhluk tersebut.\nSaat Anda mengucapkan mantra ini, Anda dapat memilih untuk membuat sihirnya beroperasi ke arah sebaliknya, mencegah makhluk bertipe tertentu meninggalkan silinder dan melindungi target di luarnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, durasinya bertambah 1 jam untuk setiap slot level di atas 3." },
      { name: "Remove Curse", components: "V, S", desc: "Dengan sentuhan Anda, semua kutukan yang memengaruhi satu makhluk atau objek berakhir. Jika benda tersebut merupakan benda sihir terkutuk, kutukannya tetap ada, tetapi mantranya merusak attunement pemiliknya terhadap benda tersebut sehingga dapat dikeluarkan atau dibuang." },
      { name: "Revivify", components: "V, S, M", desc: "Anda menyentuh makhluk yang telah mati dalam satu menit terakhir. Makhluk itu hidup kembali dengan 1 hit point. Mantra ini tidak dapat menghidupkan kembali makhluk yang mati karena usia tua, juga tidak dapat memulihkan bagian tubuh yang hilang." },
    ],
    Level4: [
      { name: "Banishment", components: "V, S, M", desc: "Anda mencoba mengirim satu makhluk yang dapat Anda lihat dalam jangkauannya ke alam eksistensi lain. Targetnya harus berhasil dalam penyelamatan karisma atau diasingkan.\nJika targetnya berasal dari alam eksistensi yang Anda tempati, Anda membuang target tersebut ke demiplane yang tidak berbahaya. Saat berada di sana, targetnya tidak berdaya. Target tetap di sana sampai mantranya berakhir, pada saat itu target muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi.\nJika target berasal dari alam eksistensi yang berbeda dari tempat Anda berada, target akan dibuang dengan suara letupan samar, dan kembali ke alam asalnya. Jika mantra berakhir sebelum 1 menit berlalu, target akan muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi. Jika tidak, targetnya tidak akan kembali.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 4." },
      { name: "Death Ward", components: "V, S", desc: "Anda menyentuh makhluk dan memberinya perlindungan dari kematian.\nPertama kali target turun menjadi 0 poin hit akibat menerima kerusakan, target malah turun menjadi 1 poin hit, dan mantra berakhir.\nJika mantra masih berlaku saat target terkena efek yang akan membunuhnya secara instan tanpa menimbulkan kerusakan, efek tersebut akan dinegasikan terhadap target, dan mantra akan berakhir." },
      { name: "Locate Creature", components: "V, S, M", desc: "Jelaskan atau beri nama makhluk yang Anda kenal. Anda merasakan arah ke lokasi makhluk itu, selama makhluk itu berada dalam jarak 1.000 kaki dari Anda. Jika makhluk itu bergerak, Anda mengetahui arah pergerakannya.\nMantra ini dapat menemukan lokasi makhluk tertentu yang Anda kenal, atau makhluk terdekat dari jenis tertentu (seperti manusia atau unicorn), selama Anda pernah melihat makhluk tersebut dari dekat--dalam jarak 30 kaki--setidaknya sekali. Jika makhluk yang Anda gambarkan atau beri nama berada dalam bentuk yang berbeda, seperti berada di bawah pengaruh mantra polimorf, mantra ini tidak akan menemukan lokasi makhluk tersebut.\nMantra ini tidak dapat menemukan lokasi makhluk jika air yang mengalir selebar 10 kaki menghalangi jalur langsung antara Anda dan makhluk tersebut." },
    ],
    Level5: [
      { name: "Dispel Evil and Good", components: "V, S, M", desc: "Energi yang berkilauan mengelilingi dan melindungi Anda dari makhluk jahat, mayat hidup, dan makhluk yang berasal dari luar Alam Material. Selama durasi tersebut, Celestial, Elemental, Fey, Fiend, dan Undead memiliki kelemahan dalam serangan terhadap Anda.\nAnda dapat mengakhiri mantra lebih awal dengan menggunakan salah satu fungsi khusus berikut.\n***Hancurkan Pesona.*** Sebagai tindakan Anda, Anda menyentuh makhluk yang dapat Anda jangkau yang terpesona, ketakutan, atau dirasuki oleh makhluk surgawi, elemen, makhluk jahat, iblis, atau mayat hidup. Makhluk yang Anda sentuh tidak lagi terpesona, ditakuti, atau dirasuki oleh makhluk tersebut.\n***Pemberhentian.*** Sebagai tindakan Anda, lakukan serangan mantra jarak dekat terhadap benda langit, elemen, makhluk halus, iblis, atau mayat hidup yang dapat Anda jangkau. Jika terjadi tabrakan, Anda mencoba untuk mengarahkan makhluk itu kembali ke pesawat asalnya. Makhluk tersebut harus berhasil dalam penyelamatan karisma atau dikirim kembali ke pesawat asalnya (jika belum ada). Jika mereka tidak berada di pesawat asal, mayat hidup dikirim ke Shadowfell, dan mereka dikirim ke Feywild." },
      { name: "Geas", components: "V", desc: "Anda memberikan perintah magis pada makhluk yang dapat Anda lihat dalam jangkauan, memaksanya untuk melakukan suatu layanan atau menahan diri dari tindakan atau aktivitas tertentu sesuai keputusan Anda. Jika makhluk itu dapat memahami Anda, ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Meskipun makhluk itu terpesona oleh Anda, dibutuhkan 5d10 kerusakan psikis setiap kali ia bertindak berlawanan dengan instruksi Anda, tetapi tidak lebih dari sekali setiap hari. Makhluk yang tidak dapat memahami Anda tidak terpengaruh oleh mantra tersebut.\nAnda dapat mengeluarkan perintah apa pun yang Anda pilih, selain aktivitas yang akan mengakibatkan kematian. Jika Anda mengeluarkan perintah bunuh diri, mantranya akan berakhir.\nAnda dapat mengakhiri mantra lebih awal dengan menggunakan tindakan untuk mengabaikannya. Mantra penghilang kutukan, pemulihan lebih besar, atau harapan juga mengakhirinya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau 8, durasinya adalah 1 tahun. Saat Anda merapal mantra ini menggunakan slot mantra level 9, mantra tersebut akan bertahan hingga diakhiri oleh salah satu mantra yang disebutkan di atas." },
      { name: "Raise Dead", components: "V, S, M", desc: "Anda menghidupkan kembali makhluk mati yang Anda sentuh, asalkan sudah mati tidak lebih dari 10 hari. Jika jiwa makhluk tersebut bersedia dan bebas untuk bergabung kembali dengan tubuhnya, makhluk tersebut akan hidup kembali dengan 1 poin pukulan.\nMantra ini juga menetralkan segala racun dan menyembuhkan penyakit non-magis yang menyerang makhluk tersebut pada saat ia mati. Namun mantra ini tidak menghilangkan penyakit magis, kutukan, atau efek serupa; jika ini tidak dihilangkan terlebih dahulu sebelum merapal mantra, itu akan berlaku saat makhluk itu hidup kembali. Mantra itu tidak bisa menghidupkan kembali makhluk undead.\nMantra ini menutup semua luka mematikan, namun tidak memulihkan bagian tubuh yang hilang. Jika makhluk itu kekurangan bagian tubuh atau organ yang tidak terpisahkan untuk kelangsungan hidupnya--kepalanya, misalnya--mantranya otomatis gagal.\nBangkit dari kematian adalah sebuah cobaan berat. Target menerima penalti -4 untuk semua serangan, lemparan penyelamatan, dan pemeriksaan kemampuan. Setiap target menyelesaikan istirahat panjang, penaltinya berkurang 1 hingga hilang." },
    ],
    Level6: [],
    Level7: [],
    Level8: [],
    Level9: [],
  },
  Ranger: {
    Cantrips: [],
    Level1: [
      { name: "Alarm", components: "V, S, M", desc: "Anda menyetel alarm terhadap gangguan yang tidak diinginkan. Pilih pintu, jendela, atau area dalam jangkauan yang tidak lebih besar dari kubus berukuran 20 kaki. Hingga mantranya berakhir, alarm akan memperingatkan Anda setiap kali makhluk kecil atau lebih besar menyentuh atau memasuki area yang dilindungi. Saat Anda mengucapkan mantra, Anda dapat menunjuk makhluk yang tidak akan membunyikan alarm. Anda juga memilih apakah alarm bersifat mental atau terdengar.\nAlarm mental memperingatkan Anda dengan ping di pikiran Anda jika Anda berada dalam jarak 1 mil dari area yang dilindungi. Ping ini membangunkan Anda jika Anda sedang tidur.\nAlarm yang dapat didengar menghasilkan suara bel tangan selama 10 detik dalam jarak 60 kaki." },
      { name: "Animal Friendship", components: "V, S, M", desc: "Mantra ini memungkinkan Anda meyakinkan binatang bahwa Anda tidak bermaksud jahat. Pilih binatang yang dapat Anda lihat dalam jangkauan. Ia harus melihat dan mendengar Anda. Jika Intelijen binatang itu 4 atau lebih tinggi, mantranya gagal. Jika tidak, binatang itu harus berhasil dalam lemparan penyelamatan kebijaksanaan atau terpesona oleh Anda selama durasi mantra tersebut. Jika Anda atau salah satu teman Anda melukai target, mantranya akan berakhir." },
      { name: "Cure Wounds", components: "V, S", desc: "Makhluk yang Anda sentuh mendapatkan kembali sejumlah poin hit yang setara dengan 1d8 + pengubah kemampuan perapalan ejaan Anda. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, penyembuhan meningkat sebesar 1d8 untuk setiap slot level di atas 1." },
      { name: "Detect Magic", components: "V, S", desc: "Selama durasi tersebut, Anda merasakan kehadiran sihir dalam jarak 30 kaki dari Anda. Jika Anda merasakan sihir dengan cara ini, Anda dapat menggunakan tindakan Anda untuk melihat aura samar di sekitar makhluk atau objek apa pun yang terlihat di area yang mengandung sihir, dan Anda mempelajari sekolah sihirnya, jika ada.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Detect Poison and Disease", components: "V, S, M", desc: "Selama durasi tersebut, Anda dapat merasakan keberadaan dan lokasi racun, makhluk beracun, dan penyakit dalam jarak 30 kaki dari Anda. Anda juga mengidentifikasi jenis racun, makhluk beracun, atau penyakit dalam setiap kasus.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Fog Cloud", components: "V, S", desc: "Anda membuat bola kabut dengan radius 20 kaki yang berpusat pada suatu titik dalam jangkauan. Bola itu menyebar ke berbagai sudut, dan areanya sangat tertutup. Itu berlangsung selama atau sampai angin dengan kecepatan sedang atau lebih besar (setidaknya 10 mil per jam) membubarkannya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, radius kabut bertambah 20 kaki untuk setiap slot level di atas 1." },
      { name: "Goodberry", components: "V, S, M", desc: "Hingga sepuluh buah beri muncul di tangan Anda dan diresapi dengan sihir selama durasi tersebut. Makhluk dapat menggunakan aksinya untuk memakan satu buah beri. Memakan buah beri memulihkan 1 titik pukulan, dan buah beri tersebut memberikan nutrisi yang cukup untuk menopang makhluk selama sehari.\nBuah beri kehilangan potensinya jika tidak dikonsumsi dalam waktu 24 jam setelah mantra ini diucapkan." },
      { name: "Hunter's Mark", components: "V", desc: "Anda memilih makhluk yang dapat Anda lihat dalam jangkauan dan secara mistis menandainya sebagai buruan Anda. Hingga mantranya berakhir, Anda memberikan kerusakan ekstra 1d6 pada target setiap kali Anda memukulnya dengan serangan senjata, dan Anda memiliki keuntungan pada pemeriksaan Kebijaksanaan (Persepsi) atau Kebijaksanaan (Kelangsungan Hidup) apa pun yang Anda lakukan untuk menemukannya. Jika target turun menjadi 0 poin hit sebelum mantra ini berakhir, Anda dapat menggunakan tindakan bonus pada giliran Anda berikutnya untuk menandai makhluk baru.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 3 atau 4, Anda dapat mempertahankan konsentrasi pada mantra tersebut hingga 8 jam. Saat Anda menggunakan slot mantra level 5 atau lebih tinggi, Anda dapat mempertahankan konsentrasi pada mantra hingga 24 jam." },
      { name: "Jump", components: "V, S, M", desc: "Anda menyentuh makhluk. Jarak lompatan makhluk itu menjadi tiga kali lipat hingga mantranya berakhir." },
      { name: "Longstrider", components: "V, S, M", desc: "Anda menyentuh makhluk. Kecepatan target meningkat 10 kaki hingga mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot mantra di atas level 1." },
      { name: "Speak with Animals", components: "V, S", desc: "Anda memperoleh kemampuan untuk memahami dan berkomunikasi secara verbal dengan binatang selama durasi tersebut. Pengetahuan dan kesadaran banyak binatang dibatasi oleh kecerdasan mereka, tetapi minimal, binatang dapat memberi Anda informasi tentang lokasi dan monster terdekat, termasuk apa pun yang dapat mereka lihat atau rasakan dalam satu hari terakhir. Anda mungkin bisa membujuk seekor binatang untuk memberikan bantuan kecil kepada Anda, sesuai kebijaksanaan GM." },
    ],
    Level2: [
      { name: "Animal Messenger", components: "V, S, M", desc: "Melalui mantra ini, Anda menggunakan binatang untuk menyampaikan pesan. Pilih binatang kecil yang dapat Anda lihat dalam jangkauannya, seperti tupai, blue jay, atau kelelawar. Anda menentukan lokasi, yang harus Anda kunjungi, dan penerima yang cocok dengan gambaran umum, seperti \"pria atau wanita berseragam penjaga kota\" atau \"kurcaci berambut merah yang memakai topi runcing\". Anda juga mengucapkan pesan hingga dua puluh lima kata. Binatang target melakukan perjalanan selama durasi mantra menuju lokasi yang ditentukan, menempuh jarak sekitar 50 mil per 24 jam untuk pembawa pesan terbang, atau 25 mil untuk hewan lain.\nSaat pembawa pesan tiba, ia menyampaikan pesan Anda kepada makhluk yang Anda gambarkan, meniru suara Anda. Utusan itu hanya berbicara kepada makhluk yang cocok dengan deskripsi yang Anda berikan. Jika pembawa pesan tidak mencapai tujuannya sebelum mantranya berakhir, pesannya akan hilang, dan binatang itu akan kembali ke tempat Anda mengucapkan mantra ini.\nJika Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, durasi mantra bertambah 48 jam untuk setiap slot level di atas 2." },
      { name: "Barkskin", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia. Hingga mantranya berakhir, kulit target akan terlihat kasar, seperti kulit kayu, dan AC target tidak boleh kurang dari 16, apa pun jenis armor yang dikenakannya." },
      { name: "Darkvision", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia memberinya kemampuan melihat dalam kegelapan. Selama durasinya, makhluk itu memiliki penglihatan gelap hingga jarak 60 kaki." },
      { name: "Find Traps", components: "V, S", desc: "Anda merasakan adanya jebakan apa pun dalam jangkauan yang berada dalam jarak pandang. Jebakan, untuk tujuan mantra ini, mencakup segala sesuatu yang dapat menimbulkan efek tiba-tiba atau tidak terduga yang Anda anggap berbahaya atau tidak diinginkan, yang secara khusus dimaksudkan oleh penciptanya. Dengan demikian, mantra tersebut akan mendeteksi area yang terkena mantra alarm, mesin terbang penangkal, atau jebakan lubang mekanis, namun tidak akan mengungkapkan kelemahan alami di lantai, langit-langit yang tidak stabil, atau lubang pembuangan yang tersembunyi.\nMantra ini hanya mengungkapkan bahwa ada jebakan. Anda tidak mempelajari lokasi setiap jebakan, namun Anda mempelajari sifat umum bahaya yang ditimbulkan oleh jebakan yang Anda rasakan." },
      { name: "Lesser Restoration", components: "V, S", desc: "Anda menyentuh suatu makhluk dan dapat mengakhiri satu penyakit atau satu kondisi yang menimpanya. Kondisinya bisa menjadi buta, tuli, lumpuh, atau keracunan." },
      { name: "Locate Animals or Plants", components: "V, S, M", desc: "Jelaskan atau beri nama jenis binatang atau tumbuhan tertentu. Berkonsentrasi pada suara alam di sekitar Anda, Anda mempelajari arah dan jarak ke makhluk atau tumbuhan terdekat dalam jarak 5 mil, jika ada." },
      { name: "Locate Object", components: "V, S, M", desc: "Jelaskan atau beri nama suatu objek yang Anda kenal. Anda merasakan arah ke lokasi objek, selama objek tersebut berada dalam jarak 1.000 kaki dari Anda. Jika suatu benda bergerak, maka diketahui arah pergerakannya.\nMantra tersebut dapat menemukan lokasi objek tertentu yang Anda kenal, selama Anda telah melihatnya dari dekat--dalam jarak 30 kaki--setidaknya sekali. Alternatifnya, mantra tersebut dapat menemukan lokasi objek terdekat dari jenis tertentu, seperti jenis pakaian, perhiasan, furnitur, perkakas, atau senjata tertentu.\nMantra ini tidak dapat menemukan lokasi suatu objek jika ada timah tebal, bahkan lembaran tipis, menghalangi jalur langsung antara Anda dan objek tersebut." },
      { name: "Pass Without Trace", components: "V, S, M", desc: "Selubung bayangan dan keheningan memancar dari Anda, menutupi Anda dan rekan Anda dari deteksi. Selama durasinya, setiap makhluk yang Anda pilih dalam jarak 30 kaki dari Anda (termasuk Anda) memiliki bonus +10 untuk pemeriksaan Dexterity (Stealth) dan tidak dapat dilacak kecuali dengan cara magis. Makhluk yang menerima bonus ini tidak meninggalkan jejak atau jejak lain dalam perjalanannya." },
      { name: "Protection from Poison", components: "V, S", desc: "Anda menyentuh makhluk. Jika diracuni, Anda menetralisir racunnya. Jika lebih dari satu racun menimpa target, Anda menetralisir satu racun yang Anda tahu ada, atau Anda menetralisir satu racun secara acak.\nSelama durasi tersebut, target memiliki keuntungan dalam menyimpan lemparan agar tidak terkena racun, dan memiliki ketahanan terhadap kerusakan akibat racun." },
      { name: "Silence", components: "V, S", desc: "Selama durasi tersebut, tidak ada suara yang dapat dihasilkan di dalam atau melewati bola berradius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan. Makhluk atau benda apa pun yang seluruhnya berada di dalam bola kebal terhadap kerusakan akibat petir, dan makhluk menjadi tuli saat berada sepenuhnya di dalamnya.\nMerapalkan mantra yang mencakup komponen verbal tidak mungkin dilakukan di sana." },
      { name: "Spike Growth", components: "V, S, M", desc: "Tanah dalam radius 20 kaki yang berpusat pada suatu titik dalam jangkauannya berputar dan menumbuhkan paku dan duri yang keras. Daerah tersebut menjadi medan yang sulit selama ini. Saat makhluk bergerak ke dalam atau di dalam area tersebut, ia menerima kerusakan tusuk sebesar 2d4 untuk setiap 5 kaki yang ia tempuh.\nTransformasi tanah disamarkan agar terlihat alami. Makhluk apa pun yang tidak dapat melihat area tersebut pada saat mantra diucapkan dapat melakukan pemeriksaan Kebijaksanaan (Persepsi) terhadap mantra Anda, simpan DC untuk mengenali medan tersebut sebagai berbahaya sebelum memasukinya." },
    ],
    Level3: [
      { name: "Conjure Animals", components: "V, S", desc: "Anda memanggil roh-roh jahat yang berbentuk binatang buas dan muncul di ruang kosong yang dapat Anda lihat dalam jangkauan. Pilih salah satu opsi berikut untuk apa yang muncul:\n- Satu binatang dengan peringkat tantangan 2 atau lebih rendah\n- Dua binatang dengan peringkat tantangan 1 atau lebih rendah\n- Empat binatang dengan peringkat tantangan 1/2 atau lebih rendah\n- Delapan binatang dengan peringkat tantangan 1/4 atau lebih rendah\n- Setiap binatang juga dianggap ganas, dan menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nMakhluk yang dipanggil ramah terhadap Anda dan teman Anda. Gulung inisiatif untuk makhluk yang dipanggil sebagai kelompok, yang memiliki giliran tersendiri. Mereka mematuhi perintah verbal apa pun yang Anda berikan kepada mereka (Anda tidak perlu melakukan tindakan apa pun). Jika Anda tidak memberikan perintah apa pun kepada mereka, mereka mempertahankan diri dari makhluk bermusuhan, tetapi sebaliknya tidak mengambil tindakan.\nGM mempunyai statistik makhluk-makhluk itu.\nLevel Tinggi: Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat tinggi tertentu, Anda memilih salah satu opsi pemanggilan di atas, dan lebih banyak makhluk muncul: dua kali lebih banyak dengan slot level 5, tiga kali lebih banyak dengan slot level 7." },
      { name: "Daylight", components: "V, S", desc: "Bola cahaya dengan radius 60 kaki menyebar dari titik yang Anda pilih dalam jangkauannya. Bola tersebut memiliki cahaya terang dan memancarkan cahaya redup sejauh 60 kaki.\nJika Anda memilih suatu titik pada suatu benda yang Anda pegang atau yang tidak sedang dipakai atau dibawa, cahaya akan bersinar dari benda tersebut dan bergerak bersamanya. Menutupi seluruh objek yang terkena dengan benda buram, seperti mangkuk atau helm, akan menghalangi cahaya.\nJika salah satu area mantra ini tumpang tindih dengan area kegelapan yang diciptakan oleh mantra level 3 atau lebih rendah, mantra yang menciptakan kegelapan tersebut akan hilang." },
      { name: "Nondetection", components: "V, S, M", desc: "Selama durasi tersebut, Anda menyembunyikan target yang Anda sentuh dari sihir ramalan. Sasarannya dapat berupa makhluk yang bersedia atau suatu tempat atau benda yang berukuran tidak lebih dari 10 kaki dalam dimensi apa pun. Targetnya tidak dapat ditargetkan oleh sihir ramalan apa pun atau dirasakan melalui sensor penglihatan magis." },
      { name: "Plant Growth", components: "V, S", desc: "Mantra ini menyalurkan vitalitas ke tanaman di area tertentu. Ada dua kemungkinan penggunaan mantra ini, memberikan manfaat langsung atau jangka panjang.\nJika Anda mengucapkan mantra ini menggunakan 1 tindakan, pilih titik dalam jangkauan. Semua tanaman normal dalam radius 100 kaki yang berpusat pada titik tersebut menjadi lebat dan ditumbuhi tanaman. Makhluk yang bergerak melalui area tersebut harus menghabiskan 4 kaki gerakan untuk setiap 1 kaki yang digerakkannya.\nAnda dapat mengecualikan satu atau lebih area dengan ukuran berapa pun di dalam area mantra agar tidak terpengaruh.\nJika Anda mengucapkan mantra ini selama 8 jam, Anda memperkaya tanah. Semua tanaman dalam radius setengah mil yang berpusat pada suatu titik dalam jangkauan akan diperkaya selama 1 tahun. Tanaman menghasilkan dua kali jumlah makanan normal saat dipanen." },
      { name: "Protection From Energy", components: "V, S", desc: "Selama durasi tersebut, makhluk yang Anda sentuh memiliki ketahanan terhadap satu jenis kerusakan pilihan Anda: asam, dingin, api, kilat, atau guntur." },
      { name: "Speak with Plants", components: "V, S", desc: "Anda mengilhami tanaman dalam jarak 30 kaki dari Anda dengan perasaan dan animasi terbatas, memberi mereka kemampuan untuk berkomunikasi dengan Anda dan mengikuti perintah sederhana Anda. Anda dapat menanyakan tanaman tentang kejadian di area mantra dalam satu hari terakhir, mendapatkan informasi tentang makhluk yang telah lewat, cuaca, dan keadaan lainnya.\nAnda juga dapat mengubah medan sulit yang disebabkan oleh pertumbuhan tanaman (seperti semak belukar dan semak belukar) menjadi medan biasa yang bertahan lama. Atau Anda dapat mengubah medan biasa yang terdapat tanaman menjadi medan sulit yang bertahan lama, menyebabkan tanaman merambat dan dahan menghalangi pengejar, misalnya.\nPabrik mungkin dapat melakukan tugas lain atas nama Anda, sesuai kebijakan GM. Mantra tersebut tidak memungkinkan tanaman untuk mencabut dirinya sendiri dan bergerak, tetapi mereka dapat dengan bebas memindahkan cabang, sulur, dan batang.\nJika ada makhluk tumbuhan di area tersebut, Anda dapat berkomunikasi dengannya seolah-olah Anda memiliki bahasa yang sama, namun Anda tidak memperoleh kemampuan magis untuk memengaruhinya.\nMantra ini dapat menyebabkan tanaman yang diciptakan oleh mantra entangle melepaskan makhluk yang tertahan." },
      { name: "Water Breathing", components: "V, S, M", desc: "Mantra ini memberikan maksimal sepuluh makhluk yang bersedia berada dalam jangkauannya dan Anda dapat melihat, kemampuan bernapas di bawah air hingga akhir masa berlakunya. Makhluk yang terkena dampak juga mempertahankan pola pernapasan normalnya." },
      { name: "Water Walk", components: "V, S, M", desc: "Mantra ini memberikan kemampuan untuk bergerak melintasi permukaan cair apa pun--seperti air, asam, lumpur, salju, pasir hisap, atau lava--seolah-olah permukaan tersebut adalah tanah padat yang tidak berbahaya (makhluk yang melintasi lava cair masih dapat menerima kerusakan akibat panas). Hingga sepuluh makhluk yang dapat Anda lihat dalam jangkauan mendapatkan kemampuan ini selama durasi tersebut.\nJika Anda menargetkan makhluk yang terendam dalam cairan, mantranya akan membawa target ke permukaan cairan dengan kecepatan 60 kaki per putaran." },
      { name: "Wind Wall", components: "V, S, M", desc: "Dinding angin kencang muncul dari tanah pada titik yang Anda pilih dalam jangkauannya. Anda dapat membuat tembok dengan panjang hingga 50 kaki, tinggi 15 kaki, dan tebal 1 kaki. Anda dapat membentuk dinding dengan cara apa pun yang Anda pilih selama dinding tersebut membentuk satu jalur yang berkesinambungan di sepanjang tanah. Dinding itu bertahan selama itu.\nSaat tembok muncul, setiap makhluk di dalam areanya harus melakukan lemparan hemat kekuatan. Makhluk menerima kerusakan sebesar 3d8 jika penyelamatan gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nAngin kencang menghalangi kabut, asap, dan gas lainnya. Makhluk atau benda terbang yang berukuran kecil atau lebih kecil tidak dapat melewati dinding. Bahan longgar dan ringan yang dibawa ke dinding terbang ke atas. Anak panah, baut, dan proyektil biasa lainnya yang diluncurkan ke sasaran di balik tembok dibelokkan ke atas dan otomatis meleset. (Batu-batu besar yang dilemparkan oleh raksasa atau mesin pengepungan, dan proyektil serupa, tidak terpengaruh.) Makhluk dalam bentuk gas tidak dapat melewatinya." },
    ],
    Level4: [
      { name: "Conjure Woodland Beings", components: "V, S, M", desc: "Anda memanggil makhluk-makhluk jahat yang muncul di ruang kosong yang dapat Anda lihat dalam jangkauan. Pilih salah satu opsi berikut untuk apa yang muncul:\n- Satu makhluk dengan peringkat tantangan 2 atau lebih rendah\n- Dua makhluk buas dengan peringkat tantangan 1 atau lebih rendah\n- Empat makhluk buas dengan peringkat tantangan 1/2 atau lebih rendah\n- Delapan makhluk buas dengan peringkat tantangan 1/4 atau lebih rendah\nMakhluk yang dipanggil menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nMakhluk yang dipanggil ramah terhadap Anda dan teman Anda. Gulung inisiatif untuk makhluk yang dipanggil sebagai kelompok, yang mempunyai giliran masing-masing. Mereka mematuhi perintah verbal apa pun yang Anda berikan kepada mereka (Anda tidak perlu melakukan tindakan apa pun). Jika Anda tidak memberikan perintah apa pun kepada mereka, mereka mempertahankan diri dari makhluk bermusuhan, tetapi sebaliknya tidak mengambil tindakan.\nGM mempunyai statistik makhluk-makhluk itu.\nLevel Tinggi: Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat tinggi tertentu, Anda memilih salah satu opsi pemanggilan di atas, dan lebih banyak makhluk muncul: dua kali lebih banyak dengan slot level 6 dan tiga kali lebih banyak dengan slot level 8." },
      { name: "Freedom of Movement", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia. Selama durasi tersebut, pergerakan target tidak terpengaruh oleh medan yang sulit, dan mantra serta efek magis lainnya tidak dapat mengurangi kecepatan target atau menyebabkan target menjadi lumpuh atau tertahan.\nTarget juga dapat menggunakan gerakan sejauh 5 kaki untuk secara otomatis melarikan diri dari pengekangan non-magis, seperti borgol atau makhluk yang digenggamnya. Terakhir, berada di bawah air tidak memberikan penalti pada pergerakan atau serangan target." },
      { name: "Locate Creature", components: "V, S, M", desc: "Jelaskan atau beri nama makhluk yang Anda kenal. Anda merasakan arah ke lokasi makhluk itu, selama makhluk itu berada dalam jarak 1.000 kaki dari Anda. Jika makhluk itu bergerak, Anda mengetahui arah pergerakannya.\nMantra ini dapat menemukan lokasi makhluk tertentu yang Anda kenal, atau makhluk terdekat dari jenis tertentu (seperti manusia atau unicorn), selama Anda pernah melihat makhluk tersebut dari dekat--dalam jarak 30 kaki--setidaknya sekali. Jika makhluk yang Anda gambarkan atau beri nama berada dalam bentuk yang berbeda, seperti berada di bawah pengaruh mantra polimorf, mantra ini tidak akan menemukan lokasi makhluk tersebut.\nMantra ini tidak dapat menemukan lokasi makhluk jika air yang mengalir selebar 10 kaki menghalangi jalur langsung antara Anda dan makhluk tersebut." },
      { name: "Stoneskin", components: "V, S, M", desc: "Mantra ini mengubah daging makhluk yang Anda sentuh menjadi sekeras batu. Hingga mantranya berakhir, target memiliki ketahanan terhadap pukulan non-magis, tusukan, dan tebasan." },
    ],
    Level5: [
      { name: "Commune With Nature", components: "V, S", desc: "Anda sebentar menjadi satu dengan alam dan mendapatkan pengetahuan tentang wilayah sekitarnya. Di alam terbuka, mantranya memberi Anda pengetahuan tentang daratan dalam jarak 3 mil dari Anda. Di gua dan lingkungan alami bawah tanah lainnya, radius dibatasi hingga 300 kaki. Mantra tidak berfungsi jika alam telah digantikan oleh konstruksi, seperti di ruang bawah tanah dan kota.\nAnda langsung mendapatkan pengetahuan hingga tiga fakta pilihan Anda tentang salah satu subjek berikut yang berkaitan dengan area tersebut:\n- medan dan badan air\n- tumbuhan, mineral, hewan, atau manusia yang lazim\n- makhluk surgawi, fey, iblis, elemental, atau undead yang kuat\n- pengaruh dari alam eksistensi lain\n- bangunan\nMisalnya, Anda dapat menentukan lokasi undead yang kuat di area tersebut, lokasi sumber utama air minum yang aman, dan lokasi kota terdekat." },
      { name: "Tree Stride", components: "V, S", desc: "Anda memperoleh kemampuan untuk memasuki pohon dan berpindah dari dalam pohon ke dalam pohon lain yang sejenis dalam jarak 500 kaki. Kedua pohon tersebut harus hidup dan setidaknya berukuran sama dengan Anda. Anda harus menggunakan gerakan 5 kaki untuk memasuki pohon. Anda langsung mengetahui lokasi semua pohon lain yang sejenis dalam jarak 500 kaki dan, sebagai bagian dari gerakan yang digunakan untuk memasuki pohon, Anda dapat masuk ke salah satu pohon tersebut atau keluar dari pohon tempat Anda berada. Anda muncul di tempat pilihan Anda dalam jarak 5 kaki dari pohon tujuan, menggunakan gerakan 5 kaki lainnya. Jika Anda tidak punya gerakan lagi, Anda muncul dalam jarak 5 kaki dari pohon yang Anda masuki.\nAnda dapat menggunakan kemampuan transportasi ini satu kali per putaran selama durasi tersebut. Anda harus mengakhiri setiap belokan di luar pohon." },
    ],
    Level6: [],
    Level7: [],
    Level8: [],
    Level9: [],
  },
  Sorcerer: {
    Cantrips: [
      { name: "Acid Splash", components: "V, S", desc: "Anda melemparkan gelembung asam. Pilih satu makhluk dalam jangkauan, atau pilih dua makhluk dalam jangkauan yang berada dalam jarak 5 kaki satu sama lain. Target harus berhasil dalam lemparan penyelamatan ketangkasan atau menerima kerusakan asam 1d6.\nKerusakan mantra ini meningkat sebesar 1d6 ketika Anda mencapai level 5 (2d6), level 11 (3d6), dan level 17 (4d6)." },
      { name: "Chill Touch", components: "V, S", desc: "Anda membuat tangan kerangka hantu di ruang makhluk dalam jangkauan. Lakukan serangan mantra jarak jauh terhadap makhluk itu untuk menyerangnya dengan dinginnya kuburan. Saat terkena serangan, target menerima 1d8 kerusakan nekrotik, dan target tidak dapat memperoleh kembali poin serangan hingga dimulainya giliran berikutnya. Sampai saat itu, tangan menempel pada sasaran.\nJika Anda mengenai target undead, ia juga memiliki kerugian pada serangan yang bergulir ke arah Anda hingga akhir giliran Anda berikutnya.\nKerusakan mantra ini meningkat sebesar 1d8 ketika Anda mencapai level 5 (2d8), level 11 (3d8), dan level 17 (4d8)." },
      { name: "Dancing Lights", components: "V, S, M", desc: "Anda membuat hingga empat lampu seukuran obor dalam jangkauan, menjadikannya tampak seperti obor, lentera, atau bola bercahaya yang melayang di udara selama durasi tersebut. Anda juga dapat menggabungkan keempat lampu menjadi satu bentuk humanoid samar-samar berukuran sedang. Apapun bentuk yang Anda pilih, setiap lampu memancarkan cahaya redup dalam radius 10 kaki.\nSebagai tindakan bonus pada giliran Anda, Anda dapat memindahkan lampu hingga 60 kaki ke tempat baru dalam jangkauan. Sebuah cahaya harus berada dalam jarak 20 kaki dari cahaya lain yang diciptakan oleh mantra ini, dan sebuah cahaya akan berkedip jika melebihi jangkauan mantranya." },
      { name: "Fire Bolt", components: "V, S", desc: "Anda melemparkan lebih banyak api ke makhluk atau objek dalam jangkauan. Lakukan serangan mantra jarak jauh terhadap target. Saat terkena, target menerima 1d10 kerusakan api. Benda mudah terbakar yang terkena mantra ini akan menyala jika tidak dipakai atau dibawa.\nKerusakan mantra ini meningkat sebesar 1d10 ketika Anda mencapai level 5 (2d10), level 11 (3d10), dan level 17 (4d10)." },
      { name: "Light", components: "V, M", desc: "Anda menyentuh satu objek yang ukurannya tidak lebih besar dari 10 kaki dalam dimensi apa pun. Hingga mantranya berakhir, objek tersebut memancarkan cahaya terang dalam radius 20 kaki dan cahaya redup dalam radius tambahan 20 kaki. Lampunya bisa diwarnai sesuka Anda. Menutupi objek sepenuhnya dengan sesuatu yang buram menghalangi cahaya. Mantra berakhir jika Anda mengucapkannya lagi atau mengabaikannya sebagai suatu tindakan.\nJika Anda mengincar benda yang dipegang atau dikenakan oleh makhluk musuh, makhluk tersebut harus berhasil melakukan lemparan penyelamatan ketangkasan untuk menghindari mantranya." },
      { name: "Mage Hand", components: "V, S", desc: "Tangan spektral dan mengambang muncul pada titik yang Anda pilih dalam jangkauan. Tangan tersebut bertahan selama atau sampai Anda mengabaikannya sebagai suatu tindakan. Tangan itu akan hilang jika jaraknya lebih dari 30 kaki dari Anda atau jika Anda mengucapkan mantra ini lagi.\nAnda dapat menggunakan tindakan Anda untuk mengontrol tangan. Anda dapat menggunakan tangan untuk memanipulasi suatu benda, membuka pintu atau wadah yang tidak terkunci, menyimpan atau mengambil suatu benda dari wadah terbuka, atau menuangkan isinya ke dalam botol. Anda dapat menggerakkan tangan hingga 30 kaki setiap kali menggunakannya.\nTangan tidak dapat menyerang, mengaktifkan item sihir, atau membawa beban lebih dari 10 pon." },
      { name: "Mending", components: "V, S, M", desc: "Mantra ini memperbaiki satu kerusakan atau robekan pada benda yang Anda sentuh, seperti kunci rusak, jubah robek, atau kantong anggur yang bocor. Selama patah atau robeknya tidak lebih dari 1 kaki di dimensi mana pun, Anda memperbaikinya, tanpa meninggalkan bekas kerusakan sebelumnya.\nMantra ini secara fisik dapat memperbaiki item atau konstruksi sihir, tetapi mantra tersebut tidak dapat memulihkan sihir ke objek tersebut." },
      { name: "Message", components: "V, S, M", desc: "Anda mengarahkan jari Anda ke arah makhluk dalam jangkauan dan membisikkan pesan. Target (dan hanya target) yang mendengar pesan tersebut dan dapat membalas dengan bisikan yang hanya dapat didengar oleh Anda.\nAnda dapat mengucapkan mantra ini melalui benda padat jika Anda familiar dengan targetnya dan mengetahui bahwa targetnya berada di luar penghalang. Keheningan magis, batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu setinggi 3 kaki menghalangi mantra tersebut. Mantranya tidak harus mengikuti garis lurus dan dapat bergerak bebas di sudut atau melalui celah." },
      { name: "Minor Illusion", components: "S, M", desc: "Anda membuat suara atau gambar suatu objek dalam jangkauan yang berlangsung selama durasi tersebut. Ilusi juga berakhir jika Anda mengabaikannya sebagai suatu tindakan atau mengucapkan mantra ini lagi.\nJika Anda membuat suara, volumenya bisa berkisar dari bisikan hingga jeritan. Bisa berupa suara Anda, suara orang lain, auman singa, tabuhan genderang, atau suara lain yang Anda pilih. Suara tersebut terus terdengar tanpa henti sepanjang durasi, atau Anda dapat membuat suara terpisah pada waktu yang berbeda sebelum mantra berakhir.\nJika Anda membuat gambar suatu objek--seperti kursi, jejak kaki berlumpur, atau peti kecil--ukurannya tidak boleh lebih dari kubus berukuran 5 kaki. Gambar tidak dapat menimbulkan suara, cahaya, bau, atau efek sensorik lainnya. Interaksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya.\nJika makhluk menggunakan tindakannya untuk memeriksa suara atau gambar, makhluk tersebut dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk mengenali ilusi apa adanya, ilusi tersebut menjadi samar bagi makhluk tersebut." },
      { name: "Poison Spray", components: "V, S", desc: "Anda mengulurkan tangan Anda ke arah makhluk yang dapat Anda lihat dalam jangkauan dan mengeluarkan kepulan gas berbahaya dari telapak tangan Anda. Makhluk itu harus berhasil melakukan penyelamatan konstitusi atau menerima kerusakan racun 1d12.\nKerusakan mantra ini meningkat sebesar 1d12 ketika Anda mencapai level 5 (2d12), level 11 (3d12), dan level 17 (4d12)." },
      { name: "Prestidigitation", components: "V, S", desc: "Mantra ini adalah trik magis kecil yang digunakan oleh perapal mantra pemula untuk latihan. Anda membuat salah satu efek ajaib berikut dalam 'jangkauan':\nAnda menciptakan efek sensorik yang seketika dan tidak berbahaya, seperti percikan api, hembusan angin, not musik yang samar, atau bau yang aneh.\nAnda langsung menyalakan atau mematikan lilin, obor, atau api unggun kecil.\nAnda langsung membersihkan atau mengotori benda yang ukurannya tidak lebih dari 1 kaki kubik.\nAnda mendinginkan, menghangatkan, atau membumbui hingga 1 kaki kubik bahan tak hidup selama 1 jam.\nAnda membuat warna, tanda kecil, atau simbol muncul pada suatu benda atau permukaan selama 1 jam.\nAnda membuat pernak-pernik non-magis atau gambar ilusi yang pas di tangan Anda dan bertahan hingga akhir giliran Anda berikutnya.\nJika Anda mengucapkan mantra ini beberapa kali, Anda dapat mengaktifkan hingga tiga efek non-instannya sekaligus, dan Anda dapat mengabaikan efek tersebut sebagai tindakan." },
      { name: "Ray of Frost", components: "V, S", desc: "Seberkas cahaya biru-putih yang dingin melesat ke arah makhluk dalam jangkauannya. Lakukan serangan mantra jarak jauh terhadap target. Saat terkena serangan, dibutuhkan 1d8 kerusakan dingin, dan kecepatannya berkurang 10 kaki hingga dimulainya giliran berikutnya.\nKerusakan mantra meningkat sebesar 1d8 ketika Anda mencapai level 5 (2d8), level 11 (3d8), dan level 17 (4d8)." },
      { name: "Shocking Grasp", components: "V, S", desc: "Petir muncul dari tangan Anda untuk memberikan kejutan pada makhluk yang Anda coba sentuh. Lakukan serangan mantra jarak dekat terhadap target. Anda memiliki keuntungan dalam serangan roll jika target memakai armor yang terbuat dari logam. Saat terkena serangan, target menerima 1d8 kerusakan petir, dan tidak dapat bereaksi hingga giliran berikutnya dimulai.\nKerusakan mantra meningkat sebesar 1d8 ketika Anda mencapai level 5 (2d8), level 11 (3d8), dan level 17 (4d8)." },
      { name: "True Strike", components: "S", desc: "Anda mengulurkan tangan dan mengarahkan jari ke sasaran dalam jangkauan. Sihir Anda memberi Anda wawasan singkat tentang pertahanan target. Pada giliran berikutnya, Anda mendapatkan keuntungan dari serangan pertama Anda terhadap target, asalkan mantra ini belum berakhir." },
    ],
    Level1: [
      { name: "Burning Hands", components: "V, S", desc: "Saat Anda memegang tangan Anda dengan ibu jari saling bersentuhan dan jari-jari terentang, selembar api tipis menyembur keluar dari ujung jari Anda yang terentang. Setiap makhluk dalam kerucut setinggi 15 kaki harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan api 3d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil.\nApi menyulut benda-benda mudah terbakar di area tersebut yang tidak dipakai atau dibawa.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 1." },
      { name: "Charm Person", components: "V, S", desc: "Anda mencoba memikat humanoid yang dapat Anda lihat dalam jangkauan. Ia harus melakukan lemparan penyelamatan yang bijaksana, dan melakukannya dengan keuntungan jika Anda atau teman Anda melawannya. Jika gagal dalam lemparan penyelamatan, ia akan terpesona oleh Anda hingga mantranya berakhir atau hingga Anda atau teman Anda melakukan sesuatu yang membahayakannya. Makhluk yang terpesona menganggap Anda sebagai kenalan yang ramah. Saat mantranya berakhir, makhluk itu tahu bahwa dia terpesona oleh Anda.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 1. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Color Spray", components: "V, S, M", desc: "Serangkaian kilatan cahaya berwarna yang mempesona muncul dari tangan Anda. Gulung 6d10; totalnya adalah berapa banyak poin serangan makhluk yang dapat dipengaruhi oleh mantra ini. Makhluk dalam kerucut setinggi 15 kaki yang berasal dari Anda akan terpengaruh dalam urutan titik hit mereka saat ini (mengabaikan makhluk tidak sadar dan makhluk yang tidak dapat melihat).\nDimulai dengan makhluk yang memiliki poin hit terendah saat ini, setiap makhluk yang terkena mantra ini akan dibutakan hingga mantranya berakhir. Kurangi poin hit setiap makhluk dari total sebelum melanjutkan ke makhluk dengan poin hit terendah berikutnya. Hit point suatu makhluk harus sama dengan atau kurang dari total yang tersisa agar makhluk tersebut dapat terpengaruh.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, putar 2d10 tambahan untuk setiap level slot di atas 1." },
      { name: "Comprehend Languages", components: "V, S, M", desc: "Selama ini, Anda memahami arti literal dari setiap bahasa lisan yang Anda dengar. Anda juga memahami bahasa tertulis apa pun yang Anda lihat, tetapi Anda harus menyentuh permukaan tempat kata-kata itu ditulis. Dibutuhkan sekitar 1 menit untuk membaca satu halaman teks.\nMantra ini tidak memecahkan kode pesan rahasia dalam teks atau mesin terbang, seperti sigil misterius, yang bukan bagian dari bahasa tertulis." },
      { name: "Detect Magic", components: "V, S", desc: "Selama durasi tersebut, Anda merasakan kehadiran sihir dalam jarak 30 kaki dari Anda. Jika Anda merasakan sihir dengan cara ini, Anda dapat menggunakan tindakan Anda untuk melihat aura samar di sekitar makhluk atau objek apa pun yang terlihat di area yang mengandung sihir, dan Anda mempelajari sekolah sihirnya, jika ada.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Disguise Self", components: "V, S", desc: "Anda membuat diri Anda sendiri--termasuk pakaian, baju besi, senjata, dan barang-barang lainnya pada diri Anda--terlihat berbeda sampai mantranya berakhir atau sampai Anda menggunakan tindakan Anda untuk mengabaikannya. Anda bisa terlihat 1 kaki lebih pendek atau lebih tinggi dan bisa terlihat kurus, gemuk, atau di antara keduanya. Anda tidak dapat mengubah tipe tubuh Anda, jadi Anda harus mengambil bentuk yang memiliki susunan dasar anggota tubuh yang sama. Jika tidak, sejauh mana ilusi itu terserah Anda.\nPerubahan yang dilakukan oleh mantra ini gagal memenuhi pemeriksaan fisik. Misalnya, jika Anda menggunakan mantra ini untuk menambahkan topi ke pakaian Anda, benda akan melewati topi tersebut, dan siapa pun yang menyentuhnya tidak akan merasakan apa pun atau akan merasakan kepala dan rambut Anda. Jika Anda menggunakan mantra ini untuk terlihat lebih kurus dari Anda, tangan seseorang yang mengulurkan tangan untuk menyentuh Anda akan menabrak Anda saat tangan itu tampak masih di udara.\nUntuk mengetahui bahwa Anda sedang menyamar, makhluk dapat menggunakan tindakannya untuk memeriksa penampilan Anda dan harus berhasil dalam pemeriksaan Intelijen (Investigasi) terhadap mantra penyelamatan DC Anda." },
      { name: "Expeditious Retreat", components: "V, S", desc: "Mantra ini memungkinkan Anda bergerak dengan kecepatan luar biasa. Saat Anda mengucapkan mantra ini, dan kemudian sebagai tindakan bonus di setiap giliran Anda hingga mantra tersebut berakhir, Anda dapat melakukan tindakan Dash." },
      { name: "False Life", components: "V, S, M", desc: "Memperkuat diri Anda dengan faksimili kehidupan necromantic, Anda mendapatkan 1d4 + 4 poin hit sementara selama durasi tersebut.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda mendapatkan 5 poin hit sementara tambahan untuk setiap slot level di atas 1." },
      { name: "Feather Fall", components: "V, M", desc: "Pilih hingga lima makhluk yang jatuh dalam jangkauan. Kecepatan turunnya makhluk yang jatuh melambat hingga 60 kaki per putaran hingga mantranya berakhir. Jika makhluk itu mendarat sebelum mantranya berakhir, ia tidak menerima kerusakan akibat jatuh dan dapat mendarat dengan kakinya, dan mantranya berakhir untuk makhluk itu." },
      { name: "Fog Cloud", components: "V, S", desc: "Anda membuat bola kabut dengan radius 20 kaki yang berpusat pada suatu titik dalam jangkauan. Bola itu menyebar ke berbagai sudut, dan areanya sangat tertutup. Itu berlangsung selama atau sampai angin dengan kecepatan sedang atau lebih besar (setidaknya 10 mil per jam) membubarkannya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, radius kabut bertambah 20 kaki untuk setiap slot level di atas 1." },
      { name: "Jump", components: "V, S, M", desc: "Anda menyentuh makhluk. Jarak lompatan makhluk itu menjadi tiga kali lipat hingga mantranya berakhir." },
      { name: "Mage Armor", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia yang tidak mengenakan baju besi, dan kekuatan magis pelindung mengelilinginya sampai mantranya berakhir. AC dasar target menjadi 13+ pengubah Dexterity-nya. Mantra berakhir jika target mengenakan baju besi atau jika Anda mengabaikan mantra sebagai suatu tindakan." },
      { name: "Magic Missile", components: "V, S", desc: "Anda menciptakan tiga anak panah kekuatan magis yang bersinar. Setiap anak panah mengenai makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan. Sebuah anak panah menimbulkan 1d4 + 1 kerusakan kekuatan pada targetnya. Semua anak panah menyerang secara bersamaan, dan Anda dapat mengarahkannya untuk mengenai satu atau beberapa makhluk.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 2 atau lebih tinggi, mantra tersebut akan menghasilkan satu anak panah lagi untuk setiap slot level di atas 1." },
      { name: "Shield", components: "V, S", desc: "Penghalang kekuatan magis yang tak terlihat muncul dan melindungi Anda. Hingga awal giliran Anda berikutnya, Anda memiliki bonus +5 untuk AC, termasuk terhadap serangan yang memicu, dan Anda tidak menerima kerusakan dari rudal ajaib." },
      { name: "Silent Image", components: "V, S, M", desc: "Anda membuat gambar suatu benda, makhluk, atau fenomena nyata lainnya yang ukurannya tidak lebih besar dari kubus berukuran 15 kaki. Gambar muncul di suatu tempat dalam jangkauan dan berlangsung selama durasi tersebut. Gambar tersebut murni visual; tidak disertai suara, bau, atau efek sensorik lainnya.\nAnda dapat menggunakan tindakan Anda untuk menyebabkan gambar berpindah ke tempat mana pun dalam jangkauan. Saat gambar berpindah lokasi, Anda dapat mengubah tampilannya sehingga gerakannya tampak natural pada gambar. Misalnya, jika Anda membuat gambar makhluk dan memindahkannya, Anda dapat mengubah gambar tersebut sehingga tampak seperti sedang berjalan.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk dapat mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut." },
      { name: "Sleep", components: "V, S, M", desc: "Mantra ini membuat makhluk tertidur secara ajaib. Gulung 5d8; totalnya adalah berapa banyak poin serangan makhluk yang dapat dipengaruhi oleh mantra ini. Makhluk dalam jarak 20 kaki dari titik yang Anda pilih dalam jangkauan akan terpengaruh dalam urutan titik serangan mereka saat ini (mengabaikan makhluk yang tidak sadarkan diri).\nDimulai dengan makhluk yang memiliki poin serangan terendah saat ini, setiap makhluk yang terkena mantra ini akan jatuh pingsan hingga mantranya berakhir, orang yang tidur menerima kerusakan, atau seseorang menggunakan tindakan untuk mengguncang atau menampar orang yang tidur tersebut hingga terbangun. Kurangi poin hit setiap makhluk dari total sebelum melanjutkan ke makhluk dengan poin hit terendah berikutnya. Hit point suatu makhluk harus sama dengan atau kurang dari total yang tersisa agar makhluk tersebut dapat terpengaruh.\nMayat hidup dan makhluk yang kebal terhadap pesona tidak terpengaruh oleh mantra ini.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, putar 2d8 tambahan untuk setiap level slot di atas 1." },
      { name: "Thunderwave", components: "V, S", desc: "Gelombang kekuatan yang menggelegar menyapu Anda. Setiap makhluk dalam kubus berukuran 15 kaki yang berasal dari Anda harus melakukan lemparan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk menerima kerusakan petir sebesar 2d8 dan didorong sejauh 10 kaki dari Anda. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan dan tidak didorong.\nSelain itu, objek tanpa jaminan yang sepenuhnya berada dalam area efek secara otomatis didorong sejauh 10 kaki dari Anda oleh efek mantra, dan mantra tersebut mengeluarkan ledakan menggelegar yang terdengar hingga jarak 300 kaki.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 1." },
    ],
    Level2: [
      { name: "Alter Self", components: "V, S", desc: "Anda mengambil bentuk yang berbeda. Saat Anda mengucapkan mantra, pilih salah satu opsi berikut, yang efeknya akan bertahan selama durasi mantra. Selama mantranya berlangsung, Anda dapat mengakhiri satu opsi sebagai tindakan untuk mendapatkan manfaat dari opsi lain.\n***Adaptasi Perairan.*** Anda menyesuaikan tubuh Anda dengan lingkungan perairan, menumbuhkan insang dan menumbuhkan jaring di antara jari-jari Anda. Anda dapat bernapas di bawah air dan mendapatkan kecepatan berenang yang setara dengan kecepatan berjalan Anda.\n***Ubah Penampilan.*** Anda mengubah penampilan Anda. Anda yang memutuskan seperti apa penampilan Anda, termasuk tinggi badan, berat badan, fitur wajah, suara Anda, panjang rambut, warna rambut, dan ciri-ciri pembeda, jika ada. Anda dapat membuat diri Anda tampil sebagai anggota ras lain, meskipun statistik Anda tidak berubah. Anda juga tidak dapat tampil sebagai makhluk dengan ukuran berbeda dari Anda, dan bentuk dasar Anda tetap sama; jika Anda berkaki dua, misalnya, Anda tidak bisa menggunakan mantra ini untuk menjadi berkaki empat. Kapan saja selama durasi mantra, Anda dapat menggunakan tindakan Anda untuk mengubah penampilan Anda lagi dengan cara ini.\n***Senjata Alami.*** Anda menumbuhkan cakar, taring, duri, tanduk, atau senjata alami lain pilihan Anda. Serangan tanpa senjata Anda menghasilkan kerusakan pukulan, penusukan, atau tebasan 1d6, sesuai dengan senjata alami yang Anda pilih, dan Anda mahir dengan serangan tanpa senjata. Terakhir, senjata alaminya adalah sihir dan Anda memiliki bonus +1 untuk serangan dan damage roll yang Anda buat menggunakannya." },
      { name: "Blindness/Deafness", components: "V", desc: "Anda bisa membutakan atau menulikan musuh. Pilih satu makhluk yang dapat Anda lihat dalam jangkauan untuk melakukan penyelamatan konstitusi. Jika gagal, target akan menjadi buta atau tuli (pilihan Anda) selama durasi tersebut. Di akhir setiap giliran, target dapat melakukan penyelamatan konstitusi. Jika berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Blur", components: "V", desc: "Tubuhmu menjadi kabur, bergeser dan bimbang terhadap siapa pun yang bisa melihatmu. Selama durasi tersebut, makhluk apa pun memiliki kelemahan dalam serangan yang menyerang Anda. Seorang penyerang kebal terhadap efek ini jika ia tidak mengandalkan penglihatan, seperti pada penglihatan buta, atau dapat melihat melalui ilusi, seperti pada penglihatan nyata." },
      { name: "Darkness", components: "V, M", desc: "Kegelapan magis menyebar dari titik yang Anda pilih dalam jangkauan hingga memenuhi bola dengan radius 15 kaki selama durasi tersebut. Kegelapan menyebar ke segala penjuru. Makhluk dengan penglihatan gelap tidak dapat melihat menembus kegelapan ini, dan cahaya non-magis tidak dapat meneranginya.\nJika titik yang Anda pilih ada pada benda yang Anda pegang atau benda yang tidak dipakai atau dibawa, kegelapan akan memancar dari benda tersebut dan bergerak bersamanya. Menutupi seluruh sumber kegelapan dengan benda buram, seperti mangkuk atau helm, akan menghalangi kegelapan.\nJika salah satu area mantra ini tumpang tindih dengan area cahaya yang diciptakan oleh mantra level 2 atau lebih rendah, mantra yang menciptakan cahaya tersebut akan hilang." },
      { name: "Darkvision", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia memberinya kemampuan melihat dalam kegelapan. Selama durasinya, makhluk itu memiliki penglihatan gelap hingga jarak 60 kaki." },
      { name: "Detect Thoughts", components: "V, S, M", desc: "Selama itu, Anda bisa membaca pikiran makhluk tertentu. Saat Anda merapal mantra dan melakukan tindakan di setiap belokan hingga mantra berakhir, Anda dapat memfokuskan pikiran Anda pada satu makhluk yang dapat Anda lihat dalam jarak 30 kaki dari Anda. Jika makhluk yang Anda pilih memiliki Kecerdasan 3 atau lebih rendah atau tidak dapat berbicara bahasa apa pun, makhluk tersebut tidak terpengaruh.\nAwalnya Anda mempelajari pemikiran permukaan makhluk itu - apa yang paling ada dalam pikirannya pada saat itu. Sebagai suatu tindakan, Anda dapat mengalihkan perhatian Anda ke pikiran makhluk lain atau mencoba menyelidiki lebih dalam pikiran makhluk yang sama. Jika Anda menyelidiki lebih dalam, target harus melakukan lemparan penyelamatan Kebijaksanaan. Jika gagal, Anda mendapatkan wawasan tentang alasannya (jika ada), keadaan emosinya, dan sesuatu yang terlintas dalam pikirannya (seperti sesuatu yang dikhawatirkan, disukai, atau dibencinya). Jika berhasil maka mantranya berakhir. Apa pun yang terjadi, target tahu bahwa Anda sedang menyelidiki pikirannya, dan kecuali Anda mengalihkan perhatian Anda ke pikiran makhluk lain, makhluk itu dapat menggunakan tindakannya pada gilirannya untuk melakukan pemeriksaan Intelijen yang ditentang oleh pemeriksaan Intelijen Anda; jika berhasil, mantranya berakhir.\nPertanyaan yang ditujukan secara verbal pada makhluk target secara alami membentuk alur pemikirannya, jadi mantra ini sangat efektif sebagai bagian dari interogasi.\nAnda juga dapat menggunakan mantra ini untuk mendeteksi keberadaan makhluk berpikir yang tidak dapat Anda lihat. Saat Anda mengucapkan mantra atau sebagai tindakan Anda selama durasi tersebut, Anda dapat mencari pikiran dalam jarak 30 kaki dari Anda. Mantranya dapat menembus penghalang, tetapi batu setinggi 2 kaki, logam apa pun setinggi 2 inci selain timah, atau lembaran timah tipis menghalangi Anda. Anda tidak dapat mendeteksi makhluk dengan Kecerdasan 3 atau lebih rendah atau makhluk yang tidak bisa berbicara bahasa apa pun.\nSetelah Anda mendeteksi keberadaan suatu makhluk dengan cara ini, Anda dapat membaca pikirannya selama sisa durasi seperti yang dijelaskan di atas, meskipun Anda tidak dapat melihatnya, tetapi ia harus tetap berada dalam jangkauan." },
      { name: "Enhance Ability", components: "V, S, M", desc: "Anda menyentuh makhluk dan memberinya peningkatan ajaib. Pilih salah satu dari efek berikut; target mendapatkan efek itu hingga mantranya berakhir.\n***Daya Tahan Beruang.*** Targetnya memiliki keunggulan dalam pemeriksaan konstitusi. Ia juga mendapatkan 2d6 poin hit sementara, yang hilang saat mantranya berakhir.\n***Kekuatan Banteng.*** Target memiliki keunggulan dalam pemeriksaan kekuatan, dan daya dukungnya berlipat ganda.\n***Rahmat Kucing.*** Target memiliki keunggulan dalam pemeriksaan ketangkasan. Ia juga tidak menerima kerusakan jika terjatuh dari ketinggian 20 kaki atau kurang jika tidak dilumpuhkan.\n***Kemegahan Elang.*** Target memiliki keunggulan dalam pemeriksaan Karisma.\n***Kelicikan Rubah.*** Targetnya memiliki keunggulan dalam pemeriksaan intelijen.\n***Kebijaksanaan Burung Hantu.*** Target memiliki keuntungan dalam pemeriksaan kebijaksanaan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Enlarge/Reduce", components: "V, S, M", desc: "Anda menyebabkan makhluk atau objek yang dapat Anda lihat dalam jangkauan menjadi lebih besar atau lebih kecil selama durasi tersebut. Pilihlah makhluk atau benda yang tidak dipakai atau dibawa. Jika targetnya tidak mau, maka bisa melakukan penyelamatan Konstitusi. Jika berhasil, mantranya tidak berpengaruh.\nJika targetnya adalah makhluk, segala sesuatu yang dikenakan dan dibawanya akan berubah ukurannya. Benda apa pun yang dijatuhkan oleh makhluk yang terkena dampak akan segera kembali ke ukuran normal.\n***Perbesar.*** Ukuran target menjadi dua kali lipat di semua dimensi, dan beratnya dikalikan delapan. Pertumbuhan ini meningkatkan ukurannya sebanyak satu kategori—dari Sedang ke Besar, misalnya. Jika tidak ada cukup ruang bagi target untuk menggandakan ukurannya, makhluk atau objek tersebut akan mencapai ukuran maksimum yang mungkin dalam ruang yang tersedia. Hingga mantranya berakhir, target juga memiliki keuntungan dalam pemeriksaan Kekuatan dan lemparan hemat Kekuatan. Senjata target juga bertambah untuk menyesuaikan dengan ukuran barunya. Saat senjata ini diperbesar, serangan target dengan senjata tersebut menghasilkan 1d4 kerusakan ekstra.\n***Kurangi.*** Ukuran target dibelah dua di semua dimensi, dan beratnya dikurangi menjadi seperdelapan dari ukuran normal. Pengurangan ini mengurangi ukurannya sebanyak satu kategori—dari Sedang ke Kecil, misalnya. Hingga mantranya berakhir, target juga mempunyai kelemahan pada pemeriksaan Kekuatan dan lemparan penghematan Kekuatan. Senjata target juga menyusut agar sesuai dengan ukuran barunya. Saat senjata ini dikurangi, serangan target dengan senjata tersebut menghasilkan kerusakan 1d4 lebih sedikit (ini tidak dapat mengurangi kerusakan di bawah 1)." },
      { name: "Gust of Wind", components: "V, S, M", desc: "Garis angin kencang sepanjang 60 kaki dan lebar 10 kaki bertiup dari Anda ke arah yang Anda pilih selama durasi mantra. Setiap makhluk yang memulai gilirannya di garis harus berhasil melakukan lemparan hemat kekuatan atau didorong sejauh 15 kaki dari Anda ke arah yang mengikuti garis.\nMakhluk apa pun yang berada dalam barisan harus menghabiskan 2 kaki gerakan untuk setiap 1 kaki yang bergerak saat bergerak mendekati Anda.\nHembusan angin menyebarkan gas atau uap, dan memadamkan lilin, obor, dan nyala api serupa yang tidak terlindungi di area tersebut. Hal ini menyebabkan api yang terlindung, seperti api lentera, menari dengan liar dan memiliki peluang 50 persen untuk memadamkannya.\nSebagai tindakan bonus di setiap giliran Anda sebelum mantra berakhir, Anda dapat mengubah arah ledakan garis dari Anda." },
      { name: "Hold Person", components: "V, S, M", desc: "Pilih humanoid yang dapat Anda lihat dalam jangkauan. Target harus berhasil melakukan penyelamatan kebijaksanaan atau menjadi lumpuh selama jangka waktu tersebut. Di akhir setiap giliran, target dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, mantranya berakhir tepat sasaran.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu humanoid tambahan untuk setiap slot level di atas 2. Humanoid harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkannya." },
      { name: "Invisibility", components: "V, S, M", desc: "Makhluk yang Anda sentuh menjadi tidak terlihat sampai mantranya berakhir. Apapun yang dikenakan atau dibawa oleh target tidak akan terlihat selama berada pada orang yang menjadi target. Mantra berakhir untuk target yang menyerang atau mengeluarkan mantra.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Knock", components: "V", desc: "Pilih objek yang dapat Anda lihat dalam jangkauan. Benda tersebut dapat berupa pintu, kotak, peti, satu set borgol, gembok, atau benda lain yang mengandung sarana duniawi atau magis yang menghalangi akses.\nTarget yang ditahan dengan kunci biasa atau yang tertahan atau terpalang akan menjadi tidak terkunci, tidak tertahan, atau tidak tertahan. Jika objek memiliki beberapa kunci, hanya satu yang terbuka.\nJika Anda memilih target yang ditutup dengan kunci misterius, mantra itu akan ditekan selama 10 menit, selama waktu tersebut target dapat dibuka dan ditutup secara normal.\nSaat Anda mengucapkan mantranya, ketukan keras, terdengar dari jarak 300 kaki, berasal dari objek target." },
      { name: "Levitate", components: "V, S, M", desc: "Satu makhluk atau objek pilihan Anda yang dapat Anda lihat dalam jangkauannya naik secara vertikal, hingga 20 kaki, dan tetap tergantung di sana selama jangka waktu tersebut. Mantra tersebut dapat mengangkat target yang beratnya mencapai 500 pon. Makhluk yang enggan berhasil melakukan penyelamatan konstitusi tidak akan terpengaruh.\nTarget dapat bergerak hanya dengan mendorong atau menarik benda atau permukaan tertentu yang berada dalam jangkauannya (seperti dinding atau langit-langit), yang memungkinkannya bergerak seolah-olah sedang memanjat. Anda dapat mengubah ketinggian target hingga 20 kaki di kedua arah pada giliran Anda. Jika Anda adalah targetnya, Anda dapat bergerak ke atas atau ke bawah sebagai bagian dari gerakan Anda. Jika tidak, Anda dapat menggunakan tindakan Anda untuk memindahkan target, yang harus tetap berada dalam jangkauan mantra.\nSaat mantranya berakhir, target akan melayang perlahan ke tanah jika masih tinggi." },
      { name: "Mirror Image", components: "V, S", desc: "Tiga duplikat ilusi diri Anda muncul di ruang Anda. Hingga mantranya berakhir, duplikatnya akan bergerak bersama Anda dan meniru tindakan Anda, berpindah posisi sehingga tidak mungkin melacak gambar mana yang asli. Anda dapat menggunakan tindakan Anda untuk menghilangkan duplikat ilusi.\nSetiap kali makhluk menargetkan Anda dengan serangan selama durasi mantra, putar d20 untuk menentukan apakah serangan tersebut menargetkan salah satu duplikat Anda.\nJika Anda memiliki tiga duplikat, Anda harus mendapatkan angka 6 atau lebih tinggi untuk mengubah target serangan menjadi duplikat. Dengan dua duplikat, Anda harus mendapatkan angka 8 atau lebih tinggi. Dengan satu duplikat, Anda harus mendapatkan angka 11 atau lebih tinggi.\nAC duplikat sama dengan 10 + pengubah Dexterity Anda. Jika serangan mengenai duplikat, duplikat tersebut akan hancur. Sebuah duplikat hanya dapat dihancurkan dengan serangan yang mengenainya. Itu mengabaikan semua kerusakan dan efek lainnya. Mantra berakhir ketika ketiga duplikatnya dihancurkan.\nMakhluk tidak terpengaruh oleh mantra ini jika ia tidak dapat melihat, jika ia mengandalkan indera selain penglihatan, seperti penglihatan buta, atau jika ia dapat melihat ilusi sebagai sesuatu yang salah, seperti penglihatan yang sebenarnya." },
      { name: "Misty Step", components: "V", desc: "Dikelilingi sebentar oleh kabut keperakan, Anda berteleportasi hingga 30 kaki ke ruang kosong yang dapat Anda lihat." },
      { name: "Scorching Ray", components: "V, S", desc: "Anda membuat tiga sinar api dan melemparkannya ke sasaran dalam jangkauan. Anda dapat melemparkannya ke satu atau beberapa sasaran.\nBuat serangan mantra jarak jauh untuk setiap sinar. Saat terkena, target menerima kerusakan api 2d6.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda membuat satu sinar tambahan untuk setiap slot level di atas 2." },
      { name: "See Invisibility", components: "V, S, M", desc: "Selama durasi mantra, Anda melihat makhluk dan objek tak terlihat seolah-olah terlihat, dan Anda dapat melihat melalui Ethereal. Benda dan makhluk halus tampak tembus cahaya." },
      { name: "Shatter", components: "V, S, M", desc: "Suara dering keras yang tiba-tiba, sangat intens, muncul dari titik pilihan Anda dalam jangkauan. Setiap makhluk dalam bola berradius 10 kaki yang berpusat pada titik tersebut harus melakukan penyelamatan Konstitusi. Makhluk menerima kerusakan guntur 3d8 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil. Makhluk yang terbuat dari bahan anorganik seperti batu, kristal, atau logam memiliki kelemahan dalam penyelamatan ini.\nBenda non-magis yang tidak dipakai atau dibawa juga akan mengalami kerusakan jika berada dalam area mantra.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan mantra meningkat sebesar 1d8 untuk setiap level slot mantra 2 yang lebih tinggi." },
      { name: "Spider Climb", components: "V, S, M", desc: "Hingga mantranya berakhir, satu makhluk yang Anda sentuh memperoleh kemampuan untuk bergerak ke atas, ke bawah, dan melintasi permukaan vertikal dan terbalik di sepanjang langit-langit, sambil membiarkan tangannya bebas. Target juga memperoleh kecepatan pendakian yang sama dengan kecepatan berjalannya." },
      { name: "Suggestion", components: "V, M", desc: "Anda menyarankan suatu rangkaian aktivitas (terbatas pada satu atau dua kalimat) dan secara ajaib memengaruhi makhluk yang dapat Anda lihat dalam jangkauan yang dapat mendengar dan memahami Anda. Makhluk yang tidak bisa dipesona akan kebal terhadap efek ini. Saran tersebut harus diungkapkan sedemikian rupa agar tindakan yang diambil terdengar masuk akal. Meminta makhluk itu untuk menusuk dirinya sendiri, melemparkan dirinya ke tombak, mengorbankan dirinya sendiri, atau melakukan tindakan berbahaya lainnya akan mengakhiri mantranya.\nTargetnya harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, ia akan melakukan tindakan yang Anda jelaskan dengan kemampuan terbaiknya. Tindakan yang disarankan dapat berlanjut sepanjang durasi. Jika aktivitas yang disarankan dapat diselesaikan dalam waktu yang lebih singkat, mantra akan berakhir saat subjek menyelesaikan apa yang diminta.\nAnda juga dapat menentukan kondisi yang akan memicu aktivitas khusus selama durasi tersebut. Misalnya, Anda mungkin menyarankan agar seorang kesatria memberikan kuda perangnya kepada pengemis pertama yang ditemuinya. Jika kondisi tidak terpenuhi sebelum mantra berakhir, aktivitas tidak akan dilakukan.\nJika Anda atau salah satu teman Anda merusak target, mantranya akan berakhir." },
      { name: "Web", components: "V, S, M", desc: "Anda membayangkan sekumpulan anyaman yang tebal dan lengket pada titik pilihan Anda dalam jangkauan. Jaring tersebut mengisi kubus berukuran 20 kaki dari titik tersebut selama durasi tersebut. Jaringnya merupakan medan yang sulit dan sedikit mengaburkan areanya.\nJika jaring tidak tertambat di antara dua benda padat (seperti dinding atau pohon) atau berlapis di lantai, dinding, atau langit-langit, jaring yang dibuat akan runtuh dengan sendirinya, dan mantra berakhir di awal giliran Anda berikutnya. Jaring yang berlapis di atas permukaan datar memiliki kedalaman 5 kaki.\nSetiap makhluk yang memulai gilirannya di jaring atau memasukinya pada gilirannya harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk tersebut akan ditahan selama ia masih berada di dalam jaring atau hingga ia terlepas.\nMakhluk yang tertahan oleh jaring dapat menggunakan aksinya untuk melakukan pemeriksaan Kekuatan terhadap mantra penyimpanan DC Anda. Jika berhasil, tidak lagi tertahan.\nJaringnya mudah terbakar. Jaring berbentuk kubus berukuran 5 kaki yang terkena api akan terbakar habis dalam 1 putaran, menimbulkan kerusakan akibat api sebesar 2d4 pada makhluk apa pun yang memulai gilirannya dalam api." },
    ],
    Level3: [
      { name: "Blink", components: "V, S", desc: "Gulung d20 di akhir setiap giliran Anda selama durasi mantra. Pada gulungan 11 atau lebih tinggi, Anda menghilang dari alam keberadaan Anda saat ini dan muncul di Alam Ethereal (mantranya gagal dan castingnya sia-sia jika Anda sudah berada di alam itu). Di awal giliran berikutnya, dan saat mantra berakhir jika Anda berada di Pesawat Ethereal, Anda kembali ke ruang kosong pilihan Anda yang dapat Anda lihat dalam jarak 10 kaki dari ruang tempat Anda menghilang. Jika tidak ada ruang kosong yang tersedia dalam rentang tersebut, Anda akan muncul di ruang kosong terdekat (dipilih secara acak jika ada lebih dari satu ruang yang jaraknya sama). Anda dapat mengabaikan mantra ini sebagai suatu tindakan.\nSaat berada di Pesawat Ethereal, Anda dapat melihat dan mendengar pesawat asal Anda, yang berwarna abu-abu, dan Anda tidak dapat melihat apa pun di sana lebih dari 60 kaki jauhnya. Anda hanya dapat mempengaruhi dan dipengaruhi oleh makhluk lain di Alam Ethereal. Makhluk yang tidak ada di sana tidak dapat melihat atau berinteraksi dengan Anda, kecuali mereka memiliki kemampuan untuk melakukannya." },
      { name: "Clairvoyance", components: "V, S, M", desc: "Anda membuat sensor tak kasat mata dalam jangkauan di lokasi yang familier bagi Anda (tempat yang pernah Anda kunjungi atau lihat sebelumnya) atau di lokasi jelas yang asing bagi Anda (seperti di balik pintu, di sudut, atau di rerimbunan pepohonan). Sensor tetap di tempatnya selama durasi tersebut, dan tidak dapat diserang atau berinteraksi dengannya.\nSaat Anda merapal mantra, Anda memilih melihat atau mendengar. Anda dapat menggunakan indra yang dipilih melalui sensor seolah-olah Anda berada di ruangnya. Saat tindakan Anda, Anda dapat beralih antara melihat dan mendengar.\nMakhluk yang dapat melihat sensor (seperti makhluk yang mendapat manfaat dari melihat tembus pandang atau penglihatan nyata) melihat bola bercahaya dan tidak berwujud seukuran kepalan tangan Anda." },
      { name: "Counterspell", components: "S", desc: "Anda mencoba mengganggu makhluk dalam proses merapal mantra. Jika makhluk tersebut mengeluarkan mantra level 3 atau lebih rendah, mantranya gagal dan tidak berpengaruh. Jika ia mengeluarkan mantra level 4 atau lebih tinggi, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika berhasil, mantra makhluk itu gagal dan tidak berpengaruh.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, mantra yang terputus tidak akan berpengaruh jika levelnya kurang dari atau sama dengan level slot mantra yang Anda gunakan." },
      { name: "Daylight", components: "V, S", desc: "Bola cahaya dengan radius 60 kaki menyebar dari titik yang Anda pilih dalam jangkauannya. Bola tersebut memiliki cahaya terang dan memancarkan cahaya redup sejauh 60 kaki.\nJika Anda memilih suatu titik pada suatu benda yang Anda pegang atau yang tidak sedang dipakai atau dibawa, cahaya akan bersinar dari benda tersebut dan bergerak bersamanya. Menutupi seluruh objek yang terkena dengan benda buram, seperti mangkuk atau helm, akan menghalangi cahaya.\nJika salah satu area mantra ini tumpang tindih dengan area kegelapan yang diciptakan oleh mantra level 3 atau lebih rendah, mantra yang menciptakan kegelapan tersebut akan hilang." },
      { name: "Dispel Magic", components: "V, S", desc: "Pilih satu makhluk, objek, atau efek magis dalam jangkauan. Mantra level 3 atau lebih rendah pada target akan berakhir. Untuk setiap mantra level 4 atau lebih tinggi pada target, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika pemeriksaan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda secara otomatis mengakhiri efek mantra pada target jika level mantra sama dengan atau kurang dari level slot mantra yang Anda gunakan." },
      { name: "Fear", components: "V, S, M", desc: "Anda memproyeksikan gambaran khayalan tentang ketakutan terburuk suatu makhluk. Setiap makhluk dalam kerucut setinggi 30 kaki harus berhasil menyelamatkan lemparan atau menjatuhkan apa pun yang dipegangnya dan menjadi ketakutan selama itu.\nSaat ketakutan dengan mantra ini, makhluk harus mengambil tindakan Dash dan menjauh dari Anda melalui rute teraman yang tersedia di setiap belokannya, kecuali tidak ada tempat untuk bergerak. Jika makhluk tersebut mengakhiri gilirannya di lokasi yang tidak terlihat oleh Anda, makhluk tersebut dapat melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan berhasil, mantra untuk makhluk itu berakhir." },
      { name: "Fireball", components: "V, S, M", desc: "Garis terang memancar dari jari telunjuk Anda ke titik yang Anda pilih dalam jangkauan dan kemudian berkembang dengan suara gemuruh rendah menjadi ledakan api. Setiap makhluk dalam bola berradius 20 kaki yang berpusat pada titik tersebut harus melakukan lemparan penyelamatan ketangkasan. Target menerima kerusakan api sebesar 8d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil.\nApi menyebar ke berbagai sudut. Ini menyulut benda-benda yang mudah terbakar di area yang tidak dipakai atau dibawa.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 3." },
      { name: "Fly", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia. Target memperoleh kecepatan terbang 60 kaki selama durasi tersebut. Saat mantranya berakhir, target akan jatuh jika masih tinggi, kecuali jika dapat menghentikan jatuhnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 3." },
      { name: "Gaseous Form", components: "V, S, M", desc: "Anda mengubah makhluk yang Anda sentuh, beserta segala sesuatu yang dikenakan dan dibawanya, menjadi awan berkabut selama itu. Mantra berakhir jika poin hit makhluk itu turun menjadi 0. Makhluk inkorporeal tidak terpengaruh.\nSedangkan dalam bentuk ini, satu-satunya cara pergerakan target adalah kecepatan terbang 10 kaki. Targetnya bisa masuk dan menempati ruang makhluk lain. Target memiliki ketahanan terhadap kerusakan non-magis, dan memiliki keunggulan dalam Kekuatan, Ketangkasan, dan lemparan hemat konstitusi. Targetnya dapat melewati lubang kecil, bukaan sempit, dan bahkan retakan belaka, meskipun cairan tersebut diperlakukan seolah-olah permukaan padat. Target tidak bisa jatuh dan tetap melayang di udara bahkan ketika terkena stun atau tidak berdaya.\nSedangkan dalam bentuk awan berkabut, target tidak dapat berbicara atau memanipulasi objek, dan objek apa pun yang dibawa atau dipegangnya tidak dapat dijatuhkan, digunakan, atau berinteraksi dengannya. Target tidak dapat menyerang atau mengeluarkan mantra." },
      { name: "Haste", components: "V, S, M", desc: "Pilih makhluk bersedia yang dapat Anda lihat dalam jangkauan. Hingga mantranya berakhir, kecepatan target menjadi dua kali lipat, ia memperoleh bonus +2 AC, ia memiliki keunggulan dalam lemparan penyelamatan ketangkasan, dan ia memperoleh tindakan tambahan di setiap putarannya. Tindakan tersebut hanya dapat digunakan untuk melakukan tindakan Serangan (satu serangan senjata saja), Dash, Disengage, Hide, atau Use an Object.\nKetika mantranya berakhir, target tidak dapat bergerak atau mengambil tindakan sampai giliran berikutnya, karena gelombang kelesuan melandanya." },
      { name: "Hypnotic Pattern", components: "S, M", desc: "Anda membuat pola warna yang berputar-putar yang terjalin di udara di dalam kubus berukuran 30 kaki dalam jangkauan. Pola itu muncul sesaat dan menghilang. Setiap makhluk di area tersebut yang melihat pola tersebut harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, makhluk itu menjadi terpesona selama durasi tersebut. Saat terpesona oleh mantra ini, makhluk itu tidak berdaya dan memiliki kecepatan 0.\nMantra berakhir untuk makhluk yang terkena dampak jika ia mengalami kerusakan atau jika orang lain menggunakan tindakan untuk mengguncang makhluk itu dari pingsannya." },
      { name: "Lightning Bolt", components: "V, S, M", desc: "Sambaran petir yang membentuk garis sepanjang 100 kaki dan lebar 5 kaki meluncur keluar dari Anda ke arah yang Anda pilih. Setiap makhluk dalam barisan harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan petir sebesar 8d6 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nPetir menyulut benda-benda mudah terbakar di area yang tidak dipakai atau dibawa.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 3." },
      { name: "Major Image", components: "V, S, M", desc: "Anda membuat gambar suatu benda, makhluk, atau fenomena nyata lainnya yang ukurannya tidak lebih besar dari kubus berukuran 20 kaki. Gambar muncul di tempat yang dapat Anda lihat dalam jangkauan dan berlangsung selama durasi tersebut. Tampaknya benar-benar nyata, termasuk suara, bau, dan suhu yang sesuai dengan benda yang digambarkan. Anda tidak dapat menciptakan panas atau dingin yang cukup untuk menyebabkan kerusakan, suara yang cukup keras untuk menyebabkan kerusakan akibat petir atau membuat tuli makhluk, atau bau yang dapat membuat makhluk sakit (seperti bau troglodyte).\nSelama Anda berada dalam jangkauan ilusi, Anda dapat menggunakan tindakan Anda untuk menyebabkan gambar berpindah ke tempat lain dalam jangkauan. Saat gambar berpindah lokasi, Anda dapat mengubah tampilannya sehingga gerakannya tampak natural pada gambar. Misalnya, jika Anda membuat gambar makhluk dan memindahkannya, Anda dapat mengubah gambar tersebut sehingga tampak seperti sedang berjalan. Demikian pula, Anda dapat menyebabkan ilusi mengeluarkan suara yang berbeda pada waktu yang berbeda, bahkan membuatnya melakukan percakapan, misalnya.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika suatu makhluk mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut, dan kualitas indra lainnya menjadi samar bagi makhluk tersebut.\nLevel Tinggi: Saat Anda merapalkan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, mantra tersebut akan bertahan hingga hilang, tanpa memerlukan konsentrasi Anda." },
      { name: "Protection From Energy", components: "V, S", desc: "Selama durasi tersebut, makhluk yang Anda sentuh memiliki ketahanan terhadap satu jenis kerusakan pilihan Anda: asam, dingin, api, kilat, atau guntur." },
      { name: "Sleet Storm", components: "V, S, M", desc: "Hingga mantranya berakhir, hujan beku dan hujan es akan turun dalam silinder setinggi 20 kaki dengan radius 40 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan. Area tersebut sangat tertutup, dan api yang terbuka di area tersebut telah padam.\nTanah di kawasan tersebut tertutup es licin sehingga menyulitkan medan. Saat makhluk memasuki area mantra untuk pertama kalinya pada suatu giliran atau memulai gilirannya di sana, ia harus melakukan lemparan penyelamatan ketangkasan. Pada penyelamatan yang gagal, ia menjadi rawan.\nJika makhluk sedang berkonsentrasi di area mantra, makhluk tersebut harus berhasil melakukan lemparan penyelamatan konstitusi terhadap penyelamatan mantra Anda DC atau kehilangan konsentrasi." },
      { name: "Slow", components: "V, S, M", desc: "Anda mengubah waktu hingga enam makhluk pilihan Anda dalam kubus berukuran 40 kaki dalam jangkauan. Setiap target harus berhasil dalam lemparan penyelamatan kebijaksanaan atau terpengaruh oleh mantra ini selama durasi tersebut.\nKecepatan target yang terpengaruh dikurangi setengahnya, dibutuhkan penalti -2 pada AC dan lemparan penyelamatan ketangkasan, dan tidak dapat menggunakan reaksi. Pada gilirannya, ia dapat menggunakan salah satu tindakan atau tindakan bonus, tidak keduanya. Terlepas dari kemampuan atau item sihir makhluk tersebut, ia tidak dapat melakukan lebih dari satu serangan jarak dekat atau jarak jauh selama gilirannya.\nJika makhluk tersebut mencoba merapal mantra dengan waktu casting 1 tindakan, putar d20. Pada level 11 atau lebih tinggi, mantra tidak akan berpengaruh hingga giliran makhluk berikutnya, dan makhluk tersebut harus menggunakan aksinya pada giliran tersebut untuk menyelesaikan mantranya. Jika tidak bisa, mantranya akan sia-sia.\nMakhluk yang terkena mantra ini melakukan lemparan penyelamatan kebijaksanaan lainnya di akhir gilirannya. Jika penyimpanan berhasil, efeknya akan berakhir." },
      { name: "Stinking Cloud", components: "V, S, M", desc: "Anda membuat bola gas berwarna kuning dengan radius 20 kaki yang berpusat pada suatu titik dalam jangkauan. Awan menyebar ke segala penjuru, dan wilayahnya sangat tertutup. Awan tetap berada di udara selama itu.\nSetiap makhluk yang sepenuhnya berada di dalam awan pada awal gilirannya harus melakukan penyelamatan konstitusi terhadap racun. Jika penyelamatan gagal, makhluk itu mengeluarkan aksinya yang berubah menjadi muntah-muntah dan terhuyung-huyung. Makhluk yang tidak perlu bernapas atau kebal terhadap racun otomatis berhasil dalam penyelamatan ini.\nAngin sedang (setidaknya 10 mil per jam) menyebarkan awan setelah 4 putaran. Angin kencang (setidaknya 20 mil per jam) menyebarkannya setelah 1 putaran." },
      { name: "Tongues", components: "V, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk memahami bahasa lisan apa pun yang didengarnya. Terlebih lagi, ketika target berbicara, makhluk apa pun yang mengetahui setidaknya satu bahasa dan dapat mendengar target akan memahami apa yang dikatakannya." },
      { name: "Water Breathing", components: "V, S, M", desc: "Mantra ini memberikan maksimal sepuluh makhluk yang bersedia berada dalam jangkauannya dan Anda dapat melihat, kemampuan bernapas di bawah air hingga akhir masa berlakunya. Makhluk yang terkena dampak juga mempertahankan pola pernapasan normalnya." },
      { name: "Water Walk", components: "V, S, M", desc: "Mantra ini memberikan kemampuan untuk bergerak melintasi permukaan cair apa pun--seperti air, asam, lumpur, salju, pasir hisap, atau lava--seolah-olah permukaan tersebut adalah tanah padat yang tidak berbahaya (makhluk yang melintasi lava cair masih dapat menerima kerusakan akibat panas). Hingga sepuluh makhluk yang dapat Anda lihat dalam jangkauan mendapatkan kemampuan ini selama durasi tersebut.\nJika Anda menargetkan makhluk yang terendam dalam cairan, mantranya akan membawa target ke permukaan cairan dengan kecepatan 60 kaki per putaran." },
    ],
    Level4: [
      { name: "Banishment", components: "V, S, M", desc: "Anda mencoba mengirim satu makhluk yang dapat Anda lihat dalam jangkauannya ke alam eksistensi lain. Targetnya harus berhasil dalam penyelamatan karisma atau diasingkan.\nJika targetnya berasal dari alam eksistensi yang Anda tempati, Anda membuang target tersebut ke demiplane yang tidak berbahaya. Saat berada di sana, targetnya tidak berdaya. Target tetap di sana sampai mantranya berakhir, pada saat itu target muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi.\nJika target berasal dari alam eksistensi yang berbeda dari tempat Anda berada, target akan dibuang dengan suara letupan samar, dan kembali ke alam asalnya. Jika mantra berakhir sebelum 1 menit berlalu, target akan muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi. Jika tidak, targetnya tidak akan kembali.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 4." },
      { name: "Blight", components: "V, S", desc: "Energi necromantic menyapu makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan, menguras kelembapan dan vitalitas darinya. Targetnya harus melakukan penyelamatan konstitusi. Target menerima 8d8 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nJika Anda menargetkan makhluk tumbuhan atau tumbuhan ajaib, lemparan penyelamatan akan merugikan, dan mantranya akan memberikan kerusakan maksimal padanya.\nJika Anda menargetkan tanaman non-magis yang bukan makhluk, seperti pohon atau semak, hal tersebut tidak akan menjadi solusi penyelamatan; itu hanya layu dan mati.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 ke atas, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas ke-4." },
      { name: "Confusion", components: "V, S, M", desc: "Mantra ini menyerang dan memutarbalikkan pikiran makhluk, menimbulkan delusi dan memicu tindakan yang tidak terkendali. Setiap makhluk dalam bola berradius 10 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan harus berhasil melakukan lemparan penyelamatan Kebijaksanaan saat Anda mengucapkan mantra ini atau terpengaruh olehnya.\nTarget yang terpengaruh tidak dapat bereaksi dan harus melempar d10 di awal setiap giliran untuk menentukan perilakunya pada giliran tersebut.\n| d10 | Perilaku |\n|---|---|\n| 1 | Makhluk itu menggunakan seluruh gerakannya untuk bergerak ke arah yang acak. Untuk menentukan arah, putar d8 dan tetapkan arah pada setiap permukaan dadu. Makhluk itu tidak mengambil tindakan pada giliran ini. |\n| 2-6 | Makhluk itu tidak bergerak atau mengambil tindakan pada giliran ini. |\n| 7-8 | Makhluk itu menggunakan aksinya untuk melakukan serangan jarak dekat terhadap makhluk yang ditentukan secara acak dalam jangkauannya. Jika tidak ada makhluk dalam jangkauannya, makhluk itu tidak akan melakukan apa pun pada giliran ini. |\n| 9-10 | Makhluk itu dapat bertindak dan bergerak dengan normal. |\nDi akhir setiap giliran, target yang terkena dampak dapat melakukan lemparan penyelamatan Wisdom. Jika berhasil, efek ini berakhir untuk target tersebut.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, radius bola bertambah 5 kaki untuk setiap slot level di atas 4." },
      { name: "Dimension Door", components: "V", desc: "Anda berteleportasi dari lokasi Anda saat ini ke tempat lain dalam jangkauan. Anda tiba di tempat yang diinginkan. Ini bisa berupa tempat yang bisa Anda lihat, yang bisa Anda visualisasikan, atau yang bisa Anda gambarkan dengan menyatakan jarak dan arah, seperti \"200 kaki lurus ke bawah\" atau \"ke atas ke arah barat laut dengan sudut 45 derajat, 300 kaki\".\nAnda boleh membawa barang selama beratnya tidak melebihi apa yang dapat Anda bawa. Anda juga dapat membawa satu makhluk berukuran Anda atau lebih kecil yang membawa perlengkapan sesuai daya dukungnya. Makhluk itu harus berada dalam jarak 5 kaki dari Anda saat Anda mengucapkan mantra ini.\nJika Anda akan tiba di tempat yang sudah ditempati oleh suatu benda atau makhluk, Anda dan makhluk apa pun yang bepergian bersama Anda masing-masing akan menerima kerusakan kekuatan 4d6, dan mantra tersebut gagal untuk memindahkan Anda." },
      { name: "Dominate Beast", components: "V, S", desc: "Anda mencoba memperdaya makhluk yang dapat Anda lihat dalam jangkauan. Ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Jika Anda atau makhluk yang bersahabat dengan Anda melawannya, ia memiliki keuntungan dalam penyelamatan.\nMeskipun makhluk itu terpesona, Anda memiliki hubungan telepati dengannya selama Anda berdua berada di alam eksistensi yang sama. Anda dapat menggunakan tautan telepati ini untuk mengeluarkan perintah kepada makhluk itu saat Anda sadar (tidak perlu tindakan apa pun), yang akan dipatuhinya sebaik mungkin. Anda dapat menentukan tindakan yang sederhana dan umum, seperti \"Serang makhluk itu\", \"Lari ke sana\", atau \"Ambil objek itu\". Jika makhluk tersebut menyelesaikan perintahnya dan tidak menerima arahan lebih lanjut dari Anda, ia akan mempertahankan dan mempertahankan dirinya dengan kemampuan terbaiknya.\nAnda dapat menggunakan tindakan Anda untuk mengambil kendali total dan tepat terhadap target. Hingga akhir giliran Anda berikutnya, makhluk itu hanya mengambil tindakan yang Anda pilih, dan tidak melakukan apa pun yang tidak Anda izinkan. Selama waktu ini, Anda juga dapat menyebabkan makhluk tersebut menggunakan reaksi, namun hal ini mengharuskan Anda menggunakan reaksi Anda sendiri juga. Setiap kali target menerima kerusakan, ia membuat lemparan penyelamatan kebijaksanaan baru terhadap mantra tersebut. Jika lemparan penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini dengan slot mantra level 9, durasinya adalah konsentrasi, hingga 8 jam." },
      { name: "Greater Invisibility", components: "V, S", desc: "Anda atau makhluk yang Anda sentuh menjadi tidak terlihat sampai mantranya berakhir. Apapun yang dikenakan atau dibawa oleh target tidak akan terlihat selama berada pada orang yang menjadi target." },
      { name: "Ice Storm", components: "V, S, M", desc: "Hujan es sekeras batu menghantam tanah dalam silinder dengan radius 20 kaki dan tinggi 40 kaki yang berpusat pada suatu titik dalam jangkauan. Setiap makhluk di dalam silinder harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima 2d8 kerusakan pukulan dan 4d6 kerusakan dingin pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nHujan es mengubah area pengaruh badai menjadi medan yang sulit hingga akhir giliran Anda berikutnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, kerusakan pukulan meningkat sebesar 1d8 untuk setiap level slot di atas 4." },
      { name: "Polymorph", components: "V, S, M", desc: "Mantra ini mengubah makhluk yang dapat Anda lihat dalam jangkauan menjadi bentuk baru. Makhluk yang tidak mau harus melakukan lemparan penyelamatan yang bijaksana untuk menghindari dampaknya. Seorang pengubah bentuk secara otomatis berhasil dalam lemparan penyelamatan ini.\nTransformasi berlangsung selama durasi tersebut, atau hingga target turun menjadi 0 poin hit atau mati. Bentuk baru dapat berupa monster apa pun yang peringkat tantangannya sama dengan atau lebih kecil dari target (atau level target, jika tidak memiliki peringkat tantangan). Statistik permainan target, termasuk skor kemampuan mental, digantikan oleh statistik binatang yang dipilih. Ia mempertahankan keselarasan dan kepribadiannya.\nTargetnya mengasumsikan titik sasaran dari bentuk barunya. Ketika ia kembali ke bentuk normalnya, makhluk itu kembali ke jumlah titik serangan yang dimilikinya sebelum ia bertransformasi. Jika poin serangannya kembali karena poin hitnya turun menjadi 0, kerusakan berlebih akan kembali ke bentuk normalnya. Selama kerusakan berlebih tidak mengurangi bentuk normal makhluk itu menjadi 0 poin serangan, ia tidak akan pingsan.\nTindakan yang dapat dilakukan makhluk ini terbatas karena sifat dari bentuk barunya, dan ia tidak dapat berbicara, merapal mantra, atau melakukan tindakan lain apa pun yang memerlukan tangan atau ucapan.\nPerlengkapan target menyatu ke dalam bentuk baru. Makhluk itu tidak dapat mengaktifkan, menggunakan, menggunakan, atau memanfaatkan peralatan apa pun." },
      { name: "Stoneskin", components: "V, S, M", desc: "Mantra ini mengubah daging makhluk yang Anda sentuh menjadi sekeras batu. Hingga mantranya berakhir, target memiliki ketahanan terhadap pukulan non-magis, tusukan, dan tebasan." },
      { name: "Wall of Fire", components: "V, S, M", desc: "Anda membuat dinding api pada permukaan padat dalam jangkauan. Anda dapat membuat tembok dengan panjang hingga 60 kaki, tinggi 20 kaki, dan tebal 1 kaki, atau dinding melingkar dengan diameter hingga 20 kaki, tinggi 20 kaki, dan tebal 1 kaki. Dindingnya buram dan tahan lama.\nSaat tembok muncul, setiap makhluk di dalam areanya harus melakukan lemparan penyelamatan Dexterity. Jika penyelamatan gagal, makhluk akan menerima kerusakan api sebesar 5d8, atau setengah kerusakan jika penyelamatan berhasil.\nSatu sisi dinding, yang Anda pilih saat mengucapkan mantra ini, menimbulkan kerusakan api 5d8 pada setiap makhluk yang mengakhiri gilirannya dalam jarak 10 kaki dari sisi itu atau di dalam dinding. Makhluk menerima kerusakan yang sama saat memasuki dinding untuk pertama kalinya pada suatu belokan atau mengakhiri belokannya di sana. Sisi lain tembok tidak menimbulkan kerusakan.\nSisi lain tembok tidak menimbulkan kerusakan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 4." },
    ],
    Level5: [
      { name: "Animate Objects", components: "V, S", desc: "Objek menjadi hidup sesuai perintah Anda. Pilih hingga sepuluh benda non-magis dalam jangkauan yang tidak dipakai atau dibawa. Target sedang dihitung sebagai dua objek, Target besar dihitung sebagai empat objek, Target besar dihitung sebagai delapan objek. Anda tidak dapat menganimasikan objek apa pun yang lebih besar dari Huge. Setiap target bernyawa dan menjadi makhluk di bawah kendali Anda hingga mantra berakhir atau hingga poin hit berkurang menjadi 0.\nSebagai tindakan bonus, Anda dapat secara mental memerintahkan makhluk apa pun yang Anda buat dengan mantra ini jika makhluk itu berada dalam jarak 500 kaki dari Anda (jika Anda mengendalikan beberapa makhluk, Anda dapat memerintahkan salah satu atau semuanya secara bersamaan, memberikan perintah yang sama kepada masing-masing makhluk). Anda memutuskan tindakan apa yang akan diambil makhluk itu dan ke mana ia akan bergerak pada giliran berikutnya, atau Anda dapat mengeluarkan perintah umum, seperti menjaga ruangan atau koridor tertentu. Jika Anda tidak mengeluarkan perintah, makhluk itu hanya akan mempertahankan diri dari makhluk musuh. Setelah diberi perintah, makhluk tersebut terus mengikutinya hingga tugasnya selesai.\n##### Statistik Objek Animasi\n| Ukuran | HP | AC | Serangan | Str | Dex |\n|---|---|---|---|---|---|\n| Kecil | 20 | 18 | +8 untuk menyerang, 1d4 + 4 kerusakan | 4 | 18 |\n| Kecil | 25 | 16 | +6 untuk menyerang, 1d8 + 2 kerusakan | 6 | 14 |\n| Sedang | 40 | 13 | +5 untuk menyerang, 2d6 + 1 kerusakan | 10 | 12 |\n| Besar | 50 | 10 | +6 untuk menyerang, 2d10 + 2 kerusakan | 14 | 10 |\n| Besar | 80 | 10 | +8 untuk menyerang, 2d12 + 4 kerusakan | 18 | 6 |\nObjek animasi adalah konstruksi dengan AC, titik pukulan, serangan, Kekuatan, dan Ketangkasan yang ditentukan oleh ukurannya. Konstitusinya 10 dan Kecerdasan dan Kebijaksanaannya 3, dan Karismanya 1. Kecepatannya 30 kaki; jika benda tersebut tidak memiliki kaki atau pelengkap lain yang dapat digunakan untuk bergerak, ia malah memiliki kecepatan terbang 30 kaki dan dapat melayang. Jika benda tersebut terpasang erat pada suatu permukaan atau benda yang lebih besar, seperti rantai yang dibaut ke dinding, kecepatannya adalah 0. Benda tersebut mempunyai penglihatan buta dengan radius 30 kaki dan buta melebihi jarak tersebut. Ketika objek yang dianimasikan turun ke 0 titik hit, ia kembali ke bentuk objek aslinya, dan sisa kerusakan akan dibawa ke bentuk objek aslinya.\nJika Anda memerintahkan suatu objek untuk menyerang, ia dapat melakukan satu serangan jarak dekat terhadap makhluk dalam jarak 5 kaki darinya. Itu membuat serangan bantingan dengan bonus serangan dan kerusakan pukulan yang ditentukan oleh ukurannya. GM mungkin memutuskan bahwa objek tertentu menimbulkan kerusakan tebasan atau tusukan berdasarkan bentuknya.\nJika Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, Anda dapat menganimasikan dua objek tambahan untuk setiap slot level di atas 5." },
      { name: "Cloudkill", components: "V, S", desc: "Anda membuat bola kabut kuning-hijau beracun dengan radius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan. Kabut menyebar ke segala penjuru. Itu berlangsung selama atau sampai angin kencang membubarkan kabut, mengakhiri mantranya. Wilayahnya sangat tertutup.\nSaat makhluk memasuki area mantra untuk pertama kalinya pada suatu giliran atau memulai gilirannya di sana, makhluk tersebut harus melakukan lemparan penyelamatan konstitusi. Makhluk itu menerima kerusakan racun 5d8 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Makhluk akan terpengaruh meskipun mereka menahan napas atau tidak perlu bernapas.\nKabut bergerak sejauh 10 kaki dari Anda pada awal setiap belokan, bergulung di sepanjang permukaan tanah. Uapnya, karena lebih berat daripada udara, tenggelam ke permukaan tanah yang paling rendah, bahkan mengalir ke lubang-lubang.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 5." },
      { name: "Cone of Cold", components: "V, S, M", desc: "Semburan udara dingin keluar dari tangan Anda. Setiap makhluk dalam kerucut setinggi 60 kaki harus melakukan penyelamatan konstitusi. Makhluk menerima kerusakan dingin sebesar 8d8 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nMakhluk yang terbunuh oleh mantra ini menjadi patung beku hingga mencair.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 5." },
      { name: "Creation", components: "V, S, M", desc: "Anda menarik gumpalan material bayangan dari Shadowfell untuk membuat objek benda nabati tak hidup dalam jangkauan: barang lunak, tali, kayu, atau yang serupa. Anda juga bisa menggunakan mantra ini untuk membuat benda mineral seperti batu, kristal, atau logam. Benda yang dibuat tidak boleh lebih besar dari kubus berukuran 5 kaki, dan benda tersebut harus dari bentuk dan bahan yang pernah Anda lihat sebelumnya.\nDurasinya tergantung bahan bendanya. Jika objek terdiri dari beberapa bahan, gunakan durasi yang paling singkat.\n| Bahan | Durasi |\n|---|---|\n| Materi sayur | 1 hari |\n| Batu atau kristal | 12 jam |\n| Logam mulia | 1 jam |\n| Permata | 10 menit |\n| Adamantine atau mitral | 1 menit |\nMenggunakan material apa pun yang dibuat oleh mantra ini sebagai komponen material mantra lain menyebabkan mantra tersebut gagal.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kubus bertambah 5 kaki untuk setiap slot level di atas 5." },
      { name: "Dominate Person", components: "V, S", desc: "Anda mencoba memperdaya humanoid yang dapat Anda lihat dalam jangkauan. Ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Jika Anda atau makhluk yang bersahabat dengan Anda melawannya, ia memiliki keuntungan dalam penyelamatan.\nMeskipun targetnya terpesona, Anda memiliki hubungan telepati dengannya selama Anda berdua berada di alam eksistensi yang sama. Anda dapat menggunakan tautan telepati ini untuk mengeluarkan perintah kepada makhluk itu saat Anda sadar (tidak perlu tindakan apa pun), yang akan dipatuhinya sebaik mungkin. Anda dapat menentukan tindakan yang sederhana dan umum, seperti \"Serang makhluk itu\", \"Lari ke sana\", atau \"Ambil objek itu\". Jika makhluk tersebut menyelesaikan perintahnya dan tidak menerima arahan lebih lanjut dari Anda, ia akan mempertahankan dan mempertahankan dirinya dengan kemampuan terbaiknya.\nAnda dapat menggunakan tindakan Anda untuk mengambil kendali total dan tepat terhadap target. Hingga akhir giliran Anda berikutnya, makhluk itu hanya mengambil tindakan yang Anda pilih, dan tidak melakukan apa pun yang tidak Anda izinkan. Selama waktu ini Anda juga dapat menyebabkan makhluk tersebut menggunakan reaksi, namun hal ini mengharuskan Anda menggunakan reaksi Anda sendiri juga.\nSetiap kali target menerima kerusakan, ia membuat lemparan penyelamatan kebijaksanaan baru terhadap mantra tersebut. Jika lemparan penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 6, durasinya adalah konsentrasi, hingga 10 menit. Jika menggunakan slot spell level 7, durasinya adalah konsentrasi, maksimal 1 jam. Saat Anda menggunakan slot mantra level 8 atau lebih tinggi, durasinya adalah konsentrasi, hingga 8 jam." },
      { name: "Hold Monster", components: "V, S, M", desc: "Pilih makhluk yang dapat Anda lihat dan jangkau. Target harus melakukan lemparan penyelamatan Kebijaksanaan atau menjadi lumpuh selama durasi mantra. Mantra ini tidak berpengaruh terhadap undead. Di akhir setiap putaran, target dapat melakukan penyelamatan baru atas Kebijaksanaan. Jika berhasil, mantranya berakhir untuk makhluk itu.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan lokasi level 6 atau lebih tinggi, Anda dapat menargetkan makhluk tambahan untuk setiap level lokasi di luar lokasi kelima. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Insect Plague", components: "V, S, M", desc: "Belalang yang berkerumun dan menggigit memenuhi bola dengan radius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauannya. Bola itu menyebar ke berbagai sudut. Bola tersebut tetap ada selama durasi tersebut, dan areanya sedikit tertutup. Area bola tersebut merupakan medan yang sulit.\nKetika area tersebut muncul, setiap makhluk di dalamnya harus melakukan penyelamatan konstitusi. Makhluk menerima kerusakan menusuk 4d10 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil. Makhluk juga harus melakukan lemparan penyelamatan ini ketika memasuki area mantra untuk pertama kalinya pada suatu giliran atau mengakhiri gilirannya di sana.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kerusakan meningkat sebesar 1d10 untuk setiap slot level di atas 5." },
      { name: "Seeming", components: "V, S", desc: "Mantra ini memungkinkan Anda mengubah penampilan sejumlah makhluk yang dapat Anda lihat dalam jangkauan. Anda memberikan setiap target yang Anda pilih penampilan baru dan ilusi. Target yang tidak bersedia dapat melakukan lemparan penyelamatan karisma, dan jika berhasil, ia tidak terpengaruh oleh mantra ini.\nMantra ini menyamarkan penampilan fisik serta pakaian, baju besi, senjata, dan perlengkapan. Anda dapat membuat setiap makhluk tampak 1 kaki lebih pendek atau lebih tinggi dan tampak kurus, gemuk, atau di antara keduanya. Anda tidak dapat mengubah tipe tubuh target, jadi Anda harus memilih bentuk yang memiliki susunan dasar anggota tubuh yang sama. Jika tidak, sejauh mana ilusi itu terserah Anda. Mantra tersebut bertahan selama durasi tersebut, kecuali Anda menggunakan tindakan Anda untuk menghilangkannya lebih cepat.\nPerubahan yang dilakukan oleh mantra ini gagal memenuhi pemeriksaan fisik. Misalnya, jika Anda menggunakan mantra ini untuk menambahkan topi ke pakaian makhluk, benda akan melewati topi tersebut, dan siapa pun yang menyentuhnya tidak akan merasakan apa pun atau akan merasakan kepala dan rambut makhluk tersebut. Jika Anda menggunakan mantra ini untuk terlihat lebih kurus dari Anda, tangan seseorang yang mengulurkan tangan untuk menyentuh Anda akan menabrak Anda saat tangan itu tampak masih di udara.\nMakhluk dapat menggunakan aksinya untuk memeriksa target dan melakukan pemeriksaan Intelijen (Investigasi) terhadap mantra penyelamatan DC Anda. Jika berhasil, ia akan menyadari bahwa targetnya sedang menyamar." },
      { name: "Telekinesis", components: "V, S", desc: "Anda memperoleh kemampuan untuk menggerakkan atau memanipulasi makhluk atau benda dengan pikiran. Saat Anda mengucapkan mantra, dan sebagai tindakan Anda di setiap putaran selama durasi tersebut, Anda dapat mengerahkan keinginan Anda pada satu makhluk atau objek yang dapat Anda lihat dalam jangkauan, menyebabkan efek yang sesuai di bawah. Anda dapat memengaruhi target yang sama setiap putaran, atau memilih target baru kapan saja. Jika Anda mengganti target, target sebelumnya tidak lagi terpengaruh oleh mantra tersebut.\n***Makhluk.*** Anda dapat mencoba memindahkan makhluk besar atau kecil. Lakukan pemeriksaan kemampuan dengan kemampuan merapal mantra Anda yang diperebutkan oleh pemeriksaan Kekuatan makhluk itu. Jika Anda memenangkan kontes, Anda memindahkan makhluk itu hingga 30 kaki ke segala arah, termasuk ke atas tetapi tidak melampaui jangkauan mantra ini. Hingga akhir giliran Anda berikutnya, makhluk itu tertahan dalam cengkeraman telekinetik Anda. Makhluk yang terangkat ke atas melayang di udara.\nPada ronde berikutnya, Anda dapat menggunakan tindakan Anda untuk mencoba mempertahankan cengkeraman telekinetik Anda pada makhluk tersebut dengan mengulangi kontes tersebut.\n***Objek.*** Anda dapat mencoba memindahkan objek yang beratnya mencapai 1.000 pon. Jika benda tersebut tidak sedang dipakai atau dibawa, Anda secara otomatis memindahkannya hingga 30 kaki ke segala arah, tetapi tidak melampaui jangkauan mantra ini.\nJika benda tersebut dipakai atau dibawa oleh makhluk, Anda harus melakukan pemeriksaan kemampuan dengan kemampuan perapalan mantra Anda yang diperebutkan oleh pemeriksaan Kekuatan makhluk tersebut. Jika berhasil, Anda menarik objek menjauh dari makhluk itu dan dapat memindahkannya hingga 30 kaki ke segala arah tetapi tidak melampaui jangkauan mantra ini.\nAnda dapat melakukan kontrol yang baik pada objek dengan cengkeraman telekinetik Anda, seperti memanipulasi alat sederhana, membuka pintu atau wadah, menyimpan atau mengambil item dari wadah terbuka, atau menuangkan isi dari botol." },
      { name: "Teleportation Circle", components: "V, M", desc: "Saat Anda mengucapkan mantra, Anda menggambar lingkaran berdiameter 10 kaki di tanah bertuliskan sigil yang menghubungkan lokasi Anda ke lingkaran teleportasi permanen pilihan Anda yang urutan sigilnya Anda ketahui dan berada pada bidang keberadaan yang sama dengan Anda. Portal berkilauan terbuka di dalam lingkaran yang Anda gambar dan tetap terbuka hingga akhir giliran Anda berikutnya. Makhluk apa pun yang memasuki portal langsung muncul dalam jarak 5 kaki dari lingkaran tujuan atau di ruang kosong terdekat jika ruang tersebut terisi.\nBanyak kuil besar, guild, dan tempat penting lainnya memiliki lingkaran teleportasi permanen yang tertulis di suatu tempat dalam batasnya. Setiap lingkaran tersebut mencakup rangkaian sigil unik--rangkaian rune magis yang disusun dalam pola tertentu. Saat pertama kali mendapatkan kemampuan untuk merapal mantra ini, Anda mempelajari rangkaian sigil untuk dua tujuan di Bidang Material, yang ditentukan oleh GM. Anda dapat mempelajari urutan sigil tambahan selama petualangan Anda. Anda dapat memasukkan urutan sigil baru ke memori setelah mempelajarinya selama 1 menit.\nAnda dapat membuat lingkaran teleportasi permanen dengan menggunakan mantra ini di lokasi yang sama setiap hari selama satu tahun. Anda tidak perlu menggunakan lingkaran untuk berteleportasi saat Anda mengucapkan mantra dengan cara ini." },
      { name: "Wall of Stone", components: "V, S, M", desc: "Dinding batu padat non-magis muncul pada titik yang Anda pilih dalam jangkauan. Dindingnya setebal 6 inci dan terdiri dari sepuluh panel berukuran 10 kaki kali 10 kaki. Setiap panel harus berdekatan dengan setidaknya satu panel lainnya. Sebagai alternatif, Anda dapat membuat panel berukuran 10 kaki kali 20 kaki yang tebalnya hanya 3 inci.\nJika dinding menembus ruang makhluk saat muncul, makhluk tersebut akan terdorong ke salah satu sisi dinding (pilihan Anda). Jika makhluk dikelilingi di semua sisi oleh dinding (atau dinding dan permukaan padat lainnya), makhluk itu dapat melakukan lemparan penyelamatan ketangkasan. Jika berhasil, ia dapat menggunakan reaksinya untuk menaikkan kecepatannya sehingga tidak lagi tertutup oleh tembok.\nDinding bisa memiliki bentuk apa pun yang Anda inginkan, meski tidak bisa menempati ruang yang sama dengan makhluk atau benda. Dinding tidak harus vertikal atau bertumpu pada fondasi yang kokoh. Namun, ia harus menyatu dan didukung secara kokoh oleh batu yang sudah ada. Jadi, kamu bisa menggunakan mantra ini untuk menjembatani jurang atau membuat tanjakan.\nJika Anda membuat bentang yang panjangnya lebih dari 20 kaki, Anda harus membagi dua ukuran setiap panel untuk membuat penyangga. Anda dapat membentuk dinding secara kasar untuk membuat crenellations, benteng, dan sebagainya.\nDinding merupakan suatu benda yang terbuat dari batu yang dapat dirusak dan ditembus. Setiap panel memiliki ketebalan AC 15 dan 30 titik hit per inci. Mengurangi panel menjadi 0 titik hit akan menghancurkannya dan mungkin menyebabkan panel yang terhubung runtuh sesuai kebijakan GM.\nJika Anda mempertahankan konsentrasi pada mantra ini selama durasinya, tembok menjadi permanen dan tidak dapat dihilangkan. Jika tidak, tembok itu akan hilang saat mantranya berakhir." },
    ],
    Level6: [
      { name: "Chain Lightning", components: "V, S, M", desc: "Anda membuat sambaran petir yang mengarah ke target pilihan Anda yang dapat Anda lihat dalam jangkauan. Tiga baut kemudian melompat dari sasaran tersebut ke sebanyak tiga sasaran lainnya, yang masing-masing harus berada dalam jarak 30 kaki dari sasaran pertama. Sasaran dapat berupa makhluk atau benda dan hanya dapat dibidik dengan salah satu baut.\nTarget harus melakukan lemparan penyelamatan ketangkasan. Target menerima 10d8 kerusakan petir pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 7 atau lebih tinggi, satu baut tambahan melompat dari target pertama ke target lain untuk setiap slot level di atas 6." },
      { name: "Circle of Death", components: "V, S, M", desc: "Sebuah bola energi negatif muncul dalam radius 60 kaki dari suatu titik dalam jangkauan. Setiap makhluk di area itu harus melakukan penyelamatan konstitusi. Target menerima 8d6 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, kerusakan meningkat sebesar 2d6 untuk setiap slot level di atas 6." },
      { name: "Disintegrate", components: "V, S, M", desc: "Sinar hijau tipis muncul dari jari telunjuk Anda ke target yang dapat Anda lihat dalam jangkauan. Sasarannya bisa berupa makhluk, benda, atau ciptaan kekuatan magis, seperti tembok yang diciptakan oleh tembok kekuatan.\nMakhluk yang menjadi sasaran mantra ini harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, target menerima 10d6 + 40 kerusakan paksa. Jika kerusakan ini mengurangi target menjadi 0 poin hit, target tersebut akan hancur.\nMakhluk yang hancur dan segala sesuatu yang dikenakan dan dibawanya, kecuali benda sihir, menjadi tumpukan debu halus berwarna abu-abu. Makhluk itu dapat dihidupkan kembali hanya melalui kebangkitan sejati atau mantra harapan.\nMantra ini secara otomatis menghancurkan objek non-magis yang besar atau lebih kecil atau ciptaan kekuatan magis. Jika targetnya adalah objek atau ciptaan kekuatan yang sangat besar atau lebih besar, mantra ini akan menghancurkan bagian berukuran 10 kaki kubik dari objek tersebut. Item sihir tidak terpengaruh oleh mantra ini.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, kerusakan meningkat sebesar 3d6 untuk setiap slot level di atas 6." },
      { name: "Eyebite", components: "V, S", desc: "Selama durasi mantranya, matamu menjadi kehampaan bertinta yang dipenuhi kekuatan menakutkan. Satu makhluk pilihan Anda dalam jarak 60 kaki dari Anda yang dapat Anda lihat harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau terpengaruh oleh salah satu efek pilihan Anda berikut selama durasi tersebut. Pada setiap giliranmu hingga mantra berakhir, kamu dapat menggunakan tindakanmu untuk menargetkan makhluk lain tetapi tidak dapat menargetkan makhluk lagi jika makhluk tersebut berhasil melakukan penyelamatan terhadap casting eyebite ini.\n***Tidur.*** Target jatuh pingsan. Ia akan bangun jika ia mengalami kerusakan atau jika makhluk lain menggunakan aksinya untuk membangunkan orang yang tidur.\n***Panik.*** Targetnya takut padamu. Di setiap belokannya, makhluk yang ketakutan harus mengambil tindakan Dash dan menjauh dari Anda melalui rute teraman dan terpendek yang tersedia, kecuali tidak ada tempat untuk bergerak. Jika target berpindah ke tempat setidaknya 60 kaki dari Anda di mana ia tidak dapat lagi melihat Anda, efek ini akan berakhir.\n***Muak.*** Target memiliki kelemahan pada serangan dan pemeriksaan kemampuan. Di akhir setiap putarannya, ia dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, efeknya berakhir." },
      { name: "Globe of Invulnerability", components: "V, S, M", desc: "Penghalang yang tidak bergerak dan sedikit berkilauan muncul dalam radius 10 kaki di sekitar Anda dan tetap ada selama durasi tersebut.\nMantra apa pun dengan level 5 atau lebih rendah yang dilemparkan dari luar penghalang tidak dapat memengaruhi makhluk atau objek di dalamnya, meskipun mantra tersebut digunakan menggunakan slot mantra level yang lebih tinggi. Mantra semacam itu dapat menargetkan makhluk dan objek di dalam penghalang, tetapi mantra tersebut tidak berpengaruh pada mereka. Demikian pula, area di dalam penghalang tidak termasuk dalam area yang terkena dampak mantra tersebut.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, penghalang akan memblokir mantra satu level lebih tinggi untuk setiap slot level di atas 6." },
      { name: "Mass Suggestion", components: "V, M", desc: "Anda menyarankan serangkaian aktivitas (terbatas pada satu atau dua kalimat) dan secara ajaib memengaruhi hingga dua belas makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan dan yang dapat mendengar serta memahami Anda. Makhluk yang tidak bisa dipesona akan kebal terhadap efek ini. Saran tersebut harus diungkapkan sedemikian rupa agar tindakan yang diambil terdengar masuk akal. Meminta makhluk itu untuk menusuk dirinya sendiri, melemparkan dirinya ke tombak, mengorbankan dirinya sendiri, atau melakukan tindakan berbahaya lainnya secara otomatis meniadakan efek mantranya.\nSetiap target harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, ia akan melakukan tindakan yang Anda jelaskan dengan kemampuan terbaiknya. Tindakan yang disarankan dapat berlanjut sepanjang durasi. Jika aktivitas yang disarankan dapat diselesaikan dalam waktu yang lebih singkat, mantra akan berakhir saat subjek menyelesaikan apa yang diminta.\nAnda juga dapat menentukan kondisi yang akan memicu aktivitas khusus selama durasi tersebut. Misalnya, Anda mungkin menyarankan agar sekelompok tentara memberikan seluruh uangnya kepada pengemis pertama yang mereka temui. Jika kondisi tidak terpenuhi sebelum mantra berakhir, aktivitas tidak dilakukan.\nJika Anda atau salah satu teman Anda merusak makhluk yang terkena mantra ini, mantra untuk makhluk itu akan berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7, durasinya adalah 10 hari. Saat Anda menggunakan slot mantra level 8, durasinya adalah 30 hari. Saat Anda menggunakan slot mantra level 9, durasinya adalah satu tahun dan satu hari." },
      { name: "Move Earth", components: "V, S, M", desc: "Pilih area medan yang tidak lebih besar dari 40 kaki pada sisi yang berada dalam jangkauan. Anda dapat membentuk kembali tanah, pasir, atau tanah liat di area tersebut dengan cara apa pun yang Anda pilih selama durasi tersebut. Anda dapat menaikkan atau menurunkan ketinggian area, membuat atau mengisi parit, mendirikan atau meratakan dinding, atau membentuk pilar. Besarnya perubahan tersebut tidak boleh melebihi setengah dimensi terbesar wilayah tersebut. Jadi, jika Anda mempengaruhi persegi berukuran 40 kaki, Anda dapat membuat pilar setinggi 20 kaki, menaikkan atau menurunkan ketinggian persegi hingga 20 kaki, menggali parit sedalam 20 kaki, dan seterusnya. Diperlukan waktu 10 menit agar perubahan ini selesai.\nDi akhir setiap 10 menit yang Anda habiskan untuk berkonsentrasi pada mantranya, Anda dapat memilih area medan baru untuk dipengaruhi.\nKarena transformasi medan terjadi secara perlahan, makhluk di area tersebut biasanya tidak dapat terjebak atau terluka oleh pergerakan tanah.\nMantra ini tidak dapat memanipulasi batu alam atau konstruksi batu. Batuan dan struktur bergeser untuk mengakomodasi medan baru. Jika cara Anda membentuk medan membuat struktur menjadi tidak stabil, maka struktur tersebut mungkin akan runtuh.\nDemikian pula mantra ini tidak mempengaruhi pertumbuhan tanaman secara langsung. Bumi yang dipindahkan membawa serta tanaman apa pun." },
      { name: "Sunbeam", components: "V, S, M", desc: "Seberkas cahaya cemerlang memancar dari tangan Anda dalam garis selebar 5 kaki dan panjang 60 kaki. Setiap makhluk dalam barisan harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk akan menerima kerusakan radiasi sebesar 6d8 dan menjadi buta hingga giliran Anda berikutnya. Jika penyelamatan berhasil, dibutuhkan setengah kerusakan dan tidak dibutakan oleh mantra ini. Mayat hidup dan cairan merembes memiliki kelemahan dalam lemparan penyelamatan ini.\nAnda dapat membuat garis pancaran baru sebagai tindakan Anda di giliran mana pun hingga mantranya berakhir.\nSelama itu, secercah cahaya cemerlang bersinar di tangan Anda. Ini memancarkan cahaya terang dalam radius 30 kaki dan cahaya redup untuk tambahan 30 kaki. Cahaya ini adalah sinar matahari." },
      { name: "True Seeing", components: "V, S, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk melihat segala sesuatu sebagaimana adanya. Selama durasi tersebut, makhluk tersebut memiliki penglihatan yang sebenarnya, mengetahui pintu rahasia yang disembunyikan oleh sihir, dan dapat melihat ke dalam Alam Ethereal, semuanya hingga jarak 120 kaki." },
    ],
    Level7: [
      { name: "Delayed Blast Fireball", components: "V, S, M", desc: "Seberkas cahaya kuning berkedip dari jari telunjuk Anda, lalu mengembun dan bertahan di titik yang dipilih dalam jangkauan sebagai manik bercahaya selama durasi tersebut. Saat mantranya berakhir, entah karena konsentrasimu terganggu atau karena kamu memutuskan untuk mengakhirinya, manik itu mekar dengan raungan rendah menjadi ledakan api yang menyebar ke segala sudut. Setiap makhluk dalam bola berradius 20 kaki yang berpusat pada titik tersebut harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan akibat kebakaran yang sama dengan total akumulasi kerusakan pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nKerusakan dasar mantranya adalah 12d6. Jika di akhir giliranmu maniknya belum meledak, kerusakannya meningkat sebesar 1d6.\nJika manik bercahaya itu disentuh sebelum jedanya habis, makhluk yang menyentuhnya harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, mantranya segera berakhir, menyebabkan manik itu meledak dalam nyala api. Jika penyelamatan berhasil, makhluk itu dapat melempar manik hingga sejauh 40 kaki. Saat mengenai makhluk atau benda padat, mantranya berakhir, dan maniknya meledak.\nApi merusak benda-benda di area tersebut dan menyulut benda-benda mudah terbakar yang tidak dipakai atau dibawa.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 8 atau lebih tinggi, kerusakan dasar meningkat sebesar 1d6 untuk setiap slot level di atas 7." },
      { name: "Etherealness", components: "V, S", desc: "Anda melangkah ke wilayah perbatasan Pesawat Ethereal, di area yang tumpang tindih dengan pesawat Anda saat ini. Anda tetap berada di Border Ethereal selama atau sampai Anda menggunakan tindakan Anda untuk menghilangkan mantranya. Selama waktu ini, Anda dapat bergerak ke segala arah. Jika Anda bergerak ke atas atau ke bawah, setiap gerakan membutuhkan satu kaki ekstra. Anda dapat melihat dan mendengar pesawat asal Anda, tetapi segala sesuatu di sana tampak abu-abu, dan Anda tidak dapat melihat apa pun yang jaraknya lebih dari 60 kaki.\nSelama berada di Alam Ethereal, Anda hanya dapat mempengaruhi dan dipengaruhi oleh makhluk lain di alam tersebut. Makhluk yang tidak berada di Alam Ethereal tidak dapat melihat Anda dan tidak dapat berinteraksi dengan Anda, kecuali jika kemampuan atau sihir khusus memberi mereka kemampuan untuk melakukannya.\nAnda mengabaikan semua objek dan efek yang tidak ada di Alam Ethereal, memungkinkan Anda bergerak melalui objek yang Anda lihat di bidang asal Anda.\nKetika mantranya berakhir, kamu segera kembali ke pesawat asalmu di tempat yang kamu tempati saat ini. Jika Anda menempati tempat yang sama dengan benda padat atau makhluk saat hal ini terjadi, Anda akan segera diarahkan ke ruang kosong terdekat yang dapat Anda tempati dan menerima kerusakan kekuatan yang setara dengan dua kali jumlah kaki yang Anda gerakkan.\nMantra ini tidak berpengaruh jika kamu mengucapkannya saat kamu berada di Alam Ethereal atau di alam yang tidak membatasinya, seperti salah satu Alam Luar.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 8 atau lebih tinggi, Anda dapat menargetkan hingga tiga makhluk yang bersedia (termasuk Anda) untuk setiap slot level di atas 7. Makhluk tersebut harus berada dalam jarak 10 kaki dari Anda saat Anda mengucapkan mantra." },
      { name: "Finger of Death", components: "V, S", desc: "Anda mengirimkan energi negatif ke seluruh makhluk yang dapat Anda lihat dalam jangkauannya, menyebabkan rasa sakit yang membakar. Targetnya harus melakukan penyelamatan konstitusi. Dibutuhkan 7d8 + 30 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nHumanoid yang terbunuh oleh mantra ini muncul di awal giliran Anda berikutnya sebagai zombie yang secara permanen berada di bawah komando Anda, mengikuti perintah lisan Anda dengan kemampuan terbaiknya." },
      { name: "Fire Storm", components: "V, S", desc: "Badai yang terdiri dari lembaran api yang menderu muncul di lokasi yang Anda pilih dalam jangkauannya. Area badai terdiri dari sepuluh kubus berukuran 10 kaki, yang dapat Anda atur sesuai keinginan. Setiap kubus harus memiliki setidaknya satu sisi yang berdekatan dengan sisi kubus lainnya. Setiap makhluk di area tersebut harus melakukan lemparan penyelamatan ketangkasan. Dibutuhkan 7d10 kerusakan akibat kebakaran pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nApi merusak benda-benda di area tersebut dan menyulut benda-benda mudah terbakar yang tidak dipakai atau dibawa. Jika Anda memilih, kehidupan tanaman di area tersebut tidak terpengaruh oleh mantra ini." },
      { name: "Plane Shift", components: "V, S, M", desc: "Anda dan hingga delapan makhluk bersedia yang bergandengan tangan dalam lingkaran akan dipindahkan ke alam eksistensi lain. Anda dapat menentukan tujuan target secara umum, seperti Kota Kuningan di Alam Elemen Api atau istana Dispater di Sembilan Neraka tingkat kedua, dan Anda muncul di atau dekat tujuan tersebut. Jika Anda mencoba mencapai Kota Kuningan, misalnya, Anda mungkin tiba di Jalan Baja, sebelum Gerbang Abu, atau melihat kota dari seberang Lautan Api, sesuai kebijaksanaan GM.\nAlternatifnya, jika Anda mengetahui urutan sigil lingkaran teleportasi di alam eksistensi lain, mantra ini dapat membawa Anda ke lingkaran itu. Jika lingkaran teleportasi terlalu kecil untuk menampung semua makhluk yang Anda pindahkan, mereka akan muncul di ruang kosong terdekat di sebelah lingkaran.\nAnda dapat menggunakan mantra ini untuk mengusir makhluk yang tidak mau ke pesawat lain. Pilih makhluk dalam jangkauan Anda dan lakukan serangan mantra jarak dekat terhadapnya. Saat terkena, makhluk tersebut harus melakukan lemparan penyelamatan karisma. Jika makhluk tersebut gagal dalam penyelamatan ini, ia akan dipindahkan ke lokasi acak di alam keberadaan yang Anda tentukan. Makhluk yang dipindahkan harus menemukan jalannya sendiri kembali ke alam keberadaan Anda saat ini." },
      { name: "Prismatic Spray", components: "V, S", desc: "Delapan sinar cahaya warna-warni memancar dari tangan Anda. Setiap sinar memiliki warna berbeda dan memiliki kekuatan serta tujuan berbeda. Setiap makhluk dalam kerucut setinggi 60 kaki harus melakukan lemparan penyelamatan ketangkasan. Untuk setiap target, putar d8 untuk menentukan sinar warna mana yang mempengaruhinya.\n***1. Merah.*** Target menerima damage api sebesar 10d6 jika penyelamatan gagal, atau setengah damage jika berhasil disimpan.\n***2. Oranye.*** Target menerima 10d6 kerusakan asam pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\n***3. Kuning.*** Target menerima 10d6 kerusakan petir pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\n***4. Hijau.*** Target menerima 10d6 kerusakan racun pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\n***5. Biru.*** Target menerima 10d6 kerusakan dingin pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\n***6. Indigo.*** Pada penyelamatan yang gagal, target tertahan. Ia kemudian harus melakukan penyelamatan konstitusi di akhir setiap putarannya. Jika berhasil menyelamatkan tiga kali, mantranya berakhir. Jika gagal menyelamatkannya tiga kali, ia akan berubah menjadi batu secara permanen dan mengalami kondisi membatu. Keberhasilan dan kegagalan tidak harus terjadi secara berurutan; lacak keduanya sampai target mengumpulkan tiga jenis.\n***7. Violet.*** Pada penyelamatan yang gagal, target menjadi buta. Ia kemudian harus melakukan lemparan penyelamatan yang bijaksana di awal giliran Anda berikutnya. Penyelamatan yang berhasil mengakhiri kebutaan. Jika penyelamatan itu gagal, makhluk itu dipindahkan ke alam eksistensi lain yang dipilih GM dan tidak lagi dibutakan. (Biasanya, makhluk yang berada di pesawat yang bukan pesawat asalnya akan dibuang pulang, sedangkan makhluk lain biasanya dibuang ke pesawat Astral atau Ethereal.)\n***8. Istimewa.*** Target terkena dua sinar. Gulung dua kali lagi, gulung ulang 8 lainnya." },
      { name: "Reverse Gravity", components: "V, S, M", desc: "Mantra ini membalikkan gravitasi dalam silinder dengan radius 50 kaki dan tinggi 100 kaki yang berpusat pada suatu titik dalam jangkauan. Semua makhluk dan benda yang entah bagaimana tidak tertambat ke tanah di area tersebut akan jatuh ke atas dan mencapai puncak area saat Anda mengucapkan mantra ini. Makhluk dapat melakukan lemparan hemat ketangkasan untuk meraih benda tetap yang dapat dijangkaunya, sehingga terhindar dari terjatuh.\nJika ada benda padat (seperti langit-langit) yang ditemui pada musim gugur ini, benda dan makhluk yang jatuh akan menghantamnya seperti yang terjadi pada saat jatuh ke bawah pada umumnya. Jika suatu benda atau makhluk mencapai puncak area tersebut tanpa menabrak apa pun, benda atau makhluk tersebut akan tetap berada di sana, sedikit terombang-ambing, selama durasi tersebut.\nDi akhir durasi, objek dan makhluk yang terkena dampak akan terjatuh kembali." },
      { name: "Teleport", components: "V", desc: "Mantra ini secara instan memindahkan Anda dan hingga delapan makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan, atau satu objek yang dapat Anda lihat dalam jangkauan, ke tujuan yang Anda pilih. Jika Anda menargetkan suatu objek, objek tersebut harus dapat masuk seluruhnya ke dalam kubus berukuran 10 kaki, dan objek tersebut tidak dapat dipegang atau dibawa oleh makhluk yang tidak mau.\nTujuan yang Anda pilih harus Anda ketahui, dan harus berada pada alam eksistensi yang sama dengan Anda. Keakraban Anda dengan tujuan menentukan apakah Anda berhasil sampai di sana. GM menggulung d100 dan melihat tabel.\n| Keakraban | Kecelakaan | Daerah Serupa | Melenceng dari Sasaran | Sesuai Sasaran |\n|---|---|---|---|---|\n| Lingkaran permanen | -- | -- | -- | 01-100 |\n| Objek terkait | -- | -- | -- | 01-100 |\n| Sangat akrab | 01-05 | 06-13 | 14-24 | 25-100 |\n| Terlihat santai | 01-33 | 34-43 | 44-53 | 54-100 |\n| Dilihat sekali | 01-43 | 44-53 | 54-73 | 74-100 |\n| Deskripsi | 01-43 | 44-53 | 54-73 | 74-100 |\n| Tujuan salah | 01-50 | 51-100 | -- | -- |\n***Familiarity.*** \"Lingkaran permanen\" artinya lingkaran teleportasi permanen yang urutan sigilnya sudah kalian ketahui.\n\"Benda terkait\" berarti Anda memiliki benda yang diambil dari tujuan yang diinginkan dalam enam bulan terakhir, seperti buku dari perpustakaan penyihir, sprei dari kamar kerajaan, atau bongkahan marmer dari makam rahasia lich.\n\"Sangat familier\" adalah tempat yang sering Anda kunjungi, tempat yang telah Anda pelajari dengan cermat, atau tempat yang dapat Anda lihat saat Anda merapal mantra.\n\"Dilihat secara santai\" adalah suatu tempat yang pernah Anda lihat lebih dari sekali tetapi tidak terlalu Anda kenal.\n\"Dilihat sekali\" adalah tempat yang pernah Anda lihat, mungkin menggunakan sihir.\n\"Deskripsi\" adalah suatu tempat yang lokasi dan penampakannya Anda ketahui melalui deskripsi orang lain, mungkin dari peta.\n\"Tujuan palsu\" adalah tempat yang tidak ada. Mungkin Anda mencoba memindai tempat suci musuh tetapi malah melihat ilusi, atau Anda mencoba berteleportasi ke lokasi familiar yang sudah tidak ada lagi.\n***Tepat Target.*** Anda dan grup Anda (atau objek target) muncul di tempat yang Anda inginkan.\n***Diluar Target.*** Anda dan grup Anda (atau objek target) muncul pada jarak acak dari tujuan dalam arah acak. Jarak yang melenceng dari sasaran adalah 1d10 x 1d10 persen dari jarak yang hendak ditempuh. Misalnya, jika Anda mencoba menempuh jarak 120 mil, mendarat melenceng, dan mendapatkan angka 5 dan 3 pada dua D10, maka Anda akan melenceng 15 persen, atau 18 mil. GM menentukan arah keluar target secara acak dengan memutar d8 dan menetapkan 1 sebagai utara, 2 sebagai timur laut, 3 sebagai timur, dan seterusnya di sekitar titik kompas.  Jika Anda berteleportasi ke kota pesisir dan terdampar sejauh 18 mil di laut, Anda bisa mendapat masalah.\n***Area Serupa.*** Anda dan grup Anda (atau objek target) berakhir di area berbeda yang secara visual atau tematis mirip dengan area target. Jika Anda menuju laboratorium di rumah, misalnya, Anda mungkin akan berakhir di laboratorium penyihir lain atau di toko perlengkapan alkimia yang memiliki banyak peralatan dan perlengkapan yang sama dengan laboratorium Anda. Umumnya, Anda muncul di tempat terdekat yang serupa, tetapi karena mantranya tidak memiliki batasan jangkauan, Anda mungkin bisa berakhir di mana saja di pesawat.\n***Kecelakaan.*** Sihir tak terduga dari mantra ini mengakibatkan perjalanan yang sulit. Setiap makhluk yang berteleportasi (atau objek target) menerima kerusakan kekuatan 3d10, dan GM memutar ulang meja untuk melihat di mana Anda berakhir (beberapa kecelakaan dapat terjadi, menimbulkan kerusakan setiap kali)." },
    ],
    Level8: [
      { name: "Dominate Monster", components: "V, S", desc: "Anda mencoba memperdaya makhluk yang dapat Anda lihat dalam jangkauan. Ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Jika Anda atau makhluk yang bersahabat dengan Anda melawannya, ia memiliki keuntungan dalam penyelamatan.\nMeskipun makhluk itu terpesona, Anda memiliki hubungan telepati dengannya selama Anda berdua berada di alam eksistensi yang sama. Anda dapat menggunakan tautan telepati ini untuk mengeluarkan perintah kepada makhluk itu saat Anda sadar (tidak perlu tindakan apa pun), yang akan dipatuhinya sebaik mungkin. Anda dapat menentukan tindakan yang sederhana dan umum, seperti \"Serang makhluk itu\", \"Lari ke sana\", atau \"Ambil objek itu\". Jika makhluk tersebut menyelesaikan perintahnya dan tidak menerima arahan lebih lanjut dari Anda, ia akan mempertahankan dan mempertahankan dirinya dengan kemampuan terbaiknya.\nAnda dapat menggunakan tindakan Anda untuk mengambil kendali total dan tepat terhadap target. Hingga akhir giliran Anda berikutnya, makhluk itu hanya mengambil tindakan yang Anda pilih, dan tidak melakukan apa pun yang tidak Anda izinkan. Selama waktu ini, Anda juga dapat menyebabkan makhluk tersebut menggunakan reaksi, namun hal ini mengharuskan Anda menggunakan reaksi Anda sendiri juga.\nSetiap kali target menerima kerusakan, ia membuat lemparan penyelamatan kebijaksanaan baru terhadap mantra tersebut. Jika lemparan penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini dengan slot mantra level 9, durasinya adalah konsentrasi, hingga 8 jam." },
      { name: "Earthquake", components: "V, S, M", desc: "Anda menciptakan gangguan seismik pada suatu titik di permukaan tanah yang dapat Anda lihat dalam jangkauannya. Selama durasi tersebut, getaran hebat melanda tanah dalam lingkaran radius 100 kaki yang berpusat di titik tersebut dan mengguncang makhluk serta bangunan yang bersentuhan dengan tanah di area tersebut.\nTanah di kawasan tersebut menjadi medan yang sulit. Setiap makhluk di tanah yang sedang berkonsentrasi harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, konsentrasi makhluk itu terganggu.\nSaat Anda mengucapkan mantra ini dan di akhir setiap giliran yang Anda habiskan untuk berkonsentrasi padanya, setiap makhluk di tanah di area tersebut harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk itu rawan terbentur.\nSpell ini dapat memberikan efek tambahan tergantung pada medan di area tersebut, seperti yang ditentukan oleh GM.\ncelah. Celah terbuka di seluruh area mantra pada awal giliran berikutnya setelah Anda mengucapkan mantra. Sebanyak 1d6 celah tersebut terbuka di lokasi yang dipilih oleh GM. Masing-masing memiliki kedalaman 1d10 x 10 kaki, lebar 10 kaki, dan memanjang dari satu tepi area mantra ke sisi yang berlawanan. Makhluk yang berdiri di tempat celah terbuka harus berhasil melakukan lemparan penyelamatan ketangkasan atau jatuh. Makhluk yang berhasil menyelamatkan bergerak dengan tepi celah saat celah terbuka.\nRetakan yang terbuka di bawah suatu struktur menyebabkan struktur tersebut runtuh secara otomatis (lihat di bawah).\nStruktur. Getaran tersebut menimbulkan 50 kerusakan besar pada struktur apa pun yang bersentuhan dengan tanah di area tersebut saat Anda merapal mantra dan di awal setiap giliran hingga mantra berakhir. Jika suatu struktur turun hingga 0 titik serangan, struktur tersebut akan runtuh dan berpotensi merusak makhluk di sekitarnya. Makhluk yang berada dalam jarak setengah dari tinggi bangunan harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk itu menerima kerusakan akibat pukulan 5d6, rawan terkena pukulan, dan terkubur di reruntuhan, memerlukan pemeriksaan Kekuatan (Atletik) DC 20 sebagai tindakan untuk melarikan diri. GM dapat mengatur DC lebih tinggi atau lebih rendah, tergantung pada sifat puing-puingnya. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan dan tidak rawan atau terkubur." },
      { name: "Incendiary Cloud", components: "V, S", desc: "Kepulan asap yang berputar-putar dengan bara api putih muncul dalam bola berradius 20 kaki yang berpusat pada suatu titik dalam jangkauan. Awan menyebar ke segala penjuru dan sangat tertutup. Itu berlangsung selama atau sampai angin dengan kecepatan sedang atau lebih besar (setidaknya 10 mil per jam) membubarkannya.\nSaat awan muncul, setiap makhluk di dalamnya harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan api sebesar 10d8 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Makhluk juga harus melakukan lemparan penyelamatan ini ketika memasuki area mantra untuk pertama kalinya pada suatu giliran atau mengakhiri gilirannya di sana.\nAwan bergerak sejauh 10 kaki dari Anda ke arah yang Anda pilih di awal setiap belokan." },
      { name: "Power Word Stun", components: "V", desc: "Anda mengucapkan kata-kata yang memiliki kekuatan yang dapat menguasai pikiran satu makhluk yang dapat Anda lihat dalam jangkauannya, membuatnya tercengang. Jika target memiliki 150 poin hit atau kurang, target akan terkena stun. Kalau tidak, mantranya tidak akan berpengaruh.\nTarget yang terkena stun harus melakukan penyelamatan konstitusi di akhir setiap giliran. Jika penyelamatan berhasil, efek menakjubkan ini berakhir." },
      { name: "Sunburst", components: "V, S, M", desc: "Sinar matahari yang cemerlang bersinar dalam radius 60 kaki yang berpusat pada titik yang Anda pilih dalam jangkauannya. Setiap makhluk dalam terang itu harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk akan menerima kerusakan radiasi 12d6 dan menjadi buta selama 1 menit. Jika penyelamatan berhasil, dibutuhkan setengah kerusakan dan tidak dibutakan oleh mantra ini. Mayat hidup dan cairan merembes memiliki kelemahan dalam lemparan penyelamatan ini.\nMakhluk yang dibutakan oleh mantra ini melakukan lemparan penyelamatan konstitusi lainnya di akhir setiap putarannya. Jika penyelamatan berhasil, ia tidak lagi dibutakan.\nMantra ini menghilangkan kegelapan apa pun di areanya yang diciptakan oleh mantra." },
    ],
    Level9: [
      { name: "Gate", components: "V, S, M", desc: "Anda membayangkan sebuah portal yang menghubungkan ruang kosong yang dapat Anda lihat dalam jangkauan ke lokasi yang tepat di alam eksistensi yang berbeda. Portalnya berupa bukaan melingkar, yang bisa Anda buat dengan diameter 5 hingga 20 kaki. Anda dapat mengarahkan portal ke arah mana pun yang Anda pilih. Portal ini bertahan selama durasi tersebut.\nPortal ini memiliki bagian depan dan belakang pada setiap bidang tempat ia muncul. Perjalanan melalui portal hanya mungkin dilakukan dengan bergerak melalui bagian depannya. Apa pun yang melakukan hal itu akan langsung dipindahkan ke pesawat lain, muncul di ruang kosong yang paling dekat dengan portal.\nDewa dan penguasa planar lainnya dapat mencegah portal yang dibuat oleh mantra ini terbuka di hadapan mereka atau di mana pun dalam domain mereka.\nSaat Anda mengucapkan mantra ini, Anda dapat mengucapkan nama makhluk tertentu (nama samaran, gelar, atau nama panggilan tidak berfungsi). Jika makhluk itu berada di pesawat selain yang Anda naiki, portal akan terbuka di sekitar makhluk yang disebutkan dan menarik makhluk itu melewatinya ke ruang kosong terdekat di sisi portal Anda. Anda tidak mendapatkan kekuatan khusus atas makhluk itu, dan ia bebas bertindak sesuai keinginan GM. Ia mungkin pergi, menyerang Anda, atau membantu Anda." },
      { name: "Meteor Swarm", components: "V, S", desc: "Bola api yang menyala-nyala jatuh ke tanah di empat titik berbeda yang dapat Anda lihat dalam jangkauannya. Setiap makhluk dalam bola berradius 40 kaki yang berpusat pada setiap titik yang Anda pilih harus melakukan lemparan penyelamatan ketangkasan. Bola itu menyebar ke berbagai sudut. Makhluk menerima 20d6 kerusakan api dan 20d6 kerusakan pukulan pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil. Makhluk yang berada di area lebih dari satu semburan api hanya terpengaruh satu kali.\nMantra tersebut merusak objek di area tersebut dan menyulut objek yang mudah terbakar yang tidak dipakai atau dibawa." },
      { name: "Power Word Kill", components: "V", desc: "Anda mengucapkan kata-kata kekuatan yang dapat memaksa satu makhluk yang Anda lihat dalam jangkauannya untuk mati seketika. Jika makhluk yang Anda pilih memiliki 100 poin hit atau kurang, ia akan mati. Kalau tidak, mantranya tidak akan berpengaruh." },
      { name: "Time Stop", components: "V", desc: "Anda menghentikan sementara aliran waktu untuk semua orang kecuali diri Anda sendiri. Tidak ada waktu berlalu untuk makhluk lain, saat Anda melakukan 1d4 + 1 putaran berturut-turut, di mana Anda dapat menggunakan tindakan dan bergerak seperti biasa.\nMantra ini berakhir jika salah satu tindakan yang Anda gunakan selama periode ini, atau efek apa pun yang Anda buat selama periode ini, memengaruhi makhluk selain Anda atau benda yang dikenakan atau dibawa oleh orang lain selain Anda. Selain itu, mantranya akan berakhir jika Anda berpindah ke tempat yang lebih dari 1.000 kaki dari lokasi Anda melemparkannya." },
      { name: "Wish", components: "V", desc: "Harapan adalah mantra terkuat yang bisa diucapkan makhluk fana. Hanya dengan berbicara keras-keras, Anda dapat mengubah fondasi realitas sesuai keinginan Anda.\nKegunaan dasar mantra ini adalah untuk menduplikasi mantra lain level 8 atau lebih rendah. Anda tidak perlu memenuhi persyaratan apa pun dalam mantra itu, termasuk komponen yang mahal. Mantra itu mulai berlaku.\nAlternatifnya, Anda dapat membuat salah satu efek pilihan Anda berikut ini:\n- Anda membuat satu objek dengan nilai hingga 25.000 gp yang bukan merupakan item ajaib. Objek tersebut tidak boleh lebih dari 300 kaki dalam dimensi apa pun, dan ia muncul di ruang kosong yang dapat Anda lihat di tanah.\n- Anda mengizinkan hingga dua puluh makhluk yang dapat Anda lihat untuk mendapatkan kembali semua titik serangan, dan Anda mengakhiri semua efek pada mereka yang dijelaskan dalam mantra pemulihan yang lebih besar.\n- Anda memberikan hingga sepuluh makhluk yang Anda lihat ketahanannya terhadap jenis kerusakan yang Anda pilih.\n- Anda memberikan hingga sepuluh makhluk yang dapat Anda lihat kekebalannya terhadap satu mantra atau efek magis lainnya selama 8 jam. Misalnya, Anda bisa membuat diri Anda dan semua teman Anda kebal terhadap serangan yang menguras nyawa lich.\n- Anda membatalkan satu event baru-baru ini dengan memaksa roll ulang dari setiap lemparan yang dilakukan dalam ronde terakhir (termasuk giliran terakhir Anda). Realitas membentuk kembali dirinya untuk mengakomodasi hasil baru. Misalnya, mantra harapan dapat membatalkan penyelamatan lawan yang berhasil, serangan kritis musuh, atau penyelamatan teman yang gagal. Anda dapat memaksa agar reroll dibuat dengan kelebihan atau kekurangan, dan Anda dapat memilih apakah akan menggunakan reroll atau roll asli.\nAnda mungkin bisa mencapai sesuatu di luar cakupan contoh di atas. Nyatakan keinginan Anda kepada GM sedetail mungkin. GM mempunyai kebebasan yang besar dalam memutuskan apa yang terjadi dalam kasus seperti itu; semakin besar keinginannya, semakin besar kemungkinan terjadi kesalahan. Mantra ini mungkin gagal, efek yang Anda inginkan mungkin hanya tercapai sebagian, atau Anda mungkin mengalami konsekuensi tak terduga akibat cara Anda mengucapkan keinginan tersebut. Misalnya, berharap seorang penjahat mati mungkin akan mendorong Anda maju ke masa ketika penjahat tersebut tidak lagi hidup, sehingga secara efektif mengeluarkan Anda dari permainan. Demikian pula, mengharapkan item sihir atau artefak legendaris mungkin akan langsung membawa Anda ke hadapan pemilik item tersebut saat ini.\nTekanan dalam merapal mantra ini untuk menghasilkan efek apa pun selain menduplikasi mantra lain akan melemahkan Anda. Setelah menahan tekanan itu, setiap kali Anda merapal mantra hingga Anda menyelesaikan istirahat panjang, Anda menerima 1d10 kerusakan nekrotik per level mantra tersebut. Kerusakan ini tidak dapat dikurangi atau dicegah dengan cara apa pun. Selain itu, Kekuatan Anda turun menjadi 3, jika belum menjadi 3 atau lebih rendah, selama 2d4 hari. Untuk setiap hari yang Anda habiskan untuk beristirahat dan tidak melakukan apa pun selain aktivitas ringan, sisa waktu pemulihan Anda berkurang 2 hari. Terakhir, ada kemungkinan 33 persen bahwa Anda tidak dapat lagi mewujudkan harapan jika Anda mengalami stres ini." },
    ],
  },
  Warlock: {
    Cantrips: [
      { name: "Chill Touch", components: "V, S", desc: "Anda membuat tangan kerangka hantu di ruang makhluk dalam jangkauan. Lakukan serangan mantra jarak jauh terhadap makhluk itu untuk menyerangnya dengan dinginnya kuburan. Saat terkena serangan, target menerima 1d8 kerusakan nekrotik, dan target tidak dapat memperoleh kembali poin serangan hingga dimulainya giliran berikutnya. Sampai saat itu, tangan menempel pada sasaran.\nJika Anda mengenai target undead, ia juga memiliki kerugian pada serangan yang bergulir ke arah Anda hingga akhir giliran Anda berikutnya.\nKerusakan mantra ini meningkat sebesar 1d8 ketika Anda mencapai level 5 (2d8), level 11 (3d8), dan level 17 (4d8)." },
      { name: "Eldritch Blast", components: "V, S", desc: "Seberkas energi berderak melesat ke arah makhluk dalam jangkauannya. Lakukan serangan mantra jarak jauh terhadap target. Saat terkena, target menerima kerusakan kekuatan 1d10. Mantra ini menciptakan lebih dari satu sinar ketika Anda mencapai level yang lebih tinggi: dua sinar di tingkat 5, tiga sinar di tingkat 11, dan empat sinar di tingkat 17. Anda dapat mengarahkan sinar ke sasaran yang sama atau ke sasaran berbeda. Buat serangan terpisah untuk setiap balok." },
      { name: "Mage Hand", components: "V, S", desc: "Tangan spektral dan mengambang muncul pada titik yang Anda pilih dalam jangkauan. Tangan tersebut bertahan selama atau sampai Anda mengabaikannya sebagai suatu tindakan. Tangan itu akan hilang jika jaraknya lebih dari 30 kaki dari Anda atau jika Anda mengucapkan mantra ini lagi.\nAnda dapat menggunakan tindakan Anda untuk mengontrol tangan. Anda dapat menggunakan tangan untuk memanipulasi suatu benda, membuka pintu atau wadah yang tidak terkunci, menyimpan atau mengambil suatu benda dari wadah terbuka, atau menuangkan isinya ke dalam botol. Anda dapat menggerakkan tangan hingga 30 kaki setiap kali menggunakannya.\nTangan tidak dapat menyerang, mengaktifkan item sihir, atau membawa beban lebih dari 10 pon." },
      { name: "Minor Illusion", components: "S, M", desc: "Anda membuat suara atau gambar suatu objek dalam jangkauan yang berlangsung selama durasi tersebut. Ilusi juga berakhir jika Anda mengabaikannya sebagai suatu tindakan atau mengucapkan mantra ini lagi.\nJika Anda membuat suara, volumenya bisa berkisar dari bisikan hingga jeritan. Bisa berupa suara Anda, suara orang lain, auman singa, tabuhan genderang, atau suara lain yang Anda pilih. Suara tersebut terus terdengar tanpa henti sepanjang durasi, atau Anda dapat membuat suara terpisah pada waktu yang berbeda sebelum mantra berakhir.\nJika Anda membuat gambar suatu objek--seperti kursi, jejak kaki berlumpur, atau peti kecil--ukurannya tidak boleh lebih dari kubus berukuran 5 kaki. Gambar tidak dapat menimbulkan suara, cahaya, bau, atau efek sensorik lainnya. Interaksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya.\nJika makhluk menggunakan tindakannya untuk memeriksa suara atau gambar, makhluk tersebut dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk mengenali ilusi apa adanya, ilusi tersebut menjadi samar bagi makhluk tersebut." },
      { name: "Poison Spray", components: "V, S", desc: "Anda mengulurkan tangan Anda ke arah makhluk yang dapat Anda lihat dalam jangkauan dan mengeluarkan kepulan gas berbahaya dari telapak tangan Anda. Makhluk itu harus berhasil melakukan penyelamatan konstitusi atau menerima kerusakan racun 1d12.\nKerusakan mantra ini meningkat sebesar 1d12 ketika Anda mencapai level 5 (2d12), level 11 (3d12), dan level 17 (4d12)." },
      { name: "Prestidigitation", components: "V, S", desc: "Mantra ini adalah trik magis kecil yang digunakan oleh perapal mantra pemula untuk latihan. Anda membuat salah satu efek ajaib berikut dalam 'jangkauan':\nAnda menciptakan efek sensorik yang seketika dan tidak berbahaya, seperti percikan api, hembusan angin, not musik yang samar, atau bau yang aneh.\nAnda langsung menyalakan atau mematikan lilin, obor, atau api unggun kecil.\nAnda langsung membersihkan atau mengotori benda yang ukurannya tidak lebih dari 1 kaki kubik.\nAnda mendinginkan, menghangatkan, atau membumbui hingga 1 kaki kubik bahan tak hidup selama 1 jam.\nAnda membuat warna, tanda kecil, atau simbol muncul pada suatu benda atau permukaan selama 1 jam.\nAnda membuat pernak-pernik non-magis atau gambar ilusi yang pas di tangan Anda dan bertahan hingga akhir giliran Anda berikutnya.\nJika Anda mengucapkan mantra ini beberapa kali, Anda dapat mengaktifkan hingga tiga efek non-instannya sekaligus, dan Anda dapat mengabaikan efek tersebut sebagai tindakan." },
      { name: "True Strike", components: "S", desc: "Anda mengulurkan tangan dan mengarahkan jari ke sasaran dalam jangkauan. Sihir Anda memberi Anda wawasan singkat tentang pertahanan target. Pada giliran berikutnya, Anda mendapatkan keuntungan dari serangan pertama Anda terhadap target, asalkan mantra ini belum berakhir." },
    ],
    Level1: [
      { name: "Charm Person", components: "V, S", desc: "Anda mencoba memikat humanoid yang dapat Anda lihat dalam jangkauan. Ia harus melakukan lemparan penyelamatan yang bijaksana, dan melakukannya dengan keuntungan jika Anda atau teman Anda melawannya. Jika gagal dalam lemparan penyelamatan, ia akan terpesona oleh Anda hingga mantranya berakhir atau hingga Anda atau teman Anda melakukan sesuatu yang membahayakannya. Makhluk yang terpesona menganggap Anda sebagai kenalan yang ramah. Saat mantranya berakhir, makhluk itu tahu bahwa dia terpesona oleh Anda.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 1. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Comprehend Languages", components: "V, S, M", desc: "Selama ini, Anda memahami arti literal dari setiap bahasa lisan yang Anda dengar. Anda juga memahami bahasa tertulis apa pun yang Anda lihat, tetapi Anda harus menyentuh permukaan tempat kata-kata itu ditulis. Dibutuhkan sekitar 1 menit untuk membaca satu halaman teks.\nMantra ini tidak memecahkan kode pesan rahasia dalam teks atau mesin terbang, seperti sigil misterius, yang bukan bagian dari bahasa tertulis." },
      { name: "Expeditious Retreat", components: "V, S", desc: "Mantra ini memungkinkan Anda bergerak dengan kecepatan luar biasa. Saat Anda mengucapkan mantra ini, dan kemudian sebagai tindakan bonus di setiap giliran Anda hingga mantra tersebut berakhir, Anda dapat melakukan tindakan Dash." },
      { name: "Hellish Rebuke", components: "V, S", desc: "Anda mengarahkan jari Anda, dan makhluk yang merusak Anda untuk sesaat dikelilingi oleh api neraka. Makhluk itu harus melakukan lemparan penyelamatan ketangkasan. Dibutuhkan 2d10 kerusakan akibat kebakaran pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, kerusakan meningkat sebesar 1d10 untuk setiap slot level di atas 1." },
      { name: "Illusory Script", components: "S, M", desc: "Anda menulis di perkamen, kertas, atau bahan tulis lain yang sesuai dan memberinya ilusi kuat yang bertahan selama itu.\nBagi Anda dan makhluk apa pun yang Anda tunjuk saat mengucapkan mantra, tulisan itu tampak normal, ditulis di tangan Anda, dan menyampaikan makna apa pun yang Anda inginkan saat menulis teks tersebut. Bagi orang lain, tulisan tersebut tampak seolah-olah ditulis dalam naskah yang tidak diketahui atau ajaib yang tidak dapat dipahami. Alternatifnya, Anda dapat membuat tulisan tersebut tampak seperti pesan yang sama sekali berbeda, ditulis dengan tangan dan bahasa yang berbeda, meskipun bahasanya haruslah bahasa yang Anda ketahui.\nJika mantranya dihilangkan, naskah asli dan ilusinya akan hilang.\nMakhluk yang memiliki pandangan sejati dapat membaca pesan tersembunyi." },
      { name: "Protection from Evil and Good", components: "V, S, M", desc: "Hingga mantranya berakhir, satu makhluk yang Anda sentuh akan terlindungi dari jenis makhluk tertentu: aberasi, surgawi, elemen, fey, iblis, dan undead.\nPerlindungan memberikan beberapa manfaat. Makhluk dengan tipe seperti itu mempunyai kelemahan dalam serangan roll terhadap target. Targetnya juga tidak bisa terpesona, ditakuti, atau dirasuki oleh mereka. Jika target sudah terpesona, ketakutan, atau dirasuki oleh makhluk tersebut, target mempunyai keuntungan pada setiap lemparan penyelamatan baru terhadap efek yang relevan." },
      { name: "Unseen Servant", components: "V, S, M", desc: "Mantra ini menciptakan kekuatan yang tidak terlihat, tidak ada artinya, dan tidak berbentuk yang melakukan tugas-tugas sederhana sesuai perintah Anda hingga mantranya berakhir. Pelayan itu muncul di ruang kosong di tanah dalam jangkauannya. Ia memiliki AC 10, 1 hit point, dan Strength 2, dan tidak dapat menyerang. Jika poin hitnya turun menjadi 0, mantranya berakhir.\nSekali di setiap giliran Anda sebagai tindakan bonus, Anda dapat secara mental memerintahkan pelayan untuk bergerak hingga 15 kaki dan berinteraksi dengan suatu objek. Pelayan dapat melakukan tugas-tugas sederhana yang dapat dilakukan oleh pelayan manusia, seperti mengambil barang, membersihkan, memperbaiki, melipat pakaian, menyalakan api, menyajikan makanan, dan menuangkan anggur. Setelah Anda memberi perintah, pelayan akan menjalankan tugas dengan kemampuan terbaiknya hingga tugas selesai, lalu menunggu perintah Anda selanjutnya.\nJika Anda memerintahkan pelayan untuk melakukan tugas yang akan memindahkannya lebih dari 60 kaki dari Anda, mantranya akan berakhir." },
    ],
    Level2: [
      { name: "Darkness", components: "V, M", desc: "Kegelapan magis menyebar dari titik yang Anda pilih dalam jangkauan hingga memenuhi bola dengan radius 15 kaki selama durasi tersebut. Kegelapan menyebar ke segala penjuru. Makhluk dengan penglihatan gelap tidak dapat melihat menembus kegelapan ini, dan cahaya non-magis tidak dapat meneranginya.\nJika titik yang Anda pilih ada pada benda yang Anda pegang atau benda yang tidak dipakai atau dibawa, kegelapan akan memancar dari benda tersebut dan bergerak bersamanya. Menutupi seluruh sumber kegelapan dengan benda buram, seperti mangkuk atau helm, akan menghalangi kegelapan.\nJika salah satu area mantra ini tumpang tindih dengan area cahaya yang diciptakan oleh mantra level 2 atau lebih rendah, mantra yang menciptakan cahaya tersebut akan hilang." },
      { name: "Enthrall", components: "V, S", desc: "Anda merangkai rangkaian kata-kata yang mengganggu, menyebabkan makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan dan yang dapat mendengar Anda melakukan penyelamatan yang bijaksana. Makhluk apa pun yang tidak dapat dipesona akan berhasil dalam lemparan penyelamatan ini secara otomatis, dan jika Anda atau teman Anda melawan makhluk tersebut, ia memiliki keuntungan dalam penyelamatan tersebut. Jika penyelamatan gagal, target memiliki kelemahan pada pemeriksaan Kebijaksanaan (Persepsi) yang dilakukan untuk mengenali makhluk apa pun selain Anda hingga mantranya berakhir atau hingga target tidak dapat lagi mendengar Anda. Mantra berakhir jika Anda tidak mampu atau tidak dapat berbicara lagi." },
      { name: "Hold Person", components: "V, S, M", desc: "Pilih humanoid yang dapat Anda lihat dalam jangkauan. Target harus berhasil melakukan penyelamatan kebijaksanaan atau menjadi lumpuh selama jangka waktu tersebut. Di akhir setiap giliran, target dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, mantranya berakhir tepat sasaran.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu humanoid tambahan untuk setiap slot level di atas 2. Humanoid harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkannya." },
      { name: "Invisibility", components: "V, S, M", desc: "Makhluk yang Anda sentuh menjadi tidak terlihat sampai mantranya berakhir. Apapun yang dikenakan atau dibawa oleh target tidak akan terlihat selama berada pada orang yang menjadi target. Mantra berakhir untuk target yang menyerang atau mengeluarkan mantra.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Mirror Image", components: "V, S", desc: "Tiga duplikat ilusi diri Anda muncul di ruang Anda. Hingga mantranya berakhir, duplikatnya akan bergerak bersama Anda dan meniru tindakan Anda, berpindah posisi sehingga tidak mungkin melacak gambar mana yang asli. Anda dapat menggunakan tindakan Anda untuk menghilangkan duplikat ilusi.\nSetiap kali makhluk menargetkan Anda dengan serangan selama durasi mantra, putar d20 untuk menentukan apakah serangan tersebut menargetkan salah satu duplikat Anda.\nJika Anda memiliki tiga duplikat, Anda harus mendapatkan angka 6 atau lebih tinggi untuk mengubah target serangan menjadi duplikat. Dengan dua duplikat, Anda harus mendapatkan angka 8 atau lebih tinggi. Dengan satu duplikat, Anda harus mendapatkan angka 11 atau lebih tinggi.\nAC duplikat sama dengan 10 + pengubah Dexterity Anda. Jika serangan mengenai duplikat, duplikat tersebut akan hancur. Sebuah duplikat hanya dapat dihancurkan dengan serangan yang mengenainya. Itu mengabaikan semua kerusakan dan efek lainnya. Mantra berakhir ketika ketiga duplikatnya dihancurkan.\nMakhluk tidak terpengaruh oleh mantra ini jika ia tidak dapat melihat, jika ia mengandalkan indera selain penglihatan, seperti penglihatan buta, atau jika ia dapat melihat ilusi sebagai sesuatu yang salah, seperti penglihatan yang sebenarnya." },
      { name: "Misty Step", components: "V", desc: "Dikelilingi sebentar oleh kabut keperakan, Anda berteleportasi hingga 30 kaki ke ruang kosong yang dapat Anda lihat." },
      { name: "Ray of Enfeeblement", components: "V, S", desc: "Sinar hitam energi yang melemahkan muncul dari jari Anda menuju makhluk dalam jangkauan. Lakukan serangan mantra jarak jauh terhadap target. Saat terkena, target hanya memberikan setengah kerusakan dengan serangan senjata yang menggunakan Kekuatan hingga mantranya berakhir.\nDi akhir setiap giliran target, ia dapat melakukan penyelamatan konstitusi terhadap mantra tersebut. Jika berhasil, mantranya berakhir." },
      { name: "Shatter", components: "V, S, M", desc: "Suara dering keras yang tiba-tiba, sangat intens, muncul dari titik pilihan Anda dalam jangkauan. Setiap makhluk dalam bola berradius 10 kaki yang berpusat pada titik tersebut harus melakukan penyelamatan Konstitusi. Makhluk menerima kerusakan guntur 3d8 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil. Makhluk yang terbuat dari bahan anorganik seperti batu, kristal, atau logam memiliki kelemahan dalam penyelamatan ini.\nBenda non-magis yang tidak dipakai atau dibawa juga akan mengalami kerusakan jika berada dalam area mantra.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan mantra meningkat sebesar 1d8 untuk setiap level slot mantra 2 yang lebih tinggi." },
      { name: "Spider Climb", components: "V, S, M", desc: "Hingga mantranya berakhir, satu makhluk yang Anda sentuh memperoleh kemampuan untuk bergerak ke atas, ke bawah, dan melintasi permukaan vertikal dan terbalik di sepanjang langit-langit, sambil membiarkan tangannya bebas. Target juga memperoleh kecepatan pendakian yang sama dengan kecepatan berjalannya." },
      { name: "Suggestion", components: "V, M", desc: "Anda menyarankan suatu rangkaian aktivitas (terbatas pada satu atau dua kalimat) dan secara ajaib memengaruhi makhluk yang dapat Anda lihat dalam jangkauan yang dapat mendengar dan memahami Anda. Makhluk yang tidak bisa dipesona akan kebal terhadap efek ini. Saran tersebut harus diungkapkan sedemikian rupa agar tindakan yang diambil terdengar masuk akal. Meminta makhluk itu untuk menusuk dirinya sendiri, melemparkan dirinya ke tombak, mengorbankan dirinya sendiri, atau melakukan tindakan berbahaya lainnya akan mengakhiri mantranya.\nTargetnya harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, ia akan melakukan tindakan yang Anda jelaskan dengan kemampuan terbaiknya. Tindakan yang disarankan dapat berlanjut sepanjang durasi. Jika aktivitas yang disarankan dapat diselesaikan dalam waktu yang lebih singkat, mantra akan berakhir saat subjek menyelesaikan apa yang diminta.\nAnda juga dapat menentukan kondisi yang akan memicu aktivitas khusus selama durasi tersebut. Misalnya, Anda mungkin menyarankan agar seorang kesatria memberikan kuda perangnya kepada pengemis pertama yang ditemuinya. Jika kondisi tidak terpenuhi sebelum mantra berakhir, aktivitas tidak akan dilakukan.\nJika Anda atau salah satu teman Anda merusak target, mantranya akan berakhir." },
    ],
    Level3: [
      { name: "Counterspell", components: "S", desc: "Anda mencoba mengganggu makhluk dalam proses merapal mantra. Jika makhluk tersebut mengeluarkan mantra level 3 atau lebih rendah, mantranya gagal dan tidak berpengaruh. Jika ia mengeluarkan mantra level 4 atau lebih tinggi, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika berhasil, mantra makhluk itu gagal dan tidak berpengaruh.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, mantra yang terputus tidak akan berpengaruh jika levelnya kurang dari atau sama dengan level slot mantra yang Anda gunakan." },
      { name: "Dispel Magic", components: "V, S", desc: "Pilih satu makhluk, objek, atau efek magis dalam jangkauan. Mantra level 3 atau lebih rendah pada target akan berakhir. Untuk setiap mantra level 4 atau lebih tinggi pada target, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika pemeriksaan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda secara otomatis mengakhiri efek mantra pada target jika level mantra sama dengan atau kurang dari level slot mantra yang Anda gunakan." },
      { name: "Fear", components: "V, S, M", desc: "Anda memproyeksikan gambaran khayalan tentang ketakutan terburuk suatu makhluk. Setiap makhluk dalam kerucut setinggi 30 kaki harus berhasil menyelamatkan lemparan atau menjatuhkan apa pun yang dipegangnya dan menjadi ketakutan selama itu.\nSaat ketakutan dengan mantra ini, makhluk harus mengambil tindakan Dash dan menjauh dari Anda melalui rute teraman yang tersedia di setiap belokannya, kecuali tidak ada tempat untuk bergerak. Jika makhluk tersebut mengakhiri gilirannya di lokasi yang tidak terlihat oleh Anda, makhluk tersebut dapat melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan berhasil, mantra untuk makhluk itu berakhir." },
      { name: "Fly", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia. Target memperoleh kecepatan terbang 60 kaki selama durasi tersebut. Saat mantranya berakhir, target akan jatuh jika masih tinggi, kecuali jika dapat menghentikan jatuhnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 3." },
      { name: "Gaseous Form", components: "V, S, M", desc: "Anda mengubah makhluk yang Anda sentuh, beserta segala sesuatu yang dikenakan dan dibawanya, menjadi awan berkabut selama itu. Mantra berakhir jika poin hit makhluk itu turun menjadi 0. Makhluk inkorporeal tidak terpengaruh.\nSedangkan dalam bentuk ini, satu-satunya cara pergerakan target adalah kecepatan terbang 10 kaki. Targetnya bisa masuk dan menempati ruang makhluk lain. Target memiliki ketahanan terhadap kerusakan non-magis, dan memiliki keunggulan dalam Kekuatan, Ketangkasan, dan lemparan hemat konstitusi. Targetnya dapat melewati lubang kecil, bukaan sempit, dan bahkan retakan belaka, meskipun cairan tersebut diperlakukan seolah-olah permukaan padat. Target tidak bisa jatuh dan tetap melayang di udara bahkan ketika terkena stun atau tidak berdaya.\nSedangkan dalam bentuk awan berkabut, target tidak dapat berbicara atau memanipulasi objek, dan objek apa pun yang dibawa atau dipegangnya tidak dapat dijatuhkan, digunakan, atau berinteraksi dengannya. Target tidak dapat menyerang atau mengeluarkan mantra." },
      { name: "Hypnotic Pattern", components: "S, M", desc: "Anda membuat pola warna yang berputar-putar yang terjalin di udara di dalam kubus berukuran 30 kaki dalam jangkauan. Pola itu muncul sesaat dan menghilang. Setiap makhluk di area tersebut yang melihat pola tersebut harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, makhluk itu menjadi terpesona selama durasi tersebut. Saat terpesona oleh mantra ini, makhluk itu tidak berdaya dan memiliki kecepatan 0.\nMantra berakhir untuk makhluk yang terkena dampak jika ia mengalami kerusakan atau jika orang lain menggunakan tindakan untuk mengguncang makhluk itu dari pingsannya." },
      { name: "Magic Circle", components: "V, S, M", desc: "Anda membuat silinder energi magis dengan radius 10 kaki dan tinggi 20 kaki yang berpusat pada suatu titik di tanah yang dapat Anda lihat dalam jangkauan. Rune bercahaya muncul setiap kali silinder berpotongan dengan lantai atau permukaan lainnya.\nPilih satu atau lebih jenis makhluk berikut: selestial, elemental, fey, iblis, atau undead. Lingkaran mempengaruhi makhluk dari tipe yang dipilih dengan cara berikut:\n- Makhluk itu tidak bisa dengan sukarela memasuki silinder dengan cara non-magis. Jika makhluk tersebut mencoba menggunakan teleportasi atau perjalanan antarplanar untuk melakukannya, ia harus berhasil melakukan lemparan penyelamatan karisma terlebih dahulu.\n- Makhluk tersebut memiliki kelemahan dalam serangan berguling terhadap target di dalam silinder.\n- Target di dalam silinder tidak dapat dipesona, ditakuti, atau dirasuki oleh makhluk tersebut.\nSaat Anda mengucapkan mantra ini, Anda dapat memilih untuk membuat sihirnya beroperasi ke arah sebaliknya, mencegah makhluk bertipe tertentu meninggalkan silinder dan melindungi target di luarnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, durasinya bertambah 1 jam untuk setiap slot level di atas 3." },
      { name: "Major Image", components: "V, S, M", desc: "Anda membuat gambar suatu benda, makhluk, atau fenomena nyata lainnya yang ukurannya tidak lebih besar dari kubus berukuran 20 kaki. Gambar muncul di tempat yang dapat Anda lihat dalam jangkauan dan berlangsung selama durasi tersebut. Tampaknya benar-benar nyata, termasuk suara, bau, dan suhu yang sesuai dengan benda yang digambarkan. Anda tidak dapat menciptakan panas atau dingin yang cukup untuk menyebabkan kerusakan, suara yang cukup keras untuk menyebabkan kerusakan akibat petir atau membuat tuli makhluk, atau bau yang dapat membuat makhluk sakit (seperti bau troglodyte).\nSelama Anda berada dalam jangkauan ilusi, Anda dapat menggunakan tindakan Anda untuk menyebabkan gambar berpindah ke tempat lain dalam jangkauan. Saat gambar berpindah lokasi, Anda dapat mengubah tampilannya sehingga gerakannya tampak natural pada gambar. Misalnya, jika Anda membuat gambar makhluk dan memindahkannya, Anda dapat mengubah gambar tersebut sehingga tampak seperti sedang berjalan. Demikian pula, Anda dapat menyebabkan ilusi mengeluarkan suara yang berbeda pada waktu yang berbeda, bahkan membuatnya melakukan percakapan, misalnya.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika suatu makhluk mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut, dan kualitas indra lainnya menjadi samar bagi makhluk tersebut.\nLevel Tinggi: Saat Anda merapalkan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, mantra tersebut akan bertahan hingga hilang, tanpa memerlukan konsentrasi Anda." },
      { name: "Remove Curse", components: "V, S", desc: "Dengan sentuhan Anda, semua kutukan yang memengaruhi satu makhluk atau objek berakhir. Jika benda tersebut merupakan benda sihir terkutuk, kutukannya tetap ada, tetapi mantranya merusak attunement pemiliknya terhadap benda tersebut sehingga dapat dikeluarkan atau dibuang." },
      { name: "Tongues", components: "V, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk memahami bahasa lisan apa pun yang didengarnya. Terlebih lagi, ketika target berbicara, makhluk apa pun yang mengetahui setidaknya satu bahasa dan dapat mendengar target akan memahami apa yang dikatakannya." },
      { name: "Vampiric Touch", components: "V, S", desc: "Sentuhan tangan Anda yang dilingkari bayangan dapat menyedot kekuatan hidup orang lain untuk menyembuhkan luka Anda. Lakukan serangan mantra jarak dekat terhadap makhluk dalam jangkauan Anda. Saat terkena, target menerima 3d6 kerusakan nekrotik, dan Anda mendapatkan kembali poin serangan yang setara dengan setengah jumlah kerusakan nekrotik yang diberikan. Hingga mantranya berakhir, Anda dapat melakukan serangan lagi di setiap giliran Anda sebagai suatu tindakan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 3." },
    ],
    Level4: [
      { name: "Banishment", components: "V, S, M", desc: "Anda mencoba mengirim satu makhluk yang dapat Anda lihat dalam jangkauannya ke alam eksistensi lain. Targetnya harus berhasil dalam penyelamatan karisma atau diasingkan.\nJika targetnya berasal dari alam eksistensi yang Anda tempati, Anda membuang target tersebut ke demiplane yang tidak berbahaya. Saat berada di sana, targetnya tidak berdaya. Target tetap di sana sampai mantranya berakhir, pada saat itu target muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi.\nJika target berasal dari alam eksistensi yang berbeda dari tempat Anda berada, target akan dibuang dengan suara letupan samar, dan kembali ke alam asalnya. Jika mantra berakhir sebelum 1 menit berlalu, target akan muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi. Jika tidak, targetnya tidak akan kembali.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 4." },
      { name: "Blight", components: "V, S", desc: "Energi necromantic menyapu makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan, menguras kelembapan dan vitalitas darinya. Targetnya harus melakukan penyelamatan konstitusi. Target menerima 8d8 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nJika Anda menargetkan makhluk tumbuhan atau tumbuhan ajaib, lemparan penyelamatan akan merugikan, dan mantranya akan memberikan kerusakan maksimal padanya.\nJika Anda menargetkan tanaman non-magis yang bukan makhluk, seperti pohon atau semak, hal tersebut tidak akan menjadi solusi penyelamatan; itu hanya layu dan mati.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 ke atas, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas ke-4." },
      { name: "Dimension Door", components: "V", desc: "Anda berteleportasi dari lokasi Anda saat ini ke tempat lain dalam jangkauan. Anda tiba di tempat yang diinginkan. Ini bisa berupa tempat yang bisa Anda lihat, yang bisa Anda visualisasikan, atau yang bisa Anda gambarkan dengan menyatakan jarak dan arah, seperti \"200 kaki lurus ke bawah\" atau \"ke atas ke arah barat laut dengan sudut 45 derajat, 300 kaki\".\nAnda boleh membawa barang selama beratnya tidak melebihi apa yang dapat Anda bawa. Anda juga dapat membawa satu makhluk berukuran Anda atau lebih kecil yang membawa perlengkapan sesuai daya dukungnya. Makhluk itu harus berada dalam jarak 5 kaki dari Anda saat Anda mengucapkan mantra ini.\nJika Anda akan tiba di tempat yang sudah ditempati oleh suatu benda atau makhluk, Anda dan makhluk apa pun yang bepergian bersama Anda masing-masing akan menerima kerusakan kekuatan 4d6, dan mantra tersebut gagal untuk memindahkan Anda." },
      { name: "Hallucinatory Terrain", components: "V, S, M", desc: "Anda membuat medan alami dalam kubus berukuran 150 kaki dalam jangkauan tampilan, suara, dan aroma seperti medan alami lainnya. Dengan demikian, lapangan terbuka atau jalan dapat dibuat menyerupai rawa, bukit, jurang, atau medan lain yang sulit atau tidak dapat dilalui. Sebuah kolam dapat dibuat tampak seperti padang rumput, jurang seperti lereng yang landai, atau selokan yang dipenuhi bebatuan seperti jalan yang lebar dan mulus. Struktur, peralatan, dan makhluk yang diproduksi di dalam area tersebut tidak berubah tampilannya.\nKarakteristik sentuhan medan tidak berubah, sehingga makhluk yang memasuki area tersebut kemungkinan besar dapat melihat melalui ilusi. Jika perbedaannya tidak terlihat jelas jika disentuh, makhluk yang memeriksa ilusi dengan cermat dapat mencoba melakukan pemeriksaan Intelijen (Investigasi) terhadap mantra Anda, simpan DC untuk tidak mempercayainya. Makhluk yang memahami ilusi apa adanya, melihatnya sebagai gambaran samar yang ditumpangkan di medan." },
    ],
    Level5: [
      { name: "Contact Other Plane", components: "V", desc: "Anda secara mental menghubungi seorang setengah dewa, roh orang bijak yang telah lama meninggal, atau entitas misterius lainnya dari alam lain. Menghubungi kecerdasan ekstraplanar ini dapat membuat Anda tegang atau bahkan patah semangat. Saat Anda mengucapkan mantra ini, lakukan lemparan penyelamatan intelijen DC 15. Jika gagal, Anda menerima kerusakan psikis 6d6 dan menjadi gila sampai Anda menyelesaikan istirahat panjang. Meskipun gila, Anda tidak dapat mengambil tindakan, tidak dapat memahami apa yang dikatakan makhluk lain, tidak dapat membaca, dan hanya berbicara omong kosong. Mantra pemulihan yang lebih besar yang diberikan kepada Anda akan mengakhiri efek ini.\nJika penyimpanan berhasil, Anda dapat mengajukan hingga lima pertanyaan kepada entitas. Anda harus mengajukan pertanyaan Anda sebelum mantranya berakhir. GM menjawab setiap pertanyaan dengan satu kata, seperti \"ya\", \"tidak\", \"mungkin\", \"tidak pernah\", \"tidak relevan\", atau \"tidak jelas\" (jika entitas tidak mengetahui jawaban atas pertanyaan tersebut). Jika jawaban satu kata akan menyesatkan, GM mungkin akan menawarkan kalimat pendek sebagai jawaban." },
      { name: "Dream", components: "V, S, M", desc: "Mantra ini membentuk mimpi makhluk. Pilih makhluk yang Anda kenal sebagai target mantra ini. Targetnya harus berada pada alam eksistensi yang sama dengan Anda. Makhluk yang tidak tidur, seperti elf, tidak dapat dihubungi dengan mantra ini. Anda, atau makhluk yang ingin Anda sentuh, memasuki kondisi trance, bertindak sebagai pembawa pesan.\nSaat berada dalam kondisi trance, pembawa pesan sadar akan sekelilingnya, namun tidak dapat mengambil tindakan atau bergerak.\nJika target tertidur, pembawa pesan muncul dalam mimpi target dan dapat berkomunikasi dengan target selama target tetap tertidur, selama durasi mantra. Pembawa pesan juga dapat membentuk lingkungan mimpi, menciptakan pemandangan alam, objek, dan gambar lainnya. Pembawa pesan dapat keluar dari kondisi trance kapan saja, mengakhiri efek mantranya lebih awal. Target mengingat mimpinya dengan sempurna saat bangun tidur. Jika target terjaga saat Anda merapal mantra, pembawa pesan mengetahuinya, dan dapat mengakhiri trance (dan mantranya) atau menunggu target tertidur, dan pada saat itulah pembawa pesan muncul dalam mimpi target.\nAnda dapat membuat pengirim pesan tampak mengerikan dan menakutkan bagi targetnya. Jika Anda melakukannya, pembawa pesan dapat menyampaikan pesan yang tidak lebih dari sepuluh kata dan kemudian target harus melakukan penyelamatan yang bijaksana. Jika penyelamatan gagal, gema monstrositas fantastik menimbulkan mimpi buruk yang berlangsung selama durasi tidur target dan mencegah target mendapatkan manfaat apa pun dari istirahat tersebut. Selain itu, ketika target terbangun, ia akan menerima 3d6 psychic damage.\nJika Anda memiliki bagian tubuh, seikat rambut, potongan kuku, atau bagian serupa dari tubuh target, target melakukan penyelamatan dengan merugikan." },
      { name: "Hold Monster", components: "V, S, M", desc: "Pilih makhluk yang dapat Anda lihat dan jangkau. Target harus melakukan lemparan penyelamatan Kebijaksanaan atau menjadi lumpuh selama durasi mantra. Mantra ini tidak berpengaruh terhadap undead. Di akhir setiap putaran, target dapat melakukan penyelamatan baru atas Kebijaksanaan. Jika berhasil, mantranya berakhir untuk makhluk itu.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan lokasi level 6 atau lebih tinggi, Anda dapat menargetkan makhluk tambahan untuk setiap level lokasi di luar lokasi kelima. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Scrying", components: "V, S, M", desc: "Anda dapat melihat dan mendengar makhluk tertentu yang Anda pilih yang berada pada alam eksistensi yang sama dengan Anda. Target harus melakukan lemparan penyelamatan yang bijaksana, yang dimodifikasi oleh seberapa baik Anda mengenal target dan jenis hubungan fisik yang Anda miliki dengannya. Jika target mengetahui Anda merapalkan mantra ini, target dapat gagal melakukan penyelamatan secara sukarela jika ingin diamati.\n| Pengetahuan | Simpan Pengubah |\n|---|---|\n| Bekas (Anda pernah mendengar tentang targetnya) | +5 |\n| Langsung (Anda sudah memenuhi target) | +0 |\n| Familiar (Anda tahu targetnya dengan baik) | -5 |\n\n| Koneksi | Simpan Pengubah |\n|---|---|\n| Kemiripan atau gambar | -2 |\n| Kepemilikan atau pakaian | -4 |\n| Bagian badan, seikat rambut, secuil kuku, atau sejenisnya | -10 |\nJika penyelamatan berhasil, target tidak terpengaruh, dan Anda tidak dapat menggunakan mantra ini lagi selama 24 jam.\nJika penyelamatan gagal, mantra tersebut menciptakan sensor tak terlihat dalam jarak 10 kaki dari target. Anda dapat melihat dan mendengar melalui sensor seolah-olah Anda berada di sana. Sensor bergerak mengikuti target, tetap berada dalam jarak 10 kaki selama durasi tersebut. Makhluk yang dapat melihat objek tak kasat mata melihat sensornya sebagai bola bercahaya seukuran kepalan tangan Anda.\nDaripada mengincar makhluk, kamu bisa memilih lokasi yang pernah kamu lihat sebelumnya sebagai target mantra ini. Ketika Anda melakukannya, sensor muncul di lokasi tersebut dan tidak bergerak." },
    ],
    Level6: [
      { name: "Circle of Death", components: "V, S, M", desc: "Sebuah bola energi negatif muncul dalam radius 60 kaki dari suatu titik dalam jangkauan. Setiap makhluk di area itu harus melakukan penyelamatan konstitusi. Target menerima 8d6 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, kerusakan meningkat sebesar 2d6 untuk setiap slot level di atas 6." },
      { name: "Conjure Fey", components: "V, S", desc: "Anda memanggil makhluk berbulu dengan peringkat tantangan 6 atau lebih rendah, atau roh berbulu yang berbentuk binatang dengan peringkat tantangan 6 atau lebih rendah. Itu muncul di ruang kosong yang dapat Anda lihat dalam jangkauan. Makhluk fey menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nMakhluk berbulu itu bersahabat dengan Anda dan teman Anda selama ini. Gulung inisiatif untuk makhluk yang mempunyai gilirannya sendiri. Ia mematuhi perintah verbal apa pun yang Anda keluarkan (Anda tidak perlu melakukan tindakan apa pun), selama perintah tersebut tidak melanggar kesejajarannya. Jika Anda tidak memberikan perintah apa pun kepada makhluk berbulu itu, ia akan mempertahankan diri dari makhluk bermusuhan, tetapi sebaliknya tidak mengambil tindakan apa pun.\nJika konsentrasimu terganggu, makhluk berbulu itu tidak akan hilang. Sebaliknya, Anda kehilangan kendali atas makhluk berbulu itu, ia menjadi bermusuhan terhadap Anda dan teman Anda, dan mungkin menyerang. Makhluk berbulu yang tidak terkendali tidak dapat Anda hilangkan, dan ia menghilang 1 jam setelah Anda memanggilnya.\nGM mempunyai statistik makhluk buas itu.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, peringkat tantangan meningkat sebesar 1 untuk setiap slot level di atas 6." },
      { name: "Create Undead", components: "V, S, M", desc: "Anda hanya bisa mengucapkan mantra ini di malam hari. Pilih hingga tiga mayat humanoid Sedang atau Kecil dalam jangkauan. Setiap mayat menjadi hantu di bawah kendali Anda. (GM memiliki statistik permainan untuk makhluk-makhluk ini.)\nSebagai tindakan bonus di setiap giliran Anda, Anda dapat secara mental memerintahkan makhluk apa pun yang Anda animasikan dengan mantra ini jika makhluk itu berada dalam jarak 120 kaki dari Anda (jika Anda mengendalikan beberapa makhluk, Anda dapat memerintahkan salah satu atau semuanya secara bersamaan, mengeluarkan perintah yang sama untuk masing-masing makhluk). Anda memutuskan tindakan apa yang akan diambil makhluk itu dan ke mana ia akan bergerak pada giliran berikutnya, atau Anda dapat mengeluarkan perintah umum, seperti menjaga ruangan atau koridor tertentu. Jika Anda tidak mengeluarkan perintah, makhluk itu hanya akan mempertahankan diri dari makhluk musuh. Setelah diberi perintah, makhluk tersebut terus mengikutinya hingga tugasnya selesai.\nMakhluk itu berada di bawah kendali Anda selama 24 jam, setelah itu ia berhenti mematuhi perintah apa pun yang Anda berikan. Untuk mempertahankan kendali atas makhluk tersebut selama 24 jam berikutnya, Anda harus mengucapkan mantra ini pada makhluk tersebut sebelum periode 24 jam saat ini berakhir. Penggunaan mantra ini menegaskan kembali kendali Anda atas hingga tiga makhluk yang telah Anda animasikan dengan mantra ini, daripada menganimasikan makhluk baru.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 7, Anda dapat menghidupkan atau menegaskan kembali kendali atas empat hantu. Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat 8, Anda dapat menganimasikan atau menegaskan kembali kendali atas lima ghoul atau dua ghast atau wight. Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat 9, Anda dapat menganimasikan atau menegaskan kembali kendali atas enam hantu, tiga hantu atau bobot, atau dua mumi." },
      { name: "Eyebite", components: "V, S", desc: "Selama durasi mantranya, matamu menjadi kehampaan bertinta yang dipenuhi kekuatan menakutkan. Satu makhluk pilihan Anda dalam jarak 60 kaki dari Anda yang dapat Anda lihat harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau terpengaruh oleh salah satu efek pilihan Anda berikut selama durasi tersebut. Pada setiap giliranmu hingga mantra berakhir, kamu dapat menggunakan tindakanmu untuk menargetkan makhluk lain tetapi tidak dapat menargetkan makhluk lagi jika makhluk tersebut berhasil melakukan penyelamatan terhadap casting eyebite ini.\n***Tidur.*** Target jatuh pingsan. Ia akan bangun jika ia mengalami kerusakan atau jika makhluk lain menggunakan aksinya untuk membangunkan orang yang tidur.\n***Panik.*** Targetnya takut padamu. Di setiap belokannya, makhluk yang ketakutan harus mengambil tindakan Dash dan menjauh dari Anda melalui rute teraman dan terpendek yang tersedia, kecuali tidak ada tempat untuk bergerak. Jika target berpindah ke tempat setidaknya 60 kaki dari Anda di mana ia tidak dapat lagi melihat Anda, efek ini akan berakhir.\n***Muak.*** Target memiliki kelemahan pada serangan dan pemeriksaan kemampuan. Di akhir setiap putarannya, ia dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, efeknya berakhir." },
      { name: "Flesh to Stone", components: "V, S, M", desc: "Anda mencoba mengubah satu makhluk yang dapat Anda lihat dalam jangkauan menjadi batu. Jika tubuh target terbuat dari daging, makhluk tersebut harus melakukan penyelamatan konstitusi. Pada penyelamatan yang gagal, ia tertahan karena dagingnya mulai mengeras. Jika penyelamatan berhasil, makhluk itu tidak terpengaruh.\nMakhluk yang terkekang oleh mantra ini harus melakukan penyelamatan konstitusi lagi di akhir setiap putarannya. Jika berhasil menyelamatkan mantra ini tiga kali, mantranya berakhir. Jika gagal menyelamatkannya tiga kali, ia akan berubah menjadi batu dan mengalami kondisi membatu selama durasi tersebut. Keberhasilan dan kegagalan tidak harus terjadi secara berurutan; lacak keduanya sampai target mengumpulkan tiga jenis.\nJika makhluk itu rusak secara fisik saat membatu, ia akan menderita kelainan serupa jika kembali ke keadaan semula.\nJika Anda mempertahankan konsentrasi pada mantra ini selama mungkin, makhluk itu akan berubah menjadi batu hingga efeknya hilang." },
      { name: "Mass Suggestion", components: "V, M", desc: "Anda menyarankan serangkaian aktivitas (terbatas pada satu atau dua kalimat) dan secara ajaib memengaruhi hingga dua belas makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan dan yang dapat mendengar serta memahami Anda. Makhluk yang tidak bisa dipesona akan kebal terhadap efek ini. Saran tersebut harus diungkapkan sedemikian rupa agar tindakan yang diambil terdengar masuk akal. Meminta makhluk itu untuk menusuk dirinya sendiri, melemparkan dirinya ke tombak, mengorbankan dirinya sendiri, atau melakukan tindakan berbahaya lainnya secara otomatis meniadakan efek mantranya.\nSetiap target harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, ia akan melakukan tindakan yang Anda jelaskan dengan kemampuan terbaiknya. Tindakan yang disarankan dapat berlanjut sepanjang durasi. Jika aktivitas yang disarankan dapat diselesaikan dalam waktu yang lebih singkat, mantra akan berakhir saat subjek menyelesaikan apa yang diminta.\nAnda juga dapat menentukan kondisi yang akan memicu aktivitas khusus selama durasi tersebut. Misalnya, Anda mungkin menyarankan agar sekelompok tentara memberikan seluruh uangnya kepada pengemis pertama yang mereka temui. Jika kondisi tidak terpenuhi sebelum mantra berakhir, aktivitas tidak dilakukan.\nJika Anda atau salah satu teman Anda merusak makhluk yang terkena mantra ini, mantra untuk makhluk itu akan berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7, durasinya adalah 10 hari. Saat Anda menggunakan slot mantra level 8, durasinya adalah 30 hari. Saat Anda menggunakan slot mantra level 9, durasinya adalah satu tahun dan satu hari." },
      { name: "True Seeing", components: "V, S, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk melihat segala sesuatu sebagaimana adanya. Selama durasi tersebut, makhluk tersebut memiliki penglihatan yang sebenarnya, mengetahui pintu rahasia yang disembunyikan oleh sihir, dan dapat melihat ke dalam Alam Ethereal, semuanya hingga jarak 120 kaki." },
    ],
    Level7: [
      { name: "Etherealness", components: "V, S", desc: "Anda melangkah ke wilayah perbatasan Pesawat Ethereal, di area yang tumpang tindih dengan pesawat Anda saat ini. Anda tetap berada di Border Ethereal selama atau sampai Anda menggunakan tindakan Anda untuk menghilangkan mantranya. Selama waktu ini, Anda dapat bergerak ke segala arah. Jika Anda bergerak ke atas atau ke bawah, setiap gerakan membutuhkan satu kaki ekstra. Anda dapat melihat dan mendengar pesawat asal Anda, tetapi segala sesuatu di sana tampak abu-abu, dan Anda tidak dapat melihat apa pun yang jaraknya lebih dari 60 kaki.\nSelama berada di Alam Ethereal, Anda hanya dapat mempengaruhi dan dipengaruhi oleh makhluk lain di alam tersebut. Makhluk yang tidak berada di Alam Ethereal tidak dapat melihat Anda dan tidak dapat berinteraksi dengan Anda, kecuali jika kemampuan atau sihir khusus memberi mereka kemampuan untuk melakukannya.\nAnda mengabaikan semua objek dan efek yang tidak ada di Alam Ethereal, memungkinkan Anda bergerak melalui objek yang Anda lihat di bidang asal Anda.\nKetika mantranya berakhir, kamu segera kembali ke pesawat asalmu di tempat yang kamu tempati saat ini. Jika Anda menempati tempat yang sama dengan benda padat atau makhluk saat hal ini terjadi, Anda akan segera diarahkan ke ruang kosong terdekat yang dapat Anda tempati dan menerima kerusakan kekuatan yang setara dengan dua kali jumlah kaki yang Anda gerakkan.\nMantra ini tidak berpengaruh jika kamu mengucapkannya saat kamu berada di Alam Ethereal atau di alam yang tidak membatasinya, seperti salah satu Alam Luar.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 8 atau lebih tinggi, Anda dapat menargetkan hingga tiga makhluk yang bersedia (termasuk Anda) untuk setiap slot level di atas 7. Makhluk tersebut harus berada dalam jarak 10 kaki dari Anda saat Anda mengucapkan mantra." },
      { name: "Finger of Death", components: "V, S", desc: "Anda mengirimkan energi negatif ke seluruh makhluk yang dapat Anda lihat dalam jangkauannya, menyebabkan rasa sakit yang membakar. Targetnya harus melakukan penyelamatan konstitusi. Dibutuhkan 7d8 + 30 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nHumanoid yang terbunuh oleh mantra ini muncul di awal giliran Anda berikutnya sebagai zombie yang secara permanen berada di bawah komando Anda, mengikuti perintah lisan Anda dengan kemampuan terbaiknya." },
      { name: "Forcecage", components: "V, S, M", desc: "Penjara berbentuk kubus yang tidak bergerak, tidak terlihat, dan terdiri dari kekuatan magis muncul di sekitar area yang Anda pilih dalam jangkauannya. Penjara bisa berupa sangkar atau kotak padat, sesuai pilihan Anda.\nPenjara berbentuk sangkar bisa berukuran hingga 20 kaki di sisinya dan terbuat dari jeruji berdiameter 1/2 inci dengan jarak 1/2 inci.\nPenjara berbentuk kotak bisa memiliki tinggi hingga 10 kaki di sisinya, menciptakan penghalang kokoh yang mencegah benda apa pun melewatinya dan memblokir mantra apa pun yang dilemparkan ke dalam atau keluar dari area tersebut.\nSaat Anda mengucapkan mantra, makhluk apa pun yang sepenuhnya berada di dalam area kandang akan terperangkap. Makhluk yang hanya berada sebagian di dalam area, atau yang terlalu besar untuk dapat masuk ke dalam area, akan didorong menjauh dari pusat area hingga mereka benar-benar berada di luar area.\nMakhluk yang berada di dalam sangkar tidak bisa keluar darinya dengan cara non-magis. Jika makhluk tersebut mencoba menggunakan teleportasi atau perjalanan antarplanar untuk meninggalkan kandang, ia harus melakukan lemparan penyelamatan karisma terlebih dahulu. Jika berhasil, makhluk itu dapat menggunakan sihir itu untuk keluar dari kandang. Jika gagal, makhluk tersebut tidak dapat keluar dari kandang dan menyia-nyiakan penggunaan mantra atau efeknya. Sangkar itu juga meluas hingga ke Alam Ethereal, menghalangi perjalanan halus.\nMantra ini tidak bisa dihilangkan dengan sihir dispel." },
      { name: "Plane Shift", components: "V, S, M", desc: "Anda dan hingga delapan makhluk bersedia yang bergandengan tangan dalam lingkaran akan dipindahkan ke alam eksistensi lain. Anda dapat menentukan tujuan target secara umum, seperti Kota Kuningan di Alam Elemen Api atau istana Dispater di Sembilan Neraka tingkat kedua, dan Anda muncul di atau dekat tujuan tersebut. Jika Anda mencoba mencapai Kota Kuningan, misalnya, Anda mungkin tiba di Jalan Baja, sebelum Gerbang Abu, atau melihat kota dari seberang Lautan Api, sesuai kebijaksanaan GM.\nAlternatifnya, jika Anda mengetahui urutan sigil lingkaran teleportasi di alam eksistensi lain, mantra ini dapat membawa Anda ke lingkaran itu. Jika lingkaran teleportasi terlalu kecil untuk menampung semua makhluk yang Anda pindahkan, mereka akan muncul di ruang kosong terdekat di sebelah lingkaran.\nAnda dapat menggunakan mantra ini untuk mengusir makhluk yang tidak mau ke pesawat lain. Pilih makhluk dalam jangkauan Anda dan lakukan serangan mantra jarak dekat terhadapnya. Saat terkena, makhluk tersebut harus melakukan lemparan penyelamatan karisma. Jika makhluk tersebut gagal dalam penyelamatan ini, ia akan dipindahkan ke lokasi acak di alam keberadaan yang Anda tentukan. Makhluk yang dipindahkan harus menemukan jalannya sendiri kembali ke alam keberadaan Anda saat ini." },
    ],
    Level8: [
      { name: "Demiplane", components: "S", desc: "Anda membuat pintu bayangan pada permukaan padat datar yang dapat Anda lihat dalam jangkauan. Pintunya cukup besar untuk memungkinkan makhluk Medium melewatinya tanpa hambatan. Saat dibuka, pintunya mengarah ke demiplane yang tampak seperti ruangan kosong berukuran 30 kaki di setiap dimensinya, terbuat dari kayu atau batu. Ketika mantranya berakhir, pintunya menghilang, dan makhluk atau benda apa pun di dalam demiplane tetap terperangkap di sana, karena pintu itu juga menghilang dari sisi lain.\nSetiap kali Anda mengucapkan mantra ini, Anda dapat membuat demiplane baru, atau menghubungkan pintu bayangan ke demiplane yang Anda buat dengan pengucapan mantra ini sebelumnya. Selain itu, jika Anda mengetahui sifat dan isi demiplane yang diciptakan oleh makhluk lain yang merapal mantra ini, Anda dapat menghubungkan pintu bayangan ke demiplane tersebut." },
      { name: "Dominate Monster", components: "V, S", desc: "Anda mencoba memperdaya makhluk yang dapat Anda lihat dalam jangkauan. Ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Jika Anda atau makhluk yang bersahabat dengan Anda melawannya, ia memiliki keuntungan dalam penyelamatan.\nMeskipun makhluk itu terpesona, Anda memiliki hubungan telepati dengannya selama Anda berdua berada di alam eksistensi yang sama. Anda dapat menggunakan tautan telepati ini untuk mengeluarkan perintah kepada makhluk itu saat Anda sadar (tidak perlu tindakan apa pun), yang akan dipatuhinya sebaik mungkin. Anda dapat menentukan tindakan yang sederhana dan umum, seperti \"Serang makhluk itu\", \"Lari ke sana\", atau \"Ambil objek itu\". Jika makhluk tersebut menyelesaikan perintahnya dan tidak menerima arahan lebih lanjut dari Anda, ia akan mempertahankan dan mempertahankan dirinya dengan kemampuan terbaiknya.\nAnda dapat menggunakan tindakan Anda untuk mengambil kendali total dan tepat terhadap target. Hingga akhir giliran Anda berikutnya, makhluk itu hanya mengambil tindakan yang Anda pilih, dan tidak melakukan apa pun yang tidak Anda izinkan. Selama waktu ini, Anda juga dapat menyebabkan makhluk tersebut menggunakan reaksi, namun hal ini mengharuskan Anda menggunakan reaksi Anda sendiri juga.\nSetiap kali target menerima kerusakan, ia membuat lemparan penyelamatan kebijaksanaan baru terhadap mantra tersebut. Jika lemparan penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini dengan slot mantra level 9, durasinya adalah konsentrasi, hingga 8 jam." },
      { name: "Feeblemind", components: "V, S, M", desc: "Anda meledakkan pikiran makhluk yang dapat Anda lihat dalam jangkauan, mencoba menghancurkan kecerdasan dan kepribadiannya. Target menerima kerusakan psikis 4d6 dan harus melakukan lemparan penyelamatan intelijen.\nJika penyelamatan gagal, skor Kecerdasan dan Karisma makhluk tersebut menjadi 1. Makhluk tersebut tidak dapat merapal mantra, mengaktifkan item sihir, memahami bahasa, atau berkomunikasi dengan cara apa pun yang dapat dimengerti. Namun, makhluk itu dapat mengidentifikasi teman-temannya, mengikuti mereka, dan bahkan melindungi mereka.\nPada akhir setiap 30 hari, makhluk itu dapat mengulangi penyelamatannya terhadap mantra ini. Jika berhasil dalam lemparan penyelamatannya, mantranya berakhir.\nMantra ini juga dapat diakhiri dengan pemulihan, penyembuhan, atau keinginan yang lebih besar." },
      { name: "Glibness", components: "V", desc: "Sampai mantranya berakhir, saat Anda melakukan pemeriksaan Karisma, Anda dapat mengganti angka yang Anda keluarkan dengan 15. Selain itu, apa pun yang Anda katakan, sihir yang akan menentukan apakah Anda mengatakan yang sebenarnya menunjukkan bahwa Anda jujur." },
      { name: "Power Word Stun", components: "V", desc: "Anda mengucapkan kata-kata yang memiliki kekuatan yang dapat menguasai pikiran satu makhluk yang dapat Anda lihat dalam jangkauannya, membuatnya tercengang. Jika target memiliki 150 poin hit atau kurang, target akan terkena stun. Kalau tidak, mantranya tidak akan berpengaruh.\nTarget yang terkena stun harus melakukan penyelamatan konstitusi di akhir setiap giliran. Jika penyelamatan berhasil, efek menakjubkan ini berakhir." },
    ],
    Level9: [
      { name: "Astral Projection", components: "V, S, M", desc: "Anda dan hingga delapan makhluk yang bersedia dalam jangkauan memproyeksikan tubuh astral Anda ke Alam Astral (mantranya gagal dan castingnya sia-sia jika Anda sudah berada di Alam Astral itu). Badan material yang Anda tinggalkan tidak sadarkan diri dan dalam keadaan mati suri; tidak membutuhkan makanan atau udara dan tidak menua.\nTubuh astral Anda hampir menyerupai wujud fana Anda dalam segala hal, meniru statistik permainan dan harta benda Anda. Perbedaan utamanya adalah penambahan tali keperakan yang memanjang dari antara tulang belikat dan berjalan di belakang Anda, memudar hingga tidak terlihat setelah 1 kaki. Tali ini adalah tambatan Anda pada tubuh material Anda. Selama tambatannya tetap utuh, Anda dapat menemukan jalan pulang. Jika kabelnya terputus--sesuatu yang dapat terjadi hanya jika efeknya secara spesifik dinyatakan demikian--jiwa dan tubuh Anda terpisah, membunuh Anda seketika.\nBentuk astral Anda dapat dengan bebas melakukan perjalanan melalui Alam Astral dan dapat melewati portal yang mengarah ke alam lain mana pun. Jika Anda memasuki pesawat baru atau kembali ke pesawat yang Anda naiki saat merapal mantra ini, tubuh dan harta benda Anda akan dipindahkan melalui tali perak, memungkinkan Anda untuk masuk kembali ke tubuh Anda saat Anda memasuki pesawat baru. Bentuk astral Anda adalah inkarnasi terpisah. Kerusakan atau dampak lain apa pun yang terjadi padanya tidak berpengaruh pada tubuh fisik Anda, juga tidak bertahan saat Anda kembali menggunakannya.\nMantra berakhir untuk Anda dan teman Anda saat Anda menggunakan tindakan Anda untuk mengabaikannya. Ketika mantranya berakhir, makhluk yang terkena dampak kembali ke tubuh fisiknya, dan dia terbangun.\nMantra ini mungkin juga berakhir lebih awal untuk Anda atau salah satu teman Anda. Mantra sihir penghilang yang berhasil digunakan terhadap tubuh astral atau fisik akan mengakhiri mantra untuk makhluk itu. Jika tubuh asli makhluk atau bentuk astralnya turun menjadi 0 poin serangan, mantra untuk makhluk tersebut berakhir. Jika mantranya berakhir dan tali peraknya masih utuh, tali tersebut akan menarik bentuk astral makhluk itu kembali ke tubuhnya, mengakhiri keadaan mati suri.\nJika Anda dikembalikan ke tubuh Anda sebelum waktunya, teman Anda tetap dalam bentuk astral dan harus menemukan jalan kembali ke tubuh mereka sendiri, biasanya dengan penurunan hingga 0 poin serangan." },
      { name: "Foresight", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia dan memberikan kemampuan terbatas untuk melihat masa depan. Selama durasi, target tidak dapat terkejut dan memiliki keunggulan dalam serangan, pengecekan kemampuan, dan penyelamatan lemparan. Selain itu, makhluk lain memiliki kelemahan dalam serangan berguling terhadap target selama durasi tersebut.\nMantra ini akan langsung berakhir jika kamu mengucapkannya lagi sebelum durasinya berakhir." },
      { name: "Imprisonment", components: "V, S, M", desc: "Anda membuat penahan ajaib untuk menahan makhluk yang dapat Anda lihat dalam jangkauan. Target harus berhasil dalam lemparan penyelamatan kebijaksanaan atau terikat oleh mantra; jika berhasil, ia kebal terhadap mantra ini jika Anda mengucapkannya lagi. Saat terkena mantra ini, makhluk tersebut tidak perlu bernapas, makan, atau minum, dan tidak menua. Mantra ramalan tidak dapat menemukan atau melihat targetnya.\nSaat Anda mengucapkan mantra, Anda memilih salah satu dari bentuk pemenjaraan berikut.\n***Penguburan.*** Targetnya dikuburkan jauh di bawah bumi dalam sebuah bola kekuatan magis yang cukup besar untuk menampung targetnya. Tidak ada yang dapat melewati bola tersebut, dan makhluk apa pun tidak dapat berteleportasi atau menggunakan perjalanan planar untuk masuk atau keluar darinya.\nKomponen khusus untuk versi mantra ini adalah bola mitral kecil.\n***Rantai.*** Rantai berat, tertanam kuat di tanah, menahan target di tempatnya. Target ditahan hingga mantranya berakhir, dan target tidak dapat bergerak atau dipindahkan dengan cara apa pun hingga saat itu.\nKomponen khusus untuk versi mantra ini adalah rantai halus dari logam mulia.\n***Penjara Lindung Nilai.*** Mantra tersebut memindahkan target ke dalam demiplane kecil yang terlindung dari teleportasi dan perjalanan planar. Demiplane dapat berupa labirin, sangkar, menara, atau struktur atau area terbatas serupa yang Anda pilih.\nKomponen khusus untuk versi mantra ini adalah representasi miniatur penjara yang terbuat dari batu giok.\n***Penahanan Minimum.*** Target menyusut hingga ketinggian 1 inci dan terkurung di dalam batu permata atau benda serupa. Cahaya dapat menembus batu permata secara normal (memungkinkan target untuk melihat keluar dan makhluk lain dapat melihat ke dalam), tetapi tidak ada benda lain yang dapat melewatinya, bahkan melalui teleportasi atau perjalanan planar. Batu permata tidak dapat dipotong atau dipatahkan selama mantranya masih berlaku.\nKomponen khusus untuk mantra versi ini adalah batu permata besar dan transparan, seperti korundum, berlian, atau rubi.\n***Tidur.*** Target tertidur dan tidak dapat dibangunkan.\nKomponen khusus untuk versi mantra ini terdiri dari ramuan obat tidur yang langka.\n***Mengakhiri Mantra.*** Selama merapal mantra, dalam versi mana pun, Anda dapat menentukan kondisi yang akan menyebabkan mantra berakhir dan melepaskan target. Kondisi tersebut bisa spesifik atau rumit sesuai pilihan Anda, namun GM harus setuju bahwa kondisi tersebut wajar dan kemungkinan besar akan terjadi. Kondisi tersebut dapat didasarkan pada nama, identitas, atau dewa suatu makhluk, tetapi sebaliknya harus didasarkan pada tindakan atau kualitas yang dapat diamati dan tidak berdasarkan pada hal-hal yang tidak berwujud seperti level, kelas, atau titik sasaran.\nMantra sihir penghilang dapat mengakhiri mantra hanya jika digunakan sebagai mantra tingkat 9, menargetkan penjara atau komponen khusus yang digunakan untuk membuatnya.\nAnda dapat menggunakan komponen khusus tertentu untuk membuat hanya satu penjara dalam satu waktu. Jika Anda merapal mantra lagi menggunakan komponen yang sama, target casting pertama akan segera terbebas dari ikatannya." },
      { name: "Power Word Kill", components: "V", desc: "Anda mengucapkan kata-kata kekuatan yang dapat memaksa satu makhluk yang Anda lihat dalam jangkauannya untuk mati seketika. Jika makhluk yang Anda pilih memiliki 100 poin hit atau kurang, ia akan mati. Kalau tidak, mantranya tidak akan berpengaruh." },
      { name: "True Polymorph", components: "V, S, M", desc: "Pilih satu makhluk atau objek non-magis yang dapat Anda lihat dalam jangkauannya. Anda mengubah makhluk menjadi makhluk lain, makhluk menjadi benda, atau benda menjadi makhluk (benda tersebut tidak boleh dipakai atau dibawa oleh makhluk lain). Transformasi berlangsung selama durasi tersebut, atau hingga target turun menjadi 0 poin hit atau mati. Jika Anda berkonsentrasi pada mantra ini selama durasi penuh, transformasinya menjadi permanen.\nPengubah bentuk tidak terpengaruh oleh mantra ini. Makhluk yang enggan dapat melakukan lemparan penyelamatan kebijaksanaan, dan jika berhasil, ia tidak terpengaruh oleh mantra ini.\n***Makhluk menjadi Makhluk.*** Jika Anda mengubah makhluk menjadi jenis makhluk lain, bentuk baru dapat berupa jenis apa pun yang Anda pilih yang peringkat tantangannya sama dengan atau lebih kecil dari target (atau levelnya, jika target tidak memiliki peringkat tantangan). Statistik permainan target, termasuk skor kemampuan mental, digantikan oleh statistik bentuk baru. Ia mempertahankan keselarasan dan kepribadiannya.\nTarget tersebut mengambil titik serangan dari bentuk barunya, dan ketika kembali ke bentuk normalnya, makhluk tersebut kembali ke jumlah titik serangan yang dimilikinya sebelum ia bertransformasi. Jika poin serangannya kembali karena poin hitnya turun menjadi 0, kerusakan berlebih akan kembali ke bentuk normalnya. Selama kerusakan berlebih tidak mengurangi bentuk normal makhluk itu menjadi 0 poin serangan, ia tidak akan pingsan.\nTindakan yang dapat dilakukan makhluk ini terbatas karena sifat dari bentuk barunya, dan ia tidak dapat berbicara, merapal mantra, atau melakukan tindakan lain apa pun yang memerlukan tangan atau ucapan kecuali jika bentuk barunya mampu melakukan tindakan tersebut.\nPerlengkapan target menyatu ke dalam bentuk baru. Makhluk itu tidak dapat mengaktifkan, menggunakan, menggunakan, atau memanfaatkan peralatan apa pun.\n***Objek menjadi Makhluk.*** Anda dapat mengubah suatu objek menjadi makhluk apa pun, asalkan ukuran makhluk tersebut tidak lebih besar dari ukuran objek dan peringkat tantangan makhluk tersebut adalah 9 atau lebih rendah. Makhluk itu ramah terhadap Anda dan teman Anda. Ia bertindak pada setiap giliran Anda. Anda memutuskan tindakan apa yang diperlukan dan bagaimana tindakannya. GM memiliki statistik makhluk itu dan menentukan semua tindakan dan pergerakannya.\nJika mantranya menjadi permanen, Anda tidak lagi mengendalikan makhluk itu. Itu mungkin tetap bersahabat dengan Anda, tergantung bagaimana Anda memperlakukannya.\n***Makhluk menjadi Objek.*** Jika Anda mengubah makhluk menjadi objek, ia akan berubah bersama apa pun yang dikenakan dan dibawanya ke dalam bentuk tersebut. Statistik makhluk itu menjadi milik objeknya, dan makhluk itu tidak memiliki ingatan tentang waktu yang dihabiskan dalam bentuk ini, setelah mantranya berakhir dan kembali ke bentuk normalnya." },
    ],
  },
  Wizard: {
    Cantrips: [
      { name: "Acid Splash", components: "V, S", desc: "Anda melemparkan gelembung asam. Pilih satu makhluk dalam jangkauan, atau pilih dua makhluk dalam jangkauan yang berada dalam jarak 5 kaki satu sama lain. Target harus berhasil dalam lemparan penyelamatan ketangkasan atau menerima kerusakan asam 1d6.\nKerusakan mantra ini meningkat sebesar 1d6 ketika Anda mencapai level 5 (2d6), level 11 (3d6), dan level 17 (4d6)." },
      { name: "Chill Touch", components: "V, S", desc: "Anda membuat tangan kerangka hantu di ruang makhluk dalam jangkauan. Lakukan serangan mantra jarak jauh terhadap makhluk itu untuk menyerangnya dengan dinginnya kuburan. Saat terkena serangan, target menerima 1d8 kerusakan nekrotik, dan target tidak dapat memperoleh kembali poin serangan hingga dimulainya giliran berikutnya. Sampai saat itu, tangan menempel pada sasaran.\nJika Anda mengenai target undead, ia juga memiliki kerugian pada serangan yang bergulir ke arah Anda hingga akhir giliran Anda berikutnya.\nKerusakan mantra ini meningkat sebesar 1d8 ketika Anda mencapai level 5 (2d8), level 11 (3d8), dan level 17 (4d8)." },
      { name: "Dancing Lights", components: "V, S, M", desc: "Anda membuat hingga empat lampu seukuran obor dalam jangkauan, menjadikannya tampak seperti obor, lentera, atau bola bercahaya yang melayang di udara selama durasi tersebut. Anda juga dapat menggabungkan keempat lampu menjadi satu bentuk humanoid samar-samar berukuran sedang. Apapun bentuk yang Anda pilih, setiap lampu memancarkan cahaya redup dalam radius 10 kaki.\nSebagai tindakan bonus pada giliran Anda, Anda dapat memindahkan lampu hingga 60 kaki ke tempat baru dalam jangkauan. Sebuah cahaya harus berada dalam jarak 20 kaki dari cahaya lain yang diciptakan oleh mantra ini, dan sebuah cahaya akan berkedip jika melebihi jangkauan mantranya." },
      { name: "Fire Bolt", components: "V, S", desc: "Anda melemparkan lebih banyak api ke makhluk atau objek dalam jangkauan. Lakukan serangan mantra jarak jauh terhadap target. Saat terkena, target menerima 1d10 kerusakan api. Benda mudah terbakar yang terkena mantra ini akan menyala jika tidak dipakai atau dibawa.\nKerusakan mantra ini meningkat sebesar 1d10 ketika Anda mencapai level 5 (2d10), level 11 (3d10), dan level 17 (4d10)." },
      { name: "Light", components: "V, M", desc: "Anda menyentuh satu objek yang ukurannya tidak lebih besar dari 10 kaki dalam dimensi apa pun. Hingga mantranya berakhir, objek tersebut memancarkan cahaya terang dalam radius 20 kaki dan cahaya redup dalam radius tambahan 20 kaki. Lampunya bisa diwarnai sesuka Anda. Menutupi objek sepenuhnya dengan sesuatu yang buram menghalangi cahaya. Mantra berakhir jika Anda mengucapkannya lagi atau mengabaikannya sebagai suatu tindakan.\nJika Anda mengincar benda yang dipegang atau dikenakan oleh makhluk musuh, makhluk tersebut harus berhasil melakukan lemparan penyelamatan ketangkasan untuk menghindari mantranya." },
      { name: "Mage Hand", components: "V, S", desc: "Tangan spektral dan mengambang muncul pada titik yang Anda pilih dalam jangkauan. Tangan tersebut bertahan selama atau sampai Anda mengabaikannya sebagai suatu tindakan. Tangan itu akan hilang jika jaraknya lebih dari 30 kaki dari Anda atau jika Anda mengucapkan mantra ini lagi.\nAnda dapat menggunakan tindakan Anda untuk mengontrol tangan. Anda dapat menggunakan tangan untuk memanipulasi suatu benda, membuka pintu atau wadah yang tidak terkunci, menyimpan atau mengambil suatu benda dari wadah terbuka, atau menuangkan isinya ke dalam botol. Anda dapat menggerakkan tangan hingga 30 kaki setiap kali menggunakannya.\nTangan tidak dapat menyerang, mengaktifkan item sihir, atau membawa beban lebih dari 10 pon." },
      { name: "Mending", components: "V, S, M", desc: "Mantra ini memperbaiki satu kerusakan atau robekan pada benda yang Anda sentuh, seperti kunci rusak, jubah robek, atau kantong anggur yang bocor. Selama patah atau robeknya tidak lebih dari 1 kaki di dimensi mana pun, Anda memperbaikinya, tanpa meninggalkan bekas kerusakan sebelumnya.\nMantra ini secara fisik dapat memperbaiki item atau konstruksi sihir, tetapi mantra tersebut tidak dapat memulihkan sihir ke objek tersebut." },
      { name: "Message", components: "V, S, M", desc: "Anda mengarahkan jari Anda ke arah makhluk dalam jangkauan dan membisikkan pesan. Target (dan hanya target) yang mendengar pesan tersebut dan dapat membalas dengan bisikan yang hanya dapat didengar oleh Anda.\nAnda dapat mengucapkan mantra ini melalui benda padat jika Anda familiar dengan targetnya dan mengetahui bahwa targetnya berada di luar penghalang. Keheningan magis, batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu setinggi 3 kaki menghalangi mantra tersebut. Mantranya tidak harus mengikuti garis lurus dan dapat bergerak bebas di sudut atau melalui celah." },
      { name: "Minor Illusion", components: "S, M", desc: "Anda membuat suara atau gambar suatu objek dalam jangkauan yang berlangsung selama durasi tersebut. Ilusi juga berakhir jika Anda mengabaikannya sebagai suatu tindakan atau mengucapkan mantra ini lagi.\nJika Anda membuat suara, volumenya bisa berkisar dari bisikan hingga jeritan. Bisa berupa suara Anda, suara orang lain, auman singa, tabuhan genderang, atau suara lain yang Anda pilih. Suara tersebut terus terdengar tanpa henti sepanjang durasi, atau Anda dapat membuat suara terpisah pada waktu yang berbeda sebelum mantra berakhir.\nJika Anda membuat gambar suatu objek--seperti kursi, jejak kaki berlumpur, atau peti kecil--ukurannya tidak boleh lebih dari kubus berukuran 5 kaki. Gambar tidak dapat menimbulkan suara, cahaya, bau, atau efek sensorik lainnya. Interaksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya.\nJika makhluk menggunakan tindakannya untuk memeriksa suara atau gambar, makhluk tersebut dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk mengenali ilusi apa adanya, ilusi tersebut menjadi samar bagi makhluk tersebut." },
      { name: "Poison Spray", components: "V, S", desc: "Anda mengulurkan tangan Anda ke arah makhluk yang dapat Anda lihat dalam jangkauan dan mengeluarkan kepulan gas berbahaya dari telapak tangan Anda. Makhluk itu harus berhasil melakukan penyelamatan konstitusi atau menerima kerusakan racun 1d12.\nKerusakan mantra ini meningkat sebesar 1d12 ketika Anda mencapai level 5 (2d12), level 11 (3d12), dan level 17 (4d12)." },
      { name: "Prestidigitation", components: "V, S", desc: "Mantra ini adalah trik magis kecil yang digunakan oleh perapal mantra pemula untuk latihan. Anda membuat salah satu efek ajaib berikut dalam 'jangkauan':\nAnda menciptakan efek sensorik yang seketika dan tidak berbahaya, seperti percikan api, hembusan angin, not musik yang samar, atau bau yang aneh.\nAnda langsung menyalakan atau mematikan lilin, obor, atau api unggun kecil.\nAnda langsung membersihkan atau mengotori benda yang ukurannya tidak lebih dari 1 kaki kubik.\nAnda mendinginkan, menghangatkan, atau membumbui hingga 1 kaki kubik bahan tak hidup selama 1 jam.\nAnda membuat warna, tanda kecil, atau simbol muncul pada suatu benda atau permukaan selama 1 jam.\nAnda membuat pernak-pernik non-magis atau gambar ilusi yang pas di tangan Anda dan bertahan hingga akhir giliran Anda berikutnya.\nJika Anda mengucapkan mantra ini beberapa kali, Anda dapat mengaktifkan hingga tiga efek non-instannya sekaligus, dan Anda dapat mengabaikan efek tersebut sebagai tindakan." },
      { name: "Ray of Frost", components: "V, S", desc: "Seberkas cahaya biru-putih yang dingin melesat ke arah makhluk dalam jangkauannya. Lakukan serangan mantra jarak jauh terhadap target. Saat terkena serangan, dibutuhkan 1d8 kerusakan dingin, dan kecepatannya berkurang 10 kaki hingga dimulainya giliran berikutnya.\nKerusakan mantra meningkat sebesar 1d8 ketika Anda mencapai level 5 (2d8), level 11 (3d8), dan level 17 (4d8)." },
      { name: "Shocking Grasp", components: "V, S", desc: "Petir muncul dari tangan Anda untuk memberikan kejutan pada makhluk yang Anda coba sentuh. Lakukan serangan mantra jarak dekat terhadap target. Anda memiliki keuntungan dalam serangan roll jika target memakai armor yang terbuat dari logam. Saat terkena serangan, target menerima 1d8 kerusakan petir, dan tidak dapat bereaksi hingga giliran berikutnya dimulai.\nKerusakan mantra meningkat sebesar 1d8 ketika Anda mencapai level 5 (2d8), level 11 (3d8), dan level 17 (4d8)." },
      { name: "True Strike", components: "S", desc: "Anda mengulurkan tangan dan mengarahkan jari ke sasaran dalam jangkauan. Sihir Anda memberi Anda wawasan singkat tentang pertahanan target. Pada giliran berikutnya, Anda mendapatkan keuntungan dari serangan pertama Anda terhadap target, asalkan mantra ini belum berakhir." },
    ],
    Level1: [
      { name: "Alarm", components: "V, S, M", desc: "Anda menyetel alarm terhadap gangguan yang tidak diinginkan. Pilih pintu, jendela, atau area dalam jangkauan yang tidak lebih besar dari kubus berukuran 20 kaki. Hingga mantranya berakhir, alarm akan memperingatkan Anda setiap kali makhluk kecil atau lebih besar menyentuh atau memasuki area yang dilindungi. Saat Anda mengucapkan mantra, Anda dapat menunjuk makhluk yang tidak akan membunyikan alarm. Anda juga memilih apakah alarm bersifat mental atau terdengar.\nAlarm mental memperingatkan Anda dengan ping di pikiran Anda jika Anda berada dalam jarak 1 mil dari area yang dilindungi. Ping ini membangunkan Anda jika Anda sedang tidur.\nAlarm yang dapat didengar menghasilkan suara bel tangan selama 10 detik dalam jarak 60 kaki." },
      { name: "Burning Hands", components: "V, S", desc: "Saat Anda memegang tangan Anda dengan ibu jari saling bersentuhan dan jari-jari terentang, selembar api tipis menyembur keluar dari ujung jari Anda yang terentang. Setiap makhluk dalam kerucut setinggi 15 kaki harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan api 3d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil.\nApi menyulut benda-benda mudah terbakar di area tersebut yang tidak dipakai atau dibawa.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 1." },
      { name: "Charm Person", components: "V, S", desc: "Anda mencoba memikat humanoid yang dapat Anda lihat dalam jangkauan. Ia harus melakukan lemparan penyelamatan yang bijaksana, dan melakukannya dengan keuntungan jika Anda atau teman Anda melawannya. Jika gagal dalam lemparan penyelamatan, ia akan terpesona oleh Anda hingga mantranya berakhir atau hingga Anda atau teman Anda melakukan sesuatu yang membahayakannya. Makhluk yang terpesona menganggap Anda sebagai kenalan yang ramah. Saat mantranya berakhir, makhluk itu tahu bahwa dia terpesona oleh Anda.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 1. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Color Spray", components: "V, S, M", desc: "Serangkaian kilatan cahaya berwarna yang mempesona muncul dari tangan Anda. Gulung 6d10; totalnya adalah berapa banyak poin serangan makhluk yang dapat dipengaruhi oleh mantra ini. Makhluk dalam kerucut setinggi 15 kaki yang berasal dari Anda akan terpengaruh dalam urutan titik hit mereka saat ini (mengabaikan makhluk tidak sadar dan makhluk yang tidak dapat melihat).\nDimulai dengan makhluk yang memiliki poin hit terendah saat ini, setiap makhluk yang terkena mantra ini akan dibutakan hingga mantranya berakhir. Kurangi poin hit setiap makhluk dari total sebelum melanjutkan ke makhluk dengan poin hit terendah berikutnya. Hit point suatu makhluk harus sama dengan atau kurang dari total yang tersisa agar makhluk tersebut dapat terpengaruh.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, putar 2d10 tambahan untuk setiap level slot di atas 1." },
      { name: "Comprehend Languages", components: "V, S, M", desc: "Selama ini, Anda memahami arti literal dari setiap bahasa lisan yang Anda dengar. Anda juga memahami bahasa tertulis apa pun yang Anda lihat, tetapi Anda harus menyentuh permukaan tempat kata-kata itu ditulis. Dibutuhkan sekitar 1 menit untuk membaca satu halaman teks.\nMantra ini tidak memecahkan kode pesan rahasia dalam teks atau mesin terbang, seperti sigil misterius, yang bukan bagian dari bahasa tertulis." },
      { name: "Detect Magic", components: "V, S", desc: "Selama durasi tersebut, Anda merasakan kehadiran sihir dalam jarak 30 kaki dari Anda. Jika Anda merasakan sihir dengan cara ini, Anda dapat menggunakan tindakan Anda untuk melihat aura samar di sekitar makhluk atau objek apa pun yang terlihat di area yang mengandung sihir, dan Anda mempelajari sekolah sihirnya, jika ada.\nMantranya dapat menembus sebagian besar penghalang, tetapi ia terhalang oleh batu setinggi 1 kaki, logam biasa 1 inci, lembaran timah tipis, atau kayu atau tanah setinggi 3 kaki." },
      { name: "Disguise Self", components: "V, S", desc: "Anda membuat diri Anda sendiri--termasuk pakaian, baju besi, senjata, dan barang-barang lainnya pada diri Anda--terlihat berbeda sampai mantranya berakhir atau sampai Anda menggunakan tindakan Anda untuk mengabaikannya. Anda bisa terlihat 1 kaki lebih pendek atau lebih tinggi dan bisa terlihat kurus, gemuk, atau di antara keduanya. Anda tidak dapat mengubah tipe tubuh Anda, jadi Anda harus mengambil bentuk yang memiliki susunan dasar anggota tubuh yang sama. Jika tidak, sejauh mana ilusi itu terserah Anda.\nPerubahan yang dilakukan oleh mantra ini gagal memenuhi pemeriksaan fisik. Misalnya, jika Anda menggunakan mantra ini untuk menambahkan topi ke pakaian Anda, benda akan melewati topi tersebut, dan siapa pun yang menyentuhnya tidak akan merasakan apa pun atau akan merasakan kepala dan rambut Anda. Jika Anda menggunakan mantra ini untuk terlihat lebih kurus dari Anda, tangan seseorang yang mengulurkan tangan untuk menyentuh Anda akan menabrak Anda saat tangan itu tampak masih di udara.\nUntuk mengetahui bahwa Anda sedang menyamar, makhluk dapat menggunakan tindakannya untuk memeriksa penampilan Anda dan harus berhasil dalam pemeriksaan Intelijen (Investigasi) terhadap mantra penyelamatan DC Anda." },
      { name: "Expeditious Retreat", components: "V, S", desc: "Mantra ini memungkinkan Anda bergerak dengan kecepatan luar biasa. Saat Anda mengucapkan mantra ini, dan kemudian sebagai tindakan bonus di setiap giliran Anda hingga mantra tersebut berakhir, Anda dapat melakukan tindakan Dash." },
      { name: "False Life", components: "V, S, M", desc: "Memperkuat diri Anda dengan faksimili kehidupan necromantic, Anda mendapatkan 1d4 + 4 poin hit sementara selama durasi tersebut.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda mendapatkan 5 poin hit sementara tambahan untuk setiap slot level di atas 1." },
      { name: "Feather Fall", components: "V, M", desc: "Pilih hingga lima makhluk yang jatuh dalam jangkauan. Kecepatan turunnya makhluk yang jatuh melambat hingga 60 kaki per putaran hingga mantranya berakhir. Jika makhluk itu mendarat sebelum mantranya berakhir, ia tidak menerima kerusakan akibat jatuh dan dapat mendarat dengan kakinya, dan mantranya berakhir untuk makhluk itu." },
      { name: "Find Familiar", components: "V, S, M", desc: "Anda mendapatkan layanan dari familiar, roh yang mengambil bentuk binatang yang Anda pilih: kelelawar, kucing, kepiting, katak (katak), elang, kadal, gurita, burung hantu, ular berbisa, ikan (quipper), tikus, gagak, kuda laut, laba-laba, atau musang. Muncul di ruang kosong dalam jangkauannya, familiar tersebut memiliki statistik dari bentuk yang dipilih, meskipun ia adalah makhluk surgawi, fey, atau iblis (pilihan Anda) dan bukan binatang buas.\nFamiliar Anda bertindak secara independen dari Anda, tetapi ia selalu mematuhi perintah Anda. Dalam pertempuran, ia mengambil inisiatif sendiri dan bertindak berdasarkan gilirannya sendiri. Familiar tidak bisa menyerang, tapi bisa melakukan tindakan lain seperti biasa.\nSaat familiar turun menjadi 0 poin hit, ia menghilang, tidak meninggalkan bentuk fisik. Itu muncul kembali setelah Anda mengucapkan mantra ini lagi.\nMeskipun familiar Anda berada dalam jarak 100 kaki dari Anda, Anda dapat berkomunikasi dengannya secara telepati. Selain itu, sebagai suatu tindakan, Anda dapat melihat melalui mata familiar Anda dan mendengar apa yang didengarnya hingga giliran Anda berikutnya dimulai, mendapatkan manfaat dari indra khusus apa pun yang dimiliki familiar tersebut. Selama masa ini, Anda tuli dan buta terhadap indra Anda sendiri.\nSebagai tindakan, Anda dapat mengabaikan familiar Anda untuk sementara. Itu menghilang ke dalam dimensi saku di mana ia menunggu panggilan Anda. Alternatifnya, Anda dapat mengabaikannya selamanya. Sebagai suatu tindakan sementara tindakan tersebut dihentikan sementara, Anda dapat menyebabkannya muncul kembali di ruang kosong mana pun dalam jarak 30 kaki dari Anda.\nAnda tidak dapat memiliki lebih dari satu familiar dalam satu waktu. Jika kamu mengucapkan mantra ini saat kamu sudah memiliki familiarnya, kamu malah menyebabkannya mengambil bentuk baru. Pilih salah satu formulir dari daftar di atas. Familiar Anda berubah menjadi makhluk pilihan.\nTerakhir, saat Anda merapalkan mantra dengan berbagai sentuhan, familiar Anda dapat mengucapkan mantra seolah-olah ia telah merapal mantra tersebut. Familiar Anda harus berada dalam jarak 100 kaki dari Anda, dan ia harus menggunakan reaksinya untuk menyampaikan mantra saat Anda mengucapkannya. Jika mantra memerlukan lemparan serangan, gunakan pengubah tindakan Anda untuk lemparan tersebut." },
      { name: "Floating Disk", components: "V, S, M", desc: "Mantra ini menciptakan bidang gaya horizontal melingkar, diameter 3 kaki dan tebal 1 inci, yang mengapung 3 kaki di atas tanah di ruang kosong pilihan Anda yang dapat Anda lihat dalam jangkauan. Disk tetap bertahan selama durasi tersebut, dan dapat menampung hingga 500 pon. Jika lebih banyak beban ditempatkan padanya, mantranya berakhir, dan semua yang ada di disk jatuh ke tanah.\nDisk tidak dapat bergerak saat Anda berada dalam jarak 20 kaki darinya. Jika Anda bergerak lebih dari 20 kaki darinya, disk akan mengikuti Anda sehingga tetap berada dalam jarak 20 kaki dari Anda. Jika dapat bergerak melintasi medan yang tidak rata, naik atau turun tangga, lereng dan sejenisnya, namun tidak dapat melintasi perubahan ketinggian 10 kaki atau lebih. Misalnya, piringan tidak dapat bergerak melintasi lubang sedalam 10 kaki, dan juga tidak dapat meninggalkan lubang tersebut jika dibuat di bagian bawah.\nJika Anda bergerak lebih dari 100 kaki dari disk (biasanya karena disk tidak dapat bergerak melewati rintangan untuk mengikuti Anda), mantranya akan berakhir." },
      { name: "Fog Cloud", components: "V, S", desc: "Anda membuat bola kabut dengan radius 20 kaki yang berpusat pada suatu titik dalam jangkauan. Bola itu menyebar ke berbagai sudut, dan areanya sangat tertutup. Itu berlangsung selama atau sampai angin dengan kecepatan sedang atau lebih besar (setidaknya 10 mil per jam) membubarkannya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, radius kabut bertambah 20 kaki untuk setiap slot level di atas 1." },
      { name: "Grease", components: "V, S, M", desc: "Minyak licin menutupi tanah dalam area seluas 10 kaki yang berpusat pada suatu titik dalam jangkauan dan mengubahnya menjadi medan yang sulit selama jangka waktu tersebut.\nKetika minyak muncul, setiap makhluk yang berdiri di areanya harus berhasil melakukan lemparan penyelamatan ketangkasan atau rawan terjatuh. Makhluk yang memasuki area tersebut atau mengakhiri gilirannya di sana juga harus berhasil melakukan lemparan penyelamatan ketangkasan atau rawan terjatuh." },
      { name: "Hideous Laughter", components: "V, S, M", desc: "Makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan menganggap segala sesuatu sebagai sesuatu yang sangat lucu dan tertawa terbahak-bahak jika mantra ini memengaruhinya. Target harus berhasil dalam lemparan penyelamatan yang bijaksana atau rawan jatuh, menjadi tidak berdaya dan tidak mampu berdiri selama jangka waktu tersebut. Makhluk dengan skor Intelijen 4 atau kurang tidak terpengaruh.\nDi akhir setiap giliran, dan setiap kali menerima kerusakan, target dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Target mempunyai keuntungan dalam penyelamatan jika dipicu oleh kerusakan. Jika berhasil, mantranya berakhir." },
      { name: "Identify", components: "V, S, M", desc: "Anda memilih satu objek yang harus Anda sentuh selama merapal mantra. Jika itu adalah benda ajaib atau benda lain yang mengandung sihir, Anda akan mempelajari propertinya dan cara menggunakannya, apakah memerlukan attunement untuk menggunakannya, dan berapa banyak muatan yang dimilikinya, jika ada. Anda mengetahui apakah ada mantra yang memengaruhi item dan apa saja pengaruhnya. Jika item dibuat oleh mantra, Anda akan mengetahui mantra mana yang menciptakannya.\nJika Anda malah menyentuh makhluk selama casting, Anda akan mengetahui mantra apa, jika ada, yang saat ini memengaruhinya." },
      { name: "Illusory Script", components: "S, M", desc: "Anda menulis di perkamen, kertas, atau bahan tulis lain yang sesuai dan memberinya ilusi kuat yang bertahan selama itu.\nBagi Anda dan makhluk apa pun yang Anda tunjuk saat mengucapkan mantra, tulisan itu tampak normal, ditulis di tangan Anda, dan menyampaikan makna apa pun yang Anda inginkan saat menulis teks tersebut. Bagi orang lain, tulisan tersebut tampak seolah-olah ditulis dalam naskah yang tidak diketahui atau ajaib yang tidak dapat dipahami. Alternatifnya, Anda dapat membuat tulisan tersebut tampak seperti pesan yang sama sekali berbeda, ditulis dengan tangan dan bahasa yang berbeda, meskipun bahasanya haruslah bahasa yang Anda ketahui.\nJika mantranya dihilangkan, naskah asli dan ilusinya akan hilang.\nMakhluk yang memiliki pandangan sejati dapat membaca pesan tersembunyi." },
      { name: "Jump", components: "V, S, M", desc: "Anda menyentuh makhluk. Jarak lompatan makhluk itu menjadi tiga kali lipat hingga mantranya berakhir." },
      { name: "Longstrider", components: "V, S, M", desc: "Anda menyentuh makhluk. Kecepatan target meningkat 10 kaki hingga mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot mantra di atas level 1." },
      { name: "Mage Armor", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia yang tidak mengenakan baju besi, dan kekuatan magis pelindung mengelilinginya sampai mantranya berakhir. AC dasar target menjadi 13+ pengubah Dexterity-nya. Mantra berakhir jika target mengenakan baju besi atau jika Anda mengabaikan mantra sebagai suatu tindakan." },
      { name: "Magic Missile", components: "V, S", desc: "Anda menciptakan tiga anak panah kekuatan magis yang bersinar. Setiap anak panah mengenai makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan. Sebuah anak panah menimbulkan 1d4 + 1 kerusakan kekuatan pada targetnya. Semua anak panah menyerang secara bersamaan, dan Anda dapat mengarahkannya untuk mengenai satu atau beberapa makhluk.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 2 atau lebih tinggi, mantra tersebut akan menghasilkan satu anak panah lagi untuk setiap slot level di atas 1." },
      { name: "Protection from Evil and Good", components: "V, S, M", desc: "Hingga mantranya berakhir, satu makhluk yang Anda sentuh akan terlindungi dari jenis makhluk tertentu: aberasi, surgawi, elemen, fey, iblis, dan undead.\nPerlindungan memberikan beberapa manfaat. Makhluk dengan tipe seperti itu mempunyai kelemahan dalam serangan roll terhadap target. Targetnya juga tidak bisa terpesona, ditakuti, atau dirasuki oleh mereka. Jika target sudah terpesona, ketakutan, atau dirasuki oleh makhluk tersebut, target mempunyai keuntungan pada setiap lemparan penyelamatan baru terhadap efek yang relevan." },
      { name: "Shield", components: "V, S", desc: "Penghalang kekuatan magis yang tak terlihat muncul dan melindungi Anda. Hingga awal giliran Anda berikutnya, Anda memiliki bonus +5 untuk AC, termasuk terhadap serangan yang memicu, dan Anda tidak menerima kerusakan dari rudal ajaib." },
      { name: "Silent Image", components: "V, S, M", desc: "Anda membuat gambar suatu benda, makhluk, atau fenomena nyata lainnya yang ukurannya tidak lebih besar dari kubus berukuran 15 kaki. Gambar muncul di suatu tempat dalam jangkauan dan berlangsung selama durasi tersebut. Gambar tersebut murni visual; tidak disertai suara, bau, atau efek sensorik lainnya.\nAnda dapat menggunakan tindakan Anda untuk menyebabkan gambar berpindah ke tempat mana pun dalam jangkauan. Saat gambar berpindah lokasi, Anda dapat mengubah tampilannya sehingga gerakannya tampak natural pada gambar. Misalnya, jika Anda membuat gambar makhluk dan memindahkannya, Anda dapat mengubah gambar tersebut sehingga tampak seperti sedang berjalan.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk dapat mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut." },
      { name: "Sleep", components: "V, S, M", desc: "Mantra ini membuat makhluk tertidur secara ajaib. Gulung 5d8; totalnya adalah berapa banyak poin serangan makhluk yang dapat dipengaruhi oleh mantra ini. Makhluk dalam jarak 20 kaki dari titik yang Anda pilih dalam jangkauan akan terpengaruh dalam urutan titik serangan mereka saat ini (mengabaikan makhluk yang tidak sadarkan diri).\nDimulai dengan makhluk yang memiliki poin serangan terendah saat ini, setiap makhluk yang terkena mantra ini akan jatuh pingsan hingga mantranya berakhir, orang yang tidur menerima kerusakan, atau seseorang menggunakan tindakan untuk mengguncang atau menampar orang yang tidur tersebut hingga terbangun. Kurangi poin hit setiap makhluk dari total sebelum melanjutkan ke makhluk dengan poin hit terendah berikutnya. Hit point suatu makhluk harus sama dengan atau kurang dari total yang tersisa agar makhluk tersebut dapat terpengaruh.\nMayat hidup dan makhluk yang kebal terhadap pesona tidak terpengaruh oleh mantra ini.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, putar 2d8 tambahan untuk setiap level slot di atas 1." },
      { name: "Thunderwave", components: "V, S", desc: "Gelombang kekuatan yang menggelegar menyapu Anda. Setiap makhluk dalam kubus berukuran 15 kaki yang berasal dari Anda harus melakukan lemparan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk menerima kerusakan petir sebesar 2d8 dan didorong sejauh 10 kaki dari Anda. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan dan tidak didorong.\nSelain itu, objek tanpa jaminan yang sepenuhnya berada dalam area efek secara otomatis didorong sejauh 10 kaki dari Anda oleh efek mantra, dan mantra tersebut mengeluarkan ledakan menggelegar yang terdengar hingga jarak 300 kaki.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 2 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 1." },
      { name: "Unseen Servant", components: "V, S, M", desc: "Mantra ini menciptakan kekuatan yang tidak terlihat, tidak ada artinya, dan tidak berbentuk yang melakukan tugas-tugas sederhana sesuai perintah Anda hingga mantranya berakhir. Pelayan itu muncul di ruang kosong di tanah dalam jangkauannya. Ia memiliki AC 10, 1 hit point, dan Strength 2, dan tidak dapat menyerang. Jika poin hitnya turun menjadi 0, mantranya berakhir.\nSekali di setiap giliran Anda sebagai tindakan bonus, Anda dapat secara mental memerintahkan pelayan untuk bergerak hingga 15 kaki dan berinteraksi dengan suatu objek. Pelayan dapat melakukan tugas-tugas sederhana yang dapat dilakukan oleh pelayan manusia, seperti mengambil barang, membersihkan, memperbaiki, melipat pakaian, menyalakan api, menyajikan makanan, dan menuangkan anggur. Setelah Anda memberi perintah, pelayan akan menjalankan tugas dengan kemampuan terbaiknya hingga tugas selesai, lalu menunggu perintah Anda selanjutnya.\nJika Anda memerintahkan pelayan untuk melakukan tugas yang akan memindahkannya lebih dari 60 kaki dari Anda, mantranya akan berakhir." },
    ],
    Level2: [
      { name: "Acid Arrow", components: "V, S, M", desc: "Panah hijau berkilauan melesat ke arah target dalam jangkauannya dan meledak dalam semprotan asam. Lakukan serangan mantra jarak jauh terhadap target. Jika terkena serangan, target akan langsung menerima kerusakan asam 4d4 dan kerusakan asam 2d4 di akhir giliran berikutnya. Jika meleset, panah akan menyiram target dengan asam dengan jumlah setengah dari kerusakan awal dan tidak ada kerusakan pada akhir giliran berikutnya.\nSaat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan (baik awal maupun nanti) meningkat sebesar 1d4 untuk setiap slot level di atas 2." },
      { name: "Alter Self", components: "V, S", desc: "Anda mengambil bentuk yang berbeda. Saat Anda mengucapkan mantra, pilih salah satu opsi berikut, yang efeknya akan bertahan selama durasi mantra. Selama mantranya berlangsung, Anda dapat mengakhiri satu opsi sebagai tindakan untuk mendapatkan manfaat dari opsi lain.\n***Adaptasi Perairan.*** Anda menyesuaikan tubuh Anda dengan lingkungan perairan, menumbuhkan insang dan menumbuhkan jaring di antara jari-jari Anda. Anda dapat bernapas di bawah air dan mendapatkan kecepatan berenang yang setara dengan kecepatan berjalan Anda.\n***Ubah Penampilan.*** Anda mengubah penampilan Anda. Anda yang memutuskan seperti apa penampilan Anda, termasuk tinggi badan, berat badan, fitur wajah, suara Anda, panjang rambut, warna rambut, dan ciri-ciri pembeda, jika ada. Anda dapat membuat diri Anda tampil sebagai anggota ras lain, meskipun statistik Anda tidak berubah. Anda juga tidak dapat tampil sebagai makhluk dengan ukuran berbeda dari Anda, dan bentuk dasar Anda tetap sama; jika Anda berkaki dua, misalnya, Anda tidak bisa menggunakan mantra ini untuk menjadi berkaki empat. Kapan saja selama durasi mantra, Anda dapat menggunakan tindakan Anda untuk mengubah penampilan Anda lagi dengan cara ini.\n***Senjata Alami.*** Anda menumbuhkan cakar, taring, duri, tanduk, atau senjata alami lain pilihan Anda. Serangan tanpa senjata Anda menghasilkan kerusakan pukulan, penusukan, atau tebasan 1d6, sesuai dengan senjata alami yang Anda pilih, dan Anda mahir dengan serangan tanpa senjata. Terakhir, senjata alaminya adalah sihir dan Anda memiliki bonus +1 untuk serangan dan damage roll yang Anda buat menggunakannya." },
      { name: "Arcane Lock", components: "V, S, M", desc: "Anda menyentuh pintu, jendela, gerbang, peti, atau pintu masuk lainnya yang tertutup, dan pintu tersebut akan terkunci selama jangka waktu tersebut. Anda dan makhluk yang Anda tunjuk saat mengucapkan mantra ini dapat membuka objek secara normal. Anda juga dapat mengatur kata sandi yang, ketika diucapkan dalam jarak 5 kaki dari objek, akan menekan mantra ini selama 1 menit. Jika tidak, mantra tersebut tidak dapat dilewati sampai mantra tersebut dipatahkan atau mantranya dihilangkan atau ditekan. Mengetuk objek akan menekan kunci misterius selama 10 menit.\nSaat terkena mantra ini, objeknya lebih sulit dipatahkan atau dibuka paksa; DC untuk memecahkannya atau mengambil kunci apa pun di dalamnya bertambah 10." },
      { name: "Arcanist's Magic Aura", components: "V, S, M", desc: "Anda menempatkan ilusi pada makhluk atau benda yang Anda sentuh sehingga mantra ramalan mengungkapkan informasi palsu tentangnya. Sasarannya bisa berupa makhluk yang rela atau benda yang tidak dibawa atau dipakai oleh makhluk lain.\nSaat Anda mengucapkan mantra, pilih salah satu atau kedua efek berikut. Efeknya bertahan selama durasi tersebut. Jika Anda mengucapkan mantra ini pada makhluk atau objek yang sama setiap hari selama 30 hari, memberikan efek yang sama setiap kali, ilusi tersebut akan bertahan hingga hilang.\n***Aura Palsu.*** Anda mengubah penampilan target menjadi mantra dan efek magis, seperti deteksi sihir, yang mendeteksi aura magis. Anda dapat membuat objek non-magis tampak magis, objek magis tampak non-magis, atau mengubah aura magis objek tersebut sehingga tampak milik aliran sihir tertentu yang Anda pilih. Saat Anda menggunakan efek ini pada suatu objek, Anda dapat membuat sihir palsu terlihat oleh makhluk mana pun yang menangani item tersebut.\n***Topeng.*** Anda mengubah tampilan target menjadi mantra dan efek magis yang mendeteksi tipe makhluk, seperti Divine Sense paladin atau pemicu mantra simbol. Anda memilih jenis makhluk dan mantra serta efek magis lainnya memperlakukan target seolah-olah itu adalah makhluk dengan jenis atau kesejajaran itu." },
      { name: "Blindness/Deafness", components: "V", desc: "Anda bisa membutakan atau menulikan musuh. Pilih satu makhluk yang dapat Anda lihat dalam jangkauan untuk melakukan penyelamatan konstitusi. Jika gagal, target akan menjadi buta atau tuli (pilihan Anda) selama durasi tersebut. Di akhir setiap giliran, target dapat melakukan penyelamatan konstitusi. Jika berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Blur", components: "V", desc: "Tubuhmu menjadi kabur, bergeser dan bimbang terhadap siapa pun yang bisa melihatmu. Selama durasi tersebut, makhluk apa pun memiliki kelemahan dalam serangan yang menyerang Anda. Seorang penyerang kebal terhadap efek ini jika ia tidak mengandalkan penglihatan, seperti pada penglihatan buta, atau dapat melihat melalui ilusi, seperti pada penglihatan nyata." },
      { name: "Continual Flame", components: "V, S, M", desc: "Nyala api, yang kecerahannya setara dengan obor, muncul dari benda yang Anda sentuh. Efeknya terlihat seperti nyala api biasa, namun tidak menimbulkan panas dan tidak menggunakan oksigen. Nyala api yang terus-menerus dapat ditutupi atau disembunyikan tetapi tidak dapat dipadamkan atau dipadamkan." },
      { name: "Darkness", components: "V, M", desc: "Kegelapan magis menyebar dari titik yang Anda pilih dalam jangkauan hingga memenuhi bola dengan radius 15 kaki selama durasi tersebut. Kegelapan menyebar ke segala penjuru. Makhluk dengan penglihatan gelap tidak dapat melihat menembus kegelapan ini, dan cahaya non-magis tidak dapat meneranginya.\nJika titik yang Anda pilih ada pada benda yang Anda pegang atau benda yang tidak dipakai atau dibawa, kegelapan akan memancar dari benda tersebut dan bergerak bersamanya. Menutupi seluruh sumber kegelapan dengan benda buram, seperti mangkuk atau helm, akan menghalangi kegelapan.\nJika salah satu area mantra ini tumpang tindih dengan area cahaya yang diciptakan oleh mantra level 2 atau lebih rendah, mantra yang menciptakan cahaya tersebut akan hilang." },
      { name: "Darkvision", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia memberinya kemampuan melihat dalam kegelapan. Selama durasinya, makhluk itu memiliki penglihatan gelap hingga jarak 60 kaki." },
      { name: "Detect Thoughts", components: "V, S, M", desc: "Selama itu, Anda bisa membaca pikiran makhluk tertentu. Saat Anda merapal mantra dan melakukan tindakan di setiap belokan hingga mantra berakhir, Anda dapat memfokuskan pikiran Anda pada satu makhluk yang dapat Anda lihat dalam jarak 30 kaki dari Anda. Jika makhluk yang Anda pilih memiliki Kecerdasan 3 atau lebih rendah atau tidak dapat berbicara bahasa apa pun, makhluk tersebut tidak terpengaruh.\nAwalnya Anda mempelajari pemikiran permukaan makhluk itu - apa yang paling ada dalam pikirannya pada saat itu. Sebagai suatu tindakan, Anda dapat mengalihkan perhatian Anda ke pikiran makhluk lain atau mencoba menyelidiki lebih dalam pikiran makhluk yang sama. Jika Anda menyelidiki lebih dalam, target harus melakukan lemparan penyelamatan Kebijaksanaan. Jika gagal, Anda mendapatkan wawasan tentang alasannya (jika ada), keadaan emosinya, dan sesuatu yang terlintas dalam pikirannya (seperti sesuatu yang dikhawatirkan, disukai, atau dibencinya). Jika berhasil maka mantranya berakhir. Apa pun yang terjadi, target tahu bahwa Anda sedang menyelidiki pikirannya, dan kecuali Anda mengalihkan perhatian Anda ke pikiran makhluk lain, makhluk itu dapat menggunakan tindakannya pada gilirannya untuk melakukan pemeriksaan Intelijen yang ditentang oleh pemeriksaan Intelijen Anda; jika berhasil, mantranya berakhir.\nPertanyaan yang ditujukan secara verbal pada makhluk target secara alami membentuk alur pemikirannya, jadi mantra ini sangat efektif sebagai bagian dari interogasi.\nAnda juga dapat menggunakan mantra ini untuk mendeteksi keberadaan makhluk berpikir yang tidak dapat Anda lihat. Saat Anda mengucapkan mantra atau sebagai tindakan Anda selama durasi tersebut, Anda dapat mencari pikiran dalam jarak 30 kaki dari Anda. Mantranya dapat menembus penghalang, tetapi batu setinggi 2 kaki, logam apa pun setinggi 2 inci selain timah, atau lembaran timah tipis menghalangi Anda. Anda tidak dapat mendeteksi makhluk dengan Kecerdasan 3 atau lebih rendah atau makhluk yang tidak bisa berbicara bahasa apa pun.\nSetelah Anda mendeteksi keberadaan suatu makhluk dengan cara ini, Anda dapat membaca pikirannya selama sisa durasi seperti yang dijelaskan di atas, meskipun Anda tidak dapat melihatnya, tetapi ia harus tetap berada dalam jangkauan." },
      { name: "Enlarge/Reduce", components: "V, S, M", desc: "Anda menyebabkan makhluk atau objek yang dapat Anda lihat dalam jangkauan menjadi lebih besar atau lebih kecil selama durasi tersebut. Pilihlah makhluk atau benda yang tidak dipakai atau dibawa. Jika targetnya tidak mau, maka bisa melakukan penyelamatan Konstitusi. Jika berhasil, mantranya tidak berpengaruh.\nJika targetnya adalah makhluk, segala sesuatu yang dikenakan dan dibawanya akan berubah ukurannya. Benda apa pun yang dijatuhkan oleh makhluk yang terkena dampak akan segera kembali ke ukuran normal.\n***Perbesar.*** Ukuran target menjadi dua kali lipat di semua dimensi, dan beratnya dikalikan delapan. Pertumbuhan ini meningkatkan ukurannya sebanyak satu kategori—dari Sedang ke Besar, misalnya. Jika tidak ada cukup ruang bagi target untuk menggandakan ukurannya, makhluk atau objek tersebut akan mencapai ukuran maksimum yang mungkin dalam ruang yang tersedia. Hingga mantranya berakhir, target juga memiliki keuntungan dalam pemeriksaan Kekuatan dan lemparan hemat Kekuatan. Senjata target juga bertambah untuk menyesuaikan dengan ukuran barunya. Saat senjata ini diperbesar, serangan target dengan senjata tersebut menghasilkan 1d4 kerusakan ekstra.\n***Kurangi.*** Ukuran target dibelah dua di semua dimensi, dan beratnya dikurangi menjadi seperdelapan dari ukuran normal. Pengurangan ini mengurangi ukurannya sebanyak satu kategori—dari Sedang ke Kecil, misalnya. Hingga mantranya berakhir, target juga mempunyai kelemahan pada pemeriksaan Kekuatan dan lemparan penghematan Kekuatan. Senjata target juga menyusut agar sesuai dengan ukuran barunya. Saat senjata ini dikurangi, serangan target dengan senjata tersebut menghasilkan kerusakan 1d4 lebih sedikit (ini tidak dapat mengurangi kerusakan di bawah 1)." },
      { name: "Flaming Sphere", components: "V, S, M", desc: "Bola api berdiameter 5 kaki muncul di ruang kosong pilihan Anda dalam jangkauan dan bertahan selama durasi tersebut. Makhluk apa pun yang mengakhiri gilirannya dalam jarak 5 kaki dari bola harus melakukan lemparan penyelamatan ketangkasan. Makhluk itu menerima kerusakan api sebesar 2d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil.\nSebagai aksi bonus, Anda dapat memindahkan bola hingga 30 kaki. Jika Anda menabrakkan bola ke makhluk, makhluk itu harus melakukan lemparan penyelamatan terhadap kerusakan bola, dan bola berhenti bergerak pada belokan ini.\nSaat menggerakkan bola, Anda dapat mengarahkannya melewati penghalang setinggi 5 kaki dan melompati lubang selebar 10 kaki. Bola tersebut menyulut benda mudah terbakar yang tidak dipakai atau dibawa, dan memancarkan cahaya terang dalam radius 20 kaki dan cahaya redup dalam radius 20 kaki tambahan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 2." },
      { name: "Gentle Repose", components: "V, S, M", desc: "Anda menyentuh mayat atau sisa-sisa lainnya. Selama durasi tersebut, target terlindungi dari pembusukan dan tidak bisa menjadi undead.\nMantra ini juga secara efektif memperpanjang batas waktu untuk membangkitkan target dari kematian, karena hari-hari yang dihabiskan di bawah pengaruh mantra ini tidak dihitung terhadap batas waktu mantra seperti membangkitkan orang mati." },
      { name: "Gust of Wind", components: "V, S, M", desc: "Garis angin kencang sepanjang 60 kaki dan lebar 10 kaki bertiup dari Anda ke arah yang Anda pilih selama durasi mantra. Setiap makhluk yang memulai gilirannya di garis harus berhasil melakukan lemparan hemat kekuatan atau didorong sejauh 15 kaki dari Anda ke arah yang mengikuti garis.\nMakhluk apa pun yang berada dalam barisan harus menghabiskan 2 kaki gerakan untuk setiap 1 kaki yang bergerak saat bergerak mendekati Anda.\nHembusan angin menyebarkan gas atau uap, dan memadamkan lilin, obor, dan nyala api serupa yang tidak terlindungi di area tersebut. Hal ini menyebabkan api yang terlindung, seperti api lentera, menari dengan liar dan memiliki peluang 50 persen untuk memadamkannya.\nSebagai tindakan bonus di setiap giliran Anda sebelum mantra berakhir, Anda dapat mengubah arah ledakan garis dari Anda." },
      { name: "Hold Person", components: "V, S, M", desc: "Pilih humanoid yang dapat Anda lihat dalam jangkauan. Target harus berhasil melakukan penyelamatan kebijaksanaan atau menjadi lumpuh selama jangka waktu tersebut. Di akhir setiap giliran, target dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, mantranya berakhir tepat sasaran.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu humanoid tambahan untuk setiap slot level di atas 2. Humanoid harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkannya." },
      { name: "Invisibility", components: "V, S, M", desc: "Makhluk yang Anda sentuh menjadi tidak terlihat sampai mantranya berakhir. Apapun yang dikenakan atau dibawa oleh target tidak akan terlihat selama berada pada orang yang menjadi target. Mantra berakhir untuk target yang menyerang atau mengeluarkan mantra.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 2." },
      { name: "Knock", components: "V", desc: "Pilih objek yang dapat Anda lihat dalam jangkauan. Benda tersebut dapat berupa pintu, kotak, peti, satu set borgol, gembok, atau benda lain yang mengandung sarana duniawi atau magis yang menghalangi akses.\nTarget yang ditahan dengan kunci biasa atau yang tertahan atau terpalang akan menjadi tidak terkunci, tidak tertahan, atau tidak tertahan. Jika objek memiliki beberapa kunci, hanya satu yang terbuka.\nJika Anda memilih target yang ditutup dengan kunci misterius, mantra itu akan ditekan selama 10 menit, selama waktu tersebut target dapat dibuka dan ditutup secara normal.\nSaat Anda mengucapkan mantranya, ketukan keras, terdengar dari jarak 300 kaki, berasal dari objek target." },
      { name: "Levitate", components: "V, S, M", desc: "Satu makhluk atau objek pilihan Anda yang dapat Anda lihat dalam jangkauannya naik secara vertikal, hingga 20 kaki, dan tetap tergantung di sana selama jangka waktu tersebut. Mantra tersebut dapat mengangkat target yang beratnya mencapai 500 pon. Makhluk yang enggan berhasil melakukan penyelamatan konstitusi tidak akan terpengaruh.\nTarget dapat bergerak hanya dengan mendorong atau menarik benda atau permukaan tertentu yang berada dalam jangkauannya (seperti dinding atau langit-langit), yang memungkinkannya bergerak seolah-olah sedang memanjat. Anda dapat mengubah ketinggian target hingga 20 kaki di kedua arah pada giliran Anda. Jika Anda adalah targetnya, Anda dapat bergerak ke atas atau ke bawah sebagai bagian dari gerakan Anda. Jika tidak, Anda dapat menggunakan tindakan Anda untuk memindahkan target, yang harus tetap berada dalam jangkauan mantra.\nSaat mantranya berakhir, target akan melayang perlahan ke tanah jika masih tinggi." },
      { name: "Locate Object", components: "V, S, M", desc: "Jelaskan atau beri nama suatu objek yang Anda kenal. Anda merasakan arah ke lokasi objek, selama objek tersebut berada dalam jarak 1.000 kaki dari Anda. Jika suatu benda bergerak, maka diketahui arah pergerakannya.\nMantra tersebut dapat menemukan lokasi objek tertentu yang Anda kenal, selama Anda telah melihatnya dari dekat--dalam jarak 30 kaki--setidaknya sekali. Alternatifnya, mantra tersebut dapat menemukan lokasi objek terdekat dari jenis tertentu, seperti jenis pakaian, perhiasan, furnitur, perkakas, atau senjata tertentu.\nMantra ini tidak dapat menemukan lokasi suatu objek jika ada timah tebal, bahkan lembaran tipis, menghalangi jalur langsung antara Anda dan objek tersebut." },
      { name: "Magic Mouth", components: "V, S, M", desc: "Anda menanam pesan ke suatu objek dalam jangkauan mantra. Pesan tersebut diungkapkan secara verbal ketika kondisi pemicu terpenuhi. Pilihlah benda yang Anda lihat, dan tidak dipakai atau dibawa oleh makhluk lain. Kemudian ucapkan pesannya, yang tidak boleh lebih dari 25 kata tetapi mendengarkannya bisa memakan waktu hingga 10 menit. Terakhir, tentukan keadaan yang memicu mantra untuk menyampaikan pesan Anda.\nKetika kondisi ini terpenuhi, mulut ajaib muncul pada objek dan mengartikulasikan pesan yang meniru suara Anda, nada yang sama yang digunakan selama penanaman pesan. Jika objek yang dipilih memiliki mulut atau sesuatu yang mendekat seperti mulut patung, mulut ajaib akan hidup pada titik ini, memberikan ilusi bahwa kata-kata tersebut berasal dari mulut objek.\nSaat Anda mengucapkan mantra ini, Anda dapat memutuskan bahwa mantra tersebut berakhir saat pesan terkirim atau mantra tersebut dapat bertahan dan mengulangi pesan tersebut kapan pun keadaan terjadi.\nKeadaan pemicunya bisa bersifat umum atau sedetail yang Anda inginkan, namun harus didasarkan pada kondisi visual atau suara yang terjadi dalam jarak 30 kaki dari objek. Misalnya, Anda dapat menginstruksikan mulut untuk berbicara ketika makhluk apa pun bergerak dalam jarak 30 kaki dari objek atau ketika bel perak berbunyi dalam jarak 30 kaki dari objek tersebut." },
      { name: "Magic Weapon", components: "V, S", desc: "Anda menyentuh senjata non-magis. Hingga mantranya berakhir, senjata itu menjadi senjata ajaib dengan bonus +1 untuk gulungan serangan dan gulungan kerusakan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, bonusnya meningkat menjadi +2. Saat Anda menggunakan slot mantra level 6 atau lebih tinggi, bonus meningkat menjadi +3." },
      { name: "Mirror Image", components: "V, S", desc: "Tiga duplikat ilusi diri Anda muncul di ruang Anda. Hingga mantranya berakhir, duplikatnya akan bergerak bersama Anda dan meniru tindakan Anda, berpindah posisi sehingga tidak mungkin melacak gambar mana yang asli. Anda dapat menggunakan tindakan Anda untuk menghilangkan duplikat ilusi.\nSetiap kali makhluk menargetkan Anda dengan serangan selama durasi mantra, putar d20 untuk menentukan apakah serangan tersebut menargetkan salah satu duplikat Anda.\nJika Anda memiliki tiga duplikat, Anda harus mendapatkan angka 6 atau lebih tinggi untuk mengubah target serangan menjadi duplikat. Dengan dua duplikat, Anda harus mendapatkan angka 8 atau lebih tinggi. Dengan satu duplikat, Anda harus mendapatkan angka 11 atau lebih tinggi.\nAC duplikat sama dengan 10 + pengubah Dexterity Anda. Jika serangan mengenai duplikat, duplikat tersebut akan hancur. Sebuah duplikat hanya dapat dihancurkan dengan serangan yang mengenainya. Itu mengabaikan semua kerusakan dan efek lainnya. Mantra berakhir ketika ketiga duplikatnya dihancurkan.\nMakhluk tidak terpengaruh oleh mantra ini jika ia tidak dapat melihat, jika ia mengandalkan indera selain penglihatan, seperti penglihatan buta, atau jika ia dapat melihat ilusi sebagai sesuatu yang salah, seperti penglihatan yang sebenarnya." },
      { name: "Misty Step", components: "V", desc: "Dikelilingi sebentar oleh kabut keperakan, Anda berteleportasi hingga 30 kaki ke ruang kosong yang dapat Anda lihat." },
      { name: "Ray of Enfeeblement", components: "V, S", desc: "Sinar hitam energi yang melemahkan muncul dari jari Anda menuju makhluk dalam jangkauan. Lakukan serangan mantra jarak jauh terhadap target. Saat terkena, target hanya memberikan setengah kerusakan dengan serangan senjata yang menggunakan Kekuatan hingga mantranya berakhir.\nDi akhir setiap giliran target, ia dapat melakukan penyelamatan konstitusi terhadap mantra tersebut. Jika berhasil, mantranya berakhir." },
      { name: "Rope Trick", components: "V, S, M", desc: "Anda menyentuh seutas tali yang panjangnya mencapai 60 kaki. Salah satu ujung tali kemudian terangkat ke udara hingga seluruh tali menggantung tegak lurus dengan tanah. Di ujung atas tali, pintu masuk tak kasat mata terbuka ke ruang ekstradimensi yang bertahan hingga mantranya berakhir.\nRuang ekstradimensi dapat dicapai dengan memanjat ke atas tali. Ruangan tersebut dapat menampung hingga delapan makhluk berukuran sedang atau lebih kecil. Tali tersebut dapat ditarik ke dalam ruang sehingga membuat tali tersebut hilang dari pandangan di luar ruang.\nSerangan dan mantra tidak bisa melewati pintu masuk atau keluar ruang ekstradimensi, tapi mereka yang berada di dalam bisa melihat keluar seolah-olah melalui jendela berukuran 3 kaki kali 5 kaki yang berpusat pada tali.\nApa pun yang berada di dalam ruang ekstradimensi akan hilang saat mantranya berakhir." },
      { name: "Scorching Ray", components: "V, S", desc: "Anda membuat tiga sinar api dan melemparkannya ke sasaran dalam jangkauan. Anda dapat melemparkannya ke satu atau beberapa sasaran.\nBuat serangan mantra jarak jauh untuk setiap sinar. Saat terkena, target menerima kerusakan api 2d6.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, Anda membuat satu sinar tambahan untuk setiap slot level di atas 2." },
      { name: "See Invisibility", components: "V, S, M", desc: "Selama durasi mantra, Anda melihat makhluk dan objek tak terlihat seolah-olah terlihat, dan Anda dapat melihat melalui Ethereal. Benda dan makhluk halus tampak tembus cahaya." },
      { name: "Shatter", components: "V, S, M", desc: "Suara dering keras yang tiba-tiba, sangat intens, muncul dari titik pilihan Anda dalam jangkauan. Setiap makhluk dalam bola berradius 10 kaki yang berpusat pada titik tersebut harus melakukan penyelamatan Konstitusi. Makhluk menerima kerusakan guntur 3d8 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil. Makhluk yang terbuat dari bahan anorganik seperti batu, kristal, atau logam memiliki kelemahan dalam penyelamatan ini.\nBenda non-magis yang tidak dipakai atau dibawa juga akan mengalami kerusakan jika berada dalam area mantra.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 3 atau lebih tinggi, kerusakan mantra meningkat sebesar 1d8 untuk setiap level slot mantra 2 yang lebih tinggi." },
      { name: "Spider Climb", components: "V, S, M", desc: "Hingga mantranya berakhir, satu makhluk yang Anda sentuh memperoleh kemampuan untuk bergerak ke atas, ke bawah, dan melintasi permukaan vertikal dan terbalik di sepanjang langit-langit, sambil membiarkan tangannya bebas. Target juga memperoleh kecepatan pendakian yang sama dengan kecepatan berjalannya." },
      { name: "Suggestion", components: "V, M", desc: "Anda menyarankan suatu rangkaian aktivitas (terbatas pada satu atau dua kalimat) dan secara ajaib memengaruhi makhluk yang dapat Anda lihat dalam jangkauan yang dapat mendengar dan memahami Anda. Makhluk yang tidak bisa dipesona akan kebal terhadap efek ini. Saran tersebut harus diungkapkan sedemikian rupa agar tindakan yang diambil terdengar masuk akal. Meminta makhluk itu untuk menusuk dirinya sendiri, melemparkan dirinya ke tombak, mengorbankan dirinya sendiri, atau melakukan tindakan berbahaya lainnya akan mengakhiri mantranya.\nTargetnya harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, ia akan melakukan tindakan yang Anda jelaskan dengan kemampuan terbaiknya. Tindakan yang disarankan dapat berlanjut sepanjang durasi. Jika aktivitas yang disarankan dapat diselesaikan dalam waktu yang lebih singkat, mantra akan berakhir saat subjek menyelesaikan apa yang diminta.\nAnda juga dapat menentukan kondisi yang akan memicu aktivitas khusus selama durasi tersebut. Misalnya, Anda mungkin menyarankan agar seorang kesatria memberikan kuda perangnya kepada pengemis pertama yang ditemuinya. Jika kondisi tidak terpenuhi sebelum mantra berakhir, aktivitas tidak akan dilakukan.\nJika Anda atau salah satu teman Anda merusak target, mantranya akan berakhir." },
      { name: "Web", components: "V, S, M", desc: "Anda membayangkan sekumpulan anyaman yang tebal dan lengket pada titik pilihan Anda dalam jangkauan. Jaring tersebut mengisi kubus berukuran 20 kaki dari titik tersebut selama durasi tersebut. Jaringnya merupakan medan yang sulit dan sedikit mengaburkan areanya.\nJika jaring tidak tertambat di antara dua benda padat (seperti dinding atau pohon) atau berlapis di lantai, dinding, atau langit-langit, jaring yang dibuat akan runtuh dengan sendirinya, dan mantra berakhir di awal giliran Anda berikutnya. Jaring yang berlapis di atas permukaan datar memiliki kedalaman 5 kaki.\nSetiap makhluk yang memulai gilirannya di jaring atau memasukinya pada gilirannya harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk tersebut akan ditahan selama ia masih berada di dalam jaring atau hingga ia terlepas.\nMakhluk yang tertahan oleh jaring dapat menggunakan aksinya untuk melakukan pemeriksaan Kekuatan terhadap mantra penyimpanan DC Anda. Jika berhasil, tidak lagi tertahan.\nJaringnya mudah terbakar. Jaring berbentuk kubus berukuran 5 kaki yang terkena api akan terbakar habis dalam 1 putaran, menimbulkan kerusakan akibat api sebesar 2d4 pada makhluk apa pun yang memulai gilirannya dalam api." },
    ],
    Level3: [
      { name: "Animate Dead", components: "V, S, M", desc: "Mantra ini menciptakan pelayan undead. Pilih tumpukan tulang atau mayat humanoid Sedang atau Kecil dalam jangkauan. Mantra Anda mengilhami target dengan mimikri kehidupan yang buruk, mengangkatnya sebagai makhluk undead. Targetnya menjadi kerangka jika Anda memilih tulang atau zombie jika Anda memilih mayat (GM memiliki statistik permainan makhluk tersebut).\nDi setiap giliran Anda, Anda dapat menggunakan tindakan bonus untuk secara mental memerintahkan makhluk apa pun yang Anda buat dengan mantra ini jika makhluk itu berada dalam jarak 60 kaki dari Anda (jika Anda mengendalikan beberapa makhluk, Anda dapat memerintahkan salah satu atau semuanya secara bersamaan, mengeluarkan perintah yang sama untuk masing-masing makhluk). Anda memutuskan tindakan apa yang akan diambil makhluk itu dan ke mana ia akan bergerak pada giliran berikutnya, atau Anda dapat mengeluarkan perintah umum, seperti menjaga ruangan atau koridor tertentu. Jika Anda tidak mengeluarkan perintah, makhluk itu hanya akan mempertahankan diri dari makhluk musuh. Setelah diberi perintah, makhluk tersebut terus mengikutinya hingga tugasnya selesai.\nMakhluk itu berada di bawah kendali Anda selama 24 jam, setelah itu ia berhenti mematuhi perintah apa pun yang Anda berikan. Untuk mempertahankan kendali atas makhluk tersebut selama 24 jam berikutnya, Anda harus mengucapkan mantra ini lagi pada makhluk tersebut sebelum periode 24 jam saat ini berakhir. Penggunaan mantra ini menegaskan kembali kendali Anda atas hingga empat makhluk yang telah Anda animasikan dengan mantra ini, daripada menganimasikan makhluk baru.\nSaat Anda mengucapkan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda menganimasikan atau menegaskan kembali kendali atas dua makhluk undead tambahan untuk setiap slot level di atas 3. Masing-masing makhluk tersebut pasti berasal dari bangkai atau tumpukan tulang yang berbeda-beda." },
      { name: "Bestow Curse", components: "V, S", desc: "Anda menyentuh makhluk, dan makhluk itu harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau menjadi terkutuk selama durasi mantra. Saat Anda mengucapkan mantra ini, pilih sifat kutukan dari opsi berikut:\n- Pilih satu skor kemampuan. Saat dikutuk, target memiliki kelemahan pada pemeriksaan kemampuan dan penyelamatan yang dilakukan dengan skor kemampuan tersebut.\n- Saat dikutuk, target memiliki kelemahan saat serangan bergulir ke arahmu.\n- Saat dikutuk, target harus melakukan lemparan penyelamatan kebijaksanaan di awal setiap putarannya. Jika gagal, tindakannya sia-sia dan tidak melakukan apa-apa.\n- Saat target dikutuk, serangan dan mantramu memberikan tambahan kerusakan nekrotik sebesar 1d8 ke target.\nMantra penghapus kutukan mengakhiri efek ini. Berdasarkan pilihan GM, Anda dapat memilih efek kutukan alternatif, tetapi efek kutukan tersebut tidak boleh lebih kuat dari yang dijelaskan di atas. GM mempunyai keputusan akhir mengenai dampak kutukan tersebut.\nLevel Tinggi: Jika Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, durasinya adalah konsentrasi, hingga 10 menit. Jika Anda menggunakan slot mantra level 5 atau lebih tinggi, durasinya adalah 8 jam. Jika Anda menggunakan slot mantra level 7 atau lebih tinggi, durasinya adalah 24 jam. Jika Anda menggunakan slot mantra level 9, mantra tersebut bertahan hingga dihilangkan. Menggunakan slot mantra level 5 atau lebih tinggi memberikan durasi yang tidak memerlukan konsentrasi." },
      { name: "Blink", components: "V, S", desc: "Gulung d20 di akhir setiap giliran Anda selama durasi mantra. Pada gulungan 11 atau lebih tinggi, Anda menghilang dari alam keberadaan Anda saat ini dan muncul di Alam Ethereal (mantranya gagal dan castingnya sia-sia jika Anda sudah berada di alam itu). Di awal giliran berikutnya, dan saat mantra berakhir jika Anda berada di Pesawat Ethereal, Anda kembali ke ruang kosong pilihan Anda yang dapat Anda lihat dalam jarak 10 kaki dari ruang tempat Anda menghilang. Jika tidak ada ruang kosong yang tersedia dalam rentang tersebut, Anda akan muncul di ruang kosong terdekat (dipilih secara acak jika ada lebih dari satu ruang yang jaraknya sama). Anda dapat mengabaikan mantra ini sebagai suatu tindakan.\nSaat berada di Pesawat Ethereal, Anda dapat melihat dan mendengar pesawat asal Anda, yang berwarna abu-abu, dan Anda tidak dapat melihat apa pun di sana lebih dari 60 kaki jauhnya. Anda hanya dapat mempengaruhi dan dipengaruhi oleh makhluk lain di Alam Ethereal. Makhluk yang tidak ada di sana tidak dapat melihat atau berinteraksi dengan Anda, kecuali mereka memiliki kemampuan untuk melakukannya." },
      { name: "Clairvoyance", components: "V, S, M", desc: "Anda membuat sensor tak kasat mata dalam jangkauan di lokasi yang familier bagi Anda (tempat yang pernah Anda kunjungi atau lihat sebelumnya) atau di lokasi jelas yang asing bagi Anda (seperti di balik pintu, di sudut, atau di rerimbunan pepohonan). Sensor tetap di tempatnya selama durasi tersebut, dan tidak dapat diserang atau berinteraksi dengannya.\nSaat Anda merapal mantra, Anda memilih melihat atau mendengar. Anda dapat menggunakan indra yang dipilih melalui sensor seolah-olah Anda berada di ruangnya. Saat tindakan Anda, Anda dapat beralih antara melihat dan mendengar.\nMakhluk yang dapat melihat sensor (seperti makhluk yang mendapat manfaat dari melihat tembus pandang atau penglihatan nyata) melihat bola bercahaya dan tidak berwujud seukuran kepalan tangan Anda." },
      { name: "Counterspell", components: "S", desc: "Anda mencoba mengganggu makhluk dalam proses merapal mantra. Jika makhluk tersebut mengeluarkan mantra level 3 atau lebih rendah, mantranya gagal dan tidak berpengaruh. Jika ia mengeluarkan mantra level 4 atau lebih tinggi, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika berhasil, mantra makhluk itu gagal dan tidak berpengaruh.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, mantra yang terputus tidak akan berpengaruh jika levelnya kurang dari atau sama dengan level slot mantra yang Anda gunakan." },
      { name: "Dispel Magic", components: "V, S", desc: "Pilih satu makhluk, objek, atau efek magis dalam jangkauan. Mantra level 3 atau lebih rendah pada target akan berakhir. Untuk setiap mantra level 4 atau lebih tinggi pada target, lakukan pemeriksaan kemampuan menggunakan kemampuan perapalan mantra Anda. DC sama dengan 10 + level mantra. Jika pemeriksaan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda secara otomatis mengakhiri efek mantra pada target jika level mantra sama dengan atau kurang dari level slot mantra yang Anda gunakan." },
      { name: "Fear", components: "V, S, M", desc: "Anda memproyeksikan gambaran khayalan tentang ketakutan terburuk suatu makhluk. Setiap makhluk dalam kerucut setinggi 30 kaki harus berhasil menyelamatkan lemparan atau menjatuhkan apa pun yang dipegangnya dan menjadi ketakutan selama itu.\nSaat ketakutan dengan mantra ini, makhluk harus mengambil tindakan Dash dan menjauh dari Anda melalui rute teraman yang tersedia di setiap belokannya, kecuali tidak ada tempat untuk bergerak. Jika makhluk tersebut mengakhiri gilirannya di lokasi yang tidak terlihat oleh Anda, makhluk tersebut dapat melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan berhasil, mantra untuk makhluk itu berakhir." },
      { name: "Fireball", components: "V, S, M", desc: "Garis terang memancar dari jari telunjuk Anda ke titik yang Anda pilih dalam jangkauan dan kemudian berkembang dengan suara gemuruh rendah menjadi ledakan api. Setiap makhluk dalam bola berradius 20 kaki yang berpusat pada titik tersebut harus melakukan lemparan penyelamatan ketangkasan. Target menerima kerusakan api sebesar 8d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil.\nApi menyebar ke berbagai sudut. Ini menyulut benda-benda yang mudah terbakar di area yang tidak dipakai atau dibawa.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 3." },
      { name: "Fly", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia. Target memperoleh kecepatan terbang 60 kaki selama durasi tersebut. Saat mantranya berakhir, target akan jatuh jika masih tinggi, kecuali jika dapat menghentikan jatuhnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 3." },
      { name: "Gaseous Form", components: "V, S, M", desc: "Anda mengubah makhluk yang Anda sentuh, beserta segala sesuatu yang dikenakan dan dibawanya, menjadi awan berkabut selama itu. Mantra berakhir jika poin hit makhluk itu turun menjadi 0. Makhluk inkorporeal tidak terpengaruh.\nSedangkan dalam bentuk ini, satu-satunya cara pergerakan target adalah kecepatan terbang 10 kaki. Targetnya bisa masuk dan menempati ruang makhluk lain. Target memiliki ketahanan terhadap kerusakan non-magis, dan memiliki keunggulan dalam Kekuatan, Ketangkasan, dan lemparan hemat konstitusi. Targetnya dapat melewati lubang kecil, bukaan sempit, dan bahkan retakan belaka, meskipun cairan tersebut diperlakukan seolah-olah permukaan padat. Target tidak bisa jatuh dan tetap melayang di udara bahkan ketika terkena stun atau tidak berdaya.\nSedangkan dalam bentuk awan berkabut, target tidak dapat berbicara atau memanipulasi objek, dan objek apa pun yang dibawa atau dipegangnya tidak dapat dijatuhkan, digunakan, atau berinteraksi dengannya. Target tidak dapat menyerang atau mengeluarkan mantra." },
      { name: "Glyph of Warding", components: "V, S, M", desc: "Saat Anda mengucapkan mantra ini, Anda menuliskan mesin terbang yang membahayakan makhluk lain, baik di permukaan (seperti meja atau bagian lantai atau dinding) atau di dalam objek yang dapat ditutup (seperti buku, gulungan, atau peti harta karun) untuk menyembunyikan mesin terbang tersebut. Jika Anda memilih suatu permukaan, mesin terbang tersebut dapat menutupi area permukaan yang diameternya tidak lebih dari 10 kaki. Jika Anda memilih suatu benda, benda itu harus tetap berada di tempatnya; jika objek dipindahkan lebih dari 10 kaki dari tempat Anda mengucapkan mantra ini, mesin terbangnya rusak, dan mantranya berakhir tanpa terpicu.\nMesin terbang tersebut hampir tidak terlihat dan memerlukan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap penyimpanan mantra DC Anda agar dapat ditemukan.\nAnda memutuskan apa yang memicu mesin terbang saat Anda mengucapkan mantranya. Untuk mesin terbang yang tertulis di suatu permukaan, pemicu yang paling umum adalah menyentuh atau berdiri di atas mesin terbang tersebut, memindahkan objek lain yang menutupi mesin terbang tersebut, mendekati dalam jarak tertentu dari mesin terbang tersebut, atau memanipulasi objek yang di atasnya mesin terbang tersebut ditorehkan. Untuk mesin terbang yang tertulis di dalam suatu objek, pemicu paling umum termasuk membuka objek tersebut, mendekati objek dalam jarak tertentu, atau melihat atau membaca mesin terbang tersebut. Setelah mesin terbang dipicu, mantra ini berakhir.\nAnda dapat menyempurnakan pemicunya lebih lanjut sehingga mantranya hanya aktif dalam keadaan tertentu atau berdasarkan karakteristik fisik (seperti tinggi atau berat), jenis makhluk (misalnya, lingkungan dapat diatur untuk memengaruhi penyimpangan atau tenggelam), atau penyelarasan. Anda juga dapat mengatur kondisi untuk makhluk yang tidak memicu mesin terbang, misalnya makhluk yang mengucapkan kata sandi tertentu.\nSaat Anda menuliskan mesin terbang, pilih *rune eksplosif* atau *mesin terbang mantra*.\n***Rune Peledak.*** Saat dipicu, mesin terbang tersebut meletus dengan energi magis dalam bola radius 20 kaki yang berpusat pada mesin terbang tersebut. Bola itu menyebar ke berbagai sudut. Setiap makhluk di area tersebut harus melakukan lemparan penyelamatan Dexterity. Makhluk menerima 5d8 kerusakan asam, dingin, api, kilat, atau guntur pada lemparan penyelamatan yang gagal (pilihan Anda saat membuat mesin terbang), atau setengah dari kerusakan pada lemparan penyelamatan yang berhasil.\n***Spell Glyph.*** Anda dapat menyimpan mantra level 3 atau lebih rendah yang telah disiapkan di mesin terbang dengan melemparkannya sebagai bagian dari pembuatan mesin terbang. Mantra tersebut harus menargetkan satu makhluk atau suatu area. Mantra yang disimpan tidak memiliki efek langsung saat digunakan dengan cara ini. Saat mesin terbang dipicu, mantra yang disimpan akan dilemparkan. Jika mantra memiliki target, mantra tersebut menargetkan makhluk yang memicu mesin terbang tersebut. Jika mantra mempengaruhi suatu area, area tersebut berpusat pada makhluk tersebut. Jika mantra tersebut memanggil makhluk bermusuhan atau membuat objek atau jebakan berbahaya, mereka akan muncul sedekat mungkin dengan penyusup dan menyerangnya. Jika mantra membutuhkan konsentrasi, mantra itu bertahan hingga durasi penuhnya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan mesin terbang rune eksplosif meningkat sebesar 1d8 untuk setiap level slot di atas 3. Jika Anda membuat mesin terbang mantra, Anda dapat menyimpan mantra apa pun hingga tingkat yang sama dengan slot yang Anda gunakan untuk mesin terbang penangkal." },
      { name: "Haste", components: "V, S, M", desc: "Pilih makhluk bersedia yang dapat Anda lihat dalam jangkauan. Hingga mantranya berakhir, kecepatan target menjadi dua kali lipat, ia memperoleh bonus +2 AC, ia memiliki keunggulan dalam lemparan penyelamatan ketangkasan, dan ia memperoleh tindakan tambahan di setiap putarannya. Tindakan tersebut hanya dapat digunakan untuk melakukan tindakan Serangan (satu serangan senjata saja), Dash, Disengage, Hide, atau Use an Object.\nKetika mantranya berakhir, target tidak dapat bergerak atau mengambil tindakan sampai giliran berikutnya, karena gelombang kelesuan melandanya." },
      { name: "Hypnotic Pattern", components: "S, M", desc: "Anda membuat pola warna yang berputar-putar yang terjalin di udara di dalam kubus berukuran 30 kaki dalam jangkauan. Pola itu muncul sesaat dan menghilang. Setiap makhluk di area tersebut yang melihat pola tersebut harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, makhluk itu menjadi terpesona selama durasi tersebut. Saat terpesona oleh mantra ini, makhluk itu tidak berdaya dan memiliki kecepatan 0.\nMantra berakhir untuk makhluk yang terkena dampak jika ia mengalami kerusakan atau jika orang lain menggunakan tindakan untuk mengguncang makhluk itu dari pingsannya." },
      { name: "Lightning Bolt", components: "V, S, M", desc: "Sambaran petir yang membentuk garis sepanjang 100 kaki dan lebar 5 kaki meluncur keluar dari Anda ke arah yang Anda pilih. Setiap makhluk dalam barisan harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan petir sebesar 8d6 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nPetir menyulut benda-benda mudah terbakar di area yang tidak dipakai atau dibawa.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 3." },
      { name: "Magic Circle", components: "V, S, M", desc: "Anda membuat silinder energi magis dengan radius 10 kaki dan tinggi 20 kaki yang berpusat pada suatu titik di tanah yang dapat Anda lihat dalam jangkauan. Rune bercahaya muncul setiap kali silinder berpotongan dengan lantai atau permukaan lainnya.\nPilih satu atau lebih jenis makhluk berikut: selestial, elemental, fey, iblis, atau undead. Lingkaran mempengaruhi makhluk dari tipe yang dipilih dengan cara berikut:\n- Makhluk itu tidak bisa dengan sukarela memasuki silinder dengan cara non-magis. Jika makhluk tersebut mencoba menggunakan teleportasi atau perjalanan antarplanar untuk melakukannya, ia harus berhasil melakukan lemparan penyelamatan karisma terlebih dahulu.\n- Makhluk tersebut memiliki kelemahan dalam serangan berguling terhadap target di dalam silinder.\n- Target di dalam silinder tidak dapat dipesona, ditakuti, atau dirasuki oleh makhluk tersebut.\nSaat Anda mengucapkan mantra ini, Anda dapat memilih untuk membuat sihirnya beroperasi ke arah sebaliknya, mencegah makhluk bertipe tertentu meninggalkan silinder dan melindungi target di luarnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, durasinya bertambah 1 jam untuk setiap slot level di atas 3." },
      { name: "Major Image", components: "V, S, M", desc: "Anda membuat gambar suatu benda, makhluk, atau fenomena nyata lainnya yang ukurannya tidak lebih besar dari kubus berukuran 20 kaki. Gambar muncul di tempat yang dapat Anda lihat dalam jangkauan dan berlangsung selama durasi tersebut. Tampaknya benar-benar nyata, termasuk suara, bau, dan suhu yang sesuai dengan benda yang digambarkan. Anda tidak dapat menciptakan panas atau dingin yang cukup untuk menyebabkan kerusakan, suara yang cukup keras untuk menyebabkan kerusakan akibat petir atau membuat tuli makhluk, atau bau yang dapat membuat makhluk sakit (seperti bau troglodyte).\nSelama Anda berada dalam jangkauan ilusi, Anda dapat menggunakan tindakan Anda untuk menyebabkan gambar berpindah ke tempat lain dalam jangkauan. Saat gambar berpindah lokasi, Anda dapat mengubah tampilannya sehingga gerakannya tampak natural pada gambar. Misalnya, jika Anda membuat gambar makhluk dan memindahkannya, Anda dapat mengubah gambar tersebut sehingga tampak seperti sedang berjalan. Demikian pula, Anda dapat menyebabkan ilusi mengeluarkan suara yang berbeda pada waktu yang berbeda, bahkan membuatnya melakukan percakapan, misalnya.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika suatu makhluk mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut, dan kualitas indra lainnya menjadi samar bagi makhluk tersebut.\nLevel Tinggi: Saat Anda merapalkan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, mantra tersebut akan bertahan hingga hilang, tanpa memerlukan konsentrasi Anda." },
      { name: "Nondetection", components: "V, S, M", desc: "Selama durasi tersebut, Anda menyembunyikan target yang Anda sentuh dari sihir ramalan. Sasarannya dapat berupa makhluk yang bersedia atau suatu tempat atau benda yang berukuran tidak lebih dari 10 kaki dalam dimensi apa pun. Targetnya tidak dapat ditargetkan oleh sihir ramalan apa pun atau dirasakan melalui sensor penglihatan magis." },
      { name: "Phantom Steed", components: "V, S", desc: "Makhluk besar mirip kuda yang tampak nyata muncul di tanah di ruang kosong pilihan Anda dalam jangkauan. Anda yang menentukan penampilan makhluk itu, tetapi ia dilengkapi dengan pelana, pahat, dan tali kekang. Peralatan apa pun yang dibuat oleh mantra tersebut akan hilang dalam kepulan asap jika dibawa lebih dari 10 kaki dari kudanya.\nSelama durasi tersebut, Anda atau makhluk yang Anda pilih dapat menunggangi kuda tersebut. Makhluk itu menggunakan statistik untuk menunggang kuda, hanya saja ia memiliki kecepatan 100 kaki dan dapat menempuh jarak 10 mil dalam satu jam, atau 13 mil dengan kecepatan tinggi. Saat mantra berakhir, kudanya perlahan memudar, memberikan waktu 1 menit kepada pengendaranya untuk turun. Mantra berakhir jika Anda menggunakan suatu tindakan untuk mengabaikannya atau jika kudanya mengalami kerusakan." },
      { name: "Protection From Energy", components: "V, S", desc: "Selama durasi tersebut, makhluk yang Anda sentuh memiliki ketahanan terhadap satu jenis kerusakan pilihan Anda: asam, dingin, api, kilat, atau guntur." },
      { name: "Remove Curse", components: "V, S", desc: "Dengan sentuhan Anda, semua kutukan yang memengaruhi satu makhluk atau objek berakhir. Jika benda tersebut merupakan benda sihir terkutuk, kutukannya tetap ada, tetapi mantranya merusak attunement pemiliknya terhadap benda tersebut sehingga dapat dikeluarkan atau dibuang." },
      { name: "Sending", components: "V, S, M", desc: "Anda mengirim pesan singkat yang terdiri dari dua puluh lima kata atau kurang kepada makhluk yang Anda kenal. Makhluk itu mendengar pesan dalam pikirannya, mengenali Anda sebagai pengirimnya jika ia mengenal Anda, dan dapat segera menjawab dengan cara yang sama. Mantra ini memungkinkan makhluk dengan skor Intelegensi minimal 1 untuk memahami maksud pesan Anda.\nAnda dapat mengirim pesan melintasi jarak berapa pun dan bahkan ke alam eksistensi lain, namun jika target berada di alam yang berbeda dari Anda, ada kemungkinan 5 persen pesan tersebut tidak sampai." },
      { name: "Sleet Storm", components: "V, S, M", desc: "Hingga mantranya berakhir, hujan beku dan hujan es akan turun dalam silinder setinggi 20 kaki dengan radius 40 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan. Area tersebut sangat tertutup, dan api yang terbuka di area tersebut telah padam.\nTanah di kawasan tersebut tertutup es licin sehingga menyulitkan medan. Saat makhluk memasuki area mantra untuk pertama kalinya pada suatu giliran atau memulai gilirannya di sana, ia harus melakukan lemparan penyelamatan ketangkasan. Pada penyelamatan yang gagal, ia menjadi rawan.\nJika makhluk sedang berkonsentrasi di area mantra, makhluk tersebut harus berhasil melakukan lemparan penyelamatan konstitusi terhadap penyelamatan mantra Anda DC atau kehilangan konsentrasi." },
      { name: "Slow", components: "V, S, M", desc: "Anda mengubah waktu hingga enam makhluk pilihan Anda dalam kubus berukuran 40 kaki dalam jangkauan. Setiap target harus berhasil dalam lemparan penyelamatan kebijaksanaan atau terpengaruh oleh mantra ini selama durasi tersebut.\nKecepatan target yang terpengaruh dikurangi setengahnya, dibutuhkan penalti -2 pada AC dan lemparan penyelamatan ketangkasan, dan tidak dapat menggunakan reaksi. Pada gilirannya, ia dapat menggunakan salah satu tindakan atau tindakan bonus, tidak keduanya. Terlepas dari kemampuan atau item sihir makhluk tersebut, ia tidak dapat melakukan lebih dari satu serangan jarak dekat atau jarak jauh selama gilirannya.\nJika makhluk tersebut mencoba merapal mantra dengan waktu casting 1 tindakan, putar d20. Pada level 11 atau lebih tinggi, mantra tidak akan berpengaruh hingga giliran makhluk berikutnya, dan makhluk tersebut harus menggunakan aksinya pada giliran tersebut untuk menyelesaikan mantranya. Jika tidak bisa, mantranya akan sia-sia.\nMakhluk yang terkena mantra ini melakukan lemparan penyelamatan kebijaksanaan lainnya di akhir gilirannya. Jika penyimpanan berhasil, efeknya akan berakhir." },
      { name: "Stinking Cloud", components: "V, S, M", desc: "Anda membuat bola gas berwarna kuning dengan radius 20 kaki yang berpusat pada suatu titik dalam jangkauan. Awan menyebar ke segala penjuru, dan wilayahnya sangat tertutup. Awan tetap berada di udara selama itu.\nSetiap makhluk yang sepenuhnya berada di dalam awan pada awal gilirannya harus melakukan penyelamatan konstitusi terhadap racun. Jika penyelamatan gagal, makhluk itu mengeluarkan aksinya yang berubah menjadi muntah-muntah dan terhuyung-huyung. Makhluk yang tidak perlu bernapas atau kebal terhadap racun otomatis berhasil dalam penyelamatan ini.\nAngin sedang (setidaknya 10 mil per jam) menyebarkan awan setelah 4 putaran. Angin kencang (setidaknya 20 mil per jam) menyebarkannya setelah 1 putaran." },
      { name: "Tiny Hut", components: "V, S, M", desc: "Kubah gaya tak bergerak dengan radius 10 kaki muncul di sekitar dan di atas Anda dan tetap diam selama jangka waktu tersebut. Mantranya berakhir jika Anda meninggalkan areanya.\nSembilan makhluk berukuran sedang atau lebih kecil dapat masuk ke dalam kubah bersama Anda. Mantra gagal jika areanya mencakup makhluk yang lebih besar atau lebih dari sembilan makhluk. Makhluk dan objek di dalam kubah saat Anda mengucapkan mantra ini dapat bergerak melewatinya dengan bebas. Semua makhluk dan benda lain dilarang melewatinya. Mantra dan efek magis lainnya tidak dapat menembus kubah atau dilemparkan ke dalamnya. Suasana di dalam ruangan nyaman dan kering, tidak peduli cuaca di luar.\nHingga mantranya berakhir, Anda dapat memerintahkan interior menjadi remang-remang atau gelap. Kubahnya buram dari luar, warna apa pun yang Anda pilih, tetapi transparan dari dalam." },
      { name: "Tongues", components: "V, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk memahami bahasa lisan apa pun yang didengarnya. Terlebih lagi, ketika target berbicara, makhluk apa pun yang mengetahui setidaknya satu bahasa dan dapat mendengar target akan memahami apa yang dikatakannya." },
      { name: "Vampiric Touch", components: "V, S", desc: "Sentuhan tangan Anda yang dilingkari bayangan dapat menyedot kekuatan hidup orang lain untuk menyembuhkan luka Anda. Lakukan serangan mantra jarak dekat terhadap makhluk dalam jangkauan Anda. Saat terkena, target menerima 3d6 kerusakan nekrotik, dan Anda mendapatkan kembali poin serangan yang setara dengan setengah jumlah kerusakan nekrotik yang diberikan. Hingga mantranya berakhir, Anda dapat melakukan serangan lagi di setiap giliran Anda sebagai suatu tindakan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 4 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 3." },
      { name: "Water Breathing", components: "V, S, M", desc: "Mantra ini memberikan maksimal sepuluh makhluk yang bersedia berada dalam jangkauannya dan Anda dapat melihat, kemampuan bernapas di bawah air hingga akhir masa berlakunya. Makhluk yang terkena dampak juga mempertahankan pola pernapasan normalnya." },
    ],
    Level4: [
      { name: "Arcane Eye", components: "V, S, M", desc: "Anda menciptakan mata ajaib yang tidak terlihat dalam jangkauan yang melayang di udara selama durasi tersebut.\nAnda secara mental menerima informasi visual dari mata, yang memiliki penglihatan normal dan penglihatan gelap hingga jarak 30 kaki. Mata bisa melihat ke segala arah.\nSebagai tindakan, Anda bisa menggerakkan mata hingga 30 kaki ke segala arah. Tidak ada batasan seberapa jauh mata dapat bergerak dari Anda, namun mata tidak dapat memasuki alam eksistensi lain. Sebuah penghalang padat menghalangi pergerakan mata, namun mata dapat melewati lubang berdiameter sekecil 1 inci." },
      { name: "Banishment", components: "V, S, M", desc: "Anda mencoba mengirim satu makhluk yang dapat Anda lihat dalam jangkauannya ke alam eksistensi lain. Targetnya harus berhasil dalam penyelamatan karisma atau diasingkan.\nJika targetnya berasal dari alam eksistensi yang Anda tempati, Anda membuang target tersebut ke demiplane yang tidak berbahaya. Saat berada di sana, targetnya tidak berdaya. Target tetap di sana sampai mantranya berakhir, pada saat itu target muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi.\nJika target berasal dari alam eksistensi yang berbeda dari tempat Anda berada, target akan dibuang dengan suara letupan samar, dan kembali ke alam asalnya. Jika mantra berakhir sebelum 1 menit berlalu, target akan muncul kembali di ruang yang tersisa atau di ruang kosong terdekat jika ruang tersebut terisi. Jika tidak, targetnya tidak akan kembali.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, Anda dapat menargetkan satu makhluk tambahan untuk setiap slot level di atas 4." },
      { name: "Black Tentacles", components: "V, S, M", desc: "Tentakel kayu hitam yang menggeliat memenuhi permukaan tanah seluas 20 kaki yang dapat Anda lihat dalam jangkauan. Selama ini, tentakel ini mengubah tanah di area tersebut menjadi medan yang sulit.\nSaat makhluk memasuki area yang terkena dampak untuk pertama kalinya dalam sebuah giliran atau memulai gilirannya di sana, makhluk tersebut harus berhasil melakukan lemparan penyelamatan Dexterity atau menerima kerusakan pukulan 3d6 dan ditahan oleh tentakel hingga mantranya berakhir. Makhluk yang memulai gilirannya di area tersebut dan sudah tertahan oleh tentakel akan menerima kerusakan sebesar 3d6.\nMakhluk yang terkekang oleh tentakel dapat menggunakan aksinya untuk melakukan pemeriksaan Kekuatan atau Ketangkasan (pilihannya) terhadap penyelamatan mantra DC Anda. Jika berhasil, ia membebaskan dirinya sendiri." },
      { name: "Blight", components: "V, S", desc: "Energi necromantic menyapu makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan, menguras kelembapan dan vitalitas darinya. Targetnya harus melakukan penyelamatan konstitusi. Target menerima 8d8 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil. Mantra ini tidak berpengaruh pada undead atau konstruksi.\nJika Anda menargetkan makhluk tumbuhan atau tumbuhan ajaib, lemparan penyelamatan akan merugikan, dan mantranya akan memberikan kerusakan maksimal padanya.\nJika Anda menargetkan tanaman non-magis yang bukan makhluk, seperti pohon atau semak, hal tersebut tidak akan menjadi solusi penyelamatan; itu hanya layu dan mati.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 ke atas, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas ke-4." },
      { name: "Confusion", components: "V, S, M", desc: "Mantra ini menyerang dan memutarbalikkan pikiran makhluk, menimbulkan delusi dan memicu tindakan yang tidak terkendali. Setiap makhluk dalam bola berradius 10 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan harus berhasil melakukan lemparan penyelamatan Kebijaksanaan saat Anda mengucapkan mantra ini atau terpengaruh olehnya.\nTarget yang terpengaruh tidak dapat bereaksi dan harus melempar d10 di awal setiap giliran untuk menentukan perilakunya pada giliran tersebut.\n| d10 | Perilaku |\n|---|---|\n| 1 | Makhluk itu menggunakan seluruh gerakannya untuk bergerak ke arah yang acak. Untuk menentukan arah, putar d8 dan tetapkan arah pada setiap permukaan dadu. Makhluk itu tidak mengambil tindakan pada giliran ini. |\n| 2-6 | Makhluk itu tidak bergerak atau mengambil tindakan pada giliran ini. |\n| 7-8 | Makhluk itu menggunakan aksinya untuk melakukan serangan jarak dekat terhadap makhluk yang ditentukan secara acak dalam jangkauannya. Jika tidak ada makhluk dalam jangkauannya, makhluk itu tidak akan melakukan apa pun pada giliran ini. |\n| 9-10 | Makhluk itu dapat bertindak dan bergerak dengan normal. |\nDi akhir setiap giliran, target yang terkena dampak dapat melakukan lemparan penyelamatan Wisdom. Jika berhasil, efek ini berakhir untuk target tersebut.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, radius bola bertambah 5 kaki untuk setiap slot level di atas 4." },
      { name: "Conjure Minor Elementals", components: "V, S", desc: "Anda memanggil elemen yang muncul di ruang kosong yang dapat Anda lihat dalam jangkauan. Anda memilih salah satu opsi berikut untuk apa yang muncul:\n- Satu elemen tantangan dengan peringkat 2 atau lebih rendah\n- Dua elemen dengan peringkat tantangan 1 atau lebih rendah\n- Empat elemen dengan peringkat tantangan 1/2 atau lebih rendah\n- Delapan elemen dengan peringkat tantangan 1/4 atau lebih rendah.\nElemen yang dipanggil oleh mantra ini menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nMakhluk yang dipanggil ramah terhadap Anda dan teman Anda. Gulung inisiatif untuk makhluk yang dipanggil sebagai kelompok, yang memiliki giliran tersendiri. Mereka mematuhi perintah verbal apa pun yang Anda berikan kepada mereka (Anda tidak perlu melakukan tindakan apa pun). Jika Anda tidak memberikan perintah apa pun kepada mereka, mereka mempertahankan diri dari makhluk bermusuhan, tetapi sebaliknya tidak mengambil tindakan.\nGM mempunyai statistik makhluk-makhluk itu.\nLevel Tinggi: Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat tinggi tertentu, Anda memilih salah satu opsi pemanggilan di atas, dan lebih banyak makhluk muncul: dua kali lebih banyak dengan slot level 6 dan tiga kali lebih banyak dengan slot level 8." },
      { name: "Control Water", components: "V, S, M", desc: "Hingga mantranya berakhir, Anda mengontrol air yang berdiri sendiri di dalam area yang Anda pilih, yaitu kubus dengan tinggi hingga 100 kaki di sisinya. Anda dapat memilih salah satu efek berikut saat menggunakan mantra ini. Sebagai tindakan pada giliran Anda, Anda dapat mengulangi efek yang sama atau memilih efek yang berbeda.\n***Banjir.*** Anda menyebabkan permukaan air di semua genangan air di area tersebut naik sebanyak 20 kaki. Jika wilayah tersebut termasuk pantai, maka air banjir akan meluap ke daratan kering.\nJika Anda memilih suatu area di perairan yang luas, Anda malah menciptakan gelombang setinggi 20 kaki yang bergerak dari satu sisi area ke sisi lainnya dan kemudian jatuh. Kendaraan besar atau kecil apa pun yang berada di jalur gelombang akan terbawa ke sisi lain. Kendaraan besar atau kecil apa pun yang terkena gelombang mempunyai peluang 25 persen untuk terbalik.\nKetinggian air tetap tinggi hingga mantra berakhir atau Anda memilih efek lain. Jika efek ini menghasilkan gelombang, gelombang tersebut akan berulang pada awal giliran Anda berikutnya selama efek banjir berlangsung.\n***Bagian Air.*** Anda menyebabkan air di area tersebut menjauh dan membuat parit. Parit tersebut membentang melintasi area mantra, dan air yang terpisah membentuk dinding di kedua sisinya. Parit tetap ada sampai mantranya berakhir atau Anda memilih efek yang berbeda. Air kemudian perlahan-lahan mengisi parit selama putaran berikutnya sampai ketinggian air kembali normal.\n***Aliran Pengalihan.*** Anda menyebabkan air yang mengalir di area tersebut bergerak ke arah yang Anda pilih, meskipun air harus mengalir melewati rintangan, ke atas tembok, atau ke arah lain yang tidak terduga. Air di area tersebut bergerak saat Anda mengarahkannya, tetapi setelah bergerak melampaui area mantra, air tersebut melanjutkan alirannya berdasarkan kondisi medan. Air terus bergerak ke arah yang Anda pilih hingga mantranya berakhir atau Anda memilih efek yang berbeda.\n***Whirlpool.*** Efek ini memerlukan badan air setidaknya 50 kaki persegi dan kedalaman 25 kaki. Anda menyebabkan pusaran air terbentuk di tengah area. Pusaran air tersebut membentuk pusaran dengan lebar dasar 5 kaki, lebar bagian atas hingga 50 kaki, dan tinggi 25 kaki. Makhluk atau benda apa pun di dalam air dan dalam jarak 25 kaki dari pusaran akan ditarik sejauh 10 kaki ke arahnya. Makhluk dapat berenang menjauh dari pusaran dengan melakukan pemeriksaan Kekuatan (Atletik) terhadap mantra Anda, simpan DC.\nKetika makhluk memasuki pusaran untuk pertama kalinya pada suatu belokan atau memulai belokannya di sana, ia harus melakukan lemparan yang menghemat kekuatan. Jika penyelamatan gagal, makhluk itu menerima kerusakan sebesar 2d8 dan terjebak dalam pusaran hingga mantranya berakhir. Jika penyelamatan berhasil, makhluk itu menerima setengah kerusakan, dan tidak terjebak dalam pusaran. Makhluk yang terjebak dalam pusaran dapat menggunakan aksinya untuk mencoba berenang menjauh dari pusaran seperti dijelaskan di atas, namun memiliki kelemahan pada pemeriksaan Kekuatan (Atletik) untuk melakukannya.\nPertama kali setiap putaran suatu benda memasuki pusaran, benda tersebut menerima kerusakan pukulan sebesar 2d8; kerusakan ini terjadi setiap putarannya tetap berada di pusaran." },
      { name: "Dimension Door", components: "V", desc: "Anda berteleportasi dari lokasi Anda saat ini ke tempat lain dalam jangkauan. Anda tiba di tempat yang diinginkan. Ini bisa berupa tempat yang bisa Anda lihat, yang bisa Anda visualisasikan, atau yang bisa Anda gambarkan dengan menyatakan jarak dan arah, seperti \"200 kaki lurus ke bawah\" atau \"ke atas ke arah barat laut dengan sudut 45 derajat, 300 kaki\".\nAnda boleh membawa barang selama beratnya tidak melebihi apa yang dapat Anda bawa. Anda juga dapat membawa satu makhluk berukuran Anda atau lebih kecil yang membawa perlengkapan sesuai daya dukungnya. Makhluk itu harus berada dalam jarak 5 kaki dari Anda saat Anda mengucapkan mantra ini.\nJika Anda akan tiba di tempat yang sudah ditempati oleh suatu benda atau makhluk, Anda dan makhluk apa pun yang bepergian bersama Anda masing-masing akan menerima kerusakan kekuatan 4d6, dan mantra tersebut gagal untuk memindahkan Anda." },
      { name: "Fabricate", components: "V, S", desc: "Anda mengubah bahan mentah menjadi produk dari bahan yang sama. Misalnya, Anda bisa membuat jembatan kayu dari rumpun pohon, tali dari sepetak rami, dan pakaian dari rami atau wol.\nPilih bahan mentah yang dapat Anda lihat dalam jangkauan. Anda dapat membuat benda besar atau lebih kecil (yang terdapat dalam kubus berukuran 10 kaki, atau delapan kubus berukuran 5 kaki yang saling terhubung), dengan jumlah bahan mentah yang cukup. Namun, jika Anda mengerjakan logam, batu, atau bahan mineral lainnya, objek yang dibuat tidak boleh lebih besar dari Medium (ditampung dalam satu kubus berukuran 5 kaki). Kualitas benda yang dibuat dengan mantra sepadan dengan kualitas bahan bakunya.\nMakhluk atau item sihir tidak dapat dibuat atau diubah dengan mantra ini. Anda juga tidak dapat menggunakannya untuk membuat item yang biasanya membutuhkan pengerjaan tingkat tinggi, seperti perhiasan, senjata, kaca, atau baju besi, kecuali Anda mahir dengan jenis peralatan pengrajin yang digunakan untuk membuat objek tersebut." },
      { name: "Faithful Hound", components: "V, S, M", desc: "Anda membayangkan hantu pengawas di ruang kosong yang dapat Anda lihat dalam jangkauan, di mana ia tetap berada selama durasi tersebut, hingga Anda mengabaikannya sebagai suatu tindakan, atau hingga Anda menjauh lebih dari 100 kaki darinya.\nAnjing itu tidak terlihat oleh semua makhluk kecuali Anda dan tidak dapat disakiti. Ketika makhluk kecil atau lebih besar datang dalam jarak 30 kaki darinya tanpa terlebih dahulu mengucapkan kata sandi yang Anda tentukan saat mengucapkan mantra ini, anjing itu mulai menggonggong dengan keras. Anjing itu melihat makhluk tak kasat mata dan bisa melihat ke dalam Alam Ethereal. Itu mengabaikan ilusi.\nDi awal setiap giliran Anda, anjing tersebut mencoba menggigit satu makhluk dalam jarak 5 kaki darinya yang memusuhi Anda. Bonus serangan anjing itu sama dengan pengubah kemampuan perapalan mantra Anda + bonus kemahiran Anda. Saat terkena, ia menimbulkan kerusakan penusuk 4d8." },
      { name: "Fire Shield", components: "V, S, M", desc: "Api tipis dan berbentuk uap mengelilingi tubuh Anda selama mantra berlangsung, memancarkan cahaya terang dalam radius 10 kaki dan cahaya redup dalam radius 10 kaki tambahan. Anda dapat mengakhiri mantra menggunakan tindakan untuk menghilangkannya.\nNyala api ada di sekitar Anda sebagai pelindung panas atau dingin, pilihan Anda. Pelindung panas memberi Anda ketahanan terhadap kerusakan dingin dan ketahanan dingin terhadap kerusakan akibat kebakaran.\nSelain itu, setiap kali makhluk dalam jarak 5 kaki dari Anda menyerang Anda dengan serangan jarak dekat, api akan muncul dari perisai. Penyerang kemudian menderita 2d8 poin kerusakan api atau dingin, tergantung modelnya." },
      { name: "Greater Invisibility", components: "V, S", desc: "Anda atau makhluk yang Anda sentuh menjadi tidak terlihat sampai mantranya berakhir. Apapun yang dikenakan atau dibawa oleh target tidak akan terlihat selama berada pada orang yang menjadi target." },
      { name: "Hallucinatory Terrain", components: "V, S, M", desc: "Anda membuat medan alami dalam kubus berukuran 150 kaki dalam jangkauan tampilan, suara, dan aroma seperti medan alami lainnya. Dengan demikian, lapangan terbuka atau jalan dapat dibuat menyerupai rawa, bukit, jurang, atau medan lain yang sulit atau tidak dapat dilalui. Sebuah kolam dapat dibuat tampak seperti padang rumput, jurang seperti lereng yang landai, atau selokan yang dipenuhi bebatuan seperti jalan yang lebar dan mulus. Struktur, peralatan, dan makhluk yang diproduksi di dalam area tersebut tidak berubah tampilannya.\nKarakteristik sentuhan medan tidak berubah, sehingga makhluk yang memasuki area tersebut kemungkinan besar dapat melihat melalui ilusi. Jika perbedaannya tidak terlihat jelas jika disentuh, makhluk yang memeriksa ilusi dengan cermat dapat mencoba melakukan pemeriksaan Intelijen (Investigasi) terhadap mantra Anda, simpan DC untuk tidak mempercayainya. Makhluk yang memahami ilusi apa adanya, melihatnya sebagai gambaran samar yang ditumpangkan di medan." },
      { name: "Ice Storm", components: "V, S, M", desc: "Hujan es sekeras batu menghantam tanah dalam silinder dengan radius 20 kaki dan tinggi 40 kaki yang berpusat pada suatu titik dalam jangkauan. Setiap makhluk di dalam silinder harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima 2d8 kerusakan pukulan dan 4d6 kerusakan dingin pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nHujan es mengubah area pengaruh badai menjadi medan yang sulit hingga akhir giliran Anda berikutnya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, kerusakan pukulan meningkat sebesar 1d8 untuk setiap level slot di atas 4." },
      { name: "Locate Creature", components: "V, S, M", desc: "Jelaskan atau beri nama makhluk yang Anda kenal. Anda merasakan arah ke lokasi makhluk itu, selama makhluk itu berada dalam jarak 1.000 kaki dari Anda. Jika makhluk itu bergerak, Anda mengetahui arah pergerakannya.\nMantra ini dapat menemukan lokasi makhluk tertentu yang Anda kenal, atau makhluk terdekat dari jenis tertentu (seperti manusia atau unicorn), selama Anda pernah melihat makhluk tersebut dari dekat--dalam jarak 30 kaki--setidaknya sekali. Jika makhluk yang Anda gambarkan atau beri nama berada dalam bentuk yang berbeda, seperti berada di bawah pengaruh mantra polimorf, mantra ini tidak akan menemukan lokasi makhluk tersebut.\nMantra ini tidak dapat menemukan lokasi makhluk jika air yang mengalir selebar 10 kaki menghalangi jalur langsung antara Anda dan makhluk tersebut." },
      { name: "Phantasmal Killer", components: "V, S", desc: "Anda memanfaatkan mimpi buruk makhluk yang dapat Anda lihat dalam jangkauan dan menciptakan manifestasi ilusi dari ketakutan terdalamnya, yang hanya dapat dilihat oleh makhluk itu. Targetnya harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, target menjadi ketakutan selama durasi tersebut. Di awal setiap giliran target sebelum mantra berakhir, target harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau menerima kerusakan psikis 4d10. Jika penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, kerusakan meningkat sebesar 1d10 untuk setiap slot level di atas 4." },
      { name: "Polymorph", components: "V, S, M", desc: "Mantra ini mengubah makhluk yang dapat Anda lihat dalam jangkauan menjadi bentuk baru. Makhluk yang tidak mau harus melakukan lemparan penyelamatan yang bijaksana untuk menghindari dampaknya. Seorang pengubah bentuk secara otomatis berhasil dalam lemparan penyelamatan ini.\nTransformasi berlangsung selama durasi tersebut, atau hingga target turun menjadi 0 poin hit atau mati. Bentuk baru dapat berupa monster apa pun yang peringkat tantangannya sama dengan atau lebih kecil dari target (atau level target, jika tidak memiliki peringkat tantangan). Statistik permainan target, termasuk skor kemampuan mental, digantikan oleh statistik binatang yang dipilih. Ia mempertahankan keselarasan dan kepribadiannya.\nTargetnya mengasumsikan titik sasaran dari bentuk barunya. Ketika ia kembali ke bentuk normalnya, makhluk itu kembali ke jumlah titik serangan yang dimilikinya sebelum ia bertransformasi. Jika poin serangannya kembali karena poin hitnya turun menjadi 0, kerusakan berlebih akan kembali ke bentuk normalnya. Selama kerusakan berlebih tidak mengurangi bentuk normal makhluk itu menjadi 0 poin serangan, ia tidak akan pingsan.\nTindakan yang dapat dilakukan makhluk ini terbatas karena sifat dari bentuk barunya, dan ia tidak dapat berbicara, merapal mantra, atau melakukan tindakan lain apa pun yang memerlukan tangan atau ucapan.\nPerlengkapan target menyatu ke dalam bentuk baru. Makhluk itu tidak dapat mengaktifkan, menggunakan, menggunakan, atau memanfaatkan peralatan apa pun." },
      { name: "Private Sanctum", components: "V, S, M", desc: "Anda membuat area dalam jangkauan aman secara ajaib. Luasnya berupa kubus yang bisa berukuran sekecil 5 kaki hingga sebesar 100 kaki di setiap sisinya. Mantra tersebut bertahan selama durasi tersebut atau hingga Anda menggunakan suatu tindakan untuk mengabaikannya.\nSaat Anda mengucapkan mantra, Anda memutuskan jenis keamanan yang diberikan mantra tersebut, dengan memilih salah satu atau semua properti berikut:\n- Suara tidak dapat melewati penghalang di tepi area yang dilindungi.\n- Penghalang area yang dikurung tampak gelap dan berkabut, menghalangi penglihatan (termasuk penglihatan gelap) melaluinya.\n- Sensor yang dibuat oleh mantra ramalan tidak dapat muncul di dalam kawasan lindung atau melewati penghalang di sekelilingnya.\n- Makhluk di area tersebut tidak dapat dijadikan sasaran mantra ramalan.\n- Tidak ada yang bisa berteleportasi ke dalam atau ke luar area yang dilindungi.\n- Perjalanan planar diblokir di dalam area yang dilindungi.\nMengucapkan mantra ini di tempat yang sama setiap hari selama setahun akan menjadikan efek ini permanen.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, Anda dapat meningkatkan ukuran kubus sebesar 100 kaki untuk setiap level slot melebihi level 4. Dengan demikian Anda bisa melindungi kubus yang satu sisinya bisa mencapai 200 kaki dengan menggunakan slot mantra level 5." },
      { name: "Resilient Sphere", components: "V, S, M", desc: "Sebuah bola kekuatan berkilauan melingkupi makhluk atau objek berukuran besar atau lebih kecil dalam jangkauannya. Makhluk yang enggan harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, makhluk itu akan dikurung selama durasi tersebut.\nTidak ada apa pun--tidak benda fisik, energi, atau efek mantra lainnya--yang dapat melewati penghalang, masuk atau keluar, meskipun makhluk di dalam bola dapat bernapas di sana. Bola tersebut kebal terhadap semua kerusakan, dan makhluk atau objek di dalamnya tidak dapat dirusak oleh serangan atau efek yang berasal dari luar, dan makhluk di dalam bola juga tidak dapat merusak apa pun di luarnya.\nBola tersebut tidak berbobot dan cukup besar untuk menampung makhluk atau benda di dalamnya. Makhluk yang tertutup dapat menggunakan aksinya untuk mendorong dinding bola dan menggelindingkan bola hingga setengah kecepatan makhluk tersebut. Demikian pula, bumi dapat diangkat dan digerakkan oleh makhluk lain.\nMantra penghancur yang menargetkan bola dunia akan menghancurkannya tanpa melukai apa pun di dalamnya." },
      { name: "Secret Chest", components: "V, S, M", desc: "Anda menyembunyikan peti, dan semua isinya, di Pesawat Ethereal. Anda harus menyentuh peti dan replika miniatur yang berfungsi sebagai komponen material mantra. Peti tersebut dapat menampung hingga 12 kaki kubik benda mati (3 kaki kali 2 kaki kali 2 kaki).\nSelagi peti tersebut tetap berada di Pesawat Ethereal, Anda dapat menggunakan suatu tindakan dan menyentuh replikanya untuk memanggil kembali peti tersebut. Itu muncul di ruang kosong di tanah dalam jarak 5 kaki dari Anda. Anda dapat mengirim peti itu kembali ke Pesawat Ethereal dengan menggunakan suatu tindakan dan menyentuh peti itu dan replikanya.\nSetelah 60 hari, ada peluang kumulatif 5 persen per hari bahwa efek mantranya berakhir. Efek ini berakhir jika Anda mengucapkan mantra ini lagi, jika peti replika yang lebih kecil dihancurkan, atau jika Anda memilih untuk mengakhiri mantra sebagai suatu tindakan. Jika mantranya berakhir dan peti yang lebih besar berada di Alam Ethereal, peti itu akan hilang dan tidak dapat diambil kembali." },
      { name: "Stone Shape", components: "V, S, M", desc: "Anda menyentuh benda batu berukuran sedang atau lebih kecil atau bagian batu tidak lebih dari 5 kaki dalam dimensi apa pun dan membentuknya menjadi bentuk apa pun yang sesuai dengan tujuan Anda. Jadi, misalnya, Anda dapat membentuk sebuah batu besar menjadi senjata, berhala, atau peti, atau membuat jalan kecil melewati dinding, asalkan tebal dinding tersebut kurang dari 5 kaki. Anda juga bisa membentuk pintu batu atau kusennya untuk menutup pintu. Objek yang Anda buat dapat memiliki hingga dua engsel dan satu kait, tetapi detail mekanis yang lebih halus tidak mungkin dilakukan." },
      { name: "Stoneskin", components: "V, S, M", desc: "Mantra ini mengubah daging makhluk yang Anda sentuh menjadi sekeras batu. Hingga mantranya berakhir, target memiliki ketahanan terhadap pukulan non-magis, tusukan, dan tebasan." },
      { name: "Wall of Fire", components: "V, S, M", desc: "Anda membuat dinding api pada permukaan padat dalam jangkauan. Anda dapat membuat tembok dengan panjang hingga 60 kaki, tinggi 20 kaki, dan tebal 1 kaki, atau dinding melingkar dengan diameter hingga 20 kaki, tinggi 20 kaki, dan tebal 1 kaki. Dindingnya buram dan tahan lama.\nSaat tembok muncul, setiap makhluk di dalam areanya harus melakukan lemparan penyelamatan Dexterity. Jika penyelamatan gagal, makhluk akan menerima kerusakan api sebesar 5d8, atau setengah kerusakan jika penyelamatan berhasil.\nSatu sisi dinding, yang Anda pilih saat mengucapkan mantra ini, menimbulkan kerusakan api 5d8 pada setiap makhluk yang mengakhiri gilirannya dalam jarak 10 kaki dari sisi itu atau di dalam dinding. Makhluk menerima kerusakan yang sama saat memasuki dinding untuk pertama kalinya pada suatu belokan atau mengakhiri belokannya di sana. Sisi lain tembok tidak menimbulkan kerusakan.\nSisi lain tembok tidak menimbulkan kerusakan.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 5 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 4." },
    ],
    Level5: [
      { name: "Animate Objects", components: "V, S", desc: "Objek menjadi hidup sesuai perintah Anda. Pilih hingga sepuluh benda non-magis dalam jangkauan yang tidak dipakai atau dibawa. Target sedang dihitung sebagai dua objek, Target besar dihitung sebagai empat objek, Target besar dihitung sebagai delapan objek. Anda tidak dapat menganimasikan objek apa pun yang lebih besar dari Huge. Setiap target bernyawa dan menjadi makhluk di bawah kendali Anda hingga mantra berakhir atau hingga poin hit berkurang menjadi 0.\nSebagai tindakan bonus, Anda dapat secara mental memerintahkan makhluk apa pun yang Anda buat dengan mantra ini jika makhluk itu berada dalam jarak 500 kaki dari Anda (jika Anda mengendalikan beberapa makhluk, Anda dapat memerintahkan salah satu atau semuanya secara bersamaan, memberikan perintah yang sama kepada masing-masing makhluk). Anda memutuskan tindakan apa yang akan diambil makhluk itu dan ke mana ia akan bergerak pada giliran berikutnya, atau Anda dapat mengeluarkan perintah umum, seperti menjaga ruangan atau koridor tertentu. Jika Anda tidak mengeluarkan perintah, makhluk itu hanya akan mempertahankan diri dari makhluk musuh. Setelah diberi perintah, makhluk tersebut terus mengikutinya hingga tugasnya selesai.\n##### Statistik Objek Animasi\n| Ukuran | HP | AC | Serangan | Str | Dex |\n|---|---|---|---|---|---|\n| Kecil | 20 | 18 | +8 untuk menyerang, 1d4 + 4 kerusakan | 4 | 18 |\n| Kecil | 25 | 16 | +6 untuk menyerang, 1d8 + 2 kerusakan | 6 | 14 |\n| Sedang | 40 | 13 | +5 untuk menyerang, 2d6 + 1 kerusakan | 10 | 12 |\n| Besar | 50 | 10 | +6 untuk menyerang, 2d10 + 2 kerusakan | 14 | 10 |\n| Besar | 80 | 10 | +8 untuk menyerang, 2d12 + 4 kerusakan | 18 | 6 |\nObjek animasi adalah konstruksi dengan AC, titik pukulan, serangan, Kekuatan, dan Ketangkasan yang ditentukan oleh ukurannya. Konstitusinya 10 dan Kecerdasan dan Kebijaksanaannya 3, dan Karismanya 1. Kecepatannya 30 kaki; jika benda tersebut tidak memiliki kaki atau pelengkap lain yang dapat digunakan untuk bergerak, ia malah memiliki kecepatan terbang 30 kaki dan dapat melayang. Jika benda tersebut terpasang erat pada suatu permukaan atau benda yang lebih besar, seperti rantai yang dibaut ke dinding, kecepatannya adalah 0. Benda tersebut mempunyai penglihatan buta dengan radius 30 kaki dan buta melebihi jarak tersebut. Ketika objek yang dianimasikan turun ke 0 titik hit, ia kembali ke bentuk objek aslinya, dan sisa kerusakan akan dibawa ke bentuk objek aslinya.\nJika Anda memerintahkan suatu objek untuk menyerang, ia dapat melakukan satu serangan jarak dekat terhadap makhluk dalam jarak 5 kaki darinya. Itu membuat serangan bantingan dengan bonus serangan dan kerusakan pukulan yang ditentukan oleh ukurannya. GM mungkin memutuskan bahwa objek tertentu menimbulkan kerusakan tebasan atau tusukan berdasarkan bentuknya.\nJika Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, Anda dapat menganimasikan dua objek tambahan untuk setiap slot level di atas 5." },
      { name: "Arcane Hand", components: "V, S, M", desc: "Anda menciptakan tangan besar dengan kekuatan yang berkilauan dan tembus cahaya di ruang kosong yang dapat Anda lihat dalam jangkauan. Tangannya bertahan selama durasi mantra, dan bergerak sesuai perintah Anda, meniru gerakan tangan Anda sendiri.\nTangan merupakan benda yang mempunyai AC 20 dan hit point sama dengan hit point maksimum Anda. Jika poin hitnya turun menjadi 0, mantranya berakhir. Ia memiliki Kekuatan 26 (+8) dan Keluwesan 10 (+0). Tangan tidak mengisi ruangnya.\nSaat Anda mengucapkan mantra dan sebagai tindakan bonus pada putaran berikutnya, Anda dapat menggerakkan tangan hingga 60 kaki dan kemudian menyebabkan salah satu efek berikut dengannya.\n***Tinju Terkepal.*** Tangan memukul satu makhluk atau benda dalam jarak 5 kaki darinya. Buat serangan mantra jarak dekat untuk tangan menggunakan statistik permainan Anda. Saat terkena, target menerima kerusakan kekuatan 4d8.\n***Tangan Kuat.*** Tangan mencoba mendorong makhluk dalam jarak 5 kaki ke arah yang Anda pilih. Lakukan pengecekan dengan Kekuatan tangan yang diperebutkan dengan pengecekan Kekuatan (Atletik) target. Jika targetnya Sedang atau lebih kecil, Anda mendapat keuntungan. Jika berhasil, tangan akan mendorong target hingga 5 kaki ditambah jumlah kaki yang setara dengan lima kali pengubah kemampuan perapalan mantra Anda. Tangan bergerak dengan target agar tetap berada dalam jarak 5 kaki darinya.\n***Menggenggam Tangan.*** Tangan tersebut mencoba untuk menggenggam makhluk besar atau kecil dalam jarak 5 kaki darinya. Anda menggunakan skor Kekuatan tangan untuk menyelesaikan grapple. Jika targetnya Sedang atau lebih kecil, Anda mendapat keuntungan. Saat tangan sedang menggenggam target, Anda dapat menggunakan aksi bonus untuk menghancurkannya. Saat Anda melakukannya, target menerima kerusakan sebesar 2d6 + pengubah kemampuan perapalan mantra Anda.\n***Tangan Interposisi.*** Tangan menempatkan dirinya di antara Anda dan makhluk yang Anda pilih hingga Anda memberikan perintah yang berbeda pada tangan tersebut. Tangan bergerak untuk tetap berada di antara Anda dan target, memberi Anda setengah perlindungan terhadap target. Target tidak dapat bergerak melewati ruang tangan jika skor Kekuatannya kurang dari atau sama dengan skor Kekuatan tangan. Jika skor Kekuatannya lebih tinggi dari skor Kekuatan tangan, target dapat bergerak ke arah Anda melalui ruang tangan, namun ruang tersebut merupakan medan yang sulit bagi target.\nSaat Anda mengucapkan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kerusakan dari opsi tangan terkepal meningkat sebesar 2d8 dan kerusakan dari tangan yang menggenggam meningkat sebesar 2d6 untuk setiap level slot di atas ke-5." },
      { name: "Cloudkill", components: "V, S", desc: "Anda membuat bola kabut kuning-hijau beracun dengan radius 20 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan. Kabut menyebar ke segala penjuru. Itu berlangsung selama atau sampai angin kencang membubarkan kabut, mengakhiri mantranya. Wilayahnya sangat tertutup.\nSaat makhluk memasuki area mantra untuk pertama kalinya pada suatu giliran atau memulai gilirannya di sana, makhluk tersebut harus melakukan lemparan penyelamatan konstitusi. Makhluk itu menerima kerusakan racun 5d8 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Makhluk akan terpengaruh meskipun mereka menahan napas atau tidak perlu bernapas.\nKabut bergerak sejauh 10 kaki dari Anda pada awal setiap belokan, bergulung di sepanjang permukaan tanah. Uapnya, karena lebih berat daripada udara, tenggelam ke permukaan tanah yang paling rendah, bahkan mengalir ke lubang-lubang.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 5." },
      { name: "Cone of Cold", components: "V, S, M", desc: "Semburan udara dingin keluar dari tangan Anda. Setiap makhluk dalam kerucut setinggi 60 kaki harus melakukan penyelamatan konstitusi. Makhluk menerima kerusakan dingin sebesar 8d8 pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nMakhluk yang terbunuh oleh mantra ini menjadi patung beku hingga mencair.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kerusakan meningkat sebesar 1d8 untuk setiap slot level di atas 5." },
      { name: "Conjure Elemental", components: "V, S, M", desc: "Anda memanggil pelayan unsur. Pilih area udara, tanah, api, atau air yang memenuhi kubus berukuran 10 kaki dalam jangkauannya. Elemen tantangan dengan peringkat 5 atau lebih rendah yang sesuai dengan area yang Anda pilih muncul di ruang kosong dalam jarak 10 kaki darinya. Misalnya, elemen api muncul dari api unggun, dan elemen tanah muncul dari tanah. Elemental menghilang ketika poin hitnya turun menjadi 0 atau ketika mantranya berakhir.\nElementalnya ramah terhadap Anda dan teman Anda selama ini. Gulung inisiatif untuk elemen yang memiliki giliran sendiri. Ia mematuhi perintah verbal apa pun yang Anda berikan padanya (Anda tidak perlu melakukan tindakan apa pun). Jika Anda tidak memberikan perintah apa pun kepada elemen tersebut, ia akan mempertahankan diri dari makhluk musuh, namun sebaliknya tidak akan melakukan tindakan apa pun.\nJika konsentrasimu terganggu, elemennya tidak hilang. Sebaliknya, Anda kehilangan kendali atas elemen tersebut, ia menjadi bermusuhan terhadap Anda dan teman Anda, dan mungkin menyerang. Elemental yang tidak terkontrol tidak dapat Anda hilangkan, dan menghilang 1 jam setelah Anda memanggilnya.\nGM memiliki statistik unsur.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, peringkat tantangan meningkat sebesar 1 untuk setiap slot level di atas 5." },
      { name: "Contact Other Plane", components: "V", desc: "Anda secara mental menghubungi seorang setengah dewa, roh orang bijak yang telah lama meninggal, atau entitas misterius lainnya dari alam lain. Menghubungi kecerdasan ekstraplanar ini dapat membuat Anda tegang atau bahkan patah semangat. Saat Anda mengucapkan mantra ini, lakukan lemparan penyelamatan intelijen DC 15. Jika gagal, Anda menerima kerusakan psikis 6d6 dan menjadi gila sampai Anda menyelesaikan istirahat panjang. Meskipun gila, Anda tidak dapat mengambil tindakan, tidak dapat memahami apa yang dikatakan makhluk lain, tidak dapat membaca, dan hanya berbicara omong kosong. Mantra pemulihan yang lebih besar yang diberikan kepada Anda akan mengakhiri efek ini.\nJika penyimpanan berhasil, Anda dapat mengajukan hingga lima pertanyaan kepada entitas. Anda harus mengajukan pertanyaan Anda sebelum mantranya berakhir. GM menjawab setiap pertanyaan dengan satu kata, seperti \"ya\", \"tidak\", \"mungkin\", \"tidak pernah\", \"tidak relevan\", atau \"tidak jelas\" (jika entitas tidak mengetahui jawaban atas pertanyaan tersebut). Jika jawaban satu kata akan menyesatkan, GM mungkin akan menawarkan kalimat pendek sebagai jawaban." },
      { name: "Creation", components: "V, S, M", desc: "Anda menarik gumpalan material bayangan dari Shadowfell untuk membuat objek benda nabati tak hidup dalam jangkauan: barang lunak, tali, kayu, atau yang serupa. Anda juga bisa menggunakan mantra ini untuk membuat benda mineral seperti batu, kristal, atau logam. Benda yang dibuat tidak boleh lebih besar dari kubus berukuran 5 kaki, dan benda tersebut harus dari bentuk dan bahan yang pernah Anda lihat sebelumnya.\nDurasinya tergantung bahan bendanya. Jika objek terdiri dari beberapa bahan, gunakan durasi yang paling singkat.\n| Bahan | Durasi |\n|---|---|\n| Materi sayur | 1 hari |\n| Batu atau kristal | 12 jam |\n| Logam mulia | 1 jam |\n| Permata | 10 menit |\n| Adamantine atau mitral | 1 menit |\nMenggunakan material apa pun yang dibuat oleh mantra ini sebagai komponen material mantra lain menyebabkan mantra tersebut gagal.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, kubus bertambah 5 kaki untuk setiap slot level di atas 5." },
      { name: "Dominate Person", components: "V, S", desc: "Anda mencoba memperdaya humanoid yang dapat Anda lihat dalam jangkauan. Ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Jika Anda atau makhluk yang bersahabat dengan Anda melawannya, ia memiliki keuntungan dalam penyelamatan.\nMeskipun targetnya terpesona, Anda memiliki hubungan telepati dengannya selama Anda berdua berada di alam eksistensi yang sama. Anda dapat menggunakan tautan telepati ini untuk mengeluarkan perintah kepada makhluk itu saat Anda sadar (tidak perlu tindakan apa pun), yang akan dipatuhinya sebaik mungkin. Anda dapat menentukan tindakan yang sederhana dan umum, seperti \"Serang makhluk itu\", \"Lari ke sana\", atau \"Ambil objek itu\". Jika makhluk tersebut menyelesaikan perintahnya dan tidak menerima arahan lebih lanjut dari Anda, ia akan mempertahankan dan mempertahankan dirinya dengan kemampuan terbaiknya.\nAnda dapat menggunakan tindakan Anda untuk mengambil kendali total dan tepat terhadap target. Hingga akhir giliran Anda berikutnya, makhluk itu hanya mengambil tindakan yang Anda pilih, dan tidak melakukan apa pun yang tidak Anda izinkan. Selama waktu ini Anda juga dapat menyebabkan makhluk tersebut menggunakan reaksi, namun hal ini mengharuskan Anda menggunakan reaksi Anda sendiri juga.\nSetiap kali target menerima kerusakan, ia membuat lemparan penyelamatan kebijaksanaan baru terhadap mantra tersebut. Jika lemparan penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 6, durasinya adalah konsentrasi, hingga 10 menit. Jika menggunakan slot spell level 7, durasinya adalah konsentrasi, maksimal 1 jam. Saat Anda menggunakan slot mantra level 8 atau lebih tinggi, durasinya adalah konsentrasi, hingga 8 jam." },
      { name: "Dream", components: "V, S, M", desc: "Mantra ini membentuk mimpi makhluk. Pilih makhluk yang Anda kenal sebagai target mantra ini. Targetnya harus berada pada alam eksistensi yang sama dengan Anda. Makhluk yang tidak tidur, seperti elf, tidak dapat dihubungi dengan mantra ini. Anda, atau makhluk yang ingin Anda sentuh, memasuki kondisi trance, bertindak sebagai pembawa pesan.\nSaat berada dalam kondisi trance, pembawa pesan sadar akan sekelilingnya, namun tidak dapat mengambil tindakan atau bergerak.\nJika target tertidur, pembawa pesan muncul dalam mimpi target dan dapat berkomunikasi dengan target selama target tetap tertidur, selama durasi mantra. Pembawa pesan juga dapat membentuk lingkungan mimpi, menciptakan pemandangan alam, objek, dan gambar lainnya. Pembawa pesan dapat keluar dari kondisi trance kapan saja, mengakhiri efek mantranya lebih awal. Target mengingat mimpinya dengan sempurna saat bangun tidur. Jika target terjaga saat Anda merapal mantra, pembawa pesan mengetahuinya, dan dapat mengakhiri trance (dan mantranya) atau menunggu target tertidur, dan pada saat itulah pembawa pesan muncul dalam mimpi target.\nAnda dapat membuat pengirim pesan tampak mengerikan dan menakutkan bagi targetnya. Jika Anda melakukannya, pembawa pesan dapat menyampaikan pesan yang tidak lebih dari sepuluh kata dan kemudian target harus melakukan penyelamatan yang bijaksana. Jika penyelamatan gagal, gema monstrositas fantastik menimbulkan mimpi buruk yang berlangsung selama durasi tidur target dan mencegah target mendapatkan manfaat apa pun dari istirahat tersebut. Selain itu, ketika target terbangun, ia akan menerima 3d6 psychic damage.\nJika Anda memiliki bagian tubuh, seikat rambut, potongan kuku, atau bagian serupa dari tubuh target, target melakukan penyelamatan dengan merugikan." },
      { name: "Geas", components: "V", desc: "Anda memberikan perintah magis pada makhluk yang dapat Anda lihat dalam jangkauan, memaksanya untuk melakukan suatu layanan atau menahan diri dari tindakan atau aktivitas tertentu sesuai keputusan Anda. Jika makhluk itu dapat memahami Anda, ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Meskipun makhluk itu terpesona oleh Anda, dibutuhkan 5d10 kerusakan psikis setiap kali ia bertindak berlawanan dengan instruksi Anda, tetapi tidak lebih dari sekali setiap hari. Makhluk yang tidak dapat memahami Anda tidak terpengaruh oleh mantra tersebut.\nAnda dapat mengeluarkan perintah apa pun yang Anda pilih, selain aktivitas yang akan mengakibatkan kematian. Jika Anda mengeluarkan perintah bunuh diri, mantranya akan berakhir.\nAnda dapat mengakhiri mantra lebih awal dengan menggunakan tindakan untuk mengabaikannya. Mantra penghilang kutukan, pemulihan lebih besar, atau harapan juga mengakhirinya.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau 8, durasinya adalah 1 tahun. Saat Anda merapal mantra ini menggunakan slot mantra level 9, mantra tersebut akan bertahan hingga diakhiri oleh salah satu mantra yang disebutkan di atas." },
      { name: "Hold Monster", components: "V, S, M", desc: "Pilih makhluk yang dapat Anda lihat dan jangkau. Target harus melakukan lemparan penyelamatan Kebijaksanaan atau menjadi lumpuh selama durasi mantra. Mantra ini tidak berpengaruh terhadap undead. Di akhir setiap putaran, target dapat melakukan penyelamatan baru atas Kebijaksanaan. Jika berhasil, mantranya berakhir untuk makhluk itu.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan lokasi level 6 atau lebih tinggi, Anda dapat menargetkan makhluk tambahan untuk setiap level lokasi di luar lokasi kelima. Makhluk-makhluk itu harus berada dalam jarak 30 kaki satu sama lain saat Anda menargetkan mereka." },
      { name: "Legend Lore", components: "V, S, M", desc: "Sebutkan atau jelaskan seseorang, tempat, atau benda. Mantra ini mengingatkan Anda ringkasan singkat tentang pengetahuan penting tentang benda yang Anda beri nama. Pengetahuan tersebut bisa berupa cerita terkini, cerita yang terlupakan, atau bahkan pengetahuan rahasia yang belum pernah diketahui secara luas. Jika benda yang Anda beri nama tidak memiliki arti penting dalam legenda, Anda tidak memperoleh informasi. Semakin banyak informasi yang Anda miliki tentang suatu hal, semakin tepat dan rinci informasi yang Anda terima.\nInformasi yang Anda pelajari akurat tetapi mungkin disajikan dalam bahasa kiasan. Contohnya, jika Anda memiliki kapak ajaib misterius di tangan, mantranya mungkin akan menghasilkan informasi berikut: \"Celakalah pelaku kejahatan yang tangannya menyentuh kapak, karena gagang kapak pun dapat mengiris tangan si jahat. Hanya Anak Batu sejati, kekasih dan kekasih Moradin, yang dapat membangkitkan kekuatan kapak yang sebenarnya, dan hanya dengan kata suci *Rudnogg* di bibir.\"" },
      { name: "Mislead", components: "S", desc: "Anda menjadi tidak terlihat pada saat yang sama ketika kembaran ilusi Anda muncul di tempat Anda berdiri. Penggandaan berlangsung selama durasi tersebut, tetapi tembus pandang berakhir jika Anda menyerang atau membaca mantra.\nAnda dapat menggunakan tindakan Anda untuk menggerakkan ilusi Anda dua kali lipat kecepatan Anda dan membuatnya memberi isyarat, berbicara, dan berperilaku dengan cara apa pun yang Anda pilih.\nAnda dapat melihat melalui matanya dan mendengar melalui telinganya seolah-olah Anda berada di tempatnya. Pada setiap giliran Anda sebagai tindakan bonus, Anda dapat beralih dari menggunakan indra Anda ke indra Anda sendiri, atau kembali lagi. Saat Anda menggunakan indranya, Anda menjadi buta dan tuli terhadap lingkungan sekitar Anda." },
      { name: "Modify Memory", components: "V, S", desc: "Anda mencoba membentuk kembali ingatan makhluk lain. Satu makhluk yang dapat Anda lihat harus melakukan lemparan penyelamat yang bijaksana. Jika Anda melawan makhluk itu, ia memiliki keuntungan dalam lemparan penyelamatan. Jika penyimpanan gagal, target akan terpesona oleh Anda selama durasi tersebut. Target yang terpesona tidak berdaya dan tidak menyadari lingkungan sekitarnya, meskipun ia masih dapat mendengar Anda. Jika terkena kerusakan atau menjadi sasaran mantra lain, mantra ini berakhir, dan tidak ada ingatan target yang diubah.\nSelama pesona ini bertahan, Anda dapat memengaruhi ingatan target tentang peristiwa yang dialaminya dalam 24 jam terakhir dan berlangsung tidak lebih dari 10 menit. Anda dapat secara permanen menghilangkan seluruh memori peristiwa tersebut, memungkinkan target mengingat peristiwa tersebut dengan kejelasan sempurna dan detail yang tepat, mengubah memorinya atas detail peristiwa tersebut, atau membuat memori mengenai beberapa peristiwa lainnya.\nAnda harus berbicara dengan target untuk menjelaskan bagaimana ingatannya terpengaruh, dan target harus dapat memahami bahasa Anda agar ingatan yang dimodifikasi dapat berakar. Pikirannya mengisi setiap celah dalam detail deskripsi Anda. Jika mantranya berakhir sebelum Anda selesai mendeskripsikan ingatan yang dimodifikasi, ingatan makhluk itu tidak berubah. Jika tidak, ingatan yang dimodifikasi akan tetap ada saat mantranya berakhir.\nMemori yang dimodifikasi tidak serta merta memengaruhi perilaku makhluk, terutama jika memori tersebut bertentangan dengan kecenderungan, keselarasan, atau kepercayaan alami makhluk tersebut. Memori modifikasi yang tidak logis, seperti menanamkan memori tentang betapa senangnya makhluk itu menyiram dirinya sendiri dengan asam, diabaikan, mungkin sebagai mimpi buruk. GM mungkin menganggap memori yang dimodifikasi terlalu tidak masuk akal untuk mempengaruhi makhluk secara signifikan.\nMantra penghilang kutukan atau mantra pemulihan yang lebih besar yang diberikan pada target akan memulihkan ingatan sebenarnya makhluk itu.\nLevel Tinggi: Jika Anda menggunakan mantra ini menggunakan slot mantra level 6 atau lebih tinggi, Anda dapat mengubah ingatan target tentang peristiwa yang terjadi hingga 7 hari yang lalu (level 6), 30 hari yang lalu (level 7), 1 tahun yang lalu (level 8), atau kapan pun di masa lalu makhluk itu (level 9)." },
      { name: "Passwall", components: "V, S, M", desc: "Sebuah lorong muncul di titik pilihan Anda yang dapat Anda lihat pada permukaan kayu, plester, atau batu (seperti dinding, langit-langit, atau lantai) dalam jangkauan, dan berlangsung selama durasi tersebut. Anda memilih dimensi bukaan: lebar hingga 5 kaki, tinggi 8 kaki, dan kedalaman 20 kaki. Jalur ini tidak menciptakan ketidakstabilan pada struktur di sekitarnya.\nSaat bukaannya menghilang, makhluk atau benda apa pun yang masih berada di jalur yang dibuat oleh mantra akan dikeluarkan dengan aman ke ruang kosong yang paling dekat dengan permukaan tempat Anda mengucapkan mantra." },
      { name: "Planar Binding", components: "V, S, M", desc: "Dengan mantra ini, Anda mencoba untuk mengikat benda langit, elemen, makhluk, atau iblis ke dalam layanan Anda. Makhluk itu harus berada dalam jangkauan selama seluruh perapalan mantra. (Biasanya, makhluk tersebut pertama kali dipanggil ke tengah lingkaran sihir terbalik agar tetap terjebak saat mantra ini digunakan.) Setelah menyelesaikan casting, target harus melakukan lemparan penyelamatan karisma. Jika penyimpanan gagal, itu pasti akan membantu Anda selama durasi tersebut. Jika makhluk itu dipanggil atau diciptakan oleh mantra lain, durasi mantra tersebut diperpanjang agar sesuai dengan durasi mantra ini.\nMakhluk yang terikat harus mengikuti instruksi Anda dengan kemampuan terbaiknya. Anda mungkin memerintahkan makhluk tersebut untuk menemani Anda berpetualang, menjaga lokasi, atau menyampaikan pesan. Makhluk itu mematuhi instruksi Anda, tetapi jika makhluk itu memusuhi Anda, ia berusaha memutarbalikkan kata-kata Anda untuk mencapai tujuannya sendiri. Jika makhluk tersebut melaksanakan instruksi Anda sepenuhnya sebelum mantranya berakhir, ia akan mendatangi Anda untuk melaporkan fakta ini jika Anda berada di alam keberadaan yang sama. Jika Anda berada di alam eksistensi lain, ia akan kembali ke tempat Anda mengikatnya dan tetap di sana hingga mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra dengan level yang lebih tinggi, durasinya meningkat menjadi 10 hari dengan slot level 6, menjadi 30 hari dengan slot level 7, menjadi 180 hari dengan slot level 8, dan menjadi satu tahun dan satu hari dengan slot mantra level 9." },
      { name: "Scrying", components: "V, S, M", desc: "Anda dapat melihat dan mendengar makhluk tertentu yang Anda pilih yang berada pada alam eksistensi yang sama dengan Anda. Target harus melakukan lemparan penyelamatan yang bijaksana, yang dimodifikasi oleh seberapa baik Anda mengenal target dan jenis hubungan fisik yang Anda miliki dengannya. Jika target mengetahui Anda merapalkan mantra ini, target dapat gagal melakukan penyelamatan secara sukarela jika ingin diamati.\n| Pengetahuan | Simpan Pengubah |\n|---|---|\n| Bekas (Anda pernah mendengar tentang targetnya) | +5 |\n| Langsung (Anda sudah memenuhi target) | +0 |\n| Familiar (Anda tahu targetnya dengan baik) | -5 |\n\n| Koneksi | Simpan Pengubah |\n|---|---|\n| Kemiripan atau gambar | -2 |\n| Kepemilikan atau pakaian | -4 |\n| Bagian badan, seikat rambut, secuil kuku, atau sejenisnya | -10 |\nJika penyelamatan berhasil, target tidak terpengaruh, dan Anda tidak dapat menggunakan mantra ini lagi selama 24 jam.\nJika penyelamatan gagal, mantra tersebut menciptakan sensor tak terlihat dalam jarak 10 kaki dari target. Anda dapat melihat dan mendengar melalui sensor seolah-olah Anda berada di sana. Sensor bergerak mengikuti target, tetap berada dalam jarak 10 kaki selama durasi tersebut. Makhluk yang dapat melihat objek tak kasat mata melihat sensornya sebagai bola bercahaya seukuran kepalan tangan Anda.\nDaripada mengincar makhluk, kamu bisa memilih lokasi yang pernah kamu lihat sebelumnya sebagai target mantra ini. Ketika Anda melakukannya, sensor muncul di lokasi tersebut dan tidak bergerak." },
      { name: "Seeming", components: "V, S", desc: "Mantra ini memungkinkan Anda mengubah penampilan sejumlah makhluk yang dapat Anda lihat dalam jangkauan. Anda memberikan setiap target yang Anda pilih penampilan baru dan ilusi. Target yang tidak bersedia dapat melakukan lemparan penyelamatan karisma, dan jika berhasil, ia tidak terpengaruh oleh mantra ini.\nMantra ini menyamarkan penampilan fisik serta pakaian, baju besi, senjata, dan perlengkapan. Anda dapat membuat setiap makhluk tampak 1 kaki lebih pendek atau lebih tinggi dan tampak kurus, gemuk, atau di antara keduanya. Anda tidak dapat mengubah tipe tubuh target, jadi Anda harus memilih bentuk yang memiliki susunan dasar anggota tubuh yang sama. Jika tidak, sejauh mana ilusi itu terserah Anda. Mantra tersebut bertahan selama durasi tersebut, kecuali Anda menggunakan tindakan Anda untuk menghilangkannya lebih cepat.\nPerubahan yang dilakukan oleh mantra ini gagal memenuhi pemeriksaan fisik. Misalnya, jika Anda menggunakan mantra ini untuk menambahkan topi ke pakaian makhluk, benda akan melewati topi tersebut, dan siapa pun yang menyentuhnya tidak akan merasakan apa pun atau akan merasakan kepala dan rambut makhluk tersebut. Jika Anda menggunakan mantra ini untuk terlihat lebih kurus dari Anda, tangan seseorang yang mengulurkan tangan untuk menyentuh Anda akan menabrak Anda saat tangan itu tampak masih di udara.\nMakhluk dapat menggunakan aksinya untuk memeriksa target dan melakukan pemeriksaan Intelijen (Investigasi) terhadap mantra penyelamatan DC Anda. Jika berhasil, ia akan menyadari bahwa targetnya sedang menyamar." },
      { name: "Telekinesis", components: "V, S", desc: "Anda memperoleh kemampuan untuk menggerakkan atau memanipulasi makhluk atau benda dengan pikiran. Saat Anda mengucapkan mantra, dan sebagai tindakan Anda di setiap putaran selama durasi tersebut, Anda dapat mengerahkan keinginan Anda pada satu makhluk atau objek yang dapat Anda lihat dalam jangkauan, menyebabkan efek yang sesuai di bawah. Anda dapat memengaruhi target yang sama setiap putaran, atau memilih target baru kapan saja. Jika Anda mengganti target, target sebelumnya tidak lagi terpengaruh oleh mantra tersebut.\n***Makhluk.*** Anda dapat mencoba memindahkan makhluk besar atau kecil. Lakukan pemeriksaan kemampuan dengan kemampuan merapal mantra Anda yang diperebutkan oleh pemeriksaan Kekuatan makhluk itu. Jika Anda memenangkan kontes, Anda memindahkan makhluk itu hingga 30 kaki ke segala arah, termasuk ke atas tetapi tidak melampaui jangkauan mantra ini. Hingga akhir giliran Anda berikutnya, makhluk itu tertahan dalam cengkeraman telekinetik Anda. Makhluk yang terangkat ke atas melayang di udara.\nPada ronde berikutnya, Anda dapat menggunakan tindakan Anda untuk mencoba mempertahankan cengkeraman telekinetik Anda pada makhluk tersebut dengan mengulangi kontes tersebut.\n***Objek.*** Anda dapat mencoba memindahkan objek yang beratnya mencapai 1.000 pon. Jika benda tersebut tidak sedang dipakai atau dibawa, Anda secara otomatis memindahkannya hingga 30 kaki ke segala arah, tetapi tidak melampaui jangkauan mantra ini.\nJika benda tersebut dipakai atau dibawa oleh makhluk, Anda harus melakukan pemeriksaan kemampuan dengan kemampuan perapalan mantra Anda yang diperebutkan oleh pemeriksaan Kekuatan makhluk tersebut. Jika berhasil, Anda menarik objek menjauh dari makhluk itu dan dapat memindahkannya hingga 30 kaki ke segala arah tetapi tidak melampaui jangkauan mantra ini.\nAnda dapat melakukan kontrol yang baik pada objek dengan cengkeraman telekinetik Anda, seperti memanipulasi alat sederhana, membuka pintu atau wadah, menyimpan atau mengambil item dari wadah terbuka, atau menuangkan isi dari botol." },
      { name: "Telepathic Bond", components: "V, S, M", desc: "Anda menjalin hubungan telepati di antara hingga delapan makhluk pilihan Anda dalam jangkauan, secara fisik menghubungkan setiap makhluk dengan makhluk lainnya selama durasi tersebut. Makhluk dengan skor Intelijen 2 atau kurang tidak terpengaruh oleh mantra ini.\nHingga mantranya berakhir, target dapat berkomunikasi secara telepati melalui ikatan tersebut baik mereka memiliki bahasa yang sama atau tidak. Komunikasi dapat dilakukan dalam jarak berapa pun, meskipun tidak dapat meluas ke alam eksistensi lain." },
      { name: "Teleportation Circle", components: "V, M", desc: "Saat Anda mengucapkan mantra, Anda menggambar lingkaran berdiameter 10 kaki di tanah bertuliskan sigil yang menghubungkan lokasi Anda ke lingkaran teleportasi permanen pilihan Anda yang urutan sigilnya Anda ketahui dan berada pada bidang keberadaan yang sama dengan Anda. Portal berkilauan terbuka di dalam lingkaran yang Anda gambar dan tetap terbuka hingga akhir giliran Anda berikutnya. Makhluk apa pun yang memasuki portal langsung muncul dalam jarak 5 kaki dari lingkaran tujuan atau di ruang kosong terdekat jika ruang tersebut terisi.\nBanyak kuil besar, guild, dan tempat penting lainnya memiliki lingkaran teleportasi permanen yang tertulis di suatu tempat dalam batasnya. Setiap lingkaran tersebut mencakup rangkaian sigil unik--rangkaian rune magis yang disusun dalam pola tertentu. Saat pertama kali mendapatkan kemampuan untuk merapal mantra ini, Anda mempelajari rangkaian sigil untuk dua tujuan di Bidang Material, yang ditentukan oleh GM. Anda dapat mempelajari urutan sigil tambahan selama petualangan Anda. Anda dapat memasukkan urutan sigil baru ke memori setelah mempelajarinya selama 1 menit.\nAnda dapat membuat lingkaran teleportasi permanen dengan menggunakan mantra ini di lokasi yang sama setiap hari selama satu tahun. Anda tidak perlu menggunakan lingkaran untuk berteleportasi saat Anda mengucapkan mantra dengan cara ini." },
      { name: "Wall of Force", components: "V, S, M", desc: "Dinding kekuatan tak kasat mata muncul pada titik yang Anda pilih dalam jangkauannya. Dinding muncul dalam orientasi apa pun yang Anda pilih, sebagai penghalang horizontal atau vertikal atau pada suatu sudut. Itu bisa mengambang bebas atau bertumpu pada permukaan padat. Anda dapat membentuknya menjadi kubah setengah bola atau bola dengan radius hingga 10 kaki, atau Anda dapat membentuk permukaan datar yang terdiri dari sepuluh panel berukuran 10 kaki kali 10 kaki. Setiap panel harus berdekatan dengan panel lainnya. Dalam bentuk apapun, tebal dindingnya 1/4 inci. Itu berlangsung selama durasi tersebut. Jika dinding menembus ruang makhluk saat muncul, makhluk tersebut didorong ke salah satu sisi dinding (pilihan Anda di sisi mana).\nTidak ada yang secara fisik dapat menembus dinding. Ia kebal terhadap semua kerusakan dan tidak bisa dihilangkan dengan sihir dispel. Namun, mantra penghancur menghancurkan dinding secara instan. Dinding tersebut juga memanjang hingga ke Bidang Ethereal, menghalangi perjalanan halus melalui dinding." },
      { name: "Wall of Stone", components: "V, S, M", desc: "Dinding batu padat non-magis muncul pada titik yang Anda pilih dalam jangkauan. Dindingnya setebal 6 inci dan terdiri dari sepuluh panel berukuran 10 kaki kali 10 kaki. Setiap panel harus berdekatan dengan setidaknya satu panel lainnya. Sebagai alternatif, Anda dapat membuat panel berukuran 10 kaki kali 20 kaki yang tebalnya hanya 3 inci.\nJika dinding menembus ruang makhluk saat muncul, makhluk tersebut akan terdorong ke salah satu sisi dinding (pilihan Anda). Jika makhluk dikelilingi di semua sisi oleh dinding (atau dinding dan permukaan padat lainnya), makhluk itu dapat melakukan lemparan penyelamatan ketangkasan. Jika berhasil, ia dapat menggunakan reaksinya untuk menaikkan kecepatannya sehingga tidak lagi tertutup oleh tembok.\nDinding bisa memiliki bentuk apa pun yang Anda inginkan, meski tidak bisa menempati ruang yang sama dengan makhluk atau benda. Dinding tidak harus vertikal atau bertumpu pada fondasi yang kokoh. Namun, ia harus menyatu dan didukung secara kokoh oleh batu yang sudah ada. Jadi, kamu bisa menggunakan mantra ini untuk menjembatani jurang atau membuat tanjakan.\nJika Anda membuat bentang yang panjangnya lebih dari 20 kaki, Anda harus membagi dua ukuran setiap panel untuk membuat penyangga. Anda dapat membentuk dinding secara kasar untuk membuat crenellations, benteng, dan sebagainya.\nDinding merupakan suatu benda yang terbuat dari batu yang dapat dirusak dan ditembus. Setiap panel memiliki ketebalan AC 15 dan 30 titik hit per inci. Mengurangi panel menjadi 0 titik hit akan menghancurkannya dan mungkin menyebabkan panel yang terhubung runtuh sesuai kebijakan GM.\nJika Anda mempertahankan konsentrasi pada mantra ini selama durasinya, tembok menjadi permanen dan tidak dapat dihilangkan. Jika tidak, tembok itu akan hilang saat mantranya berakhir." },
    ],
    Level6: [
      { name: "Chain Lightning", components: "V, S, M", desc: "Anda membuat sambaran petir yang mengarah ke target pilihan Anda yang dapat Anda lihat dalam jangkauan. Tiga baut kemudian melompat dari sasaran tersebut ke sebanyak tiga sasaran lainnya, yang masing-masing harus berada dalam jarak 30 kaki dari sasaran pertama. Sasaran dapat berupa makhluk atau benda dan hanya dapat dibidik dengan salah satu baut.\nTarget harus melakukan lemparan penyelamatan ketangkasan. Target menerima 10d8 kerusakan petir pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 7 atau lebih tinggi, satu baut tambahan melompat dari target pertama ke target lain untuk setiap slot level di atas 6." },
      { name: "Circle of Death", components: "V, S, M", desc: "Sebuah bola energi negatif muncul dalam radius 60 kaki dari suatu titik dalam jangkauan. Setiap makhluk di area itu harus melakukan penyelamatan konstitusi. Target menerima 8d6 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, kerusakan meningkat sebesar 2d6 untuk setiap slot level di atas 6." },
      { name: "Contingency", components: "V, S, M", desc: "Pilih mantra level 5 atau lebih rendah yang dapat Anda gunakan, yang memiliki waktu casting 1 tindakan, dan dapat menargetkan Anda. Anda merapal mantra itu--disebut mantra kontingen--sebagai bagian dari kontingensi casting, mengeluarkan slot mantra untuk keduanya, namun mantra kontingen tidak mulai berlaku. Sebaliknya, hal ini berlaku ketika keadaan tertentu terjadi. Anda menggambarkan keadaan itu ketika Anda mengucapkan kedua mantra tersebut. Misalnya, tindakan darurat dengan pernapasan air mungkin menetapkan bahwa pernapasan air mulai berlaku saat Anda ditelan air atau cairan serupa.\nMantra kontingen berlaku segera setelah keadaan terpenuhi untuk pertama kalinya, baik Anda menginginkannya atau tidak. dan kemudian kontingensi berakhir.\nMantra kontingen hanya berlaku pada Anda, meskipun biasanya dapat menargetkan orang lain. Anda hanya dapat menggunakan satu mantra darurat dalam satu waktu. Jika Anda mengucapkan mantra ini lagi, efek mantra darurat lainnya pada Anda akan berakhir. Selain itu, kemungkinan akan berakhir pada Anda jika komponen materialnya tidak ada pada diri Anda." },
      { name: "Create Undead", components: "V, S, M", desc: "Anda hanya bisa mengucapkan mantra ini di malam hari. Pilih hingga tiga mayat humanoid Sedang atau Kecil dalam jangkauan. Setiap mayat menjadi hantu di bawah kendali Anda. (GM memiliki statistik permainan untuk makhluk-makhluk ini.)\nSebagai tindakan bonus di setiap giliran Anda, Anda dapat secara mental memerintahkan makhluk apa pun yang Anda animasikan dengan mantra ini jika makhluk itu berada dalam jarak 120 kaki dari Anda (jika Anda mengendalikan beberapa makhluk, Anda dapat memerintahkan salah satu atau semuanya secara bersamaan, mengeluarkan perintah yang sama untuk masing-masing makhluk). Anda memutuskan tindakan apa yang akan diambil makhluk itu dan ke mana ia akan bergerak pada giliran berikutnya, atau Anda dapat mengeluarkan perintah umum, seperti menjaga ruangan atau koridor tertentu. Jika Anda tidak mengeluarkan perintah, makhluk itu hanya akan mempertahankan diri dari makhluk musuh. Setelah diberi perintah, makhluk tersebut terus mengikutinya hingga tugasnya selesai.\nMakhluk itu berada di bawah kendali Anda selama 24 jam, setelah itu ia berhenti mematuhi perintah apa pun yang Anda berikan. Untuk mempertahankan kendali atas makhluk tersebut selama 24 jam berikutnya, Anda harus mengucapkan mantra ini pada makhluk tersebut sebelum periode 24 jam saat ini berakhir. Penggunaan mantra ini menegaskan kembali kendali Anda atas hingga tiga makhluk yang telah Anda animasikan dengan mantra ini, daripada menganimasikan makhluk baru.\nLevel Tinggi: Saat Anda merapal mantra ini menggunakan slot mantra level 7, Anda dapat menghidupkan atau menegaskan kembali kendali atas empat hantu. Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat 8, Anda dapat menganimasikan atau menegaskan kembali kendali atas lima ghoul atau dua ghast atau wight. Saat Anda mengucapkan mantra ini menggunakan slot mantra tingkat 9, Anda dapat menganimasikan atau menegaskan kembali kendali atas enam hantu, tiga hantu atau bobot, atau dua mumi." },
      { name: "Disintegrate", components: "V, S, M", desc: "Sinar hijau tipis muncul dari jari telunjuk Anda ke target yang dapat Anda lihat dalam jangkauan. Sasarannya bisa berupa makhluk, benda, atau ciptaan kekuatan magis, seperti tembok yang diciptakan oleh tembok kekuatan.\nMakhluk yang menjadi sasaran mantra ini harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, target menerima 10d6 + 40 kerusakan paksa. Jika kerusakan ini mengurangi target menjadi 0 poin hit, target tersebut akan hancur.\nMakhluk yang hancur dan segala sesuatu yang dikenakan dan dibawanya, kecuali benda sihir, menjadi tumpukan debu halus berwarna abu-abu. Makhluk itu dapat dihidupkan kembali hanya melalui kebangkitan sejati atau mantra harapan.\nMantra ini secara otomatis menghancurkan objek non-magis yang besar atau lebih kecil atau ciptaan kekuatan magis. Jika targetnya adalah objek atau ciptaan kekuatan yang sangat besar atau lebih besar, mantra ini akan menghancurkan bagian berukuran 10 kaki kubik dari objek tersebut. Item sihir tidak terpengaruh oleh mantra ini.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, kerusakan meningkat sebesar 3d6 untuk setiap slot level di atas 6." },
      { name: "Eyebite", components: "V, S", desc: "Selama durasi mantranya, matamu menjadi kehampaan bertinta yang dipenuhi kekuatan menakutkan. Satu makhluk pilihan Anda dalam jarak 60 kaki dari Anda yang dapat Anda lihat harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau terpengaruh oleh salah satu efek pilihan Anda berikut selama durasi tersebut. Pada setiap giliranmu hingga mantra berakhir, kamu dapat menggunakan tindakanmu untuk menargetkan makhluk lain tetapi tidak dapat menargetkan makhluk lagi jika makhluk tersebut berhasil melakukan penyelamatan terhadap casting eyebite ini.\n***Tidur.*** Target jatuh pingsan. Ia akan bangun jika ia mengalami kerusakan atau jika makhluk lain menggunakan aksinya untuk membangunkan orang yang tidur.\n***Panik.*** Targetnya takut padamu. Di setiap belokannya, makhluk yang ketakutan harus mengambil tindakan Dash dan menjauh dari Anda melalui rute teraman dan terpendek yang tersedia, kecuali tidak ada tempat untuk bergerak. Jika target berpindah ke tempat setidaknya 60 kaki dari Anda di mana ia tidak dapat lagi melihat Anda, efek ini akan berakhir.\n***Muak.*** Target memiliki kelemahan pada serangan dan pemeriksaan kemampuan. Di akhir setiap putarannya, ia dapat melakukan lemparan penyelamatan kebijaksanaan lainnya. Jika berhasil, efeknya berakhir." },
      { name: "Flesh to Stone", components: "V, S, M", desc: "Anda mencoba mengubah satu makhluk yang dapat Anda lihat dalam jangkauan menjadi batu. Jika tubuh target terbuat dari daging, makhluk tersebut harus melakukan penyelamatan konstitusi. Pada penyelamatan yang gagal, ia tertahan karena dagingnya mulai mengeras. Jika penyelamatan berhasil, makhluk itu tidak terpengaruh.\nMakhluk yang terkekang oleh mantra ini harus melakukan penyelamatan konstitusi lagi di akhir setiap putarannya. Jika berhasil menyelamatkan mantra ini tiga kali, mantranya berakhir. Jika gagal menyelamatkannya tiga kali, ia akan berubah menjadi batu dan mengalami kondisi membatu selama durasi tersebut. Keberhasilan dan kegagalan tidak harus terjadi secara berurutan; lacak keduanya sampai target mengumpulkan tiga jenis.\nJika makhluk itu rusak secara fisik saat membatu, ia akan menderita kelainan serupa jika kembali ke keadaan semula.\nJika Anda mempertahankan konsentrasi pada mantra ini selama mungkin, makhluk itu akan berubah menjadi batu hingga efeknya hilang." },
      { name: "Freezing Sphere", components: "V, S, M", desc: "Bola energi dingin yang sangat dingin mengalir dari ujung jari Anda ke titik pilihan Anda dalam jangkauannya, lalu meledak dalam bola dengan radius 60 kaki. Setiap makhluk di dalam area tersebut harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk menerima 10d6 kerusakan dingin. Jika penyelamatan berhasil, kerusakannya akan berkurang setengahnya.\nJika bola bumi menabrak badan air atau cairan yang pada dasarnya adalah air (tidak termasuk makhluk hidup di air), bola bumi akan membekukan cairan tersebut hingga kedalaman 6 inci di atas area seluas 30 kaki persegi. Es ini bertahan selama 1 menit. Makhluk yang sedang berenang di permukaan air beku terjebak di dalam es. Makhluk yang terperangkap dapat menggunakan suatu tindakan untuk melakukan pemeriksaan Kekuatan terhadap mantra Anda, simpan DC untuk membebaskan diri.\nAnda dapat menahan diri untuk tidak menembakkan globe setelah menyelesaikan mantranya, jika Anda mau. Sebuah bola dunia kecil seukuran batu selempang, sejuk saat disentuh, muncul di tangan Anda. Kapan saja, Anda atau makhluk yang Anda beri bola bumi dapat melempar bola dunia (hingga jarak 40 kaki) atau melemparkannya dengan gendongan (hingga kisaran normal gendongan). Itu hancur saat terkena benturan, dengan efek yang sama seperti perapalan mantra normal. Anda juga dapat mengatur globe tanpa menghancurkannya. Setelah 1 menit, jika globe belum pecah, maka akan meledak.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, kerusakan meningkat sebesar 1d6 untuk setiap slot level di atas 6." },
      { name: "Globe of Invulnerability", components: "V, S, M", desc: "Penghalang yang tidak bergerak dan sedikit berkilauan muncul dalam radius 10 kaki di sekitar Anda dan tetap ada selama durasi tersebut.\nMantra apa pun dengan level 5 atau lebih rendah yang dilemparkan dari luar penghalang tidak dapat memengaruhi makhluk atau objek di dalamnya, meskipun mantra tersebut digunakan menggunakan slot mantra level yang lebih tinggi. Mantra semacam itu dapat menargetkan makhluk dan objek di dalam penghalang, tetapi mantra tersebut tidak berpengaruh pada mereka. Demikian pula, area di dalam penghalang tidak termasuk dalam area yang terkena dampak mantra tersebut.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, penghalang akan memblokir mantra satu level lebih tinggi untuk setiap slot level di atas 6." },
      { name: "Guards and Wards", components: "V, S, M", desc: "Anda membuat lingkungan yang melindungi luas lantai hingga 2.500 kaki persegi (luas 50 kaki persegi, atau seratus persegi 5 kaki atau dua puluh lima persegi 10 kaki). Area yang dikurung bisa setinggi 20 kaki, dan dibentuk sesuai keinginan. Anda dapat menangkal beberapa tingkat benteng dengan membagi area di antara mereka, selama Anda dapat berjalan ke setiap area yang berdekatan saat Anda merapal mantra.\nSaat Anda mengucapkan mantra ini, Anda dapat menentukan individu yang tidak terpengaruh oleh salah satu atau semua efek yang Anda pilih. Anda juga dapat menentukan kata sandi yang, jika diucapkan dengan lantang, membuat pembicara kebal terhadap efek ini.\nPenjaga dan lingkungan menciptakan efek berikut di dalam area yang dilindungi.\n***Koridor.*** Kabut memenuhi semua koridor yang dilindungi, membuatnya sangat tertutup. Selain itu, di setiap persimpangan atau percabangan yang menawarkan pilihan arah, terdapat kemungkinan 50 persen bahwa makhluk selain Anda akan percaya bahwa ia berjalan ke arah yang berlawanan dengan yang dipilihnya.\n***Pintu.*** Semua pintu di area yang dilindungi dikunci secara ajaib, seolah-olah disegel oleh mantra kunci misterius. Selain itu, Anda dapat menutupi hingga sepuluh pintu dengan ilusi (setara dengan fungsi objek ilusi dari mantra ilusi minor) untuk membuatnya tampak sebagai bagian dinding yang polos.\n***Tangga.*** Jaring mengisi semua tangga di area yang dilindungi dari atas ke bawah, sebagai mantra web. Untaian ini akan tumbuh kembali dalam 10 menit jika dibakar atau dirobek selama penjaga dan pelindung masih ada.\n***Efek Mantra Lainnya.*** Anda dapat menempatkan salah satu efek magis berikut pilihan Anda di dalam area pertahanan benteng.\n- Tempatkan lampu menari di empat koridor. Anda dapat menentukan program sederhana yang akan diulangi lampunya selama penjaga dan penjaga masih ada.\n- Tempatkan mulut ajaib di dua lokasi.\n- Tempatkan awan bau di dua lokasi. Uapnya muncul di tempat yang Anda tentukan; mereka kembali dalam waktu 10 menit jika disebarkan oleh angin selama penjaga dan penjaga masih ada.\n- Tempatkan hembusan angin yang konstan pada satu koridor atau ruangan.\n- Tempatkan saran di satu lokasi. Anda memilih area hingga 5 kaki persegi, dan makhluk apa pun yang masuk atau melewati area tersebut menerima saran secara mental.\nSeluruh area yang dilindungi memancarkan sihir. Pemeran sihir penghilang pada efek tertentu, jika berhasil, hanya menghilangkan efek itu.\nAnda dapat membuat struktur yang dijaga dan dilindungi secara permanen dengan merapalkan mantra ini di sana setiap hari selama satu tahun." },
      { name: "Instant Summons", components: "V, S, M", desc: "Anda menyentuh benda seberat 10 pon atau kurang yang dimensi terpanjangnya 6 kaki atau kurang. Mantra tersebut meninggalkan bekas yang tidak terlihat di permukaannya dan secara tidak terlihat menuliskan nama item pada safir yang Anda gunakan sebagai komponen material. Setiap kali Anda mengucapkan mantra ini, Anda harus menggunakan safir yang berbeda.\nKapan saja setelahnya, Anda dapat menggunakan tindakan Anda untuk mengucapkan nama item tersebut dan menghancurkan safirnya. Item tersebut langsung muncul di tangan Anda terlepas dari jarak fisik atau planar, dan mantranya berakhir.\nJika makhluk lain memegang atau membawa benda tersebut, menghancurkan safir tidak akan memindahkan benda tersebut kepada Anda, melainkan Anda akan mengetahui siapa makhluk yang memiliki benda tersebut dan kira-kira di mana makhluk tersebut berada pada saat itu.\nMenghilangkan sihir atau efek serupa yang berhasil diterapkan pada safir mengakhiri efek mantra ini." },
      { name: "Irresistible Dance", components: "V", desc: "Pilih satu makhluk yang dapat Anda lihat dalam jangkauan. Target memulai tarian komik di tempat: menyeret, menghentakkan kaki, dan melompat-lompat selama durasi tersebut. Makhluk yang tidak bisa dimantrai akan kebal terhadap mantra ini.\nMakhluk yang menari harus menggunakan seluruh gerakannya untuk menari tanpa meninggalkan ruangnya dan memiliki kelemahan pada ketangkasan, penyelamatan lemparan dan lemparan serangan. Meskipun target terpengaruh oleh mantra ini, makhluk lain memiliki keuntungan dalam serangan yang melawannya. Sebagai aksinya, makhluk yang menari melakukan lemparan penyelamatan kebijaksanaan untuk mendapatkan kembali kendali atas dirinya. Jika penyelamatan berhasil, mantranya berakhir." },
      { name: "Magic Jar", components: "V, S, M", desc: "Tubuh Anda jatuh ke dalam keadaan katatonik saat jiwa Anda meninggalkannya dan memasuki wadah yang Anda gunakan untuk komponen material mantra. Saat jiwa Anda menghuni wadah tersebut, Anda menyadari sekeliling Anda seolah-olah Anda berada di ruang wadah tersebut. Anda tidak dapat bergerak atau menggunakan reaksi. Satu-satunya tindakan yang dapat Anda ambil adalah memproyeksikan jiwa Anda hingga 100 kaki keluar dari wadah, baik kembali ke tubuh hidup Anda (dan mengakhiri mantranya) atau mencoba untuk memiliki tubuh humanoids.\nAnda dapat mencoba merasuki humanoid apa pun dalam jarak 100 kaki dari Anda yang dapat Anda lihat (makhluk yang dilindungi oleh perlindungan dari kejahatan dan kebaikan atau mantra lingkaran sihir tidak dapat dimiliki). Targetnya harus melakukan lemparan penyelamatan karisma. Jika gagal, jiwa Anda berpindah ke tubuh target, dan jiwa target terperangkap di dalam wadah. Jika berhasil, target menolak upaya Anda untuk memilikinya, dan Anda tidak dapat mencoba memilikinya lagi selama 24 jam.\nBegitu Anda memiliki tubuh makhluk, Anda mengendalikannya. Statistik permainan Anda digantikan oleh statistik makhluk itu, meskipun Anda tetap mempertahankan keselarasan dan skor Kecerdasan, Kebijaksanaan, dan Karisma Anda. Anda tetap mendapatkan manfaat dari fitur kelas Anda sendiri. Jika target memiliki level kelas apa pun, Anda tidak dapat menggunakan fitur kelas apa pun.\nSedangkan jiwa makhluk yang kerasukan dapat melihat dari wadahnya dengan menggunakan indranya sendiri, namun tidak dapat bergerak atau melakukan tindakan sama sekali.\nSaat merasuki tubuh, Anda dapat menggunakan tindakan Anda untuk kembali dari tubuh inang ke wadah jika jaraknya 100 kaki dari Anda, mengembalikan jiwa makhluk inang ke tubuhnya. Jika tubuh inang mati saat Anda berada di dalamnya, makhluk itu akan mati, dan Anda harus melakukan penyelamatan karisma terhadap DC perapal mantra Anda sendiri. Jika berhasil, Anda kembali ke wadah jika jaraknya 100 kaki dari Anda. Jika tidak, kamu mati.\nJika wadahnya hancur atau mantranya berakhir, jiwa Anda segera kembali ke tubuh Anda. Jika tubuh Anda berjarak lebih dari 100 kaki dari Anda atau jika tubuh Anda mati ketika Anda mencoba kembali ke sana, Anda akan mati. Jika jiwa makhluk lain berada di dalam wadah pada saat dimusnahkan, maka jiwa makhluk tersebut akan kembali ke tubuhnya jika tubuhnya masih hidup dan berada dalam jarak 100 kaki. Kalau tidak, makhluk itu akan mati.\nSaat mantranya berakhir, wadahnya hancur." },
      { name: "Mass Suggestion", components: "V, M", desc: "Anda menyarankan serangkaian aktivitas (terbatas pada satu atau dua kalimat) dan secara ajaib memengaruhi hingga dua belas makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan dan yang dapat mendengar serta memahami Anda. Makhluk yang tidak bisa dipesona akan kebal terhadap efek ini. Saran tersebut harus diungkapkan sedemikian rupa agar tindakan yang diambil terdengar masuk akal. Meminta makhluk itu untuk menusuk dirinya sendiri, melemparkan dirinya ke tombak, mengorbankan dirinya sendiri, atau melakukan tindakan berbahaya lainnya secara otomatis meniadakan efek mantranya.\nSetiap target harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, ia akan melakukan tindakan yang Anda jelaskan dengan kemampuan terbaiknya. Tindakan yang disarankan dapat berlanjut sepanjang durasi. Jika aktivitas yang disarankan dapat diselesaikan dalam waktu yang lebih singkat, mantra akan berakhir saat subjek menyelesaikan apa yang diminta.\nAnda juga dapat menentukan kondisi yang akan memicu aktivitas khusus selama durasi tersebut. Misalnya, Anda mungkin menyarankan agar sekelompok tentara memberikan seluruh uangnya kepada pengemis pertama yang mereka temui. Jika kondisi tidak terpenuhi sebelum mantra berakhir, aktivitas tidak dilakukan.\nJika Anda atau salah satu teman Anda merusak makhluk yang terkena mantra ini, mantra untuk makhluk itu akan berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7, durasinya adalah 10 hari. Saat Anda menggunakan slot mantra level 8, durasinya adalah 30 hari. Saat Anda menggunakan slot mantra level 9, durasinya adalah satu tahun dan satu hari." },
      { name: "Move Earth", components: "V, S, M", desc: "Pilih area medan yang tidak lebih besar dari 40 kaki pada sisi yang berada dalam jangkauan. Anda dapat membentuk kembali tanah, pasir, atau tanah liat di area tersebut dengan cara apa pun yang Anda pilih selama durasi tersebut. Anda dapat menaikkan atau menurunkan ketinggian area, membuat atau mengisi parit, mendirikan atau meratakan dinding, atau membentuk pilar. Besarnya perubahan tersebut tidak boleh melebihi setengah dimensi terbesar wilayah tersebut. Jadi, jika Anda mempengaruhi persegi berukuran 40 kaki, Anda dapat membuat pilar setinggi 20 kaki, menaikkan atau menurunkan ketinggian persegi hingga 20 kaki, menggali parit sedalam 20 kaki, dan seterusnya. Diperlukan waktu 10 menit agar perubahan ini selesai.\nDi akhir setiap 10 menit yang Anda habiskan untuk berkonsentrasi pada mantranya, Anda dapat memilih area medan baru untuk dipengaruhi.\nKarena transformasi medan terjadi secara perlahan, makhluk di area tersebut biasanya tidak dapat terjebak atau terluka oleh pergerakan tanah.\nMantra ini tidak dapat memanipulasi batu alam atau konstruksi batu. Batuan dan struktur bergeser untuk mengakomodasi medan baru. Jika cara Anda membentuk medan membuat struktur menjadi tidak stabil, maka struktur tersebut mungkin akan runtuh.\nDemikian pula mantra ini tidak mempengaruhi pertumbuhan tanaman secara langsung. Bumi yang dipindahkan membawa serta tanaman apa pun." },
      { name: "Programmed Illusion", components: "V, S, M", desc: "Anda menciptakan ilusi suatu objek, makhluk, atau fenomena lain yang terlihat dalam jangkauan yang aktif ketika kondisi tertentu terjadi. Ilusi itu tidak terlihat sampai saat itu. Ukurannya tidak boleh lebih besar dari kubus berukuran 30 kaki, dan saat Anda mengucapkan mantra, Andalah yang memutuskan bagaimana perilaku ilusi dan suara apa yang dihasilkannya. Pertunjukan bernaskah ini dapat bertahan hingga 5 menit.\nKetika kondisi yang Anda tentukan terjadi, ilusi muncul dan bekerja sesuai dengan cara yang Anda gambarkan. Setelah ilusi selesai tampil, ilusi tersebut menghilang dan tetap tidak aktif selama 10 menit. Setelah itu, ilusi dapat diaktifkan kembali.\nKondisi pemicunya bisa bersifat umum atau sedetail yang Anda inginkan, namun harus didasarkan pada kondisi visual atau suara yang terjadi dalam jarak 30 kaki dari area tersebut. Misalnya, Anda dapat menciptakan ilusi diri Anda sendiri untuk muncul dan memperingatkan orang lain yang mencoba membuka pintu yang terperangkap, atau Anda dapat mengatur ilusi agar terpicu hanya ketika makhluk mengucapkan kata atau frasa yang benar.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk dapat mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut, dan suara apa pun yang dihasilkannya akan terdengar hampa bagi makhluk tersebut." },
      { name: "Sunbeam", components: "V, S, M", desc: "Seberkas cahaya cemerlang memancar dari tangan Anda dalam garis selebar 5 kaki dan panjang 60 kaki. Setiap makhluk dalam barisan harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk akan menerima kerusakan radiasi sebesar 6d8 dan menjadi buta hingga giliran Anda berikutnya. Jika penyelamatan berhasil, dibutuhkan setengah kerusakan dan tidak dibutakan oleh mantra ini. Mayat hidup dan cairan merembes memiliki kelemahan dalam lemparan penyelamatan ini.\nAnda dapat membuat garis pancaran baru sebagai tindakan Anda di giliran mana pun hingga mantranya berakhir.\nSelama itu, secercah cahaya cemerlang bersinar di tangan Anda. Ini memancarkan cahaya terang dalam radius 30 kaki dan cahaya redup untuk tambahan 30 kaki. Cahaya ini adalah sinar matahari." },
      { name: "True Seeing", components: "V, S, M", desc: "Mantra ini memberi makhluk yang Anda sentuh kemampuan untuk melihat segala sesuatu sebagaimana adanya. Selama durasi tersebut, makhluk tersebut memiliki penglihatan yang sebenarnya, mengetahui pintu rahasia yang disembunyikan oleh sihir, dan dapat melihat ke dalam Alam Ethereal, semuanya hingga jarak 120 kaki." },
      { name: "Wall of Ice", components: "V, S, M", desc: "Anda membuat dinding es di permukaan padat dalam jangkauan. Anda dapat membentuknya menjadi kubah setengah bola atau bola dengan radius hingga 10 kaki, atau Anda dapat membentuk permukaan datar yang terdiri dari sepuluh panel berukuran 10 kaki persegi. Setiap panel harus berdekatan dengan panel lainnya. Dalam bentuk apa pun, tembok itu setebal 1 kaki dan tahan lama.\nJika dinding menembus ruang makhluk saat muncul, makhluk di dalam area tersebut akan terdorong ke salah satu sisi dinding dan harus melakukan lemparan penyelamatan ketangkasan. Pada penyelamatan yang gagal, makhluk tersebut menerima 10d6 kerusakan dingin, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nDinding merupakan suatu benda yang dapat dirusak dan ditembus. Ia memiliki titik serangan AC 12 dan 30 per bagian 10 kaki, dan rentan terhadap kerusakan akibat kebakaran. Mengurangi bagian tembok setinggi 10 kaki menjadi 0 titik serangan akan menghancurkannya dan meninggalkan selembar udara dingin di ruang yang ditempati tembok tersebut. Makhluk yang bergerak melalui lapisan udara dingin untuk pertama kalinya secara bergantian harus melakukan penyelamatan konstitusi. Makhluk itu menerima kerusakan dingin sebesar 5d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 7 atau lebih tinggi, kerusakan yang ditimbulkan dinding saat muncul meningkat sebesar 2d6, dan kerusakan karena melewati lapisan udara dingin meningkat sebesar 1d6, untuk setiap slot level di atas ke-6." },
    ],
    Level7: [
      { name: "Arcane Sword", components: "V, S, M", desc: "Anda membuat bidang kekuatan berbentuk pedang yang melayang dalam jangkauan. Itu berlangsung selama durasi tersebut.\nSaat pedang muncul, Anda melakukan serangan mantra jarak dekat terhadap target pilihan Anda dalam jarak 5 kaki dari pedang. Saat terkena, target menerima kerusakan kekuatan 3d10. Hingga mantranya berakhir, Anda dapat menggunakan aksi bonus di setiap giliran Anda untuk menggerakkan pedang hingga 20 kaki ke tempat yang dapat Anda lihat dan ulangi serangan ini terhadap target yang sama atau berbeda." },
      { name: "Delayed Blast Fireball", components: "V, S, M", desc: "Seberkas cahaya kuning berkedip dari jari telunjuk Anda, lalu mengembun dan bertahan di titik yang dipilih dalam jangkauan sebagai manik bercahaya selama durasi tersebut. Saat mantranya berakhir, entah karena konsentrasimu terganggu atau karena kamu memutuskan untuk mengakhirinya, manik itu mekar dengan raungan rendah menjadi ledakan api yang menyebar ke segala sudut. Setiap makhluk dalam bola berradius 20 kaki yang berpusat pada titik tersebut harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan akibat kebakaran yang sama dengan total akumulasi kerusakan pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nKerusakan dasar mantranya adalah 12d6. Jika di akhir giliranmu maniknya belum meledak, kerusakannya meningkat sebesar 1d6.\nJika manik bercahaya itu disentuh sebelum jedanya habis, makhluk yang menyentuhnya harus melakukan lemparan penyelamatan ketangkasan. Jika penyelamatan gagal, mantranya segera berakhir, menyebabkan manik itu meledak dalam nyala api. Jika penyelamatan berhasil, makhluk itu dapat melempar manik hingga sejauh 40 kaki. Saat mengenai makhluk atau benda padat, mantranya berakhir, dan maniknya meledak.\nApi merusak benda-benda di area tersebut dan menyulut benda-benda mudah terbakar yang tidak dipakai atau dibawa.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 8 atau lebih tinggi, kerusakan dasar meningkat sebesar 1d6 untuk setiap slot level di atas 7." },
      { name: "Etherealness", components: "V, S", desc: "Anda melangkah ke wilayah perbatasan Pesawat Ethereal, di area yang tumpang tindih dengan pesawat Anda saat ini. Anda tetap berada di Border Ethereal selama atau sampai Anda menggunakan tindakan Anda untuk menghilangkan mantranya. Selama waktu ini, Anda dapat bergerak ke segala arah. Jika Anda bergerak ke atas atau ke bawah, setiap gerakan membutuhkan satu kaki ekstra. Anda dapat melihat dan mendengar pesawat asal Anda, tetapi segala sesuatu di sana tampak abu-abu, dan Anda tidak dapat melihat apa pun yang jaraknya lebih dari 60 kaki.\nSelama berada di Alam Ethereal, Anda hanya dapat mempengaruhi dan dipengaruhi oleh makhluk lain di alam tersebut. Makhluk yang tidak berada di Alam Ethereal tidak dapat melihat Anda dan tidak dapat berinteraksi dengan Anda, kecuali jika kemampuan atau sihir khusus memberi mereka kemampuan untuk melakukannya.\nAnda mengabaikan semua objek dan efek yang tidak ada di Alam Ethereal, memungkinkan Anda bergerak melalui objek yang Anda lihat di bidang asal Anda.\nKetika mantranya berakhir, kamu segera kembali ke pesawat asalmu di tempat yang kamu tempati saat ini. Jika Anda menempati tempat yang sama dengan benda padat atau makhluk saat hal ini terjadi, Anda akan segera diarahkan ke ruang kosong terdekat yang dapat Anda tempati dan menerima kerusakan kekuatan yang setara dengan dua kali jumlah kaki yang Anda gerakkan.\nMantra ini tidak berpengaruh jika kamu mengucapkannya saat kamu berada di Alam Ethereal atau di alam yang tidak membatasinya, seperti salah satu Alam Luar.\nLevel Tinggi: Saat Anda menggunakan mantra ini menggunakan slot mantra level 8 atau lebih tinggi, Anda dapat menargetkan hingga tiga makhluk yang bersedia (termasuk Anda) untuk setiap slot level di atas 7. Makhluk tersebut harus berada dalam jarak 10 kaki dari Anda saat Anda mengucapkan mantra." },
      { name: "Finger of Death", components: "V, S", desc: "Anda mengirimkan energi negatif ke seluruh makhluk yang dapat Anda lihat dalam jangkauannya, menyebabkan rasa sakit yang membakar. Targetnya harus melakukan penyelamatan konstitusi. Dibutuhkan 7d8 + 30 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\nHumanoid yang terbunuh oleh mantra ini muncul di awal giliran Anda berikutnya sebagai zombie yang secara permanen berada di bawah komando Anda, mengikuti perintah lisan Anda dengan kemampuan terbaiknya." },
      { name: "Forcecage", components: "V, S, M", desc: "Penjara berbentuk kubus yang tidak bergerak, tidak terlihat, dan terdiri dari kekuatan magis muncul di sekitar area yang Anda pilih dalam jangkauannya. Penjara bisa berupa sangkar atau kotak padat, sesuai pilihan Anda.\nPenjara berbentuk sangkar bisa berukuran hingga 20 kaki di sisinya dan terbuat dari jeruji berdiameter 1/2 inci dengan jarak 1/2 inci.\nPenjara berbentuk kotak bisa memiliki tinggi hingga 10 kaki di sisinya, menciptakan penghalang kokoh yang mencegah benda apa pun melewatinya dan memblokir mantra apa pun yang dilemparkan ke dalam atau keluar dari area tersebut.\nSaat Anda mengucapkan mantra, makhluk apa pun yang sepenuhnya berada di dalam area kandang akan terperangkap. Makhluk yang hanya berada sebagian di dalam area, atau yang terlalu besar untuk dapat masuk ke dalam area, akan didorong menjauh dari pusat area hingga mereka benar-benar berada di luar area.\nMakhluk yang berada di dalam sangkar tidak bisa keluar darinya dengan cara non-magis. Jika makhluk tersebut mencoba menggunakan teleportasi atau perjalanan antarplanar untuk meninggalkan kandang, ia harus melakukan lemparan penyelamatan karisma terlebih dahulu. Jika berhasil, makhluk itu dapat menggunakan sihir itu untuk keluar dari kandang. Jika gagal, makhluk tersebut tidak dapat keluar dari kandang dan menyia-nyiakan penggunaan mantra atau efeknya. Sangkar itu juga meluas hingga ke Alam Ethereal, menghalangi perjalanan halus.\nMantra ini tidak bisa dihilangkan dengan sihir dispel." },
      { name: "Magnificent Mansion", components: "V, S, M", desc: "Anda membayangkan hunian ekstradimensi dalam jangkauan yang bertahan selama durasi tersebut. Anda memilih di mana salah satu pintu masuknya berada. Pintu masuknya berkilau samar dan lebarnya 5 kaki dan tinggi 10 kaki. Anda dan makhluk apa pun yang Anda tunjuk saat mengucapkan mantra dapat memasuki tempat tinggal ekstradimensi selama portalnya tetap terbuka. Anda dapat membuka atau menutup portal jika Anda berada dalam jarak 30 kaki darinya. Saat ditutup, portal tidak terlihat.\nDi luar portal terdapat serambi megah dengan banyak ruangan di luarnya. Suasananya bersih, segar, dan hangat.\nAnda dapat membuat denah lantai apa pun yang Anda suka, tetapi ruangannya tidak boleh melebihi 50 kubus, setiap kubus berukuran 10 kaki di setiap sisinya. Tempat ini dilengkapi perabotan dan dekorasi sesuai pilihan Anda. Ini berisi makanan yang cukup untuk menyajikan jamuan sembilan hidangan untuk hingga 100 orang. Staf yang terdiri dari 100 pelayan yang hampir transparan melayani semua yang masuk. Anda yang menentukan penampilan visual para pelayan ini dan pakaian mereka. Mereka sepenuhnya patuh pada perintah Anda. Setiap pelayan bisa melakukan tugas apa pun yang bisa dilakukan oleh pelayan manusia biasa, tapi mereka tidak bisa menyerang atau melakukan tindakan apa pun yang secara langsung akan membahayakan makhluk lain. Dengan demikian para pelayan dapat mengambil sesuatu, membersihkan, memperbaiki, melipat pakaian, menyalakan api, menyajikan makanan, menuangkan anggur, dan sebagainya. Para pelayan bisa pergi kemana saja di dalam mansion tapi tidak bisa meninggalkannya. Perabotan dan benda lain yang diciptakan oleh mantra ini akan menghilang menjadi asap jika dikeluarkan dari mansion. Saat mantranya berakhir, makhluk apa pun di dalam ruang ekstradimensi akan diusir ke ruang terbuka terdekat dengan pintu masuk." },
      { name: "Mirage Arcane", components: "V, S", desc: "Anda membuat medan di area seluas 1 mil persegi terlihat, terdengar, tercium, dan bahkan terasa seperti medan lainnya. Namun, bentuk umum medannya tetap sama. Lahan terbuka atau jalan dapat dibuat menyerupai rawa, bukit, jurang, atau medan lain yang sulit atau tidak dapat dilalui. Sebuah kolam dapat dibuat tampak seperti padang rumput, jurang seperti lereng yang landai, atau selokan yang dipenuhi bebatuan seperti jalan yang lebar dan mulus.\nDemikian pula, Anda dapat mengubah tampilan struktur, atau menambahkannya jika tidak ada. Mantra itu tidak menyamarkan, menyembunyikan, atau menambah makhluk.\nIlusi mencakup elemen pendengaran, visual, sentuhan, dan penciuman, sehingga dapat mengubah permukaan tanah yang bersih menjadi medan yang sulit (atau sebaliknya) atau menghambat pergerakan melalui area tersebut. Setiap bagian dari medan ilusi (seperti batu atau tongkat) yang dikeluarkan dari area mantra akan segera menghilang.\nMakhluk dengan penglihatan sejati dapat melihat melalui ilusi ke bentuk sebenarnya dari medan tersebut; namun, semua elemen ilusi lainnya tetap ada, jadi meskipun makhluk tersebut menyadari kehadiran ilusi tersebut, makhluk tersebut masih dapat berinteraksi secara fisik dengan ilusi tersebut." },
      { name: "Plane Shift", components: "V, S, M", desc: "Anda dan hingga delapan makhluk bersedia yang bergandengan tangan dalam lingkaran akan dipindahkan ke alam eksistensi lain. Anda dapat menentukan tujuan target secara umum, seperti Kota Kuningan di Alam Elemen Api atau istana Dispater di Sembilan Neraka tingkat kedua, dan Anda muncul di atau dekat tujuan tersebut. Jika Anda mencoba mencapai Kota Kuningan, misalnya, Anda mungkin tiba di Jalan Baja, sebelum Gerbang Abu, atau melihat kota dari seberang Lautan Api, sesuai kebijaksanaan GM.\nAlternatifnya, jika Anda mengetahui urutan sigil lingkaran teleportasi di alam eksistensi lain, mantra ini dapat membawa Anda ke lingkaran itu. Jika lingkaran teleportasi terlalu kecil untuk menampung semua makhluk yang Anda pindahkan, mereka akan muncul di ruang kosong terdekat di sebelah lingkaran.\nAnda dapat menggunakan mantra ini untuk mengusir makhluk yang tidak mau ke pesawat lain. Pilih makhluk dalam jangkauan Anda dan lakukan serangan mantra jarak dekat terhadapnya. Saat terkena, makhluk tersebut harus melakukan lemparan penyelamatan karisma. Jika makhluk tersebut gagal dalam penyelamatan ini, ia akan dipindahkan ke lokasi acak di alam keberadaan yang Anda tentukan. Makhluk yang dipindahkan harus menemukan jalannya sendiri kembali ke alam keberadaan Anda saat ini." },
      { name: "Prismatic Spray", components: "V, S", desc: "Delapan sinar cahaya warna-warni memancar dari tangan Anda. Setiap sinar memiliki warna berbeda dan memiliki kekuatan serta tujuan berbeda. Setiap makhluk dalam kerucut setinggi 60 kaki harus melakukan lemparan penyelamatan ketangkasan. Untuk setiap target, putar d8 untuk menentukan sinar warna mana yang mempengaruhinya.\n***1. Merah.*** Target menerima damage api sebesar 10d6 jika penyelamatan gagal, atau setengah damage jika berhasil disimpan.\n***2. Oranye.*** Target menerima 10d6 kerusakan asam pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\n***3. Kuning.*** Target menerima 10d6 kerusakan petir pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\n***4. Hijau.*** Target menerima 10d6 kerusakan racun pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\n***5. Biru.*** Target menerima 10d6 kerusakan dingin pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil.\n***6. Indigo.*** Pada penyelamatan yang gagal, target tertahan. Ia kemudian harus melakukan penyelamatan konstitusi di akhir setiap putarannya. Jika berhasil menyelamatkan tiga kali, mantranya berakhir. Jika gagal menyelamatkannya tiga kali, ia akan berubah menjadi batu secara permanen dan mengalami kondisi membatu. Keberhasilan dan kegagalan tidak harus terjadi secara berurutan; lacak keduanya sampai target mengumpulkan tiga jenis.\n***7. Violet.*** Pada penyelamatan yang gagal, target menjadi buta. Ia kemudian harus melakukan lemparan penyelamatan yang bijaksana di awal giliran Anda berikutnya. Penyelamatan yang berhasil mengakhiri kebutaan. Jika penyelamatan itu gagal, makhluk itu dipindahkan ke alam eksistensi lain yang dipilih GM dan tidak lagi dibutakan. (Biasanya, makhluk yang berada di pesawat yang bukan pesawat asalnya akan dibuang pulang, sedangkan makhluk lain biasanya dibuang ke pesawat Astral atau Ethereal.)\n***8. Istimewa.*** Target terkena dua sinar. Gulung dua kali lagi, gulung ulang 8 lainnya." },
      { name: "Project Image", components: "V, S, M", desc: "Anda membuat salinan ilusi diri Anda yang bertahan selama itu. Salinannya dapat muncul di lokasi mana pun dalam jangkauan yang pernah Anda lihat sebelumnya, terlepas dari hambatan yang ada. Ilusi tersebut tampak dan terdengar seperti Anda, namun tidak berwujud. Jika ilusi mengalami kerusakan, ilusi itu akan hilang dan mantranya berakhir.\nAnda dapat menggunakan tindakan Anda untuk menggerakkan ilusi ini hingga dua kali kecepatan Anda, dan membuatnya memberi isyarat, berbicara, dan berperilaku sesuai pilihan Anda. Itu meniru tingkah laku Anda dengan sempurna.\nAnda dapat melihat melalui matanya dan mendengar melalui telinganya seolah-olah Anda berada di ruangnya. Pada giliran Anda sebagai tindakan bonus, Anda dapat beralih dari menggunakan indra Anda ke menggunakan indra Anda sendiri, atau kembali lagi. Saat Anda menggunakan indranya, Anda menjadi buta dan tuli terhadap lingkungan sekitar Anda.\nInteraksi fisik dengan gambar mengungkapkan bahwa itu hanyalah ilusi, karena benda dapat melewatinya. Makhluk yang menggunakan tindakannya untuk memeriksa gambar dapat menentukan bahwa itu adalah ilusi dengan pemeriksaan Intelijen (Investigasi) yang berhasil terhadap mantra penyelamatan DC Anda. Jika makhluk dapat mengenali ilusi apa adanya, makhluk tersebut dapat melihat melalui gambar tersebut, dan suara apa pun yang dihasilkannya akan terdengar hampa bagi makhluk tersebut." },
      { name: "Reverse Gravity", components: "V, S, M", desc: "Mantra ini membalikkan gravitasi dalam silinder dengan radius 50 kaki dan tinggi 100 kaki yang berpusat pada suatu titik dalam jangkauan. Semua makhluk dan benda yang entah bagaimana tidak tertambat ke tanah di area tersebut akan jatuh ke atas dan mencapai puncak area saat Anda mengucapkan mantra ini. Makhluk dapat melakukan lemparan hemat ketangkasan untuk meraih benda tetap yang dapat dijangkaunya, sehingga terhindar dari terjatuh.\nJika ada benda padat (seperti langit-langit) yang ditemui pada musim gugur ini, benda dan makhluk yang jatuh akan menghantamnya seperti yang terjadi pada saat jatuh ke bawah pada umumnya. Jika suatu benda atau makhluk mencapai puncak area tersebut tanpa menabrak apa pun, benda atau makhluk tersebut akan tetap berada di sana, sedikit terombang-ambing, selama durasi tersebut.\nDi akhir durasi, objek dan makhluk yang terkena dampak akan terjatuh kembali." },
      { name: "Sequester", components: "V, S, M", desc: "Melalui mantra ini, makhluk atau objek yang diinginkan dapat disembunyikan, aman dari deteksi selama jangka waktu tertentu. Saat Anda mengucapkan mantra dan menyentuh target, target tersebut menjadi tidak terlihat dan tidak dapat ditargetkan oleh mantra ramalan atau dirasakan melalui sensor scrying yang dibuat oleh mantra ramalan.\nJika targetnya adalah makhluk, ia akan jatuh ke dalam keadaan mati suri. Waktu berhenti mengalir untuknya, dan ia tidak bertambah tua.\nAnda dapat mengatur kondisi agar mantra berakhir lebih awal. Kondisinya bisa apa saja yang Anda pilih, namun harus terjadi atau terlihat dalam jarak 1 mil dari target. Contohnya termasuk \"setelah 1.000 tahun\" atau \"ketika tarrasque terbangun\". Mantra ini juga berakhir jika target menerima kerusakan." },
      { name: "Simulacrum", components: "V, S, M", desc: "Anda membentuk duplikat ilusi dari satu binatang atau humanoid yang berada dalam jangkauan selama seluruh waktu penggunaan mantra. Duplikatnya adalah makhluk, sebagian nyata dan terbentuk dari es atau salju, dan ia dapat mengambil tindakan dan terpengaruh seperti makhluk normal. Tampaknya sama dengan aslinya, tetapi memiliki setengah titik maksimum serangan makhluk itu dan terbentuk tanpa peralatan apa pun. Jika tidak, ilusi tersebut akan menggunakan semua statistik makhluk yang diduplikasinya.\nSimulacrum ramah terhadap Anda dan makhluk yang Anda tunjuk. Ia mematuhi perintah lisan Anda, bergerak dan bertindak sesuai dengan keinginan Anda dan bertindak sesuai giliran Anda dalam pertempuran. Simulacrum tidak memiliki kemampuan untuk belajar atau menjadi lebih kuat, sehingga tidak pernah meningkatkan levelnya atau kemampuan lainnya, juga tidak dapat memperoleh kembali slot mantra yang telah dikeluarkan.\nJika simulacrum rusak, Anda dapat memperbaikinya di laboratorium alkimia, menggunakan ramuan dan mineral langka senilai 100 gp per titik hit yang diperoleh kembali. Simulacrum berlangsung hingga titik hitnya turun menjadi 0, lalu kembali menjadi salju dan langsung meleleh.\nJika Anda mengucapkan mantra ini lagi, semua duplikat aktif yang Anda buat dengan mantra ini akan langsung hancur." },
      { name: "Symbol", components: "V, S, M", desc: "Saat Anda mengucapkan mantra ini, Anda menuliskan mesin terbang yang berbahaya baik di permukaan (seperti bagian lantai, dinding, atau meja) atau di dalam objek yang dapat ditutup untuk menyembunyikan mesin terbang tersebut (seperti buku, gulungan, atau peti harta karun). Jika Anda memilih suatu permukaan, mesin terbang tersebut dapat menutupi area permukaan yang diameternya tidak lebih dari 10 kaki. Jika Anda memilih suatu benda, benda itu harus tetap berada di tempatnya; jika objek dipindahkan lebih dari 10 kaki dari tempat Anda mengucapkan mantra ini, mesin terbangnya rusak, dan mantranya berakhir tanpa terpicu.\nMesin terbang itu hampir tidak terlihat, memerlukan pemeriksaan Intelijen (Investigasi) terhadap mantra Anda, simpan DC untuk menemukannya.\nAnda memutuskan apa yang memicu mesin terbang saat Anda mengucapkan mantranya. Untuk mesin terbang yang tertulis di suatu permukaan, pemicu yang paling umum adalah menyentuh atau menginjak mesin terbang tersebut, memindahkan benda lain yang menutupinya, mendekat dalam jarak tertentu, atau memanipulasi benda yang menahannya. Untuk mesin terbang yang tertulis di dalam suatu objek, pemicu paling umum adalah membuka objek, mendekat dalam jarak tertentu, atau melihat atau membaca mesin terbang tersebut.\nAnda dapat menyempurnakan pemicunya lebih lanjut sehingga mantranya hanya diaktifkan dalam keadaan tertentu atau berdasarkan karakteristik fisik makhluk (seperti tinggi atau berat), atau jenis fisiknya (misalnya, lingkungan dapat diatur untuk memengaruhi perempuan tua atau pengubah bentuk). Anda juga dapat menentukan makhluk yang tidak memicu mesin terbang, seperti makhluk yang mengucapkan kata sandi tertentu.\nSaat Anda menuliskan mesin terbang, pilih salah satu opsi di bawah untuk efeknya. Setelah dipicu, mesin terbang tersebut bersinar, mengisi bola berradius 60 kaki dengan cahaya redup selama 10 menit, setelah itu mantranya berakhir. Setiap makhluk di dalam bola ketika mesin terbang aktif ditargetkan oleh efeknya, seperti halnya makhluk yang memasuki bola untuk pertama kalinya pada suatu belokan atau mengakhiri gilirannya di sana.\n***Kematian.*** Setiap target harus melakukan lemparan penyelamatan konstitusi, menerima 10d 10 kerusakan nekrotik pada penyelamatan yang gagal, atau setengah dari kerusakan pada penyelamatan yang berhasil.\n***Perselisihan.*** Setiap target harus melakukan penyelamatan konstitusi. Pada penyelamatan yang gagal, target bertengkar dan berdebat dengan makhluk lain selama 1 menit. Selama waktu ini, ia tidak mampu melakukan komunikasi yang berarti dan memiliki kelemahan dalam serangan dan pemeriksaan kemampuan.\n***Fear.*** Setiap target harus melakukan lemparan penyelamatan yang bijaksana dan menjadi ketakutan selama 1 menit jika penyelamatan gagal. Saat ketakutan, target menjatuhkan apa pun yang dipegangnya dan harus menjauh setidaknya 30 kaki dari mesin terbang di setiap belokannya, jika memungkinkan.\n***Keputusasaan.*** Setiap target harus melakukan lemparan penyelamatan karisma. Pada penyelamatan yang gagal, target diliputi keputusasaan selama 1 menit. Selama waktu ini, ia tidak dapat menyerang atau menargetkan makhluk apa pun dengan kemampuan, mantra, atau efek magis berbahaya lainnya.\n***Kegilaan.*** Setiap target harus melakukan penyelamatan intelijen. Jika penyelamatan gagal, target menjadi gila selama 1 menit. Makhluk gila tidak bisa mengambil tindakan, tidak bisa mengerti apa yang dikatakan makhluk lain, tidak bisa membaca, dan hanya berbicara omong kosong. GM mengontrol pergerakannya, yang tidak menentu.\n***Sakit.*** Setiap target harus melakukan lemparan penyelamatan konstitusi dan menjadi tidak berdaya dengan rasa sakit yang menyiksa selama 1 menit jika penyelamatan gagal.\n***Tidur.*** Setiap target harus melakukan lemparan penyelamatan kebijaksanaan dan jatuh pingsan selama 10 menit karena penyelamatan yang gagal. Makhluk akan terbangun jika ia menerima kerusakan atau jika seseorang menggunakan suatu tindakan untuk mengguncang atau menamparnya hingga terbangun.\n***Menakjubkan.*** Setiap target harus melakukan lemparan penyelamatan yang bijaksana dan terkena stun selama 1 menit jika penyelamatan gagal." },
      { name: "Teleport", components: "V", desc: "Mantra ini secara instan memindahkan Anda dan hingga delapan makhluk pilihan Anda yang dapat Anda lihat dalam jangkauan, atau satu objek yang dapat Anda lihat dalam jangkauan, ke tujuan yang Anda pilih. Jika Anda menargetkan suatu objek, objek tersebut harus dapat masuk seluruhnya ke dalam kubus berukuran 10 kaki, dan objek tersebut tidak dapat dipegang atau dibawa oleh makhluk yang tidak mau.\nTujuan yang Anda pilih harus Anda ketahui, dan harus berada pada alam eksistensi yang sama dengan Anda. Keakraban Anda dengan tujuan menentukan apakah Anda berhasil sampai di sana. GM menggulung d100 dan melihat tabel.\n| Keakraban | Kecelakaan | Daerah Serupa | Melenceng dari Sasaran | Sesuai Sasaran |\n|---|---|---|---|---|\n| Lingkaran permanen | -- | -- | -- | 01-100 |\n| Objek terkait | -- | -- | -- | 01-100 |\n| Sangat akrab | 01-05 | 06-13 | 14-24 | 25-100 |\n| Terlihat santai | 01-33 | 34-43 | 44-53 | 54-100 |\n| Dilihat sekali | 01-43 | 44-53 | 54-73 | 74-100 |\n| Deskripsi | 01-43 | 44-53 | 54-73 | 74-100 |\n| Tujuan salah | 01-50 | 51-100 | -- | -- |\n***Familiarity.*** \"Lingkaran permanen\" artinya lingkaran teleportasi permanen yang urutan sigilnya sudah kalian ketahui.\n\"Benda terkait\" berarti Anda memiliki benda yang diambil dari tujuan yang diinginkan dalam enam bulan terakhir, seperti buku dari perpustakaan penyihir, sprei dari kamar kerajaan, atau bongkahan marmer dari makam rahasia lich.\n\"Sangat familier\" adalah tempat yang sering Anda kunjungi, tempat yang telah Anda pelajari dengan cermat, atau tempat yang dapat Anda lihat saat Anda merapal mantra.\n\"Dilihat secara santai\" adalah suatu tempat yang pernah Anda lihat lebih dari sekali tetapi tidak terlalu Anda kenal.\n\"Dilihat sekali\" adalah tempat yang pernah Anda lihat, mungkin menggunakan sihir.\n\"Deskripsi\" adalah suatu tempat yang lokasi dan penampakannya Anda ketahui melalui deskripsi orang lain, mungkin dari peta.\n\"Tujuan palsu\" adalah tempat yang tidak ada. Mungkin Anda mencoba memindai tempat suci musuh tetapi malah melihat ilusi, atau Anda mencoba berteleportasi ke lokasi familiar yang sudah tidak ada lagi.\n***Tepat Target.*** Anda dan grup Anda (atau objek target) muncul di tempat yang Anda inginkan.\n***Diluar Target.*** Anda dan grup Anda (atau objek target) muncul pada jarak acak dari tujuan dalam arah acak. Jarak yang melenceng dari sasaran adalah 1d10 x 1d10 persen dari jarak yang hendak ditempuh. Misalnya, jika Anda mencoba menempuh jarak 120 mil, mendarat melenceng, dan mendapatkan angka 5 dan 3 pada dua D10, maka Anda akan melenceng 15 persen, atau 18 mil. GM menentukan arah keluar target secara acak dengan memutar d8 dan menetapkan 1 sebagai utara, 2 sebagai timur laut, 3 sebagai timur, dan seterusnya di sekitar titik kompas.  Jika Anda berteleportasi ke kota pesisir dan terdampar sejauh 18 mil di laut, Anda bisa mendapat masalah.\n***Area Serupa.*** Anda dan grup Anda (atau objek target) berakhir di area berbeda yang secara visual atau tematis mirip dengan area target. Jika Anda menuju laboratorium di rumah, misalnya, Anda mungkin akan berakhir di laboratorium penyihir lain atau di toko perlengkapan alkimia yang memiliki banyak peralatan dan perlengkapan yang sama dengan laboratorium Anda. Umumnya, Anda muncul di tempat terdekat yang serupa, tetapi karena mantranya tidak memiliki batasan jangkauan, Anda mungkin bisa berakhir di mana saja di pesawat.\n***Kecelakaan.*** Sihir tak terduga dari mantra ini mengakibatkan perjalanan yang sulit. Setiap makhluk yang berteleportasi (atau objek target) menerima kerusakan kekuatan 3d10, dan GM memutar ulang meja untuk melihat di mana Anda berakhir (beberapa kecelakaan dapat terjadi, menimbulkan kerusakan setiap kali)." },
    ],
    Level8: [
      { name: "Antimagic Field", components: "V, S, M", desc: "Bola antisihir tak kasat mata dengan radius 10 kaki mengelilingi Anda. Area ini terpisah dari energi magis yang menyelimuti multiverse. Di dalam bola, mantra tidak dapat digunakan, makhluk yang dipanggil menghilang, dan bahkan item sihir menjadi biasa saja. Sampai mantranya berakhir, bola itu bergerak bersama Anda, berpusat pada Anda.\nMantra dan efek magis lainnya, kecuali yang diciptakan oleh artefak atau dewa, ditekan di dalam bola dan tidak dapat menonjol ke dalamnya. Slot yang digunakan untuk merapalkan mantra yang ditekan akan dikonsumsi. Saat suatu efek ditekan, efek tersebut tidak berfungsi, namun waktu yang dihabiskan untuk menekannya dihitung berdasarkan durasinya.\n***Efek Bertarget.*** Mantra dan efek magis lainnya, seperti misil ajaib dan pesona orang, yang menargetkan makhluk atau objek di dalam bola tidak berpengaruh pada target tersebut.\n***Area Sihir.*** Area mantra atau efek magis lain, seperti bola api, tidak dapat diperluas hingga ke dalam bola. Jika bola itu tumpang tindih dengan area sihir, bagian dari area yang ditutupi oleh bola itu akan ditekan. Misalnya, nyala api yang dihasilkan oleh dinding api dipadamkan di dalam bola, sehingga menciptakan celah di dinding jika tumpang tindihnya cukup besar.\n***Mantra.*** Mantra aktif atau efek magis lainnya pada makhluk atau objek di dalam bola akan ditekan saat makhluk atau objek tersebut berada di dalamnya.\n***Item Ajaib.*** Properti dan kekuatan item sihir ditekan di dalam bola. Misalnya, pedang panjang +1 di dalam bola berfungsi sebagai pedang panjang non-magis.\nProperti dan kekuatan senjata sihir akan ditekan jika digunakan terhadap target di dalam bola atau digunakan oleh penyerang di dalam bola. Jika senjata ajaib atau amunisi ajaib sepenuhnya meninggalkan bola (misalnya, jika Anda menembakkan panah ajaib atau melemparkan tombak ajaib ke target di luar bola), keajaiban item tersebut tidak lagi ditekan segera setelah keluar.\n***Perjalanan Ajaib.*** Teleportasi dan perjalanan planar gagal bekerja di dalam bola, baik bola tersebut adalah tujuan atau titik keberangkatan untuk perjalanan ajaib tersebut. Portal ke lokasi, dunia, atau bidang eksistensi lain, serta bukaan ke ruang ekstradimensi seperti yang diciptakan oleh mantra trik tali, ditutup sementara saat berada di dalam bola.\n***Makhluk dan Benda.*** Makhluk atau benda yang dipanggil atau diciptakan oleh sihir untuk sementara menghilang dari keberadaannya di dalam bola. Makhluk seperti itu langsung muncul kembali setelah ruang yang ditempati makhluk tersebut tidak lagi berada di dalam bola.\n***Sihir Penghilang.*** Mantra dan efek magis seperti sihir penghilang tidak berpengaruh pada bola. Demikian pula, bola yang diciptakan oleh mantra medan antisihir yang berbeda tidak saling meniadakan." },
      { name: "Antipathy/Sympathy", components: "V, S, M", desc: "Mantra ini menarik atau mengusir makhluk pilihan Anda. Anda menargetkan sesuatu dalam jangkauan, baik objek atau makhluk yang besar atau lebih kecil, atau area yang tidak lebih besar dari kubus berukuran 200 kaki. Kemudian tentukan jenis makhluk cerdas, seperti naga merah, goblin, atau vampir. Anda menginvestasikan target dengan aura yang menarik atau mengusir makhluk tertentu selama durasi tersebut. Pilih antipati atau simpati sebagai efek aura.\n***Antipati.*** Pesona menyebabkan makhluk dari jenis yang Anda tunjuk merasakan dorongan kuat untuk meninggalkan area tersebut dan menghindari target. Ketika makhluk tersebut dapat melihat targetnya atau berada dalam jarak 60 kaki darinya, makhluk tersebut harus berhasil melakukan lemparan penyelamatan yang bijaksana atau menjadi ketakutan. Makhluk itu tetap ketakutan ketika ia dapat melihat targetnya atau berada dalam jarak 60 kaki darinya. Saat ditakuti oleh targetnya, makhluk tersebut harus menggunakan gerakannya untuk berpindah ke tempat aman terdekat dimana ia tidak dapat melihat targetnya. Jika makhluk tersebut bergerak lebih dari 60 kaki dari target dan tidak dapat melihatnya, makhluk tersebut tidak lagi ketakutan, namun makhluk tersebut menjadi ketakutan lagi jika ia dapat melihat kembali target atau bergerak dalam jarak 60 kaki dari target.\n***Simpati.*** Pesona menyebabkan makhluk tertentu merasakan dorongan kuat untuk mendekati target dalam jarak 60 kaki atau mampu melihatnya. Ketika makhluk tersebut dapat melihat target atau berada dalam jarak 60 kaki darinya, makhluk tersebut harus berhasil melakukan lemparan penyelamatan yang bijaksana atau menggunakan gerakannya pada setiap putarannya untuk memasuki area tersebut atau bergerak dalam jangkauan target. Ketika makhluk itu sudah melakukannya, ia tidak bisa rela menjauh dari sasarannya.\nJika target memberikan damage atau melukai makhluk yang terkena, makhluk yang terkena dapat melakukan lemparan penyelamatan kebijaksanaan untuk mengakhiri efeknya, seperti dijelaskan di bawah.\n***Mengakhiri Efeknya.*** Jika makhluk yang terkena dampak mengakhiri gilirannya saat tidak berada dalam jarak 60 kaki dari target atau dapat melihatnya, makhluk tersebut melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan berhasil, makhluk tersebut tidak lagi terpengaruh oleh target dan menganggap perasaan jijik atau tertarik sebagai sesuatu yang ajaib. Selain itu, makhluk yang terkena mantra diperbolehkan melakukan lemparan penyelamatan kebijaksanaan lagi setiap 24 jam selama mantranya masih ada.\nMakhluk yang berhasil menyelamatkan diri dari efek ini akan kebal terhadapnya selama 1 menit, setelah itu makhluk tersebut dapat terpengaruh lagi." },
      { name: "Clone", components: "V, S, M", desc: "Mantra ini menumbuhkan duplikat makhluk hidup sebagai perlindungan terhadap kematian. Klon ini terbentuk di dalam wadah tertutup dan tumbuh hingga ukuran penuh dan matang setelah 120 hari; Anda juga dapat memilih agar klon tersebut menjadi versi yang lebih muda dari makhluk yang sama. Ia tetap lembam dan bertahan tanpa batas waktu, selama wadahnya tidak terganggu.\nKapan saja setelah klon tersebut matang, jika makhluk aslinya mati, jiwanya berpindah ke klon tersebut, asalkan jiwanya bebas dan bersedia untuk kembali. Klon tersebut secara fisik identik dengan aslinya dan memiliki kepribadian, ingatan, dan kemampuan yang sama, tetapi tidak ada perlengkapan aslinya. Sisa-sisa fisik makhluk asli, jika masih ada, menjadi tidak aktif dan tidak dapat dihidupkan kembali, karena jiwa makhluk tersebut berada di tempat lain." },
      { name: "Control Weather", components: "V, S, M", desc: "Anda mengendalikan cuaca dalam jarak 5 mil dari Anda selama durasi tersebut. Anda harus berada di luar ruangan untuk mengucapkan mantra ini. Pindah ke tempat di mana Anda tidak memiliki jalur yang jelas ke langit akan mengakhiri mantranya lebih awal.\nSaat Anda merapal mantra, Anda mengubah kondisi cuaca saat ini, yang ditentukan oleh GM berdasarkan iklim dan musim. Anda dapat mengubah curah hujan, suhu, dan angin. Diperlukan waktu 1 hari 4 x 10 menit agar kondisi baru dapat diterapkan. Setelah mereka melakukannya, Anda dapat mengubah kondisinya lagi. Saat mantra berakhir, cuaca berangsur-angsur kembali normal.\nSaat Anda mengubah kondisi cuaca, temukan kondisi terkini pada tabel berikut dan ubah tahapannya satu per satu, naik atau turun. Saat mengubah arah angin, Anda dapat mengubah arahnya.\n##### Curah hujan\n| Tahap | Kondisi |\n|---|---|\n| 1 | Jelas |\n| 2 | Awan terang |\n| 3 | Mendung atau kabut tanah |\n| 4 | Hujan, hujan es, atau salju |\n| 5 | Hujan deras, hujan es, atau badai salju |\n##### Suhu\n| Tahap | Kondisi |\n|---|---|\n| 1 | Panas yang tak tertahankan |\n| 2 | Panas |\n| 3 | Hangat |\n| 4 | Keren |\n| 5 | Dingin |\n| 6 | Dingin Arktik |\n##### Angin\n| Tahap | Kondisi |\n|---|---|\n| 1 | Tenang |\n| 2 | Angin sedang |\n| 3 | Angin kencang |\n| 4 | Angin kencang |\n| 5 | Badai |" },
      { name: "Demiplane", components: "S", desc: "Anda membuat pintu bayangan pada permukaan padat datar yang dapat Anda lihat dalam jangkauan. Pintunya cukup besar untuk memungkinkan makhluk Medium melewatinya tanpa hambatan. Saat dibuka, pintunya mengarah ke demiplane yang tampak seperti ruangan kosong berukuran 30 kaki di setiap dimensinya, terbuat dari kayu atau batu. Ketika mantranya berakhir, pintunya menghilang, dan makhluk atau benda apa pun di dalam demiplane tetap terperangkap di sana, karena pintu itu juga menghilang dari sisi lain.\nSetiap kali Anda mengucapkan mantra ini, Anda dapat membuat demiplane baru, atau menghubungkan pintu bayangan ke demiplane yang Anda buat dengan pengucapan mantra ini sebelumnya. Selain itu, jika Anda mengetahui sifat dan isi demiplane yang diciptakan oleh makhluk lain yang merapal mantra ini, Anda dapat menghubungkan pintu bayangan ke demiplane tersebut." },
      { name: "Dominate Monster", components: "V, S", desc: "Anda mencoba memperdaya makhluk yang dapat Anda lihat dalam jangkauan. Ia harus berhasil dalam penyelamatan kebijaksanaan atau terpesona oleh Anda selama jangka waktu tersebut. Jika Anda atau makhluk yang bersahabat dengan Anda melawannya, ia memiliki keuntungan dalam penyelamatan.\nMeskipun makhluk itu terpesona, Anda memiliki hubungan telepati dengannya selama Anda berdua berada di alam eksistensi yang sama. Anda dapat menggunakan tautan telepati ini untuk mengeluarkan perintah kepada makhluk itu saat Anda sadar (tidak perlu tindakan apa pun), yang akan dipatuhinya sebaik mungkin. Anda dapat menentukan tindakan yang sederhana dan umum, seperti \"Serang makhluk itu\", \"Lari ke sana\", atau \"Ambil objek itu\". Jika makhluk tersebut menyelesaikan perintahnya dan tidak menerima arahan lebih lanjut dari Anda, ia akan mempertahankan dan mempertahankan dirinya dengan kemampuan terbaiknya.\nAnda dapat menggunakan tindakan Anda untuk mengambil kendali total dan tepat terhadap target. Hingga akhir giliran Anda berikutnya, makhluk itu hanya mengambil tindakan yang Anda pilih, dan tidak melakukan apa pun yang tidak Anda izinkan. Selama waktu ini, Anda juga dapat menyebabkan makhluk tersebut menggunakan reaksi, namun hal ini mengharuskan Anda menggunakan reaksi Anda sendiri juga.\nSetiap kali target menerima kerusakan, ia membuat lemparan penyelamatan kebijaksanaan baru terhadap mantra tersebut. Jika lemparan penyelamatan berhasil, mantranya berakhir.\nLevel Tinggi: Saat Anda menggunakan mantra ini dengan slot mantra level 9, durasinya adalah konsentrasi, hingga 8 jam." },
      { name: "Feeblemind", components: "V, S, M", desc: "Anda meledakkan pikiran makhluk yang dapat Anda lihat dalam jangkauan, mencoba menghancurkan kecerdasan dan kepribadiannya. Target menerima kerusakan psikis 4d6 dan harus melakukan lemparan penyelamatan intelijen.\nJika penyelamatan gagal, skor Kecerdasan dan Karisma makhluk tersebut menjadi 1. Makhluk tersebut tidak dapat merapal mantra, mengaktifkan item sihir, memahami bahasa, atau berkomunikasi dengan cara apa pun yang dapat dimengerti. Namun, makhluk itu dapat mengidentifikasi teman-temannya, mengikuti mereka, dan bahkan melindungi mereka.\nPada akhir setiap 30 hari, makhluk itu dapat mengulangi penyelamatannya terhadap mantra ini. Jika berhasil dalam lemparan penyelamatannya, mantranya berakhir.\nMantra ini juga dapat diakhiri dengan pemulihan, penyembuhan, atau keinginan yang lebih besar." },
      { name: "Incendiary Cloud", components: "V, S", desc: "Kepulan asap yang berputar-putar dengan bara api putih muncul dalam bola berradius 20 kaki yang berpusat pada suatu titik dalam jangkauan. Awan menyebar ke segala penjuru dan sangat tertutup. Itu berlangsung selama atau sampai angin dengan kecepatan sedang atau lebih besar (setidaknya 10 mil per jam) membubarkannya.\nSaat awan muncul, setiap makhluk di dalamnya harus melakukan lemparan penyelamatan ketangkasan. Makhluk menerima kerusakan api sebesar 10d8 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Makhluk juga harus melakukan lemparan penyelamatan ini ketika memasuki area mantra untuk pertama kalinya pada suatu giliran atau mengakhiri gilirannya di sana.\nAwan bergerak sejauh 10 kaki dari Anda ke arah yang Anda pilih di awal setiap belokan." },
      { name: "Maze", components: "V, S", desc: "Anda membuang makhluk yang dapat Anda lihat dalam jangkauan ke dalam demiplane labirin. Targetnya tetap di sana selama atau sampai ia lolos dari labirin.\nTarget dapat menggunakan aksinya untuk mencoba melarikan diri. Ketika melakukan hal tersebut, ia melakukan pemeriksaan Intelijen DC 20. Jika berhasil, ia lolos, dan mantranya berakhir (iblis minotaur atau goristro secara otomatis berhasil).\nSaat mantranya berakhir, target akan muncul kembali di ruang yang ditinggalkannya atau, jika ruang tersebut terisi, di ruang kosong terdekat." },
      { name: "Mind Blank", components: "V, S", desc: "Sampai mantranya berakhir, satu makhluk yang Anda sentuh akan kebal terhadap kerusakan psikis, efek apa pun yang dapat merasakan emosinya atau membaca pikirannya, mantra ramalan, dan kondisi terpesona. Mantra tersebut bahkan menggagalkan mantra keinginan dan mantra atau efek dengan kekuatan serupa yang digunakan untuk mempengaruhi pikiran target atau untuk mendapatkan informasi tentang target." },
      { name: "Power Word Stun", components: "V", desc: "Anda mengucapkan kata-kata yang memiliki kekuatan yang dapat menguasai pikiran satu makhluk yang dapat Anda lihat dalam jangkauannya, membuatnya tercengang. Jika target memiliki 150 poin hit atau kurang, target akan terkena stun. Kalau tidak, mantranya tidak akan berpengaruh.\nTarget yang terkena stun harus melakukan penyelamatan konstitusi di akhir setiap giliran. Jika penyelamatan berhasil, efek menakjubkan ini berakhir." },
      { name: "Sunburst", components: "V, S, M", desc: "Sinar matahari yang cemerlang bersinar dalam radius 60 kaki yang berpusat pada titik yang Anda pilih dalam jangkauannya. Setiap makhluk dalam terang itu harus melakukan penyelamatan konstitusi. Jika penyelamatan gagal, makhluk akan menerima kerusakan radiasi 12d6 dan menjadi buta selama 1 menit. Jika penyelamatan berhasil, dibutuhkan setengah kerusakan dan tidak dibutakan oleh mantra ini. Mayat hidup dan cairan merembes memiliki kelemahan dalam lemparan penyelamatan ini.\nMakhluk yang dibutakan oleh mantra ini melakukan lemparan penyelamatan konstitusi lainnya di akhir setiap putarannya. Jika penyelamatan berhasil, ia tidak lagi dibutakan.\nMantra ini menghilangkan kegelapan apa pun di areanya yang diciptakan oleh mantra." },
    ],
    Level9: [
      { name: "Astral Projection", components: "V, S, M", desc: "Anda dan hingga delapan makhluk yang bersedia dalam jangkauan memproyeksikan tubuh astral Anda ke Alam Astral (mantranya gagal dan castingnya sia-sia jika Anda sudah berada di Alam Astral itu). Badan material yang Anda tinggalkan tidak sadarkan diri dan dalam keadaan mati suri; tidak membutuhkan makanan atau udara dan tidak menua.\nTubuh astral Anda hampir menyerupai wujud fana Anda dalam segala hal, meniru statistik permainan dan harta benda Anda. Perbedaan utamanya adalah penambahan tali keperakan yang memanjang dari antara tulang belikat dan berjalan di belakang Anda, memudar hingga tidak terlihat setelah 1 kaki. Tali ini adalah tambatan Anda pada tubuh material Anda. Selama tambatannya tetap utuh, Anda dapat menemukan jalan pulang. Jika kabelnya terputus--sesuatu yang dapat terjadi hanya jika efeknya secara spesifik dinyatakan demikian--jiwa dan tubuh Anda terpisah, membunuh Anda seketika.\nBentuk astral Anda dapat dengan bebas melakukan perjalanan melalui Alam Astral dan dapat melewati portal yang mengarah ke alam lain mana pun. Jika Anda memasuki pesawat baru atau kembali ke pesawat yang Anda naiki saat merapal mantra ini, tubuh dan harta benda Anda akan dipindahkan melalui tali perak, memungkinkan Anda untuk masuk kembali ke tubuh Anda saat Anda memasuki pesawat baru. Bentuk astral Anda adalah inkarnasi terpisah. Kerusakan atau dampak lain apa pun yang terjadi padanya tidak berpengaruh pada tubuh fisik Anda, juga tidak bertahan saat Anda kembali menggunakannya.\nMantra berakhir untuk Anda dan teman Anda saat Anda menggunakan tindakan Anda untuk mengabaikannya. Ketika mantranya berakhir, makhluk yang terkena dampak kembali ke tubuh fisiknya, dan dia terbangun.\nMantra ini mungkin juga berakhir lebih awal untuk Anda atau salah satu teman Anda. Mantra sihir penghilang yang berhasil digunakan terhadap tubuh astral atau fisik akan mengakhiri mantra untuk makhluk itu. Jika tubuh asli makhluk atau bentuk astralnya turun menjadi 0 poin serangan, mantra untuk makhluk tersebut berakhir. Jika mantranya berakhir dan tali peraknya masih utuh, tali tersebut akan menarik bentuk astral makhluk itu kembali ke tubuhnya, mengakhiri keadaan mati suri.\nJika Anda dikembalikan ke tubuh Anda sebelum waktunya, teman Anda tetap dalam bentuk astral dan harus menemukan jalan kembali ke tubuh mereka sendiri, biasanya dengan penurunan hingga 0 poin serangan." },
      { name: "Foresight", components: "V, S, M", desc: "Anda menyentuh makhluk yang bersedia dan memberikan kemampuan terbatas untuk melihat masa depan. Selama durasi, target tidak dapat terkejut dan memiliki keunggulan dalam serangan, pengecekan kemampuan, dan penyelamatan lemparan. Selain itu, makhluk lain memiliki kelemahan dalam serangan berguling terhadap target selama durasi tersebut.\nMantra ini akan langsung berakhir jika kamu mengucapkannya lagi sebelum durasinya berakhir." },
      { name: "Gate", components: "V, S, M", desc: "Anda membayangkan sebuah portal yang menghubungkan ruang kosong yang dapat Anda lihat dalam jangkauan ke lokasi yang tepat di alam eksistensi yang berbeda. Portalnya berupa bukaan melingkar, yang bisa Anda buat dengan diameter 5 hingga 20 kaki. Anda dapat mengarahkan portal ke arah mana pun yang Anda pilih. Portal ini bertahan selama durasi tersebut.\nPortal ini memiliki bagian depan dan belakang pada setiap bidang tempat ia muncul. Perjalanan melalui portal hanya mungkin dilakukan dengan bergerak melalui bagian depannya. Apa pun yang melakukan hal itu akan langsung dipindahkan ke pesawat lain, muncul di ruang kosong yang paling dekat dengan portal.\nDewa dan penguasa planar lainnya dapat mencegah portal yang dibuat oleh mantra ini terbuka di hadapan mereka atau di mana pun dalam domain mereka.\nSaat Anda mengucapkan mantra ini, Anda dapat mengucapkan nama makhluk tertentu (nama samaran, gelar, atau nama panggilan tidak berfungsi). Jika makhluk itu berada di pesawat selain yang Anda naiki, portal akan terbuka di sekitar makhluk yang disebutkan dan menarik makhluk itu melewatinya ke ruang kosong terdekat di sisi portal Anda. Anda tidak mendapatkan kekuatan khusus atas makhluk itu, dan ia bebas bertindak sesuai keinginan GM. Ia mungkin pergi, menyerang Anda, atau membantu Anda." },
      { name: "Imprisonment", components: "V, S, M", desc: "Anda membuat penahan ajaib untuk menahan makhluk yang dapat Anda lihat dalam jangkauan. Target harus berhasil dalam lemparan penyelamatan kebijaksanaan atau terikat oleh mantra; jika berhasil, ia kebal terhadap mantra ini jika Anda mengucapkannya lagi. Saat terkena mantra ini, makhluk tersebut tidak perlu bernapas, makan, atau minum, dan tidak menua. Mantra ramalan tidak dapat menemukan atau melihat targetnya.\nSaat Anda mengucapkan mantra, Anda memilih salah satu dari bentuk pemenjaraan berikut.\n***Penguburan.*** Targetnya dikuburkan jauh di bawah bumi dalam sebuah bola kekuatan magis yang cukup besar untuk menampung targetnya. Tidak ada yang dapat melewati bola tersebut, dan makhluk apa pun tidak dapat berteleportasi atau menggunakan perjalanan planar untuk masuk atau keluar darinya.\nKomponen khusus untuk versi mantra ini adalah bola mitral kecil.\n***Rantai.*** Rantai berat, tertanam kuat di tanah, menahan target di tempatnya. Target ditahan hingga mantranya berakhir, dan target tidak dapat bergerak atau dipindahkan dengan cara apa pun hingga saat itu.\nKomponen khusus untuk versi mantra ini adalah rantai halus dari logam mulia.\n***Penjara Lindung Nilai.*** Mantra tersebut memindahkan target ke dalam demiplane kecil yang terlindung dari teleportasi dan perjalanan planar. Demiplane dapat berupa labirin, sangkar, menara, atau struktur atau area terbatas serupa yang Anda pilih.\nKomponen khusus untuk versi mantra ini adalah representasi miniatur penjara yang terbuat dari batu giok.\n***Penahanan Minimum.*** Target menyusut hingga ketinggian 1 inci dan terkurung di dalam batu permata atau benda serupa. Cahaya dapat menembus batu permata secara normal (memungkinkan target untuk melihat keluar dan makhluk lain dapat melihat ke dalam), tetapi tidak ada benda lain yang dapat melewatinya, bahkan melalui teleportasi atau perjalanan planar. Batu permata tidak dapat dipotong atau dipatahkan selama mantranya masih berlaku.\nKomponen khusus untuk mantra versi ini adalah batu permata besar dan transparan, seperti korundum, berlian, atau rubi.\n***Tidur.*** Target tertidur dan tidak dapat dibangunkan.\nKomponen khusus untuk versi mantra ini terdiri dari ramuan obat tidur yang langka.\n***Mengakhiri Mantra.*** Selama merapal mantra, dalam versi mana pun, Anda dapat menentukan kondisi yang akan menyebabkan mantra berakhir dan melepaskan target. Kondisi tersebut bisa spesifik atau rumit sesuai pilihan Anda, namun GM harus setuju bahwa kondisi tersebut wajar dan kemungkinan besar akan terjadi. Kondisi tersebut dapat didasarkan pada nama, identitas, atau dewa suatu makhluk, tetapi sebaliknya harus didasarkan pada tindakan atau kualitas yang dapat diamati dan tidak berdasarkan pada hal-hal yang tidak berwujud seperti level, kelas, atau titik sasaran.\nMantra sihir penghilang dapat mengakhiri mantra hanya jika digunakan sebagai mantra tingkat 9, menargetkan penjara atau komponen khusus yang digunakan untuk membuatnya.\nAnda dapat menggunakan komponen khusus tertentu untuk membuat hanya satu penjara dalam satu waktu. Jika Anda merapal mantra lagi menggunakan komponen yang sama, target casting pertama akan segera terbebas dari ikatannya." },
      { name: "Meteor Swarm", components: "V, S", desc: "Bola api yang menyala-nyala jatuh ke tanah di empat titik berbeda yang dapat Anda lihat dalam jangkauannya. Setiap makhluk dalam bola berradius 40 kaki yang berpusat pada setiap titik yang Anda pilih harus melakukan lemparan penyelamatan ketangkasan. Bola itu menyebar ke berbagai sudut. Makhluk menerima 20d6 kerusakan api dan 20d6 kerusakan pukulan pada penyelamatan yang gagal, atau setengah kerusakan pada penyelamatan yang berhasil. Makhluk yang berada di area lebih dari satu semburan api hanya terpengaruh satu kali.\nMantra tersebut merusak objek di area tersebut dan menyulut objek yang mudah terbakar yang tidak dipakai atau dibawa." },
      { name: "Power Word Kill", components: "V", desc: "Anda mengucapkan kata-kata kekuatan yang dapat memaksa satu makhluk yang Anda lihat dalam jangkauannya untuk mati seketika. Jika makhluk yang Anda pilih memiliki 100 poin hit atau kurang, ia akan mati. Kalau tidak, mantranya tidak akan berpengaruh." },
      { name: "Prismatic Wall", components: "V, S", desc: "Bidang cahaya beraneka warna yang berkilauan membentuk dinding buram vertikal--panjang hingga 90 kaki, tinggi 30 kaki, dan tebal 1 inci--berpusat pada titik yang dapat Anda lihat dalam jangkauan. Alternatifnya, Anda dapat membentuk dinding menjadi bola dengan diameter hingga 30 kaki yang berpusat pada titik yang Anda pilih dalam jangkauan. Tembok itu tetap di tempatnya selama ini. Jika Anda memposisikan dinding sehingga melewati ruang yang ditempati oleh makhluk, mantranya akan gagal, dan tindakan Anda serta slot mantranya akan sia-sia.\nDinding memancarkan cahaya terang hingga jarak 100 kaki dan cahaya redup hingga jarak 100 kaki tambahan. Anda dan makhluk yang Anda tunjuk pada saat Anda mengucapkan mantra dapat melewati dan tetap berada di dekat dinding tanpa cedera. Jika makhluk lain yang dapat melihat tembok bergerak dalam jarak 20 kaki darinya atau mulai berbelok ke sana, makhluk tersebut harus berhasil melakukan lemparan penyelamatan konstitusi atau menjadi buta selama 1 menit.\nDindingnya terdiri dari tujuh lapisan yang masing-masing memiliki warna berbeda. Saat makhluk mencoba menjangkau atau melewati dinding, ia melakukannya selapis demi selapis melalui seluruh lapisan dinding. Saat melewati atau mencapai setiap lapisan, makhluk tersebut harus melakukan lemparan penyelamatan ketangkasan atau terpengaruh oleh properti lapisan tersebut seperti dijelaskan di bawah.\nDinding dapat dihancurkan, juga satu lapis pada satu waktu, secara berurutan dari merah menjadi ungu, dengan cara yang spesifik untuk setiap lapisan. Setelah sebuah lapisan dihancurkan, lapisan tersebut akan tetap demikian selama durasi mantra. Batang pembatalan menghancurkan dinding prismatik, tapi medan antisihir tidak berpengaruh padanya.\n***1. Merah.*** Makhluk tersebut menerima kerusakan api sebesar 10d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Selama lapisan ini ada, serangan jarak jauh non-magis tidak dapat menembus dinding. Lapisan tersebut dapat dihancurkan dengan menimbulkan setidaknya 25 kerusakan dingin padanya.\n***2. Oranye.*** Makhluk tersebut menerima kerusakan asam 10d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Selama lapisan ini ada, serangan jarak jauh magis tidak dapat menembus dinding. Lapisan tersebut dihancurkan oleh angin kencang.\n***3. Kuning.*** Makhluk tersebut menerima kerusakan petir sebesar 10d6 jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Lapisan ini dapat dihancurkan dengan memberikan setidaknya 60 kerusakan paksa padanya.\n***4. Hijau.*** Makhluk tersebut menerima 10d6 kerusakan racun jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Mantra passwall, atau mantra lain dengan level yang sama atau lebih besar yang dapat membuka portal di permukaan padat, menghancurkan lapisan ini.\n***5. Biru.*** Makhluk tersebut menerima 10d6 kerusakan dingin jika penyelamatan gagal, atau setengah kerusakan jika penyelamatan berhasil. Lapisan ini dapat dihancurkan dengan menimbulkan setidaknya 25 kerusakan akibat kebakaran.\n***6. Indigo.*** Saat penyelamatan gagal, makhluk itu tertahan. Ia kemudian harus melakukan penyelamatan konstitusi di akhir setiap putarannya. Jika berhasil menyelamatkan tiga kali, mantranya berakhir. Jika gagal menyelamatkannya tiga kali, ia akan berubah menjadi batu secara permanen dan mengalami kondisi membatu. Keberhasilan dan kegagalan tidak harus terjadi secara berurutan; pantau keduanya sampai makhluk itu mengumpulkan tiga jenis.\nSelama lapisan ini ada, mantra tidak dapat dilemparkan menembus dinding. Lapisan tersebut dihancurkan oleh cahaya terang yang dipancarkan oleh mantra siang hari atau mantra serupa dengan level yang sama atau lebih tinggi.\n***7. Violet.*** Saat penyelamatan gagal, makhluk itu menjadi buta. Ia kemudian harus melakukan lemparan penyelamatan yang bijaksana di awal giliran Anda berikutnya. Penyelamatan yang berhasil mengakhiri kebutaan. Jika penyelamatan itu gagal, makhluk itu dipindahkan ke pesawat lain pilihan GM dan tidak lagi buta. (Biasanya, makhluk yang berada di pesawat yang bukan pesawat asalnya akan dibuang pulang, sedangkan makhluk lain biasanya dilemparkan ke pesawat Astral atau Ethereal.) Lapisan ini dihancurkan oleh mantra sihir penghilang atau mantra serupa dengan tingkat yang sama atau lebih tinggi yang dapat mengakhiri mantra dan efek magis." },
      { name: "Shapechange", components: "V, S, M", desc: "Anda mengambil bentuk makhluk yang berbeda selama durasi tersebut. Bentuk barunya bisa berupa makhluk apa pun dengan peringkat tantangan yang sama dengan level Anda atau lebih rendah. Makhluk itu tidak bisa berupa konstruksi atau undead, dan Anda pasti pernah melihat makhluk semacam itu setidaknya sekali. Anda berubah menjadi contoh rata-rata dari makhluk itu, makhluk tanpa tingkat kelas atau sifat Spellcasting.\nStatistik permainan Anda digantikan oleh statistik makhluk yang dipilih, meskipun Anda tetap mempertahankan keselarasan dan skor Kecerdasan, Kebijaksanaan, dan Karisma Anda. Anda juga mempertahankan semua keterampilan dan kemahiran menyimpan lemparan Anda, selain mendapatkan keterampilan makhluk itu. Jika makhluk tersebut memiliki kemahiran yang sama dengan Anda dan bonus yang tercantum dalam statistiknya lebih tinggi dari Anda, gunakan bonus makhluk tersebut sebagai pengganti Anda. Anda tidak dapat menggunakan aksi legendaris atau aksi sarang apa pun dalam bentuk baru.\nAnda mengasumsikan hit point dan Hit Dice dari bentuk baru. Ketika Anda kembali ke bentuk normal, Anda kembali ke jumlah poin hit yang Anda miliki sebelum Anda bertransformasi. Jika Anda kembali karena poin hit turun ke 0, kerusakan berlebih akan berpindah ke bentuk normal Anda. Selama kerusakan berlebih tidak mengurangi bentuk normalmu menjadi 0 poin serangan, kamu tidak akan pingsan.\nAnda tetap dapat memanfaatkan fitur apa pun dari kelas, ras, atau sumber lain dan dapat menggunakannya, asalkan formulir baru Anda secara fisik mampu melakukannya. Anda tidak dapat menggunakan indra khusus apa pun yang Anda miliki (misalnya, penglihatan gelap) kecuali jika bentuk baru Anda juga memiliki indera tersebut. Anda hanya dapat berbicara jika makhluk tersebut dapat berbicara secara normal.\nSaat Anda bertransformasi, Anda memilih apakah perlengkapan Anda jatuh ke tanah, menyatu menjadi bentuk baru, atau aus karenanya. Peralatan yang dipakai berfungsi seperti biasa. GM menentukan apakah praktis bagi wujud baru untuk memakai peralatan, berdasarkan bentuk dan ukuran makhluk tersebut. Peralatan Anda tidak berubah bentuk atau ukuran untuk menyesuaikan dengan bentuk baru, dan peralatan apa pun yang tidak dapat dipakai oleh bentuk baru harus jatuh ke tanah atau bergabung ke dalam bentuk baru Anda. Peralatan yang digabungkan tidak berpengaruh pada kondisi tersebut.\nSelama durasi mantra ini, Anda dapat menggunakan tindakan Anda untuk mengambil bentuk berbeda dengan mengikuti batasan dan aturan yang sama untuk bentuk aslinya, dengan satu pengecualian: jika bentuk baru Anda memiliki poin hit lebih banyak daripada formulir saat ini, poin hit Anda tetap pada nilainya saat ini." },
      { name: "Time Stop", components: "V", desc: "Anda menghentikan sementara aliran waktu untuk semua orang kecuali diri Anda sendiri. Tidak ada waktu berlalu untuk makhluk lain, saat Anda melakukan 1d4 + 1 putaran berturut-turut, di mana Anda dapat menggunakan tindakan dan bergerak seperti biasa.\nMantra ini berakhir jika salah satu tindakan yang Anda gunakan selama periode ini, atau efek apa pun yang Anda buat selama periode ini, memengaruhi makhluk selain Anda atau benda yang dikenakan atau dibawa oleh orang lain selain Anda. Selain itu, mantranya akan berakhir jika Anda berpindah ke tempat yang lebih dari 1.000 kaki dari lokasi Anda melemparkannya." },
      { name: "True Polymorph", components: "V, S, M", desc: "Pilih satu makhluk atau objek non-magis yang dapat Anda lihat dalam jangkauannya. Anda mengubah makhluk menjadi makhluk lain, makhluk menjadi benda, atau benda menjadi makhluk (benda tersebut tidak boleh dipakai atau dibawa oleh makhluk lain). Transformasi berlangsung selama durasi tersebut, atau hingga target turun menjadi 0 poin hit atau mati. Jika Anda berkonsentrasi pada mantra ini selama durasi penuh, transformasinya menjadi permanen.\nPengubah bentuk tidak terpengaruh oleh mantra ini. Makhluk yang enggan dapat melakukan lemparan penyelamatan kebijaksanaan, dan jika berhasil, ia tidak terpengaruh oleh mantra ini.\n***Makhluk menjadi Makhluk.*** Jika Anda mengubah makhluk menjadi jenis makhluk lain, bentuk baru dapat berupa jenis apa pun yang Anda pilih yang peringkat tantangannya sama dengan atau lebih kecil dari target (atau levelnya, jika target tidak memiliki peringkat tantangan). Statistik permainan target, termasuk skor kemampuan mental, digantikan oleh statistik bentuk baru. Ia mempertahankan keselarasan dan kepribadiannya.\nTarget tersebut mengambil titik serangan dari bentuk barunya, dan ketika kembali ke bentuk normalnya, makhluk tersebut kembali ke jumlah titik serangan yang dimilikinya sebelum ia bertransformasi. Jika poin serangannya kembali karena poin hitnya turun menjadi 0, kerusakan berlebih akan kembali ke bentuk normalnya. Selama kerusakan berlebih tidak mengurangi bentuk normal makhluk itu menjadi 0 poin serangan, ia tidak akan pingsan.\nTindakan yang dapat dilakukan makhluk ini terbatas karena sifat dari bentuk barunya, dan ia tidak dapat berbicara, merapal mantra, atau melakukan tindakan lain apa pun yang memerlukan tangan atau ucapan kecuali jika bentuk barunya mampu melakukan tindakan tersebut.\nPerlengkapan target menyatu ke dalam bentuk baru. Makhluk itu tidak dapat mengaktifkan, menggunakan, menggunakan, atau memanfaatkan peralatan apa pun.\n***Objek menjadi Makhluk.*** Anda dapat mengubah suatu objek menjadi makhluk apa pun, asalkan ukuran makhluk tersebut tidak lebih besar dari ukuran objek dan peringkat tantangan makhluk tersebut adalah 9 atau lebih rendah. Makhluk itu ramah terhadap Anda dan teman Anda. Ia bertindak pada setiap giliran Anda. Anda memutuskan tindakan apa yang diperlukan dan bagaimana tindakannya. GM memiliki statistik makhluk itu dan menentukan semua tindakan dan pergerakannya.\nJika mantranya menjadi permanen, Anda tidak lagi mengendalikan makhluk itu. Itu mungkin tetap bersahabat dengan Anda, tergantung bagaimana Anda memperlakukannya.\n***Makhluk menjadi Objek.*** Jika Anda mengubah makhluk menjadi objek, ia akan berubah bersama apa pun yang dikenakan dan dibawanya ke dalam bentuk tersebut. Statistik makhluk itu menjadi milik objeknya, dan makhluk itu tidak memiliki ingatan tentang waktu yang dihabiskan dalam bentuk ini, setelah mantranya berakhir dan kembali ke bentuk normalnya." },
      { name: "Weird", components: "V, S", desc: "Dengan memanfaatkan ketakutan terdalam sekelompok makhluk, Anda menciptakan makhluk ilusi dalam pikiran mereka, yang hanya dapat dilihat oleh mereka. Setiap makhluk dalam bola berradius 30 kaki yang berpusat pada titik pilihan Anda dalam jangkauan harus melakukan lemparan penyelamatan yang bijaksana. Jika penyelamatan gagal, makhluk menjadi ketakutan selama itu. Ilusi tersebut membangkitkan ketakutan terdalam makhluk tersebut, mewujudkan mimpi buruk terburuknya sebagai ancaman yang tidak dapat didamaikan. Di awal setiap giliran makhluk yang ketakutan, ia harus berhasil melakukan lemparan penyelamatan kebijaksanaan atau menerima kerusakan psikis 4d10. Jika penyelamatan berhasil, mantra untuk makhluk itu berakhir." },
      { name: "Wish", components: "V", desc: "Harapan adalah mantra terkuat yang bisa diucapkan makhluk fana. Hanya dengan berbicara keras-keras, Anda dapat mengubah fondasi realitas sesuai keinginan Anda.\nKegunaan dasar mantra ini adalah untuk menduplikasi mantra lain level 8 atau lebih rendah. Anda tidak perlu memenuhi persyaratan apa pun dalam mantra itu, termasuk komponen yang mahal. Mantra itu mulai berlaku.\nAlternatifnya, Anda dapat membuat salah satu efek pilihan Anda berikut ini:\n- Anda membuat satu objek dengan nilai hingga 25.000 gp yang bukan merupakan item ajaib. Objek tersebut tidak boleh lebih dari 300 kaki dalam dimensi apa pun, dan ia muncul di ruang kosong yang dapat Anda lihat di tanah.\n- Anda mengizinkan hingga dua puluh makhluk yang dapat Anda lihat untuk mendapatkan kembali semua titik serangan, dan Anda mengakhiri semua efek pada mereka yang dijelaskan dalam mantra pemulihan yang lebih besar.\n- Anda memberikan hingga sepuluh makhluk yang Anda lihat ketahanannya terhadap jenis kerusakan yang Anda pilih.\n- Anda memberikan hingga sepuluh makhluk yang dapat Anda lihat kekebalannya terhadap satu mantra atau efek magis lainnya selama 8 jam. Misalnya, Anda bisa membuat diri Anda dan semua teman Anda kebal terhadap serangan yang menguras nyawa lich.\n- Anda membatalkan satu event baru-baru ini dengan memaksa roll ulang dari setiap lemparan yang dilakukan dalam ronde terakhir (termasuk giliran terakhir Anda). Realitas membentuk kembali dirinya untuk mengakomodasi hasil baru. Misalnya, mantra harapan dapat membatalkan penyelamatan lawan yang berhasil, serangan kritis musuh, atau penyelamatan teman yang gagal. Anda dapat memaksa agar reroll dibuat dengan kelebihan atau kekurangan, dan Anda dapat memilih apakah akan menggunakan reroll atau roll asli.\nAnda mungkin bisa mencapai sesuatu di luar cakupan contoh di atas. Nyatakan keinginan Anda kepada GM sedetail mungkin. GM mempunyai kebebasan yang besar dalam memutuskan apa yang terjadi dalam kasus seperti itu; semakin besar keinginannya, semakin besar kemungkinan terjadi kesalahan. Mantra ini mungkin gagal, efek yang Anda inginkan mungkin hanya tercapai sebagian, atau Anda mungkin mengalami konsekuensi tak terduga akibat cara Anda mengucapkan keinginan tersebut. Misalnya, berharap seorang penjahat mati mungkin akan mendorong Anda maju ke masa ketika penjahat tersebut tidak lagi hidup, sehingga secara efektif mengeluarkan Anda dari permainan. Demikian pula, mengharapkan item sihir atau artefak legendaris mungkin akan langsung membawa Anda ke hadapan pemilik item tersebut saat ini.\nTekanan dalam merapal mantra ini untuk menghasilkan efek apa pun selain menduplikasi mantra lain akan melemahkan Anda. Setelah menahan tekanan itu, setiap kali Anda merapal mantra hingga Anda menyelesaikan istirahat panjang, Anda menerima 1d10 kerusakan nekrotik per level mantra tersebut. Kerusakan ini tidak dapat dikurangi atau dicegah dengan cara apa pun. Selain itu, Kekuatan Anda turun menjadi 3, jika belum menjadi 3 atau lebih rendah, selama 2d4 hari. Untuk setiap hari yang Anda habiskan untuk beristirahat dan tidak melakukan apa pun selain aktivitas ringan, sisa waktu pemulihan Anda berkurang 2 hari. Terakhir, ada kemungkinan 33 persen bahwa Anda tidak dapat lagi mewujudkan harapan jika Anda mengalami stres ini." },
    ],
  },
};
